formatDateYM = (date: Date): string => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  return `${year}-${month}`;
}

formatDateYMD = (date: Date): string => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

attachmentsToDtos = (
  attachments: Attachment[],
): AttachmentDto[] | undefined => {
  if (!attachments.length) return undefined;
  return attachments.map(attachmentToDto);
}

attachmentToDto = (attachment: Attachment): AttachmentDto => {
  if (!attachment.url) {
    throw new Error(`Attachment "${attachment.name}" has not been uploaded`);
  }

  return {
    type: attachment.contentType,
    title: attachment.name,
    url: attachment.url,
  } as AttachmentDto;
}

createMessagePair = (
  content: string,
  customContent?: MessageCustomContent,
  deploymentId?: string | null,
): MessagePair => {
  const now = Date.now();
  const timestamp = new Date(now).toISOString();

  return {
    userMessage: {
      role: MessageRole.User,
      content,
      timestamp,
      ...(customContent && Object.keys(customContent).length
        ? { custom_content: customContent }
        : {}),
    },
    assistantMessage: {
      role: MessageRole.Assistant,
      content: '',
      timestamp,
      ...(deploymentId ? { deploymentId } : {}),
    },
  };
}

export interface MessagePair {
  userMessage: Message;
  assistantMessage: Message;
}

hasActiveToolConfig = (
  value: Record<string, boolean> | undefined,
): boolean => value != null && Object.keys(value).length > 0

isMessageChanged = (
  originalMessage: Message,
  newText: string,
  keptDisplayAttachments: DisplayAttachment[],
  newAttachments: Attachment[],
  skills?: RequestSkill[],
): boolean => {
  if (newText !== originalMessage.content) return true;
  if (newAttachments.length > 0) return true;
  const originalAttachmentCount =
    originalMessage.custom_content?.attachments?.length ?? 0;
  if (keptDisplayAttachments.length !== originalAttachmentCount) return true;
  return (
    skills != null &&
    isSkillsChanged(originalMessage.custom_content?.skills, skills)
  );
}

shouldRerunGenerationOnEdit = (
  messages: Message[],
  messageIndex: number,
  newText: string,
  keptDisplayAttachments: DisplayAttachment[],
  newAttachments: Attachment[],
  skills?: RequestSkill[],
): boolean => {
  const originalMessage = messages[messageIndex];
  if (!originalMessage) return false;

  return (
    isMessageChanged(
      originalMessage,
      newText,
      keptDisplayAttachments,
      newAttachments,
      skills,
    ) || isAnswerIncomplete(messages[messageIndex + 1])
  );
}

getStarterConversationText = (
  starter: StarterOption,
  description?: string,
): string => {
  const { populateText } = starter['dial:widgetOptions'];

  if (populateText == null && description) {
    return description;
  }

  return getStarterPopulateText(starter);
}

getStarterSubmitText = (
  starter: StarterOption,
  description?: string,
): string => {
  const { populateText, submit } = starter['dial:widgetOptions'];

  if (submit && populateText == null) {
    return '';
  }

  return getStarterConversationText(starter, description);
}

applyChunkToMessages = (
  messages: Message[],
  messageIndex: number,
  chunk: StreamChunk,
): Message[] | null => {
  const delta = chunk.choices[0]?.delta;
  const content = delta?.content ?? '';
  const formSchema = delta?.custom_content?.form_schema;
  const attachments = delta?.custom_content?.attachments;
  const stages = delta?.custom_content?.stages;
  const annotations = delta?.custom_content?.annotations;
  const rawAnnotations = delta?.custom_fields?.annotations;
  const state = delta?.custom_content?.state;
  const hasContentUpdate =
    !!content ||
    !!formSchema ||
    !!attachments?.length ||
    !!stages?.length ||
    !!annotations?.length ||
    !!rawAnnotations?.length ||
    !!state;
  const responseId =
    delta?.responseId ?? (hasContentUpdate ? chunk.id : undefined);

  if (!hasContentUpdate && !responseId) return null;

  return messages.map((message, index) => {
    if (index !== messageIndex) return message;

    const allAttachments = [
      ...(message.custom_content?.attachments ?? []),
      ...(attachments ?? []),
    ];
    const normalizedRawAnnotations = rawAnnotations?.length
      ? normalizeRawAnnotations(rawAnnotations, allAttachments)
      : [];
    const incomingAnnotations = [
      ...(annotations ?? []),
      ...normalizedRawAnnotations,
    ];

    const hasCustomContentUpdate =
      formSchema ||
      attachments?.length ||
      stages?.length ||
      incomingAnnotations.length ||
      state;

    return {
      ...message,
      content: content ? message.content + content : message.content,
      ...(responseId && { responseId }),
      ...(hasCustomContentUpdate && {
        custom_content: {
          ...message.custom_content,
          ...(formSchema && { form_schema: formSchema }),
          ...(attachments?.length && {
            attachments: allAttachments,
          }),
          ...(stages?.length && {
            stages: mergeStages(message.custom_content?.stages ?? [], stages),
          }),
          ...(incomingAnnotations.length && {
            annotations: mergeAnnotations(
              message.custom_content?.annotations ?? [],
              incomingAnnotations,
            ),
          }),
          ...(state && { state }),
        },
      }),
    };
  });
}

mergeStages = (existing: Stage[], incoming: Stage[]): Stage[] => {
  const result = [...existing];
  for (const stage of incoming) {
    const idx = result.findIndex((s) => s.index === stage.index);
    if (idx >= 0) {
      result[idx] = {
        ...result[idx],
        ...stage,
        name: (result[idx].name ?? '') + (stage.name ?? ''),
        content:
          (result[idx].content ?? '') + (stage.content ?? '') || undefined,
        attachments: stage.attachments?.length
          ? mergeStageAttachments(
              result[idx].attachments ?? [],
              stage.attachments,
            )
          : result[idx].attachments,
      };
    } else {
      /*
       * A brand-new stage's first chunk can carry `name: null` (DIAL Core's
       * "stage opened, name pending" signal, before the name text streams
       * in) — `Stage.name` is typed as non-nullable, so this must be
       * normalized here the same way the merge branch above already
       * coalesces `null` to `''`, or downstream renderers that assume a
       * string (e.g. `cleanStageName`) crash on the very first chunk.
       */
      result.push({ ...stage, name: stage.name ?? '' });
    }
  }
  return result;
}

getConversationPath = (conversationId: string): string => {
  const slashIndex = conversationId.indexOf('/');
  const path =
    slashIndex === -1
      ? conversationId
      : conversationId.substring(slashIndex + 1);
  return safeDecodeURI(path);
}

isAwaitingGenerationResume = (
  conversation: Conversation,
): boolean => {
  const lastMessage = conversation.messages[conversation.messages.length - 1];
  return (
    !!lastMessage &&
    lastMessage.role === MessageRole.Assistant &&
    !hasGeneratedPayload(lastMessage) &&
    lastMessage.streamErrorMessage == null &&
    !lastMessage.wasStoppedByUser
  );
}

sanitizeFileName = (name: string): string => {
  const { base: baseName, extension } = splitFileNameExtension(name);

  const sanitizedBase = stripTrailingDotsAndWhitespace(
    baseName.replace(new RegExp(NOT_ALLOWED_SYMBOLS_REGEXP.source, 'g'), '_'),
  );

  if (sanitizedBase === '') {
    return name;
  }

  return trimFileNameToByteLimit(`${sanitizedBase}${extension}`);
}

splitFileNameExtension = (
  fileName: string,
): { base: string; extension: string } => {
  const dotIndex = fileName.lastIndexOf('.');
  const hasExtension = dotIndex > 0;
  return {
    base: hasExtension ? fileName.slice(0, dotIndex) : fileName,
    extension: hasExtension ? fileName.slice(dotIndex) : '',
  };
}

trimFileNameToByteLimit = (name: string, limit = 255): string => {
  if (getUtf8ByteLength(name) <= limit) return name;

  const { base, extension: ext } = splitFileNameExtension(name);
  const extBytes = getUtf8ByteLength(ext);
  const baseLimit = limit - extBytes;

  if (baseLimit <= 0) {
    return truncateToUtf8Bytes(name, limit);
  }

  return `${truncateToUtf8Bytes(base, baseLimit)}${ext}`;
}

createMcpAppsApiClient = (
  toolsetsApi: ToolsetsApi,
): McpAppsApiClient => ({
  fetchResourceHtml: async (toolsetId, resourceUri) => {
    try {
      const { raw } = await toolsetsApi.getToolsetMcpAppResourceRaw({
        toolsetName: safeDecodeURIComponent(toolsetId),
        resourceUri,
      });
      return await raw.text();
    } catch (err) {
      if (err instanceof ResponseError) {
        throw new McpAppResourceFetchError(err.response.status);
      }
      throw err;
    }
  },
  callTool: async (toolsetId, toolName, args, kind) => {
    const { result } = await toolsetsApi.callToolsetMcpAppTool({
      toolsetName: safeDecodeURIComponent(toolsetId),
      mcpAppToolCallRequestDto: {
        toolName,
        arguments: args as object,
        kind: kind as McpAppToolCallRequestDtoKindEnum,
      },
    });
    return result as CallToolResult;
  },
  listAppTools: async (deploymentId, kind) => {
    const { tools } = await toolsetsApi.listMcpAppTools({
      deploymentId: safeDecodeURIComponent(deploymentId),
      kind,
    });
    return tools;
  },
  listToolNames: async (deploymentId, kind) => {
    const { toolNames } = await toolsetsApi.listMcpToolNames({
      deploymentId: safeDecodeURIComponent(deploymentId),
      kind: kind as ListMcpToolNamesKindEnum,
    });
    return toolNames;
  },
})

export class McpAppResourceFetchError extends Error {
  constructor(public readonly status: number) {
    super(`Failed to fetch MCP app resource: HTTP ${status}`);
  }
}

export interface McpAppsApiClient {
  /** Fetches a toolset's MCP Apps `ui://` resource and resolves to its HTML body. Throws `McpAppResourceFetchError` on a non-OK response. */
  fetchResourceHtml: FetchMcpAppResourceHtml;
  /** Forwards an MCP App's tool call (self-initiated, or `@epam/ai-dial-mcp-apps`'s live re-call) through chat-api. */
  callTool: CallMcpAppTool;
  /** Lists the tools of an MCP-capable deployment that declare an MCP Apps UI resource. */
  listAppTools: (
    deploymentId: string,
    kind: McpDeploymentKind,
  ) => Promise<McpAppToolSummary[]>;
  /** Lists every tool name exposed by an MCP-capable deployment's `tools/list`, unfiltered. */
  listToolNames: (
    deploymentId: string,
    kind: McpDeploymentKind,
  ) => Promise<string[]>;
}

useMcpAppTools = (
  client: McpAppsApiClient,
  deployment: DeploymentItemDto | undefined,
  messages: Message[],
  toolsets: DialToolsetDto[],
): McpAppToolRef[] => {
  const [directTools, setDirectTools] = useState<McpAppToolRef[]>([]);
  const [indirectTools, setIndirectTools] = useState<McpAppToolRef[]>([]);
  const fetchedToolsetIdsRef = useRef<Set<string>>(new Set());

  useEffect(() => {
    fetchedToolsetIdsRef.current = new Set();
    setIndirectTools([]);

    if (deployment?.features?.mcp !== true) {
      setDirectTools([]);
      return;
    }
    if (deployment.type !== 'toolset' && deployment.type !== 'application') {
      setDirectTools([]);
      return;
    }
    const deploymentId = deployment.id;
    const kind: McpDeploymentKind = deployment.type;

    const loadDirectTools = async () => {
      try {
        const tools = await client.listAppTools(deploymentId, kind);
        setDirectTools(
          tools.map(({ resourceUri, toolName }) => ({
            toolsetId: deploymentId,
            resourceUri,
            toolName,
            mcpToolName: toolName,
            kind,
            discovery: 'direct',
          })),
        );
      } catch {
        setDirectTools([]);
      }
    };
    void loadDirectTools();
  }, [deployment?.id, deployment?.type, deployment?.features?.mcp, client]);

  const toolCallNames = useMemo(
    () => collectToolCallNames(messages),
    [messages],
  );

  useEffect(() => {
    if (toolCallNames.size === 0) return;

    const candidateToolsets = toolsets.filter((toolset) => {
      if (fetchedToolsetIdsRef.current.has(toolset.id)) return false;
      const prefix = `${toolset.displayName ?? toolset.id}_`;
      return [...toolCallNames].some((name) => name.startsWith(prefix));
    });
    if (candidateToolsets.length === 0) return;

    for (const toolset of candidateToolsets) {
      fetchedToolsetIdsRef.current.add(toolset.id);
    }

    const loadIndirectTools = async () => {
      const results = await Promise.all(
        candidateToolsets.map(async (toolset) => {
          try {
            const tools = await client.listAppTools(toolset.id, 'toolset');
            return tools.map(({ resourceUri, toolName }) => ({
              toolsetId: toolset.id,
              resourceUri,
              toolName: `${toolset.displayName ?? toolset.id}_${toolName}`,
              mcpToolName: toolName,
              kind: 'toolset' as McpDeploymentKind,
              discovery: 'indirect' as const,
            }));
          } catch {
            return [];
          }
        }),
      );
      setIndirectTools((prev) => [...prev, ...results.flat()]);
    };
    void loadIndirectTools();
  }, [toolCallNames, toolsets, client]);

  return [...directTools, ...indirectTools];
}

export interface McpAppHostContextParams {
  /** Host's current theme id (e.g. `'light'`/`'dark'`), used when `mcpAppTheme` is unset. */
  theme: string;
  /** Operator-configured MCP App theme override, if any. */
  mcpAppTheme?: string;
  /** Host's current i18n locale (BCP 47). */
  locale: string;
  /** Operator-configured MCP App user-agent override. Defaults to the browser's own `navigator.userAgent`. */
  mcpAppUserAgent?: string;
  /**
   * Display modes the host can switch an app between via
   * `ui/request-display-mode`. Defaults to `['inline', 'fullscreen']` — the
   * compact inline preview and the full-width canvas.
   */
  availableDisplayModes?: McpAppDisplayMode[];
}

useMcpAppHostAdapter = (
  displayMode: 'inline' | 'fullscreen',
  client: McpAppsApiClient,
  sandboxUrl: string | null,
  hostContextParams: McpAppHostContextParams,
  hostInfo: Implementation,
): McpAppHostAdapter => {
  const hostContext = useMcpAppHostContext(displayMode, hostContextParams);

  const callTool = useMemo<CallMcpAppTool>(
    () => async (toolsetId, toolName, args, kind) => {
      try {
        return await client.callTool(toolsetId, toolName, args, kind);
      } catch (error) {
        throw new Error(
          (await getApiErrorMessage(error)) ?? `Tool call "${toolName}" failed`,
        );
      }
    },
    [client],
  );

  return useMemo(
    () => ({
      hostContext,
      hostInfo,
      sandboxUrl,
      fetchResourceHtml: client.fetchResourceHtml,
      callTool,
    }),
    [hostContext, hostInfo, sandboxUrl, client.fetchResourceHtml, callTool],
  );
}

useOpenMcpAppCanvas = (
  cache: McpAppResponseCache,
  hostAdapter: McpAppHostAdapter,
  labels: UseOpenMcpAppCanvasLabels,
  onBeforeOpen?: () => void,
) => {
  const { openCanvas, openCanvasLoading, closeCanvas } = useAttachmentCanvas();
  const { hostContext, hostInfo, sandboxUrl, fetchResourceHtml, callTool } =
    hostAdapter;

  /*
   * An app mounted in the full-width canvas can ask to go back inline via
   * `ui/request-display-mode` — answered by closing the canvas, which
   * restores the message's inline preview (both surfaces share `cache`, so
   * the app remounts without re-fetching). Any other mode request keeps the
   * canvas. Declared before `openMcpAppCanvas` so its closure can reference
   * it without a ref.
   */
  const handleRequestDisplayMode = useCallback(
    (mode: McpAppDisplayMode): McpAppDisplayMode => {
      if (mode === 'inline') {
        closeCanvas();
        return 'inline';
      }
      return 'fullscreen';
    },
    [closeCanvas],
  );

  /*
   * `onReload` below needs to re-invoke `openMcpAppCanvas` recursively, but
   * referencing it directly from inside its own `useCallback` initializer is
   * a temporal-dead-zone access (`openMcpAppCanvas` isn't declared yet at
   * that point). Routed through a ref, updated after every render in the
   * effect below, and read only from `onReload`'s event-handler closure
   * (never during render) so the "latest" version is always called.
   */
  const openMcpAppCanvasRef = useRef<
    | ((
        match: McpAppToolRef,
        canvasKey?: string,
        toolCall?: McpAppToolCallSeed,
        forceReload?: boolean,
      ) => Promise<boolean>)
    | null
  >(null);

  const openMcpAppCanvas = useCallback(
    async (
      match: McpAppToolRef,
      canvasKey?: string,
      toolCall?: McpAppToolCallSeed,
      forceReload = false,
    ): Promise<boolean> => {
      if (sandboxUrl == null) {
        return false;
      }

      onBeforeOpen?.();
      openCanvasLoading(match.mcpToolName, canvasKey);

      try {
        const seedKey = computeMcpAppSeedKey(toolCall);
        const fetchFresh = async (): Promise<{
          html: string;
          toolResult: CallToolResult | undefined;
        }> => {
          const [html, toolResult] = await Promise.all([
            fetchResourceHtml(match.toolsetId, match.resourceUri),
            resolveMcpAppToolResult(match, toolCall, callTool),
          ]);
          return { html, toolResult };
        };

        let html: string;
        let toolResult: CallToolResult | undefined;
        if (canvasKey != null && !forceReload) {
          /*
           * `getOrFetch` coalesces this with a concurrent in-flight fetch for
           * the same message — e.g. the inline preview is still loading when
           * the user expands to the canvas — instead of racing a second,
           * redundant fetch/live tool re-call.
           */
          ({ html, toolResult } = await cache.getOrFetch(
            canvasKey,
            seedKey,
            fetchFresh,
          ));
        } else {
          ({ html, toolResult } = await fetchFresh());
          if (canvasKey != null) {
            cache.set(canvasKey, { html, toolResult }, seedKey);
          }
        }

        openCanvas(
          {
            type: AttachmentContentType.McpApp,
            html,
            sandboxUrl,
            toolInput: toolCall?.toolInput,
            toolResult,
            hostContext,
            hostInfo,
            onToolCall: (name, args) =>
              callTool(match.toolsetId, name, args, match.kind),
            onRequestDisplayMode: handleRequestDisplayMode,
            onReload: () => {
              if (canvasKey != null) cache.invalidate(canvasKey);
              void openMcpAppCanvasRef.current?.(
                match,
                canvasKey,
                toolCall,
                true,
              );
            },
          },
          match.mcpToolName,
          canvasKey,
        );
        return true;
      } catch (error) {
        const isForbidden =
          error instanceof McpAppResourceFetchError && error.status === 403;
        openCanvas(
          {
            type: AttachmentContentType.Error,
            errorType: isForbidden
              ? AttachmentErrorType.Forbidden
              : AttachmentErrorType.LoadFailed,
            label: isForbidden
              ? labels.forbiddenErrorLabel
              : labels.loadErrorLabel,
          },
          match.mcpToolName,
          canvasKey,
        );
        return false;
      }
    },
    [
      openCanvas,
      openCanvasLoading,
      onBeforeOpen,
      sandboxUrl,
      hostContext,
      hostInfo,
      fetchResourceHtml,
      callTool,
      cache,
      labels,
      handleRequestDisplayMode,
    ],
  );

  useEffect(() => {
    openMcpAppCanvasRef.current = openMcpAppCanvas;
  }, [openMcpAppCanvas]);

  return { openMcpAppCanvas };
}

export interface UseOpenMcpAppCanvasLabels {
  /** Error label shown when the resource fetch is forbidden (HTTP 403). */
  forbiddenErrorLabel: string;
  /** Error label shown for any other resource-load/tool-call failure. */
  loadErrorLabel: string;
}

export interface UseGridEditingScrollOptions {
  /** Picks the row to scroll to among the rows newly added since the last `rowDataUpdated`. Defaults to the first row flagged `isTemporary`, or the first new row. */
  resolveTargetNode?: (
    newNodes: IRowNode<FileManagerGridRow>[],
  ) => IRowNode<FileManagerGridRow> | null;
}

export interface UseGridEditingScrollResult {
  /** Pass to `DialFileManager`'s `onGridApiChange` prop. */
  handleGridApiChange: (api: GridApi<FileManagerGridRow>) => void;
  /** Re-seeds the known-row-id set without scrolling — call on a data-source change such as a tab switch. */
  reset: () => void;
}

useGridEditingScroll = ({
  resolveTargetNode = defaultResolveTargetNode,
}: UseGridEditingScrollOptions = {}): UseGridEditingScrollResult => {
  const knownRowIdsRef = useRef<Set<string>>(new Set());
  const knownRowIdsInitializedRef = useRef(false);
  const subscribedApiRef = useRef<GridApi<FileManagerGridRow> | null>(null);

  const reset = useCallback(() => {
    knownRowIdsRef.current = new Set();
    knownRowIdsInitializedRef.current = false;
  }, []);

  const handleCellEditingStarted = useCallback(
    (event: CellEditingStartedEvent<FileManagerGridRow>) => {
      const { api } = event;
      if (!api.isDestroyed() && event.rowIndex != null) {
        api.ensureIndexVisible(event.rowIndex);
      }
    },
    [],
  );

  const handleRowDataUpdated = useCallback(
    (event: RowDataUpdatedEvent<FileManagerGridRow>) => {
      const { api } = event;
      const currentIds = new Set<string>();
      const newNodes: IRowNode<FileManagerGridRow>[] = [];

      api.forEachNode((node) => {
        const id = node.data?.id;
        if (!id) return;
        currentIds.add(id);
        if (
          knownRowIdsInitializedRef.current &&
          !knownRowIdsRef.current.has(id)
        ) {
          newNodes.push(node);
        }
      });

      knownRowIdsRef.current = currentIds;
      knownRowIdsInitializedRef.current = true;

      const targetNode = resolveTargetNode(newNodes);
      if (targetNode) {
        scrollRowIntoView(api, targetNode);
      }
    },
    [resolveTargetNode],
  );

  const handleGridApiChange = useCallback(
    (api: GridApi<FileManagerGridRow>) => {
      const previousApi = subscribedApiRef.current;
      if (previousApi === api) return;

      if (previousApi != null) {
        previousApi.removeEventListener(
          'cellEditingStarted',
          handleCellEditingStarted,
        );
        previousApi.removeEventListener('rowDataUpdated', handleRowDataUpdated);
      }

      api.addEventListener('cellEditingStarted', handleCellEditingStarted);
      api.addEventListener('rowDataUpdated', handleRowDataUpdated);
      subscribedApiRef.current = api;
    },
    [handleCellEditingStarted, handleRowDataUpdated],
  );

  useEffect(() => {
    return () => {
      const api = subscribedApiRef.current;
      if (api != null && !api.isDestroyed()) {
        api.removeEventListener('cellEditingStarted', handleCellEditingStarted);
        api.removeEventListener('rowDataUpdated', handleRowDataUpdated);
      }
      subscribedApiRef.current = null;
    };
  }, [handleCellEditingStarted, handleRowDataUpdated]);

  return { handleGridApiChange, reset };
}

export interface ApiErrorDetails {
  /** HTTP status code carried by the error, when available. */
  status?: number;
  /** Resolved human-readable error message, or `null` when none could be resolved. */
  message: string | null;
  /** Extracted W3C trace ID, when the error's response carries a valid `traceparent`. */
  traceId?: string;
}

isConversationNotFoundError = (error: unknown): boolean => {
  const response = getErrorResponse(error);
  if (!response?.status) return false;
  return response.status === 404;
}

getApiErrorMessage = async (
  error: unknown,
): Promise<string | null> => {
  const response = getErrorResponse(error);
  if (response) {
    try {
      const body = await response.json();
      const message = resolveMessageFromBody(body);
      if (message !== null) return message;
    } catch {
      return null;
    }
  }

  if (error instanceof Error && error.message) return error.message;

  return null;
}

getApiErrorDetails = async (
  error: unknown,
): Promise<ApiErrorDetails> => {
  const response = getErrorResponse(error);
  const status = response?.status;

  let message: string | null = null;
  let bodyTraceId: string | undefined;
  let jsonBodyFailed = false;

  if (response) {
    try {
      const responseForBody =
        typeof response.clone === 'function' ? response.clone() : response;
      const body = await responseForBody.json();
      message = resolveMessageFromBody(body);
      if (isRecord(body)) {
        bodyTraceId = extractTraceId(body.traceparent);
      }
    } catch {
      jsonBodyFailed = true;
    }
  }

  if (
    !jsonBodyFailed &&
    message === null &&
    error instanceof Error &&
    error.message
  ) {
    message = error.message;
  }

  const traceId =
    bodyTraceId ??
    extractTraceId(
      typeof response?.headers?.get === 'function'
        ? response.headers.get('traceparent')
        : undefined,
    );

  return { status, message, traceId };
}

export interface CreateCsrfMiddlewareDeps {
  /** Returns the currently held CSRF token, or `null` when none is set. */
  getCsrfToken: () => string | null;
  /** Stores a CSRF token captured from a response header, or `null` to clear it. */
  setCsrfToken: (token: string | null) => void;
}

createCsrfMiddleware = (
  deps: CreateCsrfMiddlewareDeps,
): Middleware => ({
  pre: async (context) => {
    const token = deps.getCsrfToken();
    if (context.init.method === 'GET' || token === null) {
      return context;
    }
    const headers = new Headers(context.init.headers);
    headers.set('X-CSRF-Token', token);
    return {
      ...context,
      init: {
        ...context.init,
        headers,
      },
    };
  },
  post: async (context) => {
    const rotated = context.response.headers.get('x-csrf-token');
    if (rotated) deps.setCsrfToken(rotated);
    return context.response;
  },
})

export interface UnauthorizedErrorLike extends Error {
  readonly status: 401;
  readonly url: string;
}

export interface CreateUnauthorizedMiddlewareDeps {
  /** Notifies the host that a request was unauthorized (also expected to clear any held CSRF token). */
  notifyUnauthorized: (url: string) => void;
  /** Attempts to refresh the CSRF token, de-duplicating concurrent calls. */
  refreshCsrfToken: () => Promise<CsrfRefreshOutcome>;
  /** Classifies a response body as an invalid-CSRF error. */
  isInvalidCsrfErrorBody: (body: string) => boolean;
  /** Returns the currently held CSRF token, or `null` when none is set. */
  getCsrfToken: () => string | null;
  /**
   * Stores a CSRF token captured from a response header. Needed here (in
   * addition to the CSRF middleware's own `post` hook) because the
   * invalid-CSRF retry issues its own `fetch` outside the generated-client
   * middleware pipeline, so its response header is never seen by that hook.
   */
  setCsrfToken: (token: string | null) => void;
  /** Constructs the error thrown to signal an unauthorized request. */
  createUnauthorizedError: (url: string) => UnauthorizedErrorLike;
}

createUnauthorizedMiddleware = (
  deps: CreateUnauthorizedMiddlewareDeps,
): Middleware => {
  const retryWithFreshCsrf = async (
    context: MiddlewarePostContext,
  ): Promise<Response> => {
    const dispatchToken = getDispatchCsrfToken(context.init);
    const currentToken = deps.getCsrfToken();

    if (currentToken !== null && currentToken !== dispatchToken) {
      // A concurrent request already refreshed the token; reuse it.
      return fetchWithCsrfToken(context, currentToken);
    }

    const refreshed = await deps.refreshCsrfToken();
    if (refreshed.status === 'unauthorized') {
      deps.notifyUnauthorized(context.url);
      throw deps.createUnauthorizedError(context.url);
    }
    if (refreshed.status !== 'ok') {
      throw new Error(`CSRF refresh failed for ${context.url}`);
    }

    return fetchWithCsrfToken(context, refreshed.token);
  };

  const handleRetryResponse = async (
    context: MiddlewarePostContext,
    response: Response,
  ): Promise<Response> => {
    const rotated = response.headers.get('x-csrf-token');
    if (rotated) {
      deps.setCsrfToken(rotated);
    }

    if (response.status === 401) {
      deps.notifyUnauthorized(context.url);
      throw deps.createUnauthorizedError(context.url);
    }

    if (!response.ok) {
      const errorBody = await readResponseBody(response);
      if (response.status === 403 && deps.isInvalidCsrfErrorBody(errorBody)) {
        deps.notifyUnauthorized(context.url);
        throw deps.createUnauthorizedError(context.url);
      }
      throw new Error(
        `Request failed with status ${response.status} for ${context.init.method ?? 'GET'} ${context.url}: ${errorBody}`,
      );
    }

    return response;
  };

  return {
    post: async (context) => {
      if (context.response.status === 401) {
        deps.notifyUnauthorized(context.url);
        throw deps.createUnauthorizedError(context.url);
      }
      if (context.response.status === 403) {
        const body = await readResponseBody(context.response);
        if (deps.isInvalidCsrfErrorBody(body)) {
          const retryResponse = await retryWithFreshCsrf(context);
          return handleRetryResponse(context, retryResponse);
        }
      }
      return context.response;
    },
  };
}

export interface UseAttachmentActionParams {
  /** Resolves a DIAL Core file id to a downloadable URL. */
  resolveDownloadUrl: ResolveDownloadUrl;
}

export interface UseAttachmentActionResult {
  /** Default click handler for an attachment tile: download, canvas-preview, or open-in-browser. */
  handleAttachmentClick: (attachment: DisplayAttachment) => void;
}

downloadAttachment = (
  attachment: DisplayAttachment,
  resolveDownloadUrl: ResolveDownloadUrl,
): boolean => {
  const { url, name, contentType, data } = attachment;

  if (url != null && isDialFileId(url)) {
    const downloadUrl = resolveDownloadUrl(url);
    if (downloadUrl == null) return false;

    triggerAnchorDownload(
      downloadUrl,
      ensureDownloadFilename(name, url, contentType),
    );
    return true;
  }

  /* Generated attachments (e.g. a produced .md report) can arrive inline in
   * `data` rather than as a DIAL file, in which case there is no download URL
   * to resolve — build the blob locally instead. */
  if (data != null) {
    triggerBlobDownload(
      base64ToBlob(data, contentType || MIMEType.Plain),
      ensureDownloadFilename(name, url, contentType),
    );
    return true;
  }

  return false;
}

useAttachmentAction = ({
  resolveDownloadUrl,
}: UseAttachmentActionParams): UseAttachmentActionResult => {
  const { openCanvas } = useAttachmentCanvas();

  const handleAttachmentClick = useCallback(
    (attachment: DisplayAttachment): void => {
      const { url, referenceUrl, data, name } = attachment;

      if (url != null || data != null) {
        downloadAttachment(attachment, resolveDownloadUrl);
        return;
      }

      if (referenceUrl == null) return;

      const resource: AttachmentResource = {
        type: attachment.contentType,
        url: referenceUrl,
        title: name,
      };

      const canvasContent = referenceAttachmentToPdfCanvasContent(
        resource,
        resolveDownloadUrl,
      );
      if (canvasContent) {
        openCanvas(canvasContent, name);
        return;
      }

      openAnnotationAttachment(resource, resolveDownloadUrl);
    },
    [openCanvas, resolveDownloadUrl],
  );

  return { handleAttachmentClick };
}

export enum AttachmentValidationErrorReason {
  /** No MIME types are allowed at all — attachments are disabled entirely. */
  NoTypesAllowed = 'noTypesAllowed',
  /** The attachment's content type is not among the allowed MIME types. */
  UnsupportedType = 'unsupportedType',
  /** The attachment's file size exceeds `maxFileSizeBytes`. */
  FileTooLarge = 'fileTooLarge',
}

export interface AttachmentValidationErrorEvent {
  /** Why the attachment(s) were rejected. */
  reason: AttachmentValidationErrorReason;
  /** The resolved MIME types the caller currently allows (possibly empty). Present only when `reason` is `NoTypesAllowed` or `UnsupportedType`. */
  allowedMimeTypes?: string[];
  /** Already-formatted, non-translated extension list (e.g. ".png, .jpg"), present only when `reason` is `UnsupportedType`. */
  formats?: string;
  /** The size limit, in bytes, that was exceeded. Present only when `reason` is `FileTooLarge`. */
  maxFileSizeBytes?: number;
}

export interface UseAttachmentValidationParams {
  /** Resolved MIME types currently allowed for attachments. */
  allowedMimeTypes: string[];
  /** Maximum attachment file size, in bytes. When omitted, no file is rejected for size. */
  maxFileSizeBytes?: number;
  /** Called with a structured event when a rejected attachment is reported, at most once per debounce window. */
  onValidationError?: (event: AttachmentValidationErrorEvent) => void;
  /** Debounce window, in ms, before firing `onValidationError` for a rejected file. Defaults to `100`. */
  debounceMs?: number;
}

export interface UseAttachmentValidationResult {
  /** The resolved MIME types currently allowed for attachments (echoes the `allowedMimeTypes` param). */
  inputAttachmentTypes: string[];
  /** Whether at least one MIME type is currently allowed. */
  isAttachmentsAllowed: boolean;
  /** Classifies an attachment as allowed (`undefined`) or rejected (`AttachmentErrorReason`). */
  validateAttachment: (
    attachment: Attachment,
  ) => AttachmentErrorReason | undefined;
  /** `<input accept>` string derived from `allowedMimeTypes`, or `undefined` when any type accepts everything. */
  fileAccept: string | undefined;
}

useAttachmentValidation = ({
  allowedMimeTypes,
  maxFileSizeBytes,
  onValidationError,
  debounceMs = DEFAULT_UNSUPPORTED_TYPE_DEBOUNCE_MS,
}: UseAttachmentValidationParams): UseAttachmentValidationResult => {
  // Content-stable per chat-hooks-attachment-validation spec.
  const stableMimeTypesRef = useRef<string[]>(allowedMimeTypes);
  if (
    stableMimeTypesRef.current.length !== allowedMimeTypes.length ||
    stableMimeTypesRef.current.some(
      (mimeType, index) => mimeType !== allowedMimeTypes[index],
    )
  ) {
    stableMimeTypesRef.current = allowedMimeTypes;
  }
  const stableAllowedMimeTypes = stableMimeTypesRef.current;

  const isAttachmentsAllowed = stableAllowedMimeTypes.length > 0;

  const fileAccept = useMemo(
    () => mimeTypesToFileAccept(stableAllowedMimeTypes),
    [stableAllowedMimeTypes],
  );

  const unsupportedTypeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(
    null,
  );
  const fileTooLargeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(
    null,
  );

  useEffect(
    () => () => {
      if (unsupportedTypeTimerRef.current != null) {
        clearTimeout(unsupportedTypeTimerRef.current);
      }
      if (fileTooLargeTimerRef.current != null) {
        clearTimeout(fileTooLargeTimerRef.current);
      }
    },
    [],
  );

  const validateAttachment = useCallback(
    (attachment: Attachment): AttachmentErrorReason | undefined => {
      if (!isMimeTypeAllowed(attachment.contentType, stableAllowedMimeTypes)) {
        if (unsupportedTypeTimerRef.current != null) {
          clearTimeout(unsupportedTypeTimerRef.current);
        }
        unsupportedTypeTimerRef.current = setTimeout(() => {
          const noTypesAllowed = stableAllowedMimeTypes.length === 0;
          onValidationError?.({
            reason: noTypesAllowed
              ? AttachmentValidationErrorReason.NoTypesAllowed
              : AttachmentValidationErrorReason.UnsupportedType,
            allowedMimeTypes: stableAllowedMimeTypes,
            ...(noTypesAllowed
              ? {}
              : {
                  formats: mimeTypesToExtensionLabels(stableAllowedMimeTypes),
                }),
          });
          unsupportedTypeTimerRef.current = null;
        }, debounceMs);
        return AttachmentErrorReason.UnsupportedType;
      }

      if (maxFileSizeBytes != null && attachment.file.size > maxFileSizeBytes) {
        if (fileTooLargeTimerRef.current != null) {
          clearTimeout(fileTooLargeTimerRef.current);
        }
        fileTooLargeTimerRef.current = setTimeout(() => {
          onValidationError?.({
            reason: AttachmentValidationErrorReason.FileTooLarge,
            maxFileSizeBytes,
          });
          fileTooLargeTimerRef.current = null;
        }, debounceMs);
        return AttachmentErrorReason.FileTooLarge;
      }

      return undefined;
    },
    [stableAllowedMimeTypes, maxFileSizeBytes, debounceMs, onValidationError],
  );

  return {
    inputAttachmentTypes: stableAllowedMimeTypes,
    isAttachmentsAllowed,
    validateAttachment,
    fileAccept,
  };
}

toPublishRuleDto = (rule: PublicationRule): PublishRuleDto => ({
  source: rule.source,
  targets: rule.targets,
  function: rule.function as unknown as PublishRuleDto['function'],
})

export interface PublishApiClient {
  /** Submits a publication request for one catalog entity into `folderPath`. */
  publishCatalogEntity: (
    entityType: CatalogPublishEntityType,
    entityId: string,
    body: PublishCatalogEntityDto,
  ) => Promise<PublishResultDto>;
  /**
   * Submits a removal request for one already-published folder of a catalog
   * entity. The removal takes effect only after an administrator approves it,
   * so callers must report a pending request rather than a completed removal.
   */
  unpublishCatalogEntity: (
    entityType: CatalogPublishEntityType,
    entityId: string,
    body: UnpublishCatalogEntityDto,
  ) => Promise<UnpublishResultDto>;
  /** Reads the folders one catalog entity is already published to. */
  getCatalogPublishHistory: (
    entityType: CatalogPublishEntityType,
    entityId: string,
  ) => Promise<PublishHistoryEntryDto[]>;
  /** Reads a destination folder's already-configured access rules. */
  getPublishRules: (folderPath: string) => Promise<PublicationRule[]>;
}

createPublishApiClient = (
  publishApi: PublishApi,
): PublishApiClient => ({
  publishCatalogEntity: (entityType, entityId, body) =>
    publishApi.publishCatalogEntity({
      entityType,
      entityId,
      publishCatalogEntityDto: body,
    }),
  unpublishCatalogEntity: (entityType, entityId, body) =>
    publishApi.unpublishCatalogEntity({
      entityType,
      entityId,
      unpublishCatalogEntityDto: body,
    }),
  getCatalogPublishHistory: (entityType, entityId) =>
    publishApi.getCatalogPublishHistory({ entityType, entityId }),
  getPublishRules: async (folderPath) => {
    const response = await publishApi.getPublishRules({ folderPath });
    return response.rules.map(({ function: ruleFunction, ...rule }) => ({
      ...rule,
      function: ruleFunction as unknown as PublicationRuleFunction,
    }));
  },
})

export interface DeploymentGenerationApiSupport {
  hasChatCompletion?: boolean;
  hasResponsesApi?: boolean;
}

buildDeploymentConnectApi = (
  baseUrl: string,
  id: string,
  { hasChatCompletion, hasResponsesApi }: DeploymentGenerationApiSupport,
): CatalogItemApiDetails | undefined => {
  const endpoints: EndpointOption[] = [];

  if (hasChatCompletion) {
    const url = buildChatCompletionsUrl(baseUrl, id);
    endpoints.push({
      label: 'Chat Completions',
      url,
      snippets: [
        {
          language: CodeLanguage.Curl,
          code: `curl -X POST '${url}?api-version=<api-version>' \\\n  -H 'Content-Type: application/json' \\\n  -H 'Api-Key: <key>' \\\n  -d '{"messages":[{"role":"user","content":"Hello"}]}'`,
        },
      ],
    });
  }

  if (hasResponsesApi) {
    const url = buildResponsesUrl(baseUrl);
    endpoints.push({
      label: 'Responses',
      url,
      snippets: [
        {
          language: CodeLanguage.Curl,
          code: `curl -X POST '${url}' \\\n  -H 'Content-Type: application/json' \\\n  -H 'Api-Key: <key>' \\\n  -d '{"model":"${id}","input":"Hello"}'`,
        },
      ],
    });
  }

  if (endpoints.length === 0) return undefined;

  return {
    resource: { modelId: decodeDeploymentPathForDisplay(id) },
    endpoints,
  };
}

findDeploymentByIdOrReference = (
  deployments: DeploymentItemDto[],
  idOrReference: string | null | undefined,
): DeploymentItemDto | undefined => {
  if (!idOrReference) return undefined;
  return (
    deployments.find((deployment) => deployment.id === idOrReference) ??
    deployments.find((deployment) => deployment.reference === idOrReference)
  );
}

