export interface DeploymentLimitsLabels {
  /** Heading of the group every token stat row is listed under. */
  tokenGroup: string;
  /** Label for the tokens-per-day stat row. */
  tokensPerDay: string;
  /** Label for the tokens-per-week stat row. */
  tokensPerWeek: string;
  /** Label for the tokens-per-month stat row. */
  tokensPerMonth: string;
  /** Note shown instead of a total on a row whose limit follows the cost limit. */
  followsCostLimit: string;
  /** Formats the "$X spent" caption under a row's label. */
  formatSpentCaption: (amount: string) => string;
  /** Formats the combined used/total display value for a capped row. */
  formatValueLabel: (used: string, total: string) => string;
  /** Formats the ARIA label for a capped progress row. */
  formatProgressAriaLabel: (params: {
    label: string;
    used: string;
    total: string;
  }) => string;
  /** Formats the ARIA label for an unlimited row, which has no total to announce. */
  formatFollowsCostLimitAriaLabel: (params: {
    label: string;
    used: string;
  }) => string;
}

mapDeploymentLimitsDtoToCatalogLimits = (
  dto: DeploymentLimitsResponseDto | undefined,
  labels: DeploymentLimitsLabels,
): CatalogItemLimits | undefined => {
  if (dto == null) {
    return undefined;
  }

  const usableStats: LimitStatsDto[] = [];
  const rows = LIMIT_STAT_MAPPINGS.flatMap((mapping) => {
    const stats = dto[mapping.key];
    if (!isUsableLimitStats(stats)) {
      return [];
    }

    usableStats.push(stats);
    const captionLabel = buildSpentCaption(dto[mapping.costKey], labels);
    return [
      mapLimitStatsToRow(
        stats,
        labels[mapping.labelField],
        captionLabel,
        labels,
      ),
    ];
  });

  return rows.length > 0
    ? {
        groups: [{ label: labels.tokenGroup, rows }],
        status: getOverallStatus(usableStats),
      }
    : undefined;
}

export interface MonthlyUsageLimit {
  /** Normalized used-token count. */
  used: number;
  /** Configured monthly token limit. */
  total: number;
  /** Remaining monthly tokens, clamped to zero. */
  remaining: number;
  /** Monthly utilization percentage, clamped to 0–100. */
  usedPercent: number;
}

mapDeploymentLimitsToInput = (
  dto: DeploymentLimitsResponseDto | undefined,
): MonthlyUsageLimit | undefined => {
  const stats = dto?.monthTokenStats;

  if (
    stats == null ||
    !Number.isFinite(stats.total) ||
    !Number.isFinite(stats.used) ||
    stats.total <= 0 ||
    stats.total >= Number.MAX_SAFE_INTEGER
  ) {
    return undefined;
  }

  const used = Math.max(0, stats.used);

  return {
    used,
    total: stats.total,
    remaining: Math.max(0, stats.total - used),
    usedPercent: Math.min(100, Math.round((used / stats.total) * 100)),
  };
}

mapDeploymentToolsetCredentials = (
  toolsetId: string,
  authSettings: DialToolsetAuthSettingsDto | undefined,
  isAdmin: boolean,
): CatalogItemCredentials | undefined => {
  if (authSettings == null) return undefined;

  const isPublic = isPublicToolsetId(toolsetId);
  const userStatus = authSettings.userLevelAuthStatus
    ? AUTH_STATUS_MAP[authSettings.userLevelAuthStatus]
    : undefined;
  const globalStatus = authSettings.globalAuthStatus
    ? AUTH_STATUS_MAP[authSettings.globalAuthStatus]
    : undefined;

  const isCoveredByGlobalAuth =
    !isAdmin &&
    isPublic &&
    userStatus !== CredentialStatus.SignedIn &&
    globalStatus === CredentialStatus.SignedIn;
  const authenticationType = isCoveredByGlobalAuth
    ? ToolsetAuthenticationType.None
    : AUTHENTICATION_TYPE_MAP[authSettings.authenticationType];

  return {
    authenticationType,
    userStatus,
    globalStatus,
    isPublic,
    isManageableByAdmin: isAdmin && isPublic,
    apiKeyHeader: authSettings.apiKeyHeader,
  };
}

export interface DeploymentFolderLabels {
  personal: string;
  shared: string;
  public: string;
}

resolveDeploymentFolder = (
  deployment: Pick<
    DeploymentItemDto,
    'isMy' | 'sharedWithMe' | 'applicationFolder'
  > &
    Partial<Pick<DeploymentItemDto, 'type'>>,
  labels: DeploymentFolderLabels,
): string[] => {
  if (deployment.isMy) {
    return [labels.personal];
  }

  const segments = stripPrefixSegments(
    deployment.applicationFolder ?? '',
    APPLICATIONS_PREFIX,
  );

  if (deployment.sharedWithMe) {
    return [labels.shared, ...segments.slice(1)];
  }

  /* Configured applications with plain IDs have no applicationFolder. */
  if (
    segments.length === 0 &&
    deployment.type?.toLowerCase() === 'application'
  ) {
    return [labels.public];
  }

  if (segments[0]?.toLowerCase() === PUBLIC_SEGMENT) {
    return [labels.public, ...segments.slice(1)];
  }

  return segments;
}

