export interface MapToolsetToCatalogItemOptions {
  favoriteIds?: ReadonlySet<string>;
  isAdmin?: boolean;
  folderLabels?: DeploymentFolderLabels;
  /** The viewer's active display locale, used to resolve `displayName`/`description`. */
  activeLocale: string;
  /** The fixed content language `displayName`/`description` fall back to when `activeLocale` has no entry. */
  primaryLocale: string;
  /** Resolves a toolset's raw `iconUrl` to a displayable URL. Host-owned. */
  resolveIconUrl: (iconUrl: string | undefined) => string | undefined;
}

mapToolsetToCatalogItem = (
  toolset: DialToolsetDto,
  {
    favoriteIds = new Set(),
    isAdmin = false,
    folderLabels,
    activeLocale,
    primaryLocale,
    resolveIconUrl,
  }: MapToolsetToCatalogItemOptions,
): CatalogItem => {
  const name =
    resolveLocalizedText(toolset.displayName, activeLocale, primaryLocale) ||
    toolset.toolset ||
    toolset.reference ||
    toolset.id;
  const allowedTools = toolset.allowedTools ?? [];

  return {
    id: toolset.id,
    type: CatalogEntityType.Toolset,
    name,
    description: resolveLocalizedText(
      toolset.description,
      activeLocale,
      primaryLocale,
    ),
    iconUrl: resolveIconUrl(toolset.iconUrl),
    version: toolset.displayVersion ?? '',
    lastUsed: formatLastUsed(toolset.updatedAt),
    updatedAt: toolset.updatedAt,
    createdAt: toolset.createdAt,
    isFeatured: false,
    isHidden: false,
    topics: toolset.descriptionKeywords ?? [],
    isUserFavorite: favoriteIds.has(toolset.id),
    isStarred: favoriteIds.has(toolset.id),
    isMyApp: toolset.isMy ?? false,
    sharedWithMe: toolset.sharedWithMe ?? false,
    isEditable: !!(toolset.isMy || toolset.canEdit),
    folder: resolveToolsetFolder(toolset, folderLabels),
    credentials: mapDeploymentToolsetCredentials(
      toolset.id,
      toolset.authSettings,
      isAdmin,
    ),
    details:
      allowedTools.length > 0
        ? {
            tools: {
              tools: allowedTools.map((tool) => ({ name: tool })),
            },
          }
        : undefined,
  };
}

mapToolsetCredentials = (
  toolsetId: string,
  data: ToolsetEntityDetails,
  isAdmin: boolean,
): CatalogItemCredentials | undefined => {
  const authenticationType =
    TOOLSET_AUTHENTICATION_TYPE_MAP[
      data.specification?.authentication ?? AuthenticationType.None
    ];
  if (authenticationType == null) return undefined;

  const { userLevel, global } = data.specification?.authStatus ?? {};
  const isPublic = isPublicToolsetId(toolsetId);
  const userStatus = userLevel ? TOOLSET_AUTH_STATUS_MAP[userLevel] : undefined;
  const globalStatus = global ? TOOLSET_AUTH_STATUS_MAP[global] : undefined;

  return {
    authenticationType,
    userStatus,
    globalStatus,
    isPublic,
    isManageableByAdmin: isAdmin && isPublic,
    apiKeyHeader: data.specification?.authStatus?.apiKeyHeader,
  };
}

mapEntityDetailsToCatalogDetails = (
  details: EntitySpecificDetails,
): CatalogItemTabData => {
  switch (details.type) {
    case 'MODEL':
      return mapModelDetails(details.data);
    case 'AGENT':
      return mapAgentDetails(details.data);
    case 'TOOLSET':
      return mapToolsetDetails(details.data);
  }
}

mapDeploymentDetailsDtoToEntityDetails = (
  dto: DeploymentDetailsDto,
): EntitySpecificDetails => {
  switch (dto.type) {
    case 'model':
      return mapModelDetailsDto(dto);
    case 'application':
      return mapApplicationDetailsDto(dto);
    case 'toolset':
      return mapToolsetDetailsDto(dto);
  }
}

export interface PromptOverviewLabels {
  authorLabel: string;
  updatedLabel: string;
  sectionTitle: string;
}

buildPromptOverview = (
  prompt: PromptResponseDto,
  labels: PromptOverviewLabels,
): CatalogItemOverview => {
  const specs: OverviewSpec[] = [];

  /* DIAL Core omits the author on resources written before it tracked one. */
  if (prompt.author) {
    specs.push({ label: labels.authorLabel, value: prompt.author });
  }
  specs.push({
    label: labels.updatedLabel,
    value: formatCalendarDate(prompt.updatedAt),
  });

  return { sections: [{ title: labels.sectionTitle, specs }] };
}

export interface MapPromptToCatalogItemOptions {
  /** Personal/Shared/Public folder labels; i18n stays at the app edge. */
  folderLabels: DeploymentFolderLabels;
  /** Author/updated/section-title labels for the Overview tab; i18n stays at the app edge. */
  overviewLabels: PromptOverviewLabels;
  /** Namespace the prompt came from; drives ownership flags and the folder prefix. */
  source: PromptSource;
  /** Favorited resource ids from the user config, keyed by prompt path. */
  favoriteIds: ReadonlySet<string>;
}

mapPromptToCatalogItem = (
  prompt: PromptResponseDto,
  {
    folderLabels,
    overviewLabels,
    source,
    favoriteIds,
  }: MapPromptToCatalogItemOptions,
): CatalogItem => {
  const isPersonal = source === PromptSource.Personal;
  const id = prompt.id;
  const isFavorite = favoriteIds.has(id);

  return {
    id,
    type: CatalogEntityType.Prompt,
    name: prompt.name,
    description: prompt.description ?? '',
    /* Prompts are unversioned — the backend exposes no version field. */
    version: '',
    lastUsed: formatLastUsed(prompt.updatedAt),
    createdAt: prompt.createdAt,
    updatedAt: prompt.updatedAt,
    isFeatured: false,
    isHidden: false,
    /* The prompts API exposes no topics, so there is nothing to filter on. */
    topics: [],
    /* Favorites live in the user config's `prompts.installed`, keyed by path. */
    isUserFavorite: isFavorite,
    isStarred: isFavorite,
    isMyApp: prompt.isMy ?? isPersonal,
    sharedWithMe: prompt.sharedWithMe ?? source === PromptSource.SharedWithMe,
    isEditable:
      source !== PromptSource.Public && (prompt.canEdit ?? isPersonal),
    folder: resolvePromptFolder(prompt.folderId, source, folderLabels),
    /*
     * `listPrompts` already returns the body, so the details panel can render
     * both tabs before `onFetchDetails` settles; the fetch then refreshes them.
     */
    details: {
      ...(prompt.content
        ? { promptContent: { content: prompt.content } }
        : undefined),
      overview: buildPromptOverview(prompt, overviewLabels),
    },
  };
}

export interface MapSkillToCatalogItemOptions {
  /** Personal/Shared/Public folder labels; i18n stays at the app edge. */
  folderLabels: DeploymentFolderLabels;
  /** Namespace the skill came from; drives ownership flags and the folder prefix. */
  source: SkillSource;
  /** Favorited resource ids from the user config, keyed by skill resource URL. */
  favoriteIds: ReadonlySet<string>;
}

mapSkillToCatalogItem = (
  skill: SkillMetadataItemDto,
  { folderLabels, source, favoriteIds }: MapSkillToCatalogItemOptions,
): CatalogItem => {
  const isFavorite = favoriteIds.has(skill.url);
  const isPublic = source === SkillSource.Public;
  const isPersonal = source === SkillSource.Personal;

  return {
    id: skill.url,
    type: CatalogEntityType.Skill,
    name: skill.name,
    /*
     * Listing-sourced description (Core PR #1970); folders and older Cores
     * carry none, and the details fetch's manifest frontmatter stays
     * authoritative once it lands.
     */
    description: skill.description ?? '',
    /* Skills are unversioned — the metadata exposes no version field. */
    version: '',
    lastUsed: formatLastUsed(skill.updatedAt),
    createdAt: skill.createdAt,
    updatedAt: skill.updatedAt,
    isFeatured: false,
    isHidden: false,
    /* The skills API exposes no topics, so there is nothing to filter on. */
    topics: [],
    isUserFavorite: isFavorite,
    isStarred: isFavorite,
    /* Only the personal namespace can confer ownership; public/shared metadata is untrusted. */
    isMyApp: isPersonal && (skill.isMy ?? true),
    sharedWithMe: skill.sharedWithMe ?? source === SkillSource.SharedWithMe,
    isEditable: !isPublic && (skill.canEdit ?? isPersonal),
    folder: resolveSkillFolder(skill.parentPath, source, folderLabels),
  };
}

export interface SkillOverviewLabels {
  whenToUseLabel: string;
  allowedToolsLabel: string;
  bundledResourcesLabel: string;
  specificationSectionTitle: string;
  authorLabel: string;
  updatedLabel: string;
  fileCountLabel: string;
  detailsSectionTitle: string;
}

resolveSkillManifestFileId = (
  files: SkillMetadataItemDto[],
  skillPath: string,
): string => {
  const normalizedSkillPath = stripSurroundingSlashes(skillPath);
  const filesRoot = normalizedSkillPath
    ? `${normalizedSkillPath}/files`
    : 'files';
  const manifest = selectFileItems(files).find((file) => {
    const path = stripSurroundingSlashes(file.path);
    return (
      path === SKILL_MANIFEST_FILE ||
      path === `files/${SKILL_MANIFEST_FILE}` ||
      path === `${filesRoot}/${SKILL_MANIFEST_FILE}`
    );
  });

  return manifest?.path ?? SKILL_MANIFEST_FILE;
}

buildSkillOverview = (
  skill: SkillMetadataItemDto | undefined,
  files: SkillMetadataItemDto[],
  about: SkillAboutDetails | undefined,
  labels: SkillOverviewLabels,
): CatalogItemOverview => {
  const sections: OverviewSection[] = [];

  const specification = buildSpecificationSection(about, labels);
  if (specification != null) sections.push(specification);

  const specs: OverviewSpec[] = [];

  /* DIAL Core omits the author on resources written before it tracked one. */
  if (skill?.author) {
    specs.push({ label: labels.authorLabel, value: skill.author });
  }
  specs.push({
    label: labels.updatedLabel,
    value: skill?.updatedAt ? formatCalendarDate(skill.updatedAt) : '',
  });

  specs.push({
    label: labels.fileCountLabel,
    value: String(selectFileItems(files).length),
  });

  sections.push({ title: labels.detailsSectionTitle, specs });

  return { sections };
}

buildSkillContentTree = (
  files: SkillMetadataItemDto[],
  skillPath: string,
): CatalogContentTreeNode[] => {
  const folderNodesByPath = new Map<string, CatalogContentFolderNode>();
  const roots: CatalogContentTreeNode[] = [];

  for (const entry of files) {
    const displayPath = stripSkillPathPrefix(entry.path, skillPath);
    if (displayPath == null) continue;

    if (entry.nodeType === SkillMetadataItemDtoNodeTypeEnum.Folder) {
      getOrCreateFolderChain(displayPath, folderNodesByPath, roots);
      continue;
    }

    const lastSlash = displayPath.lastIndexOf('/');
    const parentPath = lastSlash === -1 ? '' : displayPath.slice(0, lastSlash);
    const parentItems = getOrCreateFolderChain(
      parentPath,
      folderNodesByPath,
      roots,
    );
    parentItems.push({
      type: CatalogContentNodeType.File,
      id: entry.path,
      name: entry.name,
    });
  }

  sortContentTree(roots, true);
  return roots;
}

readSkillFileBytes = async (
  response: Response,
): Promise<Uint8Array | null> => {
  const declaredLength = Number(response.headers.get('content-length'));
  if (
    Number.isFinite(declaredLength) &&
    declaredLength > SKILL_MANIFEST_MAX_BYTES
  ) {
    return null;
  }

  const buffer = await response.arrayBuffer();
  if (buffer.byteLength > SKILL_MANIFEST_MAX_BYTES) return null;

  return new Uint8Array(buffer);
}

readSkillFilePreviewBytes = async (
  response: Response,
): Promise<Uint8Array> => new Uint8Array(await response.arrayBuffer())

readSkillManifest = async (
  response: Response,
): Promise<string | null> => {
  const bytes = await readSkillFileBytes(response);
  if (bytes == null) return null;

  return new TextDecoder().decode(bytes);
}

export enum McpResourceKind {
  /** Toolsets, served under `/v1/toolset/{id}/mcp`. */
  Toolset = 'toolset',
  /** Application deployments, served under `/v1/deployments/{id}/mcp`. */
  Application = 'application',
}

resolveMcpResourceKind = (
  type: CatalogEntityType,
  supportsMcp?: boolean,
): McpResourceKind | null => {
  if (type === CatalogEntityType.Toolset) return McpResourceKind.Toolset;
  if (type === CatalogEntityType.Agent && supportsMcp === true) {
    return McpResourceKind.Application;
  }
  return null;
}

buildConnectApi = (
  baseUrl: string,
  id: string,
  kind: McpResourceKind,
): CatalogItemApiDetails => {
  const url = MCP_URL_BUILDERS[kind](baseUrl, id);
  return {
    resource: { endpointUrl: url },
    snippets: [
      {
        language: CodeLanguage.Curl,
        code: `curl -X POST ${url} \\\n  -H 'Content-Type: application/json' \\\n  -H 'Api-Key: <key>' \\\n  -d '{"jsonrpc":"2.0","id":1,"method":"tools/list"}'`,
      },
    ],
  };
}

toPublishEntityType = (
  type: CatalogEntityType,
): CatalogPublishEntityType | undefined => PUBLISHABLE_ENTITY_TYPES[type]

mapPublishHistoryEntryDto = (
  dto: PublishHistoryEntryDto,
): PublishHistoryEntry => ({
  version: dto.version,
  publishedAt: Date.parse(dto.publishedAt),
  folderPath: dto.folderPath.split('/').filter(Boolean),
  publishCredentials: dto.publishCredentials,
})

mapPublishConversationResultDto = (
  dto: PublishConversationResultDto,
): PublishHistoryEntry => ({
  /* A conversation carries no version, so any entry for a folder already means
   * "published here" — see `usePublishFlow`. */
  publishedAt: Date.parse(dto.publishedAt),
  folderPath: dto.folderPath.split('/').filter(Boolean),
})

deriveFavoriteItems = (
  items: readonly CatalogItem[],
): CatalogItem[] => items.filter((item) => item.isUserFavorite)

deriveAvailableTabIds = <T extends CatalogEntityType>(
  items: readonly CatalogItem[],
  tabOrder: readonly T[],
): T[] => {
  const presentTypes = new Set(items.map((item) => item.type));
  return tabOrder.filter((type) => presentTypes.has(type));
}

reconcileFilterTopics = (
  persistedTopics: ReadonlySet<string>,
  items: readonly CatalogItem[],
): Set<string> => {
  const availableTopics = new Set(items.flatMap((item) => item.topics));
  return new Set(
    Array.from(persistedTopics).filter((topic) => availableTopics.has(topic)),
  );
}

export enum CatalogPrimaryActionType {
  Deployment = 'deployment',
  Prompt = 'prompt',
}

export interface CatalogPrimaryActionDeployment {
  /** Discriminant. */
  kind: CatalogPrimaryActionType.Deployment;
  /** Deployment entity id. */
  id: string;
}

export interface CatalogPrimaryActionPrompt {
  /** Discriminant. */
  kind: CatalogPrimaryActionType.Prompt;
  /** Prompt entity id. */
  id: string;
  /** Display name of the prompt. */
  name: string;
  /** Short description of the prompt. */
  description: string;
  /** Resolved prompt body (seeded from details or fetched). */
  content: string;
  /** Whether the prompt body contains at least one `{{parameter}}` placeholder. */
  hasParameters: boolean;
}

resolveCatalogPrimaryAction = async (
  item: CatalogItem,
  fetchPrompt: (item: CatalogItem) => Promise<PromptResponseDto>,
): Promise<CatalogPrimaryActionResult> => {
  if (item.type !== CatalogEntityType.Prompt) {
    return { kind: CatalogPrimaryActionType.Deployment, id: item.id };
  }

  let content = item.details?.promptContent?.content;
  if (content == null) {
    const dto = await fetchPrompt(item);
    content = dto.content;
  }

  return {
    kind: CatalogPrimaryActionType.Prompt,
    id: item.id,
    name: item.name,
    description: item.description,
    content,
    hasParameters: extractPromptParams(content).length > 0,
  };
}

