  getDeploymentDetails(deploymentId: string): Promise<DeploymentDetailsDto>;
  /** Fetches rate-limit data for a deployment. */
  getDeploymentLimits(
    deploymentId: string,
  ): Promise<DeploymentLimitsResponseDto>;
  /** Fetches a personal or shared prompt by its full `prompts/{bucket}/{path}` resource id. */
  getPrompt(id: string): Promise<PromptResponseDto>;
  /** Fetches a public (organisation) prompt by its bucket-relative path. */
  getPublicPrompt(path: string): Promise<PromptResponseDto>;
}

export interface UseCatalogItemDetailsOptions {
  /** Configured API adapter used for all network calls. */
  api: CatalogDetailsApi;
  /**
   * Combined array of all skills visible to this user
   * (personal + shared + public) for overview metadata lookup.
   */
  skills: SkillMetadataItemDto[];
  /** Whether the current user has admin privileges (affects toolset credential visibility). */
  isAdmin: boolean;
  /** DIAL Core external base URL used for Connect-tab endpoint construction. */
  dialCoreExternalUrl: string | null | undefined;
  /** Labels for skill overview section headers. */
  skillOverviewLabels: SkillOverviewLabels;
  /** Labels for prompt overview section headers. */
  promptOverviewLabels: PromptOverviewLabels;
  /** Labels for deployment limits table. */
  deploymentLimitsLabels: DeploymentLimitsLabels;
}

export interface UseCatalogItemDetailsResult {
  /**
   * Fetches full detail data for a catalog item.
   * Returns `undefined` on failure (error handled by caller).
   */
  onFetchDetails(
    item: CatalogItem,
  ): Promise<CatalogItemDetailsFetchResult | undefined>;
  /**
   * Loads the text content of a file inside the currently open skill's package.
   * Returns `undefined` when the file cannot be read or is a directory.
   */
  onLoadContentFile(fileId: string): Promise<string | undefined>;
  /**
   * Downloads and returns preview bytes for a file inside the currently open skill's package.
   * Throws on HTTP errors, unparseable ids, and size-limit violations.
   */
  onLoadSkillDetailsFile(fileId: string): Promise<SkillFileContent>;
}

useCatalogItemDetails = ({
  api,
  skills,
  isAdmin,
  dialCoreExternalUrl,
  skillOverviewLabels,
  promptOverviewLabels,
  deploymentLimitsLabels,
}: UseCatalogItemDetailsOptions): UseCatalogItemDetailsResult => {
  /*
   * The skill pipeline (manifest, file listing, in-package file loads) lives
   * in the skill-scoped hook; only the dispatch on entity type stays here.
   */
  const { onFetchSkillDetails, onLoadContentFile, onLoadSkillDetailsFile } =
    useSkillItemDetails({ api, skills, skillOverviewLabels });

  const onFetchDetails = useCallback(
    async (
      item: CatalogItem,
    ): Promise<CatalogItemDetailsFetchResult | undefined> => {
      if (item.type === CatalogEntityType.Prompt) {
        try {
          const fetchPromptDto = buildFetchPromptDto(api);
          const dto = await fetchPromptDto(item);
          return {
            promptContent: { content: dto.content },
            overview: buildPromptOverview(dto, promptOverviewLabels),
          };
        } catch {
          return undefined;
        }
      }

      if (item.type === CatalogEntityType.Skill) {
        return onFetchSkillDetails(item);
      }

      try {
        const limitsPromise =
          item.type === CatalogEntityType.Model
            ? api.getDeploymentLimits(item.id).catch(() => undefined)
            : Promise.resolve(undefined);

        const [dto, limitsDto] = await Promise.all([
          api.getDeploymentDetails(item.id),
          limitsPromise,
        ]);

        const entityDetails = mapDeploymentDetailsDtoToEntityDetails(dto);
        const catalogDetails = mapEntityDetailsToCatalogDetails(entityDetails);
        const mcpResourceKind = resolveMcpResourceKind(
          item.type,
          item.supportsMcp,
        );

        const deploymentConnectApi =
          entityDetails.type === 'MODEL' || entityDetails.type === 'AGENT'
            ? buildDeploymentConnectApi(dialCoreExternalUrl ?? '', item.id, {
                hasChatCompletion:
                  entityDetails.data.capabilities?.hasChatCompletion,
                hasResponsesApi:
                  entityDetails.data.capabilities?.hasResponsesApi,
              })
            : undefined;

        return {
          ...catalogDetails,
          api:
            mcpResourceKind != null
              ? buildConnectApi(
                  dialCoreExternalUrl ?? '',
                  item.id,
                  mcpResourceKind,
                )
              : (deploymentConnectApi ?? catalogDetails.api),
          limits: mapDeploymentLimitsDtoToCatalogLimits(
            limitsDto,
            deploymentLimitsLabels,
          ),
          credentials:
            entityDetails.type === 'TOOLSET'
              ? mapToolsetCredentials(item.id, entityDetails.data, isAdmin)
              : undefined,
        };
      } catch {
        return undefined;
      }
    },
    [
      api,
      isAdmin,
      deploymentLimitsLabels,
      dialCoreExternalUrl,
      promptOverviewLabels,
      onFetchSkillDetails,
    ],
  );

  return { onFetchDetails, onLoadContentFile, onLoadSkillDetailsFile };
}

export interface ToolsetCredentialsNotification {
  variant: NotificationVariant;
  title?: string;
  message: string;
  requestId?: string;
}

export interface ToolsetCredentialsMessageLabels {
  user: (params: { name: string; version?: string }) => string;
  org: (params: { name: string; version?: string }) => string;
  global: (params: { name: string; version?: string }) => string;
}

export interface ToolsetCredentialsLabels {
  loginSuccessTitle: string;
  loginSuccess: ToolsetCredentialsMessageLabels;
  apiKeyAddedSuccessTitle: string;
  apiKeyAddedSuccess: ToolsetCredentialsMessageLabels;
  logoutSuccessTitle: string;
  logoutSuccess: ToolsetCredentialsMessageLabels;
  apiKeyDeletedSuccessTitle: string;
  apiKeyDeletedSuccess: ToolsetCredentialsMessageLabels;
  popupBlockedError: string;
  loginFailedError: string;
  logoutFailedError: string;
}

export interface UseCatalogToolsetCredentialsParams {
  isAdmin: boolean;
  toolsets: DialToolsetDto[];
  refetchToolsets: () => Promise<void>;
  /** Route the OAuth popup redirects back to once the provider completes. */
  callbackPath: string;
  /** Already-configured DIAL Core operation: submits credentials for one toolset. */
  loginToolset: (
    toolsetId: string,
    body: ToolsetLoginBodyDto,
  ) => Promise<unknown>;
  /** Already-configured DIAL Core operation: clears credentials for one toolset. */
  logoutToolset: (
    toolsetId: string,
    body: ToolsetLogoutBodyDto,
  ) => Promise<unknown>;
  /** Already-configured DIAL Core operation: re-reads one toolset. */
  getToolset: (toolsetId: string) => Promise<DialToolsetDto>;
  /** Localized notification copy, resolved by the host. */
  labels: ToolsetCredentialsLabels;
  /** Called to surface a host notification. */
  onNotify: (notification: ToolsetCredentialsNotification) => void;
}

export interface UseCatalogToolsetCredentialsResult {
  handleLogin: (
    item: CatalogItem,
    params: { level: CredentialsLevel; apiKey?: string },
  ) => Promise<void>;
  handleLogout: (
    item: CatalogItem,
    params: { level: CredentialsLevel },
  ) => Promise<void>;
}

useCatalogToolsetCredentials = ({
  isAdmin,
  toolsets,
  refetchToolsets,
  callbackPath,
  loginToolset,
  logoutToolset,
  getToolset,
  labels,
  onNotify,
}: UseCatalogToolsetCredentialsParams): UseCatalogToolsetCredentialsResult => {
  const getLevelStatus = useCallback(
    (
      item: CatalogItem,
      level: CredentialsLevel,
    ): CredentialStatus | undefined =>
      level === CredentialsLevel.User
        ? item.credentials?.userStatus
        : item.credentials?.globalStatus,
    [],
  );

  const showLoginSuccess = useCallback(
    (item: CatalogItem, level: CredentialsLevel) => {
      const isAdminAndPublic = isAdmin && !!item.credentials?.isPublic;
      const isApiKey =
        item.credentials?.authenticationType ===
        ToolsetAuthenticationType.ApiKey;
      if (isApiKey) {
        const formatMessage = pickCredentialsMessage(
          level,
          isAdminAndPublic,
          labels.apiKeyAddedSuccess,
        );
        onNotify({
          variant: NotificationVariant.Success,
          title: labels.apiKeyAddedSuccessTitle,
          message: formatMessage({ name: item.name, version: item.version }),
        });
        return;
      }
      const formatMessage = pickCredentialsMessage(
        level,
        isAdminAndPublic,
        labels.loginSuccess,
      );
      onNotify({
        variant: NotificationVariant.Success,
        title: labels.loginSuccessTitle,
        message: formatMessage({ name: item.name, version: item.version }),
      });
    },
    [isAdmin, labels, onNotify],
  );

  const showLogoutSuccess = useCallback(
    (item: CatalogItem, level: CredentialsLevel) => {
      const isAdminAndPublic = isAdmin && !!item.credentials?.isPublic;
      const isApiKey =
        item.credentials?.authenticationType ===
        ToolsetAuthenticationType.ApiKey;
      if (isApiKey) {
        const formatMessage = pickCredentialsMessage(
          level,
          isAdminAndPublic,
          labels.apiKeyDeletedSuccess,
        );
        onNotify({
          variant: NotificationVariant.Success,
          title: labels.apiKeyDeletedSuccessTitle,
          message: formatMessage({ name: item.name, version: item.version }),
        });
        return;
      }
      const formatMessage = pickCredentialsMessage(
        level,
        isAdminAndPublic,
        labels.logoutSuccess,
      );
      onNotify({
        variant: NotificationVariant.Success,
        title: labels.logoutSuccessTitle,
        message: formatMessage({ name: item.name, version: item.version }),
      });
    },
    [isAdmin, labels, onNotify],
  );

  const { login: loginToolsetShared } = useToolsetLogin({
    callbackPath,
    loginToolset,
    logoutToolset,
    getToolset,
  });

  const handleLogin = useCallback(
    async (
      item: CatalogItem,
      params: { level: CredentialsLevel; apiKey?: string },
    ) => {
      const authenticationType = item.credentials?.authenticationType;
      const credentialsLevel =
        params.level === CredentialsLevel.User
          ? ToolsetCredentialsLevel.User
          : ToolsetCredentialsLevel.Global;
      const toolset = toolsets.find((candidate) => candidate.id === item.id);

      const outcome = await loginToolsetShared({
        toolsetId: item.id,
        credentialsLevel,
        authenticationType: toToolsetAuthType(authenticationType),
        apiKey: params.apiKey,
        oauthSettings: {
          clientId: toolset?.authSettings?.clientId,
          authorizationEndpoint: toolset?.authSettings?.authorizationEndpoint,
          scopes: toolset?.authSettings?.scopesSupported,
          codeChallenge: toolset?.authSettings?.codeChallenge,
          codeChallengeMethod: toolset?.authSettings?.codeChallengeMethod,
        },
        isCurrentlyFailed:
          getLevelStatus(item, params.level) === CredentialStatus.Failed,
      });

      switch (outcome.type) {
        case ToolsetLoginOutcomeType.Success:
          showLoginSuccess(item, params.level);
          await refetchToolsets();
          return;
        case ToolsetLoginOutcomeType.PopupBlocked:
          onNotify({
            variant: NotificationVariant.Error,
            message: labels.popupBlockedError,
          });
          return;
        case ToolsetLoginOutcomeType.Failure:
          onNotify({
            variant: NotificationVariant.Error,
            message: labels.loginFailedError,
          });
          return;
        case ToolsetLoginOutcomeType.Cancelled:
          // Silent — a genuine cancel needs no notification.
          return;
      }
    },
    [
      toolsets,
      labels,
      onNotify,
      getLevelStatus,
      showLoginSuccess,
      refetchToolsets,
      loginToolsetShared,
    ],
  );

  const handleLogout = useCallback(
    async (item: CatalogItem, params: { level: CredentialsLevel }) => {
      const credentialsLevel =
        params.level === CredentialsLevel.User
          ? ToolsetCredentialsLevel.User
          : ToolsetCredentialsLevel.Global;
      try {
        const body: ToolsetLogoutBodyDto = {
          url: item.id,
          credentialsLevel,
          authenticationType: item.credentials?.authenticationType,
        };
        await logoutToolset(item.id, body);
        showLogoutSuccess(item, params.level);
        await refetchToolsets();
      } catch (error) {
        const { traceId } = await getApiErrorDetails(error);
        onNotify({
          variant: NotificationVariant.Error,
          message: labels.logoutFailedError,
          requestId: traceId,
        });
      }
    },
    [logoutToolset, labels, onNotify, showLogoutSuccess, refetchToolsets],
  );

  return {
    handleLogin,
    handleLogout,
  };
}

export interface SkillDetailsApi {
  /** Downloads a raw skill file, returning the raw fetch `Response`. */
  downloadSkillFile(
    bucket: string,
    path: string,
    filePath: string,
    signal?: AbortSignal,
  ): Promise<Response>;
  /** Lists files inside a skill package. */
  listSkillFiles(
    params: {
      bucket: string;
      filePath: string;
      path?: string;
      token?: string;
      limit?: number;
      recursive?: boolean;
    },
    signal?: AbortSignal,
  ): Promise<SkillFileListResponseDto>;
  /**
   * Fetches a single skill's own authoritative metadata (`author`,
   * `updatedAt`, and the rest of `SkillMetadataItemDto`) — not the catalog
   * listing entry, which may be sparse for a shared skill.
   */
  getSkillMetadata(
    bucket: string,
    path: string,
    signal?: AbortSignal,
  ): Promise<SkillMetadataItemDto>;
}

export interface UseSkillItemDetailsOptions {
  /** Configured API adapter used for all network calls. */
  api: SkillDetailsApi;
  /**
   * Combined array of all skills visible to this user
   * (personal + shared + public) for overview metadata lookup.
   */
  skills: SkillMetadataItemDto[];
  /** Labels for skill overview section headers. */
  skillOverviewLabels: SkillOverviewLabels;
}

export interface UseSkillItemDetailsResult {
  /**
   * Fetches full detail data for a skill catalog item.
   * Returns `undefined` on failure (error handled by caller).
   */
  onFetchSkillDetails(
    item: CatalogItem,
  ): Promise<CatalogItemDetailsFetchResult | undefined>;
  /**
   * Loads the text content of a file inside the currently open skill's package.
   * Returns `undefined` when the file cannot be read or is a directory.
   */
  onLoadContentFile(fileId: string): Promise<string | undefined>;
  /**
   * Downloads and returns preview bytes for a file inside the currently open skill's package.
   * Throws on HTTP errors, unparseable ids, and size-limit violations.
   */
  onLoadSkillDetailsFile(fileId: string): Promise<SkillFileContent>;
}

useSkillItemDetails = ({
  api,
  skills,
  skillOverviewLabels,
}: UseSkillItemDetailsOptions): UseSkillItemDetailsResult => {
  /* Tracks the last skill whose details panel was opened, for file downloads. */
  const openSkillRef = useRef<ParsedSkillResourceUrl | null>(null);

  const onFetchSkillDetails = useCallback(
    async (
      item: CatalogItem,
    ): Promise<CatalogItemDetailsFetchResult | undefined> => {
      const parsed = parseSkillResourceUrl(item.id);
      if (parsed == null) return undefined;

      const { bucket, path } = parsed;
      openSkillRef.current = parsed;

      const [manifest, files, metadata] = await Promise.allSettled([
        api
          .downloadSkillFile(bucket, path, SKILL_MANIFEST_FILE)
          .then(readSkillManifest),
        api.listSkillFiles({ bucket, path, filePath: '', recursive: true }),
        api.getSkillMetadata(bucket, path),
      ]);

      const parsedManifest =
        manifest.status === 'fulfilled' && manifest.value != null
          ? parseSkillManifestDocument(manifest.value)
          : undefined;

      /*
       * Authoritative when the metadata request fulfilled (D7): the listing
       * entry is only the fallback for a rejection, never a gap-filler for a
       * fulfilled response missing a field.
       */
      const skill =
        metadata.status === 'fulfilled'
          ? metadata.value
          : skills.find((candidate) => candidate.url === item.id);

      const overview =
        files.status === 'fulfilled'
          ? buildSkillOverview(
              skill,
              files.value.items,
              parsedManifest?.about,
              skillOverviewLabels,
            )
          : undefined;

      const contentFiles =
        files.status === 'fulfilled'
          ? buildSkillContentTree(files.value.items, path)
          : [];

      const selectedFileId =
        files.status === 'fulfilled'
          ? resolveSkillManifestFileId(files.value.items, path)
          : SKILL_MANIFEST_FILE;

      if (parsedManifest == null && overview == null) return undefined;

      return {
        ...(parsedManifest != null
          ? {
              promptContent: {
                content: parsedManifest.body,
                ...(parsedManifest.description != null
                  ? { description: parsedManifest.description }
                  : {}),
                files: contentFiles,
                selectedFileId,
              },
            }
          : {}),
        ...(overview != null ? { overview } : {}),
      };
    },
    [api, skills, skillOverviewLabels],
  );

  const onLoadContentFile = useCallback(
    async (fileId: string): Promise<string | undefined> => {
      const openSkill = openSkillRef.current;
      if (openSkill == null) return undefined;

      const filePath = resolveSkillFileDownloadPath(fileId, openSkill.path);
      if (filePath == null) return undefined;

      const response = await api.downloadSkillFile(
        openSkill.bucket,
        openSkill.path,
        filePath,
      );
      const text = await readSkillManifest(response);
      if (text == null) return undefined;

      return filePath === SKILL_MANIFEST_FILE
        ? parseSkillManifestDocument(text).body
        : text;
    },
    [api],
  );

  const onLoadSkillDetailsFile = useCallback(
    async (fileId: string): Promise<SkillFileContent> => {
      const openSkill = openSkillRef.current;
      if (openSkill == null) throw new Error('No skill details are open');

      const filePath = resolveSkillFileDownloadPath(fileId, openSkill.path);
      if (filePath == null) throw new Error('A folder cannot be previewed');

      const response = await api.downloadSkillFile(
        openSkill.bucket,
        openSkill.path,
        filePath,
      );

      if (!response.ok) {
        throw Object.assign(
          new Error(`File preview failed with status ${response.status}`),
          { status: response.status },
        );
      }

      const bytes = await readSkillFilePreviewBytes(response);

      const responseMimeType =
        response.headers.get('content-type')?.split(';')[0].trim() || undefined;

      return {
        bytes,
        /* Core commonly sends this generic value; omitting it lets the same extension inference as Skill Builder run. */
        mimeType:
          responseMimeType === 'application/octet-stream'
            ? undefined
            : responseMimeType,
      };
    },
    [api],
  );

  return { onFetchSkillDetails, onLoadContentFile, onLoadSkillDetailsFile };
}

export interface UseSkillDetailsPanelDataOptions {
  /** Configured API adapter used for all network calls. */
  api: SkillDetailsApi;
  /** The user's own skills. */
  skills: SkillMetadataItemDto[];
  /** Skills shared with the user. */
  sharedWithMe?: SkillMetadataItemDto[];
  /** Public skills. */
  publicSkills?: SkillMetadataItemDto[];
  /**
   * Resource URL (`skills/{bucket}/{path}`) of the skill whose details are
   * shown; `null` when the panel is closed, which resolves no item.
   */
  skillId: string | null;
  /** Personal/Shared/Public folder labels for the mapped item's folder path. */
  folderLabels: DeploymentFolderLabels;
  /** Labels for the skill overview section headers. */
  skillOverviewLabels: SkillOverviewLabels;
  /** Favorited resource ids, keyed by skill resource URL. */
  favoriteIds: ReadonlySet<string>;
}

export interface UseSkillDetailsPanelDataResult {
  /**
   * The selected skill as a catalog item with its fetched details merged in;
   * `null` while no skill is selected or the skill is not in the listings.
   */
  detailsPanelItem: CatalogItem | null;
  /** Whether the details fetch for the current item is in flight. */
  isDetailsLoading: boolean;
  /** Whether the resolved skill is currently favorited. */
  isStarred: boolean;
  /**
   * Downloads and returns preview bytes for a file inside the open skill's
   * package. Throws on HTTP errors, unparseable ids, and size-limit
   * violations.
   */
  onLoadSkillDetailsFile(fileId: string): Promise<SkillFileContent>;
}

useSkillDetailsPanelData = ({
  api,
  skills,
  sharedWithMe,
  publicSkills,
  skillId,
  folderLabels,
  skillOverviewLabels,
  favoriteIds,
}: UseSkillDetailsPanelDataOptions): UseSkillDetailsPanelDataResult => {
  const allSkills = useMemo<SkillMetadataItemDto[]>(
    () => [...skills, ...(sharedWithMe ?? []), ...(publicSkills ?? [])],
    [skills, sharedWithMe, publicSkills],
  );

  const { onFetchSkillDetails, onLoadSkillDetailsFile } = useSkillItemDetails({
    api,
    skills: allSkills,
    skillOverviewLabels,
  });

  const skill = useMemo(
    () => allSkills.find((candidate) => candidate.url === skillId) ?? null,
    [allSkills, skillId],
  );

  /*
   * The source decides the item's folder prefix and ownership flags; the
   * three listing arrays are disjoint, so the first match wins.
   */
  const skillSource = useMemo(() => {
    if (skills.some((candidate) => candidate.url === skillId)) {
      return SkillSource.Personal;
    }
    if (sharedWithMe?.some((candidate) => candidate.url === skillId)) {
      return SkillSource.SharedWithMe;
    }
    return SkillSource.Public;
  }, [skills, sharedWithMe, skillId]);

  const catalogItem = useMemo(() => {
    if (skill == null) return null;
    return mapSkillToCatalogItem(skill, {
      folderLabels,
      source: skillSource,
      favoriteIds,
    });
  }, [skill, skillSource, folderLabels, favoriteIds]);

  const [fetchedDetails, setFetchedDetails] =
    useState<CatalogItemDetailsFetchResult | null>(null);
  const [isDetailsLoading, setIsDetailsLoading] = useState(false);

  /*
   * Paired with the effect's own `isCancelled` flag: closing and reopening
   * the same skill runs the cleanup and a new effect, but a token captured
   * at call time additionally guards against the earlier request's response
   * landing after the newer request started (see `Catalog.tsx`'s equivalent
   * `pendingRequestIdRef` guard, design.md D9).
   */
  const requestIdRef = useRef(0);

  useEffect(() => {
    if (catalogItem == null) return;

    /*
     * Keyed on the item's id rather than its identity: a favorite toggle
     * rebuilds the `CatalogItem` without changing what should load.
     * `onFetchSkillDetails` depends on the skills listing, and re-running on
     * listing refreshes would refetch details the panel already holds.
     */

    setIsDetailsLoading(true);
    setFetchedDetails(null);
    let isCancelled = false;
    const requestId = ++requestIdRef.current;

    onFetchSkillDetails(catalogItem).then((details) => {
      if (isCancelled || requestIdRef.current !== requestId) return;
      setFetchedDetails(details ?? null);
      setIsDetailsLoading(false);
    });

    return () => {
      isCancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps -- keyed on the item's id only, so a rebuilt CatalogItem does not refetch
  }, [catalogItem?.id]);

  /*
   * Mirrors the Catalog page's merge: the fetch result's tab data lands on the
   * item; skills carry no credentials, so that channel stays empty.
   */
  const detailsPanelItem = useMemo(() => {
    if (catalogItem == null) return null;
    if (fetchedDetails == null) return catalogItem;
    const { credentials, ...tabData } = fetchedDetails;
    return {
      ...catalogItem,
      details: tabData,
      credentials: credentials ?? catalogItem.credentials,
    };
  }, [catalogItem, fetchedDetails]);

  return {
    detailsPanelItem,
    isDetailsLoading,
    isStarred: catalogItem != null && favoriteIds.has(catalogItem.id),
    onLoadSkillDetailsFile,
  };
}

export enum FavoriteEntityType {
  Deployment = 'deployment',
  Toolset = 'toolset',
  Prompt = 'prompt',
  Skill = 'skill',
}

export interface FavoritesPayload {
  deployments: string[];
  toolsets: string[];
  prompts: string[];
  skills: string[];
}

export interface UseFavoriteEntitiesStateParams {
  /** Fetches the initial set of favorite ids from the server. */
  loadFavorites: () => Promise<FavoritesPayload>;
  /** Persists a single favorite toggle for the given entity type. */
  updateFavorite: (
    id: string,
    isFavorite: boolean,
    entityType: FavoriteEntityType,
  ) => Promise<void>;
}

export interface UseFavoriteEntitiesStateResult {
  /** Union of all installed entity ids across every category. */
  favoriteIds: ReadonlySet<string>;
  /** True until the initial load has settled. */
  isLoading: boolean;
  /** Optimistically toggles a favorite and rolls back on persistence failure. */
  toggleFavorite: (
    id: string,
    isFavorite: boolean,
    entityType?: FavoriteEntityType,
  ) => Promise<void>;
}

useFavoriteEntitiesState = ({
  loadFavorites,
  updateFavorite,
}: UseFavoriteEntitiesStateParams): UseFavoriteEntitiesStateResult => {
  const [favoriteIds, setFavoriteIds] = useState<ReadonlySet<string>>(
    new Set(),
  );
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const cancelled = { value: false };

    const load = async () => {
      try {
        const payload = await loadFavorites();
        if (!cancelled.value) {
          setFavoriteIds(
            new Set([
              ...payload.deployments,
              ...payload.toolsets,
              ...payload.prompts,
              ...payload.skills,
            ]),
          );
        }
      } catch {
        /* silently fall back to empty set */
      } finally {
        if (!cancelled.value) {
          setIsLoading(false);
        }
      }
    };

    load();

    return () => {
      cancelled.value = true;
    };
  }, [loadFavorites]);

  const toggleFavorite = useCallback(
    async (
      id: string,
      isFavorite: boolean,
      entityType = FavoriteEntityType.Deployment,
    ): Promise<void> => {
      setFavoriteIds((prev) => {
        const next = new Set(prev);
        if (isFavorite) {
          next.add(id);
        } else {
          next.delete(id);
        }
        return next;
      });

      try {
        await updateFavorite(id, isFavorite, entityType);
      } catch (error) {
        setFavoriteIds((prev) => {
          const restored = new Set(prev);
          if (isFavorite) {
            restored.delete(id);
          } else {
            restored.add(id);
          }
          return restored;
        });
        throw error;
      }
    },
    [updateFavorite],
  );

  return useMemo(
    () => ({ favoriteIds, isLoading, toggleFavorite }),
    [favoriteIds, isLoading, toggleFavorite],
  );
}

export interface UsePublishFoldersParams {
  /** Lists one folder level of the Organization/public files bucket. */
  listPublicFiles: (params: { path?: string }) => Promise<ListFilesResponseDto>;
  /**
   * Folder path keys (`path.join('/')`) the user has published to before.
   * Owned by the host, which is also what persists them — this hook never
   * touches browser storage (library isolation).
   */
  rememberedFolderKeys?: string[];
  /**
   * Called with the next remembered-key list when {@link
   * UsePublishFoldersResult.rememberPublishFolder} records a destination.
   * Omit it for a host that does not persist destinations.
   */
  onRememberedFolderKeysChange?: (folderKeys: string[]) => void;
}

export interface UsePublishFoldersResult {
  /** Folder tree loaded so far from the Organization/public bucket. */
  folderItems: PublishFolderNode[];
  /** Folder path keys currently expanded in the tree. */
  expandedPaths: Set<string>;
  /** Folder path keys whose children have already been fetched. */
  loadedPaths: Set<string>;
  /** Folder path keys currently being fetched. */
  loadingPaths: Set<string>;
  /** Called by the folder tree when the set of expanded folders changes. */
  onExpandedPathsChange: (paths: Set<string>) => void;
  /**
   * Adds a folder under `parentPath` to the in-memory tree only — it is
   * never created on the backend here. The path becomes real once the user
   * actually publishes to it: the publish request writes to the nested
   * `folderPath`, which DIAL Core storage creates implicitly, the same way
   * writing a file to a new prefix does. This avoids leaving an orphaned
   * empty folder behind when the user picks a new-folder name and then
   * cancels the publish. Because the folder exists only locally, it is kept
   * apart from the listing cache, so a listing that arrives afterwards
   * cannot drop it again.
   */
  onCreatePublishFolder: (parentPath: string[], name: string) => Promise<void>;
  /**
   * Records `folderPath` as a publish destination the user has actually used,
   * so it keeps appearing in the tree on later publishes. Call it after a
   * successful publish.
   */
  rememberPublishFolder: (folderPath: string[]) => void;
  /** Heuristic write-access check for a folder path (see the TODO above). */
  hasPublishWriteAccess: (folderPath: string[]) => boolean;
}

usePublishFolders = ({
  listPublicFiles,
  rememberedFolderKeys,
  onRememberedFolderKeysChange,
}: UsePublishFoldersParams): UsePublishFoldersResult => {
  const [cache, setCache] = useState<Map<string, ListFilesItemDto[]>>(
    () => new Map(),
  );
  const [expandedPaths, setExpandedPaths] = useState<Set<string>>(
    () => new Set(),
  );
  const [loadingPaths, setLoadingPaths] = useState<Set<string>>(
    () => new Set(),
  );
  /*
   * Folders created during this session, kept as path keys outside `cache`
   * because they exist only locally (see `onCreatePublishFolder`). Holding
   * them in the listing cache instead lost them whenever the parent's real
   * listing landed afterwards — which is exactly what "Add child" on a
   * not-yet-listed folder triggers, since it expands that folder (#8568).
   */
  const [createdFolderKeys, setCreatedFolderKeys] = useState<string[]>([]);

  const loadedPaths = useMemo(() => {
    const result = new Set<string>();
    expandedPaths.forEach((pathKey) => {
      const apiPath = pathKey ? `${pathKey}/` : '';
      if (cache.has(apiPath)) {
        result.add(pathKey);
      }
    });
    return result;
  }, [expandedPaths, cache]);

  const fetchFolder = useCallback(
    async (apiPath: string) => {
      setLoadingPaths((prev) => new Set(prev).add(apiPath));
      try {
        const { items } = await listPublicFiles({ path: apiPath || undefined });
        setCache((prev) => new Map(prev).set(apiPath, items));
      } finally {
        setLoadingPaths((prev) => {
          const next = new Set(prev);
          next.delete(apiPath);
          return next;
        });
      }
    },
    [listPublicFiles],
  );

  useEffect(() => {
    void fetchFolder('');
    /* Root folder is fetched once, on mount. */
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const onExpandedPathsChange = useCallback(
    (nextExpandedPaths: Set<string>) => {
      setExpandedPaths(nextExpandedPaths);
      nextExpandedPaths.forEach((pathKey) => {
        const apiPath = `${pathKey}/`;
        if (!cache.has(apiPath) && !loadingPaths.has(apiPath)) {
          void fetchFolder(apiPath);
        }
      });
    },
    [cache, loadingPaths, fetchFolder],
  );

  const onCreatePublishFolder = useCallback(
    (parentPath: string[], name: string): Promise<void> => {
      const folderKey = toFolderPathKey([...parentPath, name]);
      setCreatedFolderKeys((prev) =>
        prev.includes(folderKey) ? prev : [...prev, folderKey],
      );
      return Promise.resolve();
    },
    [],
  );

  const rememberPublishFolder = useCallback(
    (folderPath: string[]) => {
      const folderKey = toFolderPathKey(folderPath);
      /* Guarded: the stored value is user-visible and survives app versions. */
      const storedKeys = Array.isArray(rememberedFolderKeys)
        ? rememberedFolderKeys
        : [];
      if (!folderKey || storedKeys.includes(folderKey)) {
        return;
      }
      onRememberedFolderKeysChange?.(
        [folderKey, ...storedKeys].slice(0, MAX_REMEMBERED_FOLDERS),
      );
    },
    [rememberedFolderKeys, onRememberedFolderKeysChange],
  );

  const hasPublishWriteAccess = useCallback(
    (folderPath: string[]) => !folderPath.includes(RESTRICTED_FOLDER_SEGMENT),
    [],
  );

  const folderItems = useMemo(() => {
    const storedKeys = Array.isArray(rememberedFolderKeys)
      ? rememberedFolderKeys.filter((key) => typeof key === 'string')
      : [];
    return mergeFolderPaths(buildFolderNodes(cache, '', []), [
      ...storedKeys.map(fromFolderPathKey),
      ...createdFolderKeys.map(fromFolderPathKey),
    ]);
  }, [cache, rememberedFolderKeys, createdFolderKeys]);

  return {
    folderItems,
    expandedPaths,
    loadedPaths,
    loadingPaths,
    onExpandedPathsChange,
    onCreatePublishFolder,
    rememberPublishFolder,
    hasPublishWriteAccess,
  };
}

export interface AnnouncementListItemLink {
  /** Visible text of the call to action. */
  label: string;
  /** Absolute `http`/`https` target the call to action opens. */
  href: string;
}

export interface AnnouncementListItem {
  /** Plain-text heading of the entry. */
  title: string;
  /** Supporting copy of the entry, sanitized before it is rendered. */
  description?: string | null;
  /** Optional call to action shown at the end of the entry. */
  link?: AnnouncementListItemLink | null;
}

export interface AnnouncementContent {
  title: string | null;
  description: string | null;
  html: string | null;
  /** Entries of the popover the banner opens. */
  items?: readonly AnnouncementListItem[];
}

hasStructuredAnnouncement = ({
  title,
  description,
}: AnnouncementContent): boolean =>
  isNonEmpty(title) || isNonEmpty(description)

buildAnnouncementSignature = (
  content: AnnouncementContent,
): string => {
  if (!hasStructuredAnnouncement(content)) {
    return content.html ?? '';
  }

  const payload: AnnouncementSignaturePayload = {
    title: content.title ?? '',
    description: content.description ?? '',
  };

  const items = content.items ?? [];
  if (items.length > 0) {
    payload.items = buildItemsSignature(items);
  }

  return JSON.stringify(payload);
}

