export class GenerationConflictError extends Error {
  constructor(message: string = DEFAULT_GENERATION_CONFLICT_MESSAGE) {
    super(message);
    this.name = 'GenerationConflictError';
  }
}

export interface ChatStreamCompletionOptions {
  onChunk: (chunk: StreamChunk) => void;
  onComplete: () => void;
  onError: (error: Error) => void;
  signal?: AbortSignal;
}

export interface CreateChatStreamApiDeps {
  /** Returns the currently held CSRF token, or `null` when none is set. */
  getCsrfToken: () => string | null;
  /** Stores a CSRF token captured from a response header. */
  setCsrfToken: (token: string | null) => void;
  /** Base path for the completion/stop endpoints, e.g. `/api/v1/conversations`. */
  completionsBasePath: string;
  /** Resolves the caller's current timezone, attached as `X-Timezone` when non-empty. */
  getTimezone?: () => string | undefined;
  /** `fetch` implementation to issue requests through. Defaults to the global `fetch`. */
  fetchImpl?: typeof fetch;
}

export interface ChatStreamApi {
  streamCompletion: (
    path: string,
    message: string | undefined,
    model: string,
    options: ChatStreamCompletionOptions,
    customContent?: MessageCustomContent,
    generationId?: string,
    mode?: SendCompletionDtoModeEnum,
    messageIndex?: number,
    clientChannelId?: string,
  ) => void;
  stopCompletion: (dto: {
    generationId: string;
    path: string;
  }) => Promise<void>;
}

createChatStreamApi = (
  deps: CreateChatStreamApiDeps,
): ChatStreamApi => {
  const { completionsBasePath } = deps;
  /*
   * Resolved per-call (not captured once at factory-construction time) so a
   * test's `vi.stubGlobal('fetch', ...)` — applied after this factory is
   * constructed at module load — still takes effect, matching the pre-move
   * implementation's direct global `fetch` reference.
   */
  const doFetch: typeof fetch = (...args) => (deps.fetchImpl ?? fetch)(...args);

  const stopCompletion = async (dto: {
    generationId: string;
    path: string;
  }): Promise<void> => {
    const response = await doFetch(`${completionsBasePath}/completions/stop`, {
      method: 'POST',
      credentials: 'include',
      headers: {
        ...JSON_HEADERS,
        ...(deps.getCsrfToken() != null
          ? { 'X-CSRF-Token': deps.getCsrfToken() as string }
          : {}),
      },
      body: JSON.stringify(dto),
    });

    const rotatedCsrf = response.headers.get('x-csrf-token');
    if (rotatedCsrf) deps.setCsrfToken(rotatedCsrf);

    if (!response.ok) {
      throw new Error(`stopCompletion failed: ${response.status}`);
    }
  };

  const streamCompletion = (
    path: string,
    message: string | undefined,
    model: string,
    options: ChatStreamCompletionOptions,
    customContent?: MessageCustomContent,
    generationId?: string,
    mode?: SendCompletionDtoModeEnum,
    messageIndex?: number,
    clientChannelId?: string,
  ): void => {
    const { onChunk, onComplete, onError, signal } = options;

    const run = async () => {
      let response: Response;
      try {
        const timezone = deps.getTimezone?.();
        response = await doFetch(`${completionsBasePath}/completions`, {
          method: 'POST',
          credentials: 'include',
          signal,
          headers: {
            ...JSON_HEADERS,
            ...(deps.getCsrfToken() != null
              ? { 'X-CSRF-Token': deps.getCsrfToken() as string }
              : {}),
            ...(timezone ? { 'X-Timezone': timezone } : {}),
          },
          body: JSON.stringify({
            path,
            message: message ?? '',
            model,
            custom_content: customContent || {},
            ...(generationId != null && { generationId }),
            ...(mode != null && { mode }),
            ...(messageIndex != null && { messageIndex }),
            ...(clientChannelId != null && { clientChannelId }),
          }),
        });
      } catch (err) {
        if (err instanceof Error && err.name === 'AbortError') return;
        onError(err instanceof Error ? err : new Error(String(err)));
        return;
      }

      const rotatedCsrf = response.headers.get('x-csrf-token');
      if (rotatedCsrf) deps.setCsrfToken(rotatedCsrf);

      if (!response.ok) {
        if (response.status === GENERATION_CONFLICT_STATUS) {
          onError(new GenerationConflictError());
          return;
        }
        onError(
          new Error(`Stream request failed with status ${response.status}`),
        );
        return;
      }

      if (!response.body) {
        onError(new Error('No response body'));
        return;
      }

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';
      let hasError = false;

      const handleError = (err: Error) => {
        hasError = true;
        onError(err);
      };

      try {
        while (true) {
          const { done, value } = await reader.read();

          if (done) {
            if (buffer.trim()) parseSSELine(buffer, onChunk, handleError);
            break;
          }

          buffer += decoder.decode(value, { stream: true });

          const lines = buffer.split('\n');
          buffer = lines.pop() ?? '';

          for (const line of lines) {
            parseSSELine(line, onChunk, handleError);
          }
        }
        if (!hasError) onComplete();
      } catch (err) {
        if (err instanceof Error && err.name === 'AbortError') return;
        onError(err instanceof Error ? err : new Error(String(err)));
      } finally {
        reader.releaseLock();
      }
    };

    run();
  };

  return { streamCompletion, stopCompletion };
}

shouldWatchForDisplayNameUpdate = (
  conversation: Conversation,
): boolean => {
  const nonStatusMessages = conversation.messages.filter(
    (message) => message.role !== MessageRole.Status,
  );
  if (nonStatusMessages.length < 2) return false;

  const dto = conversation as ConversationResponseDto;
  return dto.llmNamingDone !== true;
}

formatAppVersion = (version: string): string => {
  const trimmed = version.trim();
  return /^v/i.test(trimmed) ? trimmed : `v${trimmed}`;
}

getModelIdFromConversationId = (
  id: string,
): string | undefined => {
  const segments = id.split('/');

  // Minimum structure: "conversations", "{bucket}", "{deploymentPart}__{title}"
  if (segments.length < 3) return undefined;

  // segments[0] = "conversations", segments[1] = bucket
  const afterBucket = segments.slice(2);
  const deploymentSegments =
    afterBucket[0] === SCHEDULER_SEGMENT ? afterBucket.slice(2) : afterBucket;

  /*
   * Find the FIRST segment that contains '__'. Everything before it
   * is the deployment ID prefix; the part before '__' in that segment is the
   * final piece of the deployment ID.
   */
  const separatorIndex = deploymentSegments.findIndex((seg) =>
    seg.includes(CONVERSATION_NAME_SEPARATOR),
  );

  if (separatorIndex === -1) return undefined;

  const separatorSegment = deploymentSegments[separatorIndex];
  const prefixParts = deploymentSegments
    .slice(0, separatorIndex)
    .filter(Boolean);
  const isApplicationDeployment = prefixParts[0] === APPLICATIONS_PATH_SEGMENT;
  const lastDeploymentPart = getDeploymentIdPartFromFilenamePart(
    separatorSegment,
    isApplicationDeployment,
  );

  const allParts = [...prefixParts, lastDeploymentPart].filter(Boolean);
  return allParts.length > 0 ? allParts.join('/') : undefined;
}

export interface GreetingTranslations {
  morningWithName: string;
  morningNoName: string;
  afternoonWithName: string;
  afternoonNoName: string;
  eveningWithName: string;
  eveningNoName: string;
  nightWithName: string;
  nightNoName: string;
}

getTimeOfDayGreeting = (
  hour: number,
  translations: GreetingTranslations,
  firstName?: string,
): string => {
  const hasName = firstName != null && firstName.length > 0;

  if (hour >= 5 && hour <= 11) {
    return hasName ? translations.morningWithName : translations.morningNoName;
  }
  if (hour >= 12 && hour <= 16) {
    return hasName
      ? translations.afternoonWithName
      : translations.afternoonNoName;
  }
  if (hour >= 17 && hour <= 20) {
    return hasName ? translations.eveningWithName : translations.eveningNoName;
  }
  return hasName ? translations.nightWithName : translations.nightNoName;
}

createDeploymentChangedMessage = (
  previousDeploymentId: string | null,
  newDeploymentId: string,
): StatusMessage => {
  const custom_content: StatusMessageCustomContent = {
    event_type: StatusEvent.ModelChanged,
    previous_deployment_id: previousDeploymentId,
    new_deployment_id: newDeploymentId,
  };
  return {
    id: generateUUID(),
    role: MessageRole.Status,
    content: '',
    timestamp: new Date().toISOString(),
    deploymentId: newDeploymentId,
    custom_content,
  };
}

getLastDeploymentId = (messages: Message[]): string | null => {
  for (let i = messages.length - 1; i >= 0; i--) {
    const msg = messages[i];
    if (
      isStatusMessage(msg) &&
      msg.custom_content?.event_type === StatusEvent.ModelChanged
    ) {
      return msg.custom_content.new_deployment_id;
    }
    if (msg.deploymentId) return msg.deploymentId;
  }
  return null;
}

getLastUserMessageToolConfiguration = (
  messages: Message[],
): Record<string, unknown> | undefined => {
  for (let i = messages.length - 1; i >= 0; i--) {
    if (messages[i].role === MessageRole.User) {
      return messages[i].custom_content?.configuration_value;
    }
  }
  return undefined;
}

normalizeResponseFormat = (
  value: string | undefined,
): ResponseFormat => {
  const lower = (value ?? '').toLowerCase().replace(/[^a-z]/g, '');
  if (lower === 'plaintext') return ResponseFormat.PlainText;
  return ResponseFormat.Markdown;
}

toOverlayMessages = (messages: Message[]): OverlayChatMessage[] =>
  messages.map((message, index) => {
    const stages = toOverlayStages(message.custom_content?.stages);
    return {
      id: index.toString(),
      role: message.role,
      content: message.content,
      ...(stages ? { stages } : {}),
    };
  })

export interface QuickAppConversationStartersSettings {
  starters: StarterOption[];
  introText: string | undefined;
  isChatMessageInputDisabled: boolean;
}

getQuickAppConversationStarters = (
  conversationStarters: unknown,
): QuickAppConversationStartersSettings => {
  if (
    !isRecord(conversationStarters) ||
    !Array.isArray(conversationStarters.starters)
  ) {
    return {
      starters: [],
      introText: undefined,
      isChatMessageInputDisabled: false,
    };
  }

  const shouldSubmit = conversationStarters.autoSubmit !== false;
  const starters = conversationStarters.starters
    .filter(isRecord)
    .map((starter) => ({
      title: getTrimmedString(starter.title),
      text: getTrimmedString(starter.text),
    }))
    .filter(
      (starter): starter is { title: string; text: string } =>
        starter.title != null && starter.text != null,
    )
    .map((starter, index): StarterOption => ({
      const: index,
      title: starter.title,
      'dial:widgetOptions': {
        populateText: starter.text,
        submit: shouldSubmit,
        confirmationMessage: null,
      },
    }));

  return {
    starters,
    introText: getTrimmedString(conversationStarters.introText),
    isChatMessageInputDisabled:
      conversationStarters.chatMessageInputDisabled === true,
  };
}

export interface RawStageAttachment {
  /** Zero-based position in the attachment list. */
  index?: number | null;
  /** MIME type of the attachment content. */
  type?: string | null;
  /** Display name shown in the UI. */
  title?: string | null;
  /** Inline base-64 encoded content. */
  data?: string | null;
  /** Remote URL pointing to the attachment content. */
  url?: string | null;
  /** MIME type of the referenced resource. */
  reference_type?: string | null;
  /** URL of an alternate reference resource. */
  reference_url?: string | null;
}

export interface RawStage {
  /** Ordering key. Defaults to `0` when absent. */
  index?: number | null;
  /** Stage title. `null` on the chunk that opens the stage. */
  name?: string | null;
  /** Terminal state as a raw wire string; anything other than `'completed'`/`'failed'` means still running. */
  status?: string | null;
  /** Additional stage text. */
  content?: string | null;
  /** Short source/category label shown beside the stage name. */
  tag?: string | null;
  /** Files produced or referenced by this stage. */
  attachments?: RawStageAttachment[] | null;
}

export interface RawStageSource {
  /** Custom content as the DIAL wire format spells it. */
  custom_content?: { stages?: RawStage[] | null } | null;
  /** Custom content as a camelCasing host spells it. */
  customContent?: { stages?: RawStage[] | null } | null;
}

toStage = (stage: RawStage): Stage => ({
  index: stage.index ?? 0,
  name: stage.name ?? '',
  status: toStageStatus(stage.status),
  ...(stage.content != null && { content: stage.content }),
  ...(stage.tag != null && { tag: stage.tag }),
  ...(stage.attachments?.length && {
    attachments: stage.attachments.map(toStageAttachment),
  }),
})

mapStages = (
  source: RawStage[] | RawStageSource | null | undefined,
): Stage[] | undefined => {
  const stages = Array.isArray(source)
    ? source
    : (source?.custom_content?.stages ?? source?.customContent?.stages);

  if (!stages?.length) return undefined;

  return stages.map(toStage);
}

getStartersFromSchema = (
  schema: DeploymentConfigurationSchema | null | undefined,
): {
  starters: StarterOption[];
  propertyKey: string | undefined;
  description: string | undefined;
} => {
  const properties = schema?.properties;
  if (!properties) {
    return { starters: [], propertyKey: undefined, description: undefined };
  }

  let key: string | undefined;
  if ('starter' in properties) {
    key = 'starter';
  } else if ('button' in properties) {
    key = 'button';
  }

  if (!key) {
    return { starters: [], propertyKey: undefined, description: undefined };
  }

  const property = properties[key];
  const oneOf = property?.oneOf;
  const description =
    typeof property?.description === 'string'
      ? property.description
      : undefined;

  if (!Array.isArray(oneOf)) {
    return { starters: [], propertyKey: key, description };
  }

  return { starters: oneOf as StarterOption[], propertyKey: key, description };
}

buildToolsetAuthorizeUrl = (
  auth: ToolsetOAuthSettings,
  redirectUri: string,
  state: string,
): string | null => {
  if (!auth.authorizationEndpoint?.trim() || !auth.clientId?.trim()) {
    return null;
  }
  try {
    const url = new URL(auth.authorizationEndpoint.trim());
    if (!isEndpointTransportSecure(url)) {
      return null;
    }
    url.searchParams.set('response_type', 'code');
    url.searchParams.set('client_id', auth.clientId.trim());
    url.searchParams.set('redirect_uri', redirectUri);
    if (auth.codeChallenge) {
      url.searchParams.set('code_challenge', auth.codeChallenge);
    }
    if (auth.codeChallengeMethod) {
      url.searchParams.set('code_challenge_method', auth.codeChallengeMethod);
    }
    url.searchParams.set('state', state);
    if (auth.scopes && auth.scopes.length > 0) {
      url.searchParams.set('scope', auth.scopes.join(' '));
    }
    return url.toString();
  } catch {
    return null;
  }
}

export interface WaitForToolsetOAuthResultOptions {
  /** Resource id echoed back in a success result. */
  toolsetId: string;
  /** Credentials level echoed back in a success result. */
  credentialsLevel: ToolsetCredentialsLevel;
  /**
   * The host's callback route — the same path the flow's popup was opened
   * against. The popup-URL reader treats a same-origin URL as a result only
   * when its pathname equals this value, so a host serving more than one
   * callback route passes whichever one it actually opened.
   */
  callbackPath: string;
  timeoutMs?: number;
  pollIntervalMs?: number;
}

waitForToolsetOAuthResult = (
  popup: Window,
  flowId: string,
  {
    toolsetId,
    credentialsLevel,
    callbackPath,
    timeoutMs = DEFAULT_OAUTH_RESULT_TIMEOUT_MS,
    pollIntervalMs = DEFAULT_OAUTH_POPUP_POLL_INTERVAL_MS,
  }: WaitForToolsetOAuthResultOptions,
): Promise<ToolsetOAuthResult> =>
  new Promise((resolve) => {
    let channel: BroadcastChannel | undefined;
    let isSettled = false;

    /*
     * Deferred by a macrotask so an acknowledgement posted immediately before
     * this still reaches the callback popup — closing the channel in the same
     * tick discards it, which would strand a popup whose `WindowProxy` was
     * severed and which therefore relies on that acknowledgement to close
     * itself.
     */
    const closeChannelWhenFlushed = () => {
      const pending = channel;
      channel = undefined;
      if (pending == null) return;
      setTimeout(() => pending.close(), 0);
    };

    const finish = (outcome: ToolsetOAuthResult) => {
      if (isSettled) return;
      isSettled = true;
      clearInterval(pollId);
      clearTimeout(timeoutId);
      window.removeEventListener('focus', handleOpenerFocus);
      closeChannelWhenFlushed();
      resolve(outcome);
    };

    const finishReportedResult = (result: ToolsetOAuthChannelMessage) => {
      channel?.postMessage({
        type: ToolsetOAuthChannelControlType.ResultAcknowledged,
      });
      try {
        popup.close();
      } catch {
        // The result is already consumed; popup cleanup is best-effort.
      }
      finish(result);
    };

    const readResultFromPopupUrl = (): ToolsetOAuthChannelMessage | null => {
      try {
        const popupUrl = new URL(popup.location.href);
        if (
          popupUrl.origin !== window.location.origin ||
          popupUrl.pathname !== callbackPath
        ) {
          return null;
        }

        const result = popupUrl.searchParams.get(
          ToolsetOAuthCallbackQuery.Result,
        );
        if (result === ToolsetOAuthResultType.Success) {
          return {
            type: ToolsetOAuthResultType.Success,
            toolsetId,
            credentialsLevel,
          };
        }
        if (result === ToolsetOAuthResultType.Failure) {
          return {
            type: ToolsetOAuthResultType.Failure,
            reason: getOAuthFailureReason(
              popupUrl.searchParams.get(
                ToolsetOAuthCallbackQuery.FailureReason,
              ),
            ),
          };
        }
      } catch {
        // Cross-origin popup URLs are unreadable until the provider returns.
      }
      return null;
    };

    const handleOpenerFocus = () => {
      const reportedResult = readResultFromPopupUrl();
      if (reportedResult != null) {
        finishReportedResult(reportedResult);
        return;
      }
      if (popup.closed) {
        finish({ type: ToolsetOAuthResultType.Cancelled });
      }
    };

    try {
      channel = new BroadcastChannel(getToolsetOAuthChannelName(flowId));
      channel.onmessage = (event: MessageEvent<unknown>) => {
        if (!isToolsetOAuthChannelMessage(event.data)) return;
        finishReportedResult(event.data);
      };
    } catch {
      // URL polling is the deterministic fallback when channels are unavailable.
    }
    window.addEventListener('focus', handleOpenerFocus);

    const pollId = setInterval(() => {
      const reportedResult = readResultFromPopupUrl();
      if (reportedResult != null) {
        finishReportedResult(reportedResult);
        return;
      }
    }, pollIntervalMs);

    const timeoutId = setTimeout(() => {
      popup.close();
      finish({ type: ToolsetOAuthResultType.Cancelled });
    }, timeoutMs);

    const reportedResult = readResultFromPopupUrl();
    if (reportedResult != null) finishReportedResult(reportedResult);
  })

export interface ToolsetOAuthSettings {
  clientId?: string;
  authorizationEndpoint?: string;
  scopes?: string[];
  codeChallenge?: string;
  codeChallengeMethod?: string;
}

export interface ToolsetRedirectState {
  toolsetId: string;
  credentialsLevel?: ToolsetCredentialsLevel;
  redirectUri?: string;
  /** CSRF state token generated by the client before the OAuth redirect. */
  state?: string;
  /**
   * Which sign-in endpoint the host's callback route should submit the
   * authorization code to. Defaults to `Toolset` when absent so every
   * existing redirect state (written before this field existed) keeps
   * calling the toolset login unchanged. `ExternalService` reuses the same
   * popup/BroadcastChannel machinery with `toolsetId` repurposed as an
   * `{appId}::{serviceId}` composite key. `OfflineCredentials` reuses the
   * same machinery again, with `toolsetId` repurposed as a fixed sentinel
   * correlation id (`'offline-credentials'`) — the field carries no real
   * toolset/external-service meaning there, only the opaque
   * flow-correlation string the shared popup/`BroadcastChannel` utilities
   * require structurally.
   */
  resourceKind?: OAuthResourceKind;
  /**
   * Whether the user agreed the application may use the resulting credential
   * while they are away. Carried through the popup because the choice is made
   * before the redirect and the code exchange happens after it — the callback
   * route has no other way to learn it. Absent means "not granted".
   */
  offlineUsageConsent?: boolean;
}

export type ToolsetOAuthInitiationResult =
  | {
      type: ToolsetOAuthInitiationResultType.Started;
      popup: Window;
      flowId: string;
    }
  | { type: ToolsetOAuthInitiationResultType.Blocked }
  | { type: ToolsetOAuthInitiationResultType.InvalidConfig };

export interface ToolsetOAuthSuccessMessage {
  type: ToolsetOAuthResultType.Success;
  toolsetId: string;
  credentialsLevel: ToolsetCredentialsLevel;
}

export interface ToolsetOAuthFailureMessage {
  type: ToolsetOAuthResultType.Failure;
  reason: ToolsetOAuthFailureReason;
}

export interface ToolsetOAuthResultAcknowledgement {
  type: ToolsetOAuthChannelControlType.ResultAcknowledged;
}

export type ToolsetOAuthResult =
  | ToolsetOAuthSuccessMessage
  | ToolsetOAuthFailureMessage
  | { type: ToolsetOAuthResultType.Cancelled };

navigateToolsetOAuthPopup = (
  popup: Window,
  auth: ToolsetOAuthSettings,
  toolsetId: string,
  callbackPath: string,
  credentialsLevel: ToolsetCredentialsLevel = ToolsetCredentialsLevel.User,
  resourceKind: OAuthResourceKind = OAuthResourceKind.Toolset,
  offlineUsageConsent?: boolean,
): ToolsetOAuthInitiationResult => {
  const redirectUri = getToolsetRedirectUri(callbackPath);
  const state = generateUUID();
  const url = buildToolsetAuthorizeUrl(auth, redirectUri, state);
  if (!url) {
    popup.close();
    return { type: ToolsetOAuthInitiationResultType.InvalidConfig };
  }
  return writeRedirectStateAndNavigate(
    popup,
    url,
    state,
    toolsetId,
    credentialsLevel,
    redirectUri,
    resourceKind,
    offlineUsageConsent,
  );
}

initiateOAuthLogin = (
  auth: ToolsetOAuthSettings,
  toolsetId: string,
  callbackPath: string,
  credentialsLevel: ToolsetCredentialsLevel = ToolsetCredentialsLevel.User,
  offlineUsageConsent?: boolean,
): ToolsetOAuthInitiationResult => {
  const redirectUri = getToolsetRedirectUri(callbackPath);
  const state = generateUUID();
  const url = buildToolsetAuthorizeUrl(auth, redirectUri, state);
  if (!url) return { type: ToolsetOAuthInitiationResultType.InvalidConfig };

  const popup = openToolsetOAuthPopup();
  if (!popup) return { type: ToolsetOAuthInitiationResultType.Blocked };

  return writeRedirectStateAndNavigate(
    popup,
    url,
    state,
    toolsetId,
    credentialsLevel,
    redirectUri,
    OAuthResourceKind.Toolset,
    offlineUsageConsent,
  );
}

decodeToolsetId = (id: string): string =>
  id
    .split('/')
    .map((segment) => {
      try {
        return decodeURIComponent(segment);
      } catch {
        return segment;
      }
    })
    .join('/')

isPublicToolsetId = (toolsetId: string): boolean => {
  if (!toolsetId.startsWith(TOOLSETS_ID_PREFIX)) return false;
  const bucket = toolsetId.slice(TOOLSETS_ID_PREFIX.length).split('/')[0];
  return bucket === PUBLIC_BUCKET_SEGMENT;
}

export enum ToolsetAuthTypes {
  None = 'NONE',
  ApiKey = 'API_KEY',
  OAuth = 'OAUTH',
}

export enum ToolsetAuthStatus {
  SignedIn = 'SIGNED_IN',
  SignedOut = 'SIGNED_OUT',
  Failed = 'FAILED',
}

export enum ToolsetCredentialsLevel {
  Global = 'GLOBAL',
  User = 'USER',
  App = 'APP',
}

export enum WithLogin {
  WithLogin = 'with-login',
  WithoutLogin = 'without-login',
  WithConfig = 'with-config',
}

export enum ToolsetOAuthInitiationResultType {
  /** The popup was opened and navigated to the provider's authorize URL. */
  Started = 'started',
  /** The browser blocked the popup before it could be opened. */
  Blocked = 'blocked',
  /** The toolset's OAuth configuration is missing required fields. */
  InvalidConfig = 'invalid-config',
}

export enum ToolsetOAuthResultType {
  Success = 'success',
  Failure = 'failure',
  /** The popup was closed and focus returned to its opener, or the flow timed out. */
  Cancelled = 'cancelled',
}

export enum ToolsetOAuthFailureReason {
  MissingCode = 'missing-code',
  MissingRedirectState = 'missing-redirect-state',
  StateMismatch = 'state-mismatch',
  LoginRequestFailed = 'login-request-failed',
}

export enum ToolsetOAuthChannelControlType {
  ResultAcknowledged = 'result-acknowledged',
}

export enum ToolsetOAuthCallbackQuery {
  Result = 'toolsetOAuthResult',
  FailureReason = 'toolsetOAuthFailureReason',
}

export interface OAuthExchangeParams {
  /** One-time authorization code the provider returned. */
  code: string;
  /** Redirect URI the code was issued against, to be echoed back to the backend. */
  redirectUri: string;
  /** Credentials level resolved from the stored redirect state. */
  credentialsLevel: ToolsetCredentialsLevel;
  /** The full redirect state the flow stored before navigating to the provider. */
  redirectState: ToolsetRedirectState;
}

export interface UseOAuthCallbackCompletionParams {
  /**
   * Query parameters of the callback URL. Read once per mount; the hook takes
   * `code` and `state` from it.
   */
  searchParams: URLSearchParams;
  /**
   * Path used to build the `redirect_uri` echoed back to the backend when the
   * stored redirect state carries none — every state written by the current
   * flow does, so this only covers states written before that field existed.
   */
  callbackPath: string;
  /**
   * Performs the code-for-credentials exchange. Resolving `null` reports
   * success; resolving a failure reason reports that reason (for a host-side
   * validation the hook cannot perform, such as an unparseable resource id);
   * rejecting reports `LoginRequestFailed`.
   */
  exchange: (
    params: OAuthExchangeParams,
  ) => Promise<ToolsetOAuthFailureReason | null>;
}

export interface UseOAuthCallbackCompletionResult {
  /** True until the flow has reported an outcome. */
  isInProgress: boolean;
  /** Reason the flow failed, or `null` while in progress or on success. */
  failureReason: ToolsetOAuthFailureReason | null;
}

useOAuthCallbackCompletion = ({
  searchParams,
  callbackPath,
  exchange,
}: UseOAuthCallbackCompletionParams): UseOAuthCallbackCompletionResult => {
  const [isInProgress, setIsInProgress] = useState(true);
  const [failureReason, setFailureReason] =
    useState<ToolsetOAuthFailureReason | null>(null);

  /* Guard against StrictMode double-invocation of the effect. */
  const hasRun = useRef(false);
  const exchangeRef = useRef(exchange);
  exchangeRef.current = exchange;
  const callbackPathRef = useRef(callbackPath);
  callbackPathRef.current = callbackPath;

  useEffect(() => {
    if (hasRun.current) return;
    hasRun.current = true;

    const settle = (
      flowId: string | undefined,
      message: ToolsetOAuthChannelMessage,
    ) => {
      reportResult(flowId, message);
      setIsInProgress(false);
      setFailureReason(
        message.type === ToolsetOAuthResultType.Failure ? message.reason : null,
      );
    };

    const complete = async () => {
      const code = searchParams.get('code');
      const state = searchParams.get('state');
      const redirectState = readRedirectState();
      sessionStorage.removeItem(TOOLSET_REDIRECT_STATE_KEY);
      const flowId = redirectState?.state ?? state ?? undefined;

      /*
       * Remove the one-time authorization code from the address bar/history
       * before making the login request. `reportResult` later replaces this
       * clean URL with the non-secret completion marker.
       */
      replacePopupUrl(
        new URL(window.location.pathname, window.location.origin),
      );

      if (!code || !redirectState?.toolsetId) {
        settle(flowId, {
          type: ToolsetOAuthResultType.Failure,
          reason: !redirectState?.toolsetId
            ? ToolsetOAuthFailureReason.MissingRedirectState
            : ToolsetOAuthFailureReason.MissingCode,
        });
        return;
      }

      if (redirectState.state != null && redirectState.state !== state) {
        settle(flowId, {
          type: ToolsetOAuthResultType.Failure,
          reason: ToolsetOAuthFailureReason.StateMismatch,
        });
        return;
      }

      const credentialsLevel =
        redirectState.credentialsLevel ?? ToolsetCredentialsLevel.User;
      const redirectUri =
        redirectState.redirectUri ??
        `${window.location.origin}${callbackPathRef.current}`;

      try {
        const reason = await exchangeRef.current({
          code,
          redirectUri,
          credentialsLevel,
          redirectState,
        });
        if (reason != null) {
          settle(flowId, {
            type: ToolsetOAuthResultType.Failure,
            reason,
          });
          return;
        }

        settle(flowId, {
          type: ToolsetOAuthResultType.Success,
          toolsetId: redirectState.toolsetId,
          credentialsLevel,
        });
      } catch {
        settle(flowId, {
          type: ToolsetOAuthResultType.Failure,
          reason: ToolsetOAuthFailureReason.LoginRequestFailed,
        });
      }
    };

    void complete();
  }, [searchParams]);

  return { isInProgress, failureReason };
}

export enum ToolsetLoginOutcomeType {
  Success = 'success',
  Failure = 'failure',
  PopupBlocked = 'popup-blocked',
  Cancelled = 'cancelled',
}

export interface ToolsetLoginOutcome {
  /** Which terminal branch the attempt resolved through. */
  type: ToolsetLoginOutcomeType;
}

export interface ToolsetLoginParams {
  /** Already-encoded toolset id/url, as returned by `listToolsets`/`getToolset`. */
  toolsetId: string;
  /** Credentials level the submitted credentials apply to. */
  credentialsLevel: ToolsetCredentialsLevel;
  /** Authentication mechanism the toolset requires. */
  authenticationType: ToolsetAuthTypes;
  /** Required for `ToolsetAuthTypes.ApiKey`. */
  apiKey?: string;
  /** Required for `ToolsetAuthTypes.OAuth`. */
  oauthSettings?: ToolsetOAuthSettings;
  /**
   * Whether the target level's cached status is currently `FAILED` — API key
   * logins log that level out first when true. Ignored when `forceStale` is
   * set, and never consulted for OAuth (OAuth does not log out before
   * retrying).
   */
  isCurrentlyFailed?: boolean;
  /**
   * Always logs out the target level first (for both API key and OAuth)
   * regardless of the cached status — set by callers reacting to a
   * DIAL-Core-pushed `toolset/signin` event, which is proof the cached
   * status may be stale even when it still reads `SIGNED_IN`.
   */
  forceStale?: boolean;
  /**
   * Whether the user agreed an application may use this credential while they
   * are away. DIAL Core gates every on-behalf-of mint on it, so a toolset
   * signed in without it works interactively and still fails with
   * `consent-required` in the background. Absent means not granted.
   */
  offlineUsageConsent?: boolean;
}

export interface UseToolsetLoginParams {
  /**
   * The host's OAuth callback route. Resolved against `window.location.origin`
   * for the `redirect_uri`, and compared against the popup's pathname when
   * reading a completion marker out of its URL.
   */
  callbackPath: string;
  /** Submits credentials for one toolset at one credentials level. */
  loginToolset: (
    toolsetId: string,
    body: ToolsetLoginBodyDto,
  ) => Promise<unknown>;
  /** Clears stored credentials for one toolset at one credentials level. */
  logoutToolset: (
    toolsetId: string,
    body: ToolsetLogoutBodyDto,
  ) => Promise<unknown>;
  /** Re-reads a toolset so a reported cancellation can be checked against the backend. */
  getToolset: (toolsetId: string) => Promise<DialToolsetDto>;
}

export interface UseToolsetLoginResult {
  /** Runs one API-key or OAuth login attempt and resolves its outcome. */
  login: (params: ToolsetLoginParams) => Promise<ToolsetLoginOutcome>;
}

useToolsetLogin = ({
  callbackPath,
  loginToolset,
  logoutToolset,
  getToolset,
}: UseToolsetLoginParams): UseToolsetLoginResult => {
  const logoutLevel = useCallback(
    async (
      toolsetId: string,
      credentialsLevel: ToolsetCredentialsLevel,
      authenticationType: ToolsetAuthTypes,
    ): Promise<void> => {
      try {
        await logoutToolset(toolsetId, {
          url: toolsetId,
          credentialsLevel:
            credentialsLevel as ToolsetLogoutBodyDto['credentialsLevel'],
          authenticationType:
            authenticationType as ToolsetLogoutBodyDto['authenticationType'],
        });
      } catch {
        // Best-effort: a failed pre-emptive logout should not block the retry.
      }
    },
    [logoutToolset],
  );

  const loginWithOAuth = useCallback(
    async (params: ToolsetLoginParams): Promise<ToolsetLoginOutcome> => {
      const {
        toolsetId,
        credentialsLevel,
        oauthSettings,
        forceStale,
        offlineUsageConsent,
      } = params;
      const authSettings: ToolsetOAuthSettings = {
        clientId: oauthSettings?.clientId,
        authorizationEndpoint: oauthSettings?.authorizationEndpoint,
        scopes: oauthSettings?.scopes,
        codeChallenge: oauthSettings?.codeChallenge,
        codeChallengeMethod: oauthSettings?.codeChallengeMethod,
      };

      /*
       * When a pre-emptive logout is needed, the popup must still be opened
       * as the first, fully synchronous statement so the browser treats it
       * as user-triggered — `initiateOAuthLogin` does that internally, but
       * only when it runs with no `await` ahead of it. Opening the popup
       * blank first and navigating it after the logout (via
       * `navigateToolsetOAuthPopup`) preserves that guarantee even though a
       * network call now has to happen before the provider URL is known.
       */
      const initiation = forceStale
        ? await (async () => {
            const popup = openToolsetOAuthPopup();
            if (!popup) {
              return {
                type: ToolsetOAuthInitiationResultType.Blocked,
              } as const;
            }
            await logoutLevel(
              toolsetId,
              credentialsLevel,
              ToolsetAuthTypes.OAuth,
            );
            return navigateToolsetOAuthPopup(
              popup,
              authSettings,
              toolsetId,
              callbackPath,
              credentialsLevel,
              OAuthResourceKind.Toolset,
              offlineUsageConsent,
            );
          })()
        : initiateOAuthLogin(
            authSettings,
            toolsetId,
            callbackPath,
            credentialsLevel,
            offlineUsageConsent,
          );

      if (initiation.type === ToolsetOAuthInitiationResultType.Blocked) {
        return { type: ToolsetLoginOutcomeType.PopupBlocked };
      }
      if (initiation.type !== ToolsetOAuthInitiationResultType.Started) {
        return { type: ToolsetLoginOutcomeType.Failure };
      }

      const result = await waitForToolsetOAuthResult(
        initiation.popup,
        initiation.flowId,
        {
          toolsetId,
          credentialsLevel,
          callbackPath,
        },
      );

      if (result.type === ToolsetOAuthResultType.Success) {
        emitToolsetLoginSuccess<ToolsetCredentialsLevel>({
          toolsetId,
          credentialsLevel,
        });
        return { type: ToolsetLoginOutcomeType.Success };
      }
      if (result.type === ToolsetOAuthResultType.Failure) {
        return { type: ToolsetLoginOutcomeType.Failure };
      }

      /*
       * Treat the backend as the final authority if popup tracking or
       * cross-process message delivery ever still reports a false cancel.
       * This avoids reporting cancellation for a login that actually
       * completed server-side.
       */
      try {
        const refreshed = await getToolset(toolsetId);
        const statusField =
          credentialsLevel === ToolsetCredentialsLevel.User
            ? refreshed.authSettings?.userLevelAuthStatus
            : refreshed.authSettings?.globalAuthStatus;
        if (statusField === ToolsetAuthStatus.SignedIn) {
          emitToolsetLoginSuccess<ToolsetCredentialsLevel>({
            toolsetId,
            credentialsLevel,
          });
          return { type: ToolsetLoginOutcomeType.Success };
        }
      } catch {
        // Best-effort verification only — a genuine cancel stays silent.
      }
      return { type: ToolsetLoginOutcomeType.Cancelled };
    },
    [callbackPath, getToolset, logoutLevel],
  );

  const loginWithApiKey = useCallback(
    async (params: ToolsetLoginParams): Promise<ToolsetLoginOutcome> => {
      const {
        toolsetId,
        credentialsLevel,
        authenticationType,
        apiKey,
        isCurrentlyFailed,
        forceStale,
        offlineUsageConsent,
      } = params;

      try {
        if (forceStale || isCurrentlyFailed) {
          await logoutLevel(toolsetId, credentialsLevel, authenticationType);
        }
        const body: ToolsetLoginBodyDto = {
          url: toolsetId,
          credentialsLevel:
            credentialsLevel as ToolsetLoginBodyDto['credentialsLevel'],
          authenticationType:
            authenticationType as ToolsetLoginBodyDto['authenticationType'],
          apiKey: apiKey?.trim(),
          offlineUsageConsent,
        };
        await loginToolset(toolsetId, body);
        emitToolsetLoginSuccess<ToolsetCredentialsLevel>({
          toolsetId,
          credentialsLevel,
        });
        return { type: ToolsetLoginOutcomeType.Success };
      } catch {
        return { type: ToolsetLoginOutcomeType.Failure };
      }
    },
    [loginToolset, logoutLevel],
  );

  const login = useCallback(
    (params: ToolsetLoginParams): Promise<ToolsetLoginOutcome> =>
      params.authenticationType === ToolsetAuthTypes.OAuth
        ? loginWithOAuth(params)
        : loginWithApiKey(params),
    [loginWithOAuth, loginWithApiKey],
  );

  return { login };
}

export interface ExportedPrompt {
  /** Prompt path within the prompts namespace, doubling as its stable id. */
  id: string;
  /** Display name. */
  name: string;
  /** Description, empty when the prompt has none. */
  description: string;
  /** Prompt text, `{{variable}}` placeholders included verbatim. */
  content: string;
  /** Parent folder path; absent for a root-level prompt. */
  folderId?: string;
}

export interface PromptExportFormat {
  /** Format version discriminator, shared with the conversation export envelope. */
  version: 5;
  /** Exported prompts. */
  prompts: ExportedPrompt[];
  /** Folders the exported prompts belong to, outermost first. */
  folders: ExportFolder[];
}

buildPromptExportEnvelope = (
  prompt: PromptResponseDto,
): PromptExportFormat => ({
  version: 5,
  prompts: [
    {
      id: prompt.id,
      name: prompt.name,
      description: prompt.description ?? '',
      content: prompt.content,
      ...(prompt.folderId ? { folderId: prompt.folderId } : undefined),
    },
  ],
  folders: buildFolderChain(prompt.folderId),
})

buildPromptExportFileName = (
  promptName: string,
  appName: string,
  date: Date = new Date(),
): string => {
  const safeName = promptName.replace(FILE_NAME_UNSAFE_PATTERN, '_');
  return `${formatDateYMD(date)}_${appName}_prompt_${safeName}.json`;
}

export enum PromptFieldError {
  /** The field is required and was left empty. */
  Required = 'required',
  /** The value exceeds the backend's length limit for the field. */
  TooLong = 'tooLong',
  /** The name contains characters the backend's allowlist rejects. */
  InvalidName = 'invalidName',
  /** The backend reported an existing prompt or folder at the target path. */
  Conflict = 'conflict',
}

validatePromptName = (name: string): PromptFieldError | null => {
  const trimmed = name.trim();
  if (trimmed.length === 0) return PromptFieldError.Required;
  if (trimmed.length > PROMPT_NAME_MAX_LENGTH) return PromptFieldError.TooLong;
  if (!PROMPT_NAME_PATTERN.test(trimmed)) return PromptFieldError.InvalidName;
  return null;
}

validatePromptContent = (
  content: string,
): PromptFieldError | null => {
  if (content.trim().length === 0) return PromptFieldError.Required;
  if (content.length > PROMPT_CONTENT_MAX_LENGTH) {
    return PromptFieldError.TooLong;
  }
  return null;
}

getRemainingCharacters = (
  value: string,
  maxLength: number,
): number | null => {
  const remaining = maxLength - value.length;
  return remaining <= PROMPT_COUNTER_ANNOUNCE_THRESHOLD ? remaining : null;
}

export enum PromptSource {
  /** The caller's own prompt, editable and deletable by them. */
  Personal = 'personal',
  /** Shared with the caller by another user; permissions determine editability. */
  SharedWithMe = 'sharedWithMe',
  /** Organisation-wide prompt; read-only for every user. */
  Public = 'public',
}

export interface ParsedPromptResourceUrl {
  /** DIAL Core bucket name. */
  bucket: string;
  /** Path to the prompt within that bucket. */
  path: string;
}

parsePromptResourceUrl = (
  url: string,
): ParsedPromptResourceUrl | null => {
  if (!url.startsWith(PROMPT_RESOURCE_PREFIX)) return null;
  const rest = url.slice(PROMPT_RESOURCE_PREFIX.length);
  const slashIndex = rest.indexOf('/');
  if (slashIndex <= 0) return null;
  const bucket = rest.slice(0, slashIndex);
  const path = rest.slice(slashIndex + 1);
  if (bucket === '' || path === '') return null;
  return { bucket, path };
}

export interface UsePromptsStateParams {
  /** Fetches the aggregate prompt listing from the server. */
  listPrompts: () => Promise<PromptListResponseDto>;
}

export interface UsePromptsStateResult {
  /** The caller's own prompts. */
  prompts: PromptResponseDto[];
  /** Folders in the caller's own prompt namespace. */
  folders: PromptFolderResponseDto[];
  /** Prompts other users have shared with the caller. */
  sharedWithMe: PromptResponseDto[];
  /** Organisation-wide (public) prompts, read-only for every user. */
  publicPrompts: PromptResponseDto[];
  /** Folders in the organisation prompt namespace. */
  publicFolders: PromptFolderResponseDto[];
  /** True until the aggregate prompt listing has settled. */
  isLoading: boolean;
  /** Rejection reason of the most recent failed list request, or `null`. */
  error: unknown;
  /** Re-reads personal, shared-with-me, and organisation prompts. */
  refetch: () => Promise<void>;
  /** Compatibility alias for the aggregate refetch — same function reference as `refetch`. */
  refetchPublicPrompts: () => Promise<void>;
}

usePromptsState = ({
  listPrompts,
}: UsePromptsStateParams): UsePromptsStateResult => {
  const [prompts, setPrompts] = useState<PromptResponseDto[]>([]);
  const [folders, setFolders] = useState<PromptFolderResponseDto[]>([]);
  const [sharedWithMe, setSharedWithMe] = useState<PromptResponseDto[]>([]);
  const [publicPrompts, setPublicPrompts] = useState<PromptResponseDto[]>([]);
  const [publicFolders, setPublicFolders] = useState<PromptFolderResponseDto[]>(
    [],
  );
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<unknown>(null);

  const refetch = useCallback(async () => {
    try {
      const response = await listPrompts();
      setPrompts(response.prompts);
      setFolders(response.folders);
      setSharedWithMe(response.sharedWithMe);
      setPublicPrompts(response.publicPrompts ?? []);
      setPublicFolders(response.publicFolders ?? []);
      setError(null);
    } catch (err) {
      setError(err);
    }
  }, [listPrompts]);

  useEffect(() => {
    const cancelled = { value: false };

    const load = async () => {
      const response = await listPrompts().catch((reason: unknown) => {
        if (!cancelled.value) setError(reason);
        return null;
      });
      if (cancelled.value) return;

      if (response != null) {
        setPrompts(response.prompts);
        setFolders(response.folders);
        setSharedWithMe(response.sharedWithMe);
        setPublicPrompts(response.publicPrompts ?? []);
        setPublicFolders(response.publicFolders ?? []);
        setError(null);
      }

      setIsLoading(false);
    };

    load();

    return () => {
      cancelled.value = true;
    };
  }, [listPrompts]);

  return useMemo(
    () => ({
      prompts,
      folders,
      sharedWithMe,
      publicPrompts,
      publicFolders,
      isLoading,
      error,
      refetch,
      refetchPublicPrompts: refetch,
    }),
    [
      prompts,
      folders,
      sharedWithMe,
      publicPrompts,
      publicFolders,
      isLoading,
      error,
      refetch,
    ],
  );
}

export enum UnsupportedTriggerReason {
  /** `trigger.cron.fields` uses a shape (extra keys, or both `day_of_week` and `day`) the editor's schedule controls cannot represent. */
  UnsupportedCronShape = 'unsupportedCronShape',
  /** Neither or both of `trigger.date`/`trigger.cron` are set, so the schedule type cannot be determined. */
  UnsupportedTriggerType = 'unsupportedTriggerType',
  /** The task is missing `model` or `prompt`, so it cannot be represented as a valid update payload. */
  MissingRequiredFields = 'missingRequiredFields',
}

export type ScheduledTaskDtoMappingResult =
  | { ok: true; values: ScheduledTaskCreateFormValues }
  | { ok: false; reason: UnsupportedTriggerReason };

mapFormValuesToCreateBody = (
  values: ScheduledTaskCreateFormValues,
): CreateScheduledTaskBodyDto => {
  const trigger: ScheduleTriggerDto =
    values.repeat === ScheduledTaskRepeat.OneTime
      ? { date: new Date(values.runAt ?? '').toISOString() }
      : {
          cron: {
            fields: buildCronFields(values),
            ...(values.startDate
              ? {
                  startDate: buildCronWindowBoundary(
                    values.startDate,
                    CronWindowEdge.Start,
                  ),
                }
              : {}),
            ...(values.endDate
              ? {
                  endDate: buildCronWindowBoundary(
                    values.endDate,
                    CronWindowEdge.End,
                  ),
                }
              : {}),
          },
        };

  const trimmedDescription = values.description?.trim();

  return {
    displayName: values.displayName.trim(),
    trigger,
    model: values.modelId,
    prompt: values.prompt.trim(),
    ...(trimmedDescription ? { description: trimmedDescription } : {}),
  };
}

mapFormValuesToUpdateBody = (
  values: ScheduledTaskCreateFormValues,
): UpdateScheduledTaskBodyDto => mapFormValuesToCreateBody(values)

mapScheduledTaskDtoToFormValues = (
  dto: ScheduledTaskDto,
): ScheduledTaskDtoMappingResult => {
  if (!dto.model || !dto.prompt) {
    return {
      ok: false,
      reason: UnsupportedTriggerReason.MissingRequiredFields,
    };
  }

  const { date, cron } = dto.trigger;
  const hasDate = !!date;
  const hasCron = !!cron;
  if (hasDate === hasCron) {
    return {
      ok: false,
      reason: UnsupportedTriggerReason.UnsupportedTriggerType,
    };
  }

  const base: Pick<
    ScheduledTaskCreateFormValues,
    'displayName' | 'modelId' | 'prompt' | 'description'
  > = {
    displayName: dto.displayName,
    modelId: dto.model,
    prompt: dto.prompt,
    ...(dto.description ? { description: dto.description } : {}),
  };

  if (hasDate) {
    return {
      ok: true,
      values: {
        ...base,
        repeat: ScheduledTaskRepeat.OneTime,
        runAt: isoToLocalDateTime(date as string),
        time: DEFAULT_TIME_PLACEHOLDER,
      },
    };
  }

  if (!cron) {
    return {
      ok: false,
      reason: UnsupportedTriggerReason.UnsupportedTriggerType,
    };
  }

  const parsed = parseCronFields(cron.fields);
  if (!parsed.ok) {
    return { ok: false, reason: UnsupportedTriggerReason.UnsupportedCronShape };
  }

  if (parsed.isHourly) {
    return {
      ok: true,
      values: {
        ...base,
        repeat: ScheduledTaskRepeat.Hourly,
        time: DEFAULT_TIME_PLACEHOLDER,
        minute: parsed.minute,
        ...(cron.startDate
          ? { startDate: isoToLocalDateOnly(cron.startDate) }
          : {}),
        ...(cron.endDate ? { endDate: isoToLocalDateOnly(cron.endDate) } : {}),
      },
    };
  }

  let repeat = ScheduledTaskRepeat.Daily;
  if (parsed.dayOfWeek) {
    repeat = ScheduledTaskRepeat.Weekly;
  } else if (parsed.dayOfMonth) {
    repeat = ScheduledTaskRepeat.Monthly;
  }

  return {
    ok: true,
    values: {
      ...base,
      repeat,
      time: parsed.time,
      ...(parsed.dayOfWeek ? { dayOfWeek: parsed.dayOfWeek } : {}),
      ...(parsed.dayOfMonth ? { dayOfMonth: parsed.dayOfMonth } : {}),
      ...(cron.startDate
        ? { startDate: isoToLocalDateOnly(cron.startDate) }
        : {}),
      ...(cron.endDate ? { endDate: isoToLocalDateOnly(cron.endDate) } : {}),
    },
  };
}

isValidSkillRelativePath = (relativePath: string): boolean => {
  if (relativePath === '' || relativePath.startsWith('/')) return false;
  if (WINDOWS_DRIVE_PATTERN.test(relativePath)) return false;
  if (relativePath.includes('\\')) return false;
  if (CONTROL_CHAR_PATTERN.test(relativePath)) return false;

  const segments = relativePath.split('/');
  if (
    segments.some(
      (segment) => segment === '' || segment === '.' || segment === '..',
    )
  ) {
    return false;
  }
  if (segments.some((segment) => RESERVED_ENTRY_NAMES.has(segment))) {
    return false;
  }
  if (RESERVED_FIRST_SEGMENTS.has(segments[0])) {
    return false;
  }

  return true;
}

normalizeSkillName = (input: string): string => {
  const hyphenated = input.toLowerCase().replace(/[^a-z0-9]+/g, '-');
  /*
   * Each run of invalid characters above collapses to a single hyphen, so at
   * most one hyphen can sit at either end — trimming one character per side is
   * enough. A `/^-+|-+$/` regex would be equivalent but quadratic: repetition
   * anchored at `$` with an unanchored start makes the engine retry from every
   * offset (CodeQL js/polynomial-redos).
   */
  return hyphenated.replace(/^-/, '').replace(/-$/, '');
}

export interface SkillManifestValues {
  /** Normalized skill name. */
  name: string;
  /** Short description of what the skill does. */
  description: string;
  /** The skill's instructions body (Markdown). */
  instructions: string;
}

buildSkillManifest = ({
  name,
  description,
  instructions,
}: SkillManifestValues): string => {
  const frontmatter = stringify({ name, description }).trimEnd();
  return `---\n${frontmatter}\n---\n\n${instructions}`;
}

buildSkillManifestFromFrontmatter = (
  baseFrontmatter: Record<string, unknown>,
  name: string,
  description: string,
  instructions: string,
): string => {
  const merged = { ...baseFrontmatter, name, description };
  const frontmatter = stringify(merged).trimEnd();
  return `---\n${frontmatter}\n---\n\n${instructions}`;
}

export interface ParsedSkillManifest {
  /** The full parsed frontmatter object, including fields this app never renders. */
  frontmatter: Record<string, unknown>;
  /** The instructions body following the closing `---` delimiter. */
  instructions: string;
}

parseSkillManifest = (
  manifestText: string,
): ParsedSkillManifest => {
  const match = FRONTMATTER_PATTERN.exec(manifestText);
  if (!match) {
    throw new Error('SKILL.md is missing its YAML frontmatter block');
  }
  const [, frontmatterText, rest] = match;
  const frontmatter = (parse(frontmatterText) ?? {}) as Record<string, unknown>;
  const instructions = rest.replace(/^\r?\n/, '');
  return { frontmatter, instructions };
}

export interface UnpackedSkillArchive {
  /** The root `SKILL.md` entry's decoded text content. */
  manifestText: string;
  /** Every non-manifest entry, keyed by relative path. */
  files: Map<string, Uint8Array>;
}

unpackSkillArchive = (bytes: Uint8Array): UnpackedSkillArchive => {
  const entries = unzipSync(bytes);
  const manifestBytes = entries[SKILL_MANIFEST_FILE];
  if (manifestBytes == null) {
    throw new Error(
      `Skill archive is missing a root ${SKILL_MANIFEST_FILE} file`,
    );
  }

  const files = new Map<string, Uint8Array>();
  for (const [path, content] of Object.entries(entries)) {
    if (path === SKILL_MANIFEST_FILE || path.endsWith('/')) continue;
    files.set(path, content);
  }

  return {
    manifestText: new TextDecoder().decode(manifestBytes),
    files,
  };
}

nameFromPath = (path: string): string => {
  const lastSlash = path.lastIndexOf('/');
  return lastSlash === -1 ? path : path.slice(lastSlash + 1);
}

export interface SkillFilesPayload {
  /** Relative paths, positionally paired with `files`. */
  filePaths: string[];
  /** File contents, positionally paired with `filePaths`. */
  files: Blob[];
}

buildSkillFilesPayload = (
  files: SkillFileTreeNode[],
  filesContent: Map<string, SkillFileContent>,
): SkillFilesPayload => {
  const fileNodes = files.filter(
    (node) => node.kind === SkillFileNodeKind.File,
  );
  return {
    filePaths: fileNodes.map((node) => node.path),
    files: fileNodes.map((node) =>
      skillFileBytesToBlob(
        filesContent.get(node.path)?.bytes ?? new Uint8Array(0),
      ),
    ),
  };
}

export interface SkillManifestImportCandidate {
  /** The `SkillFileUploadCandidate.id` this manifest came from. */
  candidateId: string;
  /** The imported manifest's `name` field. */
  name: string;
  /** The imported manifest's `description` field. */
  description: string;
  /** The imported manifest's full parsed frontmatter, including unknown fields. */
  frontmatter: Record<string, unknown>;
  /** The imported manifest's instructions body. */
  instructions: string;
}

export interface SkillFileBatchValidationMessages {
  /** Shown when a required field (e.g. a candidate's path) is empty. */
  required: string;
  /** Shown when a candidate's path collides with a reserved entry name. */
  pathReserved: string;
  /** Shown when a candidate's path fails DIAL's relative-path rules. */
  pathInvalid: string;
  /** Shown when a candidate's path duplicates another candidate or an existing file. */
  pathDuplicate: string;
  /** Shown when a candidate exceeds the per-file size limit; receives the formatted limit. */
  fileTooLarge: (maxSize: string) => string;
  /** Shown when a root-level `SKILL.md`-like path has the wrong casing. */
  manifestCasingInvalid: string;
  /** Shown when the batch stages more than one root `SKILL.md`. */
  manifestDuplicate: string;
  /** Shown when a root `SKILL.md`'s bytes are not valid UTF-8. */
  manifestInvalidUtf8: string;
  /** Shown when a root `SKILL.md`'s frontmatter is missing or missing `name`/`description`. */
  manifestInvalidFrontmatter: string;
  /** Shown when the batch's projected total package size exceeds the limit. */
  totalSizeExceeded: string;
  /** Shown when the batch's projected total file count exceeds the limit. */
  totalCountExceeded: string;
}

export interface SkillFileBatchValidationContext {
  /** Paths already present in the editor's supporting-file tree. */
  existingPaths: string[];
  /** Sum of the bytes already held for existing supporting files. */
  existingTotalBytes: number;
  /** UTF-8 byte length of the currently generated/loaded root `SKILL.md`. */
  manifestByteLength: number;
  /** Localized messages. */
  messages: SkillFileBatchValidationMessages;
}

export interface SkillFileBatchValidationOutcome {
  /** One result per candidate, in the same order as the input. */
  results: SkillFileValidationResult[];
  /** Batch-level errors (projected total size/count, multiple manifests). */
  batchErrors: SkillFileBatchError[];
  /** The single accepted manifest import, when the batch has exactly one valid `SKILL.md`. */
  manifestCandidate?: SkillManifestImportCandidate;
}

validateSkillFileBatch = async (
  candidates: SkillFileUploadCandidate[],
  context: SkillFileBatchValidationContext,
): Promise<SkillFileBatchValidationOutcome> => {
  const { existingPaths, existingTotalBytes, manifestByteLength, messages } =
    context;
  const results: SkillFileValidationResult[] = [];
  const batchErrors: SkillFileBatchError[] = [];
  const existingPathSet = new Set(existingPaths);

  // Count occurrences of each supporting-file path up front, so every
  // candidate sharing a duplicated path is marked invalid — not just the
  // second (and later) occurrences.
  const pathOccurrences = new Map<string, number>();
  for (const { path } of candidates) {
    if (path === SKILL_MANIFEST_FILE) continue;
    pathOccurrences.set(path, (pathOccurrences.get(path) ?? 0) + 1);
  }

  let stagedSupportingBytes = 0;
  const countedSupportingPaths = new Set<string>();
  let manifestCandidate: SkillManifestImportCandidate | undefined;
  let manifestFileSize = manifestByteLength;
  let manifestCandidateCount = 0;

  for (const candidate of candidates) {
    const { id, file, path } = candidate;
    let error: string | undefined;
    let kind = SkillFileCandidateKind.SupportingFile;

    const isRootManifestCasingVariant =
      path.toLowerCase() === SKILL_MANIFEST_FILE.toLowerCase() &&
      path !== SKILL_MANIFEST_FILE;

    if (isRootManifestCasingVariant) {
      error = messages.manifestCasingInvalid;
    } else if (path === SKILL_MANIFEST_FILE) {
      kind = SkillFileCandidateKind.Manifest;
      manifestCandidateCount += 1;
      if (file.size > SKILL_FILE_UPLOAD_MAX_BYTES) {
        error = messages.fileTooLarge(
          formatFileSize(SKILL_FILE_UPLOAD_MAX_BYTES),
        );
      } else {
        try {
          const text = await file.text();
          if (text.includes('�')) {
            error = messages.manifestInvalidUtf8;
          } else {
            const { frontmatter, instructions } = parseSkillManifest(text);
            const name =
              typeof frontmatter.name === 'string' ? frontmatter.name : '';
            const description =
              typeof frontmatter.description === 'string'
                ? frontmatter.description
                : '';
            if (!name.trim() || !description.trim()) {
              error = messages.manifestInvalidFrontmatter;
            } else if (manifestCandidateCount === 1) {
              manifestCandidate = {
                candidateId: id,
                name,
                description,
                frontmatter,
                instructions,
              };
              manifestFileSize = file.size;
            }
          }
        } catch {
          error = messages.manifestInvalidFrontmatter;
        }
      }
    } else if (!path) {
      error = messages.required;
    } else if (!isValidSkillRelativePath(path)) {
      error = messages.pathInvalid;
    } else if (
      existingPathSet.has(path) ||
      (pathOccurrences.get(path) ?? 0) > 1
    ) {
      error = messages.pathDuplicate;
    } else if (file.size > SKILL_FILE_UPLOAD_MAX_BYTES) {
      error = messages.fileTooLarge(
        formatFileSize(SKILL_FILE_UPLOAD_MAX_BYTES),
      );
    }

    if (!error && kind === SkillFileCandidateKind.SupportingFile) {
      countedSupportingPaths.add(path);
      stagedSupportingBytes += file.size;
    }

    results.push({
      candidateId: id,
      status: error
        ? SkillFileValidationStatus.Invalid
        : SkillFileValidationStatus.Valid,
      kind,
      error,
    });
  }

  if (manifestCandidateCount > 1) {
    batchErrors.push({ message: messages.manifestDuplicate });
    manifestCandidate = undefined;
    manifestFileSize = manifestByteLength;
    for (const result of results) {
      if (result.kind === SkillFileCandidateKind.Manifest && !result.error) {
        result.status = SkillFileValidationStatus.Invalid;
        result.error = messages.manifestDuplicate;
      }
    }
  }

  const projectedTotalBytes =
    existingTotalBytes + stagedSupportingBytes + manifestFileSize;
  if (projectedTotalBytes > SKILL_UPLOAD_MAX_TOTAL_BYTES) {
    batchErrors.push({ message: messages.totalSizeExceeded });
  }

  const projectedTotalFiles =
    existingPathSet.size + countedSupportingPaths.size + 1;
  if (projectedTotalFiles > SKILL_UPLOAD_MAX_FILES) {
    batchErrors.push({ message: messages.totalCountExceeded });
  }

  return { results, batchErrors, manifestCandidate };
}

export interface SkillFileContent {
  /** The file's raw bytes. */
  bytes: Uint8Array;
  /**
   * MIME type from the original browser `File.type`. Omit for edit-mode ZIP
   * entries, which carry no MIME metadata — the type is then inferred from
   * the file's path.
   */
  mimeType?: string;
}

skillFileToAttachment = (
  node: SkillFileTreeNode,
  content: SkillFileContent,
): Attachment => {
  const contentType =
    content.mimeType || inferMimeTypeFromPath(node.path) || '';
  const file = new File(
    [new Uint8Array(content.bytes)],
    node.name,
    contentType ? { type: contentType } : undefined,
  );

  return {
    id: node.path,
    name: node.name,
    contentType,
    type: getAttachmentTypeFromMime(contentType),
    status: RequestStatus.Idle,
    file,
  };
}

export enum SkillEditorLoadState {
  /** The edit-mode download/parse flow is in flight. */
  Loading = 'loading',
  /** The skill loaded successfully (or create mode, which starts here). */
  Loaded = 'loaded',
  /** The download/parse flow failed for a reason other than 403/404. */
  Error = 'error',
  /** The caller lacks permission to read the skill. */
  Forbidden = 'forbidden',
  /** The skill no longer exists at the given path. */
  NotFound = 'not-found',
}

export interface SkillEditorLoadClient {
  /** Downloads the whole-skill ZIP archive. */
  downloadSkill: (bucket: string, path: string) => Promise<Response>;
  /** Downloads one file within the skill (the manifest or a supporting file). */
  downloadSkillFile: (
    bucket: string,
    path: string,
    filePath: string,
  ) => Promise<Response>;
  /** Lists the skill's files when the whole-skill ZIP route is unusable. */
  listSkillFiles: (params: {
    bucket: string;
    path?: string;
    filePath: string;
    recursive?: boolean;
  }) => Promise<SkillFileListResponseDto>;
}

export interface UseSkillEditorLoadParams {
  /** Whether the form is editing an existing skill rather than creating a new one. */
  isEditMode: boolean;
  /** DIAL Core bucket holding the skill. Load is skipped until this resolves. */
  bucket: string | undefined;
  /** Path to the skill within `bucket`. */
  skillPath: string | null | undefined;
  /** Already-configured download operations. */
  client: SkillEditorLoadClient;
}

export interface UseSkillEditorLoadResult {
  /** Current load-state machine value driving the form's presentation. */
  loadState: SkillEditorLoadState;
  /** The loaded (or, in create mode, seeded) manifest values. */
  loadedValues: SkillEditorValues | undefined;
  /** Updates `loadedValues`, e.g. after a manifest import. */
  setLoadedValues: Dispatch<SetStateAction<SkillEditorValues | undefined>>;
  /** The loaded supporting-file tree. */
  files: SkillFileTreeNode[];
  /** Updates `files`, e.g. after a batch commit or node removal. */
  setFiles: Dispatch<SetStateAction<SkillFileTreeNode[]>>;
  /** In-memory bytes for every supporting file, keyed by relative path. */
  filesContentRef: React.MutableRefObject<Map<string, SkillFileContent>>;
  /** The loaded manifest's full parsed frontmatter, including fields the form never renders. */
  frontmatterRef: React.MutableRefObject<Record<string, unknown>>;
  /** The concurrency ETag from the load, sent back as `If-Match` on save. */
  etagRef: React.MutableRefObject<string | undefined>;
  /** The skill path the currently loaded state belongs to. */
  loadedPathRef: React.MutableRefObject<string | undefined>;
  /** Re-attempts the edit-mode download (load-error retry or post-conflict reload). */
  retryLoad: () => void;
}

useSkillEditorLoad = ({
  isEditMode,
  bucket,
  skillPath,
  client,
}: UseSkillEditorLoadParams): UseSkillEditorLoadResult => {
  const [loadState, setLoadState] = useState<SkillEditorLoadState>(
    isEditMode ? SkillEditorLoadState.Loading : SkillEditorLoadState.Loaded,
  );
  const [loadAttempt, setLoadAttempt] = useState(0);
  const [loadedValues, setLoadedValues] = useState<
    SkillEditorValues | undefined
  >();
  const etagRef = useRef<string | undefined>(undefined);
  const frontmatterRef = useRef<Record<string, unknown>>({});
  const loadedPathRef = useRef<string | undefined>(undefined);

  const [files, setFiles] = useState<SkillFileTreeNode[]>([]);
  const filesContentRef = useRef<Map<string, SkillFileContent>>(new Map());

  useEffect(() => {
    if (!isEditMode || !bucket) return;
    if (skillPath == null) {
      setLoadState(SkillEditorLoadState.Error);
      return;
    }

    let cancelled = false;
    setLoadState(SkillEditorLoadState.Loading);

    (async () => {
      /*
       * Let StrictMode finish its development-only setup → cleanup → setup
       * cycle before opening a streaming HTTP response. Aborting that first
       * stream can make Vite's dev proxy write to an already-ended response.
       */
      await Promise.resolve();
      if (cancelled) return;

      try {
        let loadedSkill: LoadedSkill;
        try {
          loadedSkill = await loadSkillArchive(client, bucket, skillPath);
        } catch (error) {
          const status = getApiErrorStatus(error);
          if (!(error instanceof InvalidSkillArchiveError) && status !== 400) {
            throw error;
          }
          /*
           * Core installations differ in whole-skill ZIP behavior. The same
           * manifest/file endpoints used by Catalog details are the
           * compatibility path when the ZIP route resolves the skill as a
           * grouping folder or returns an unusable archive.
           */
          loadedSkill = await loadSkillFiles(client, bucket, skillPath);
        }
        const { frontmatter, instructions } = parseSkillManifest(
          loadedSkill.manifestText,
        );
        if (cancelled) return;

        etagRef.current = loadedSkill.etag;
        frontmatterRef.current = frontmatter;
        loadedPathRef.current = skillPath;
        filesContentRef.current = new Map(
          [...loadedSkill.files].map(([path, bytes]) => [path, { bytes }]),
        );
        setFiles(
          [...loadedSkill.files.keys()].map((path) => ({
            path,
            name: nameFromPath(path),
            kind: SkillFileNodeKind.File,
          })),
        );
        setLoadedValues({
          name: typeof frontmatter.name === 'string' ? frontmatter.name : '',
          description:
            typeof frontmatter.description === 'string'
              ? frontmatter.description
              : '',
          instructions,
        });
        setLoadState(SkillEditorLoadState.Loaded);
      } catch (err) {
        if (cancelled) return;
        const status = getApiErrorStatus(err);
        if (status === 403) setLoadState(SkillEditorLoadState.Forbidden);
        else if (status === 404) setLoadState(SkillEditorLoadState.NotFound);
        else setLoadState(SkillEditorLoadState.Error);
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [isEditMode, bucket, skillPath, loadAttempt, client]);

  return {
    loadState,
    loadedValues,
    setLoadedValues,
    files,
    setFiles,
    filesContentRef,
    frontmatterRef,
    etagRef,
    loadedPathRef,
    retryLoad: () => setLoadAttempt((attempt) => attempt + 1),
  };
}

export interface SkillEditorSubmitClient {
  /** Creates a new skill. */
  createSkill: (
    bucket: string,
    path: string,
    skillManifest: string,
    filePaths: string[],
    files: Blob[],
  ) => Promise<SkillUploadResponseDto>;
  /** Updates an existing skill, sending `ifMatch` as the concurrency guard. */
  updateSkill: (
    bucket: string,
    path: string,
    skillManifest: string,
    filePaths: string[],
    files: Blob[],
    ifMatch: string,
  ) => Promise<SkillUploadResponseDto>;
}

export interface SkillEditorSubmitMessages {
  /** Shown when a required field is empty. */
  required: string;
  /** Shown when the normalized skill name fails DIAL's naming rules. */
  nameInvalid: string;
  /** Shown when the skill name already exists (409), or defensively on an unreachable create-mode 412. */
  nameConflict: string;
  /** Shown when the submitted package exceeds the server's size limit (413). */
  archiveTooLarge: string;
  /** Shown when the backend is temporarily unavailable (503). */
  serviceUnavailable: string;
  /** Fallback shown for a 400 whose response body carries no message. */
  pathInvalid: string;
  /** Generic fallback shown for any other error status. */
  saveError: string;
  /** Notification title on a successful create. */
  saveSuccessTitle: string;
  /** Notification message on a successful create, given the created name. */
  createSuccess: (name: string) => string;
  /** Notification title on a successful update. */
  updateSuccessTitle: string;
  /** Notification message on a successful update, given the skill's name. */
  updateSuccess: (name: string) => string;
  /** Shown when a save hits a stale-ETag conflict (412) in edit mode. */
  conflictMessage: string;
}

export interface SkillEditorSubmitNotification {
  /** Notification style. */
  variant: NotificationVariant;
  /** Optional heading. */
  title?: string;
  /** Body text. */
  message: string;
  /** W3C trace ID, when the triggering error carried one. */
  requestId?: string;
}

export interface UseSkillEditorSubmitParams {
  /** DIAL Core bucket the skill is saved to. */
  bucket: string | undefined;
  /** Whether the form is editing an existing skill rather than creating a new one. */
  isEditMode: boolean;
  /** The editor's current supporting-file tree. */
  files: SkillFileTreeNode[];
  /** In-memory bytes for every supporting file, keyed by relative path. */
  filesContentRef: React.MutableRefObject<Map<string, SkillFileContent>>;
  /** The loaded (or imported) manifest's full parsed frontmatter. */
  frontmatterRef: React.MutableRefObject<Record<string, unknown>>;
  /** The path the currently loaded edit-mode state belongs to. */
  loadedPathRef: React.MutableRefObject<string | undefined>;
  /** The concurrency ETag from the load, sent back as `If-Match` on save. */
  etagRef: React.MutableRefObject<string | undefined>;
  /** Where to navigate on a successful save. */
  returnUrl: string;
  /** Refetches the host's skill listing after a successful save. */
  refetchSkills: () => Promise<void>;
  /** Already-configured create/update operations. */
  client: SkillEditorSubmitClient;
  /** Localized messages, resolved by the host. */
  messages: SkillEditorSubmitMessages;
  /** Called with `returnUrl` after a successful save. */
  onNavigate: (url: string) => void;
  /** Called to surface a host notification (success toast or unexpected-error toast). */
  onNotify: (notification: SkillEditorSubmitNotification) => void;
}

export interface UseSkillEditorSubmitResult {
  /** Current submit-phase. */
  phase: SubmitPhase;
  /** Inline field validation errors. */
  errors: SkillEditorErrors;
  /** General submit-time error, distinct from a stale-edit `conflict`. */
  submitError: string | undefined;
  /** Present when the last save hit a stale-ETag conflict. */
  conflict: { message: string } | undefined;
  /** Clears `conflict`, e.g. once the host has reloaded the latest skill. */
  clearConflict: () => void;
  /** Validates and submits the given form values. */
  handleSubmit: (values: SkillEditorValues) => Promise<void>;
}

useSkillEditorSubmit = ({
  bucket,
  isEditMode,
  files,
  filesContentRef,
  frontmatterRef,
  loadedPathRef,
  etagRef,
  returnUrl,
  refetchSkills,
  client,
  messages,
  onNavigate,
  onNotify,
}: UseSkillEditorSubmitParams): UseSkillEditorSubmitResult => {
  const [errors, setErrors] = useState<SkillEditorErrors>({});
  const [submitError, setSubmitError] = useState<string | undefined>();
  const [conflict, setConflict] = useState<{ message: string } | undefined>();
  const [phase, setPhase] = useState<SubmitPhase>('idle');
  const lastAttemptRef = useRef<LastAttempt | null>(null);

  const applyUploadErrorStatus = useCallback(
    async (err: unknown) => {
      const status = getApiErrorStatus(err);
      switch (status) {
        case 409:
          setErrors({ name: messages.nameConflict });
          return;
        case 412:
          /*
           * In edit mode this is a genuine stale-edit conflict, handled
           * separately by `handleSubmit` before this function is ever
           * called. In create mode it is unreachable (create never sends
           * `If-Match`) — treated defensively the same as `409` should it
           * ever occur, which would indicate an unexpected upstream change.
           */
          setErrors({ name: messages.nameConflict });
          return;
        case 413:
          setSubmitError(messages.archiveTooLarge);
          return;
        case 503:
          setSubmitError(messages.serviceUnavailable);
          return;
        case 400: {
          /*
           * A 400 has no single fixed cause (bad archive, rejected manifest
           * field, upstream request-shape issue, ...) — show the BFF's own
           * message (which now forwards DIAL Core's `upstreamMessage`)
           * instead of a fixed, potentially misleading guess.
           */
          const { message } = await getApiErrorDetails(err);
          setSubmitError(message ?? messages.pathInvalid);
          return;
        }
        default: {
          const { traceId } = await getApiErrorDetails(err);
          setSubmitError(messages.saveError);
          onNotify({
            variant: NotificationVariant.Error,
            message: messages.saveError,
            requestId: traceId,
          });
        }
      }
    },
    [messages, onNotify],
  );

  const handleSubmitCreate = useCallback(
    async (values: SkillEditorValues) => {
      const normalizedName = normalizeSkillName(values.name);
      if (!normalizedName || !isValidSkillRelativePath(normalizedName)) {
        setErrors({ name: messages.nameInvalid });
        return;
      }

      const fingerprint = fingerprintAttempt(values, files);
      const cached = lastAttemptRef.current;
      const canReuse = cached != null && cached.fingerprint === fingerprint;

      const path = normalizedName;
      let skillManifest: string;
      let filePaths: string[];
      let fileBlobs: Blob[];
      if (canReuse) {
        ({ skillManifest, filePaths, files: fileBlobs } = cached);
      } else {
        /*
         * A dropped SKILL.md's unknown frontmatter fields (e.g. `version`)
         * are preserved by merging into the imported frontmatter object
         * rather than always building a fresh one — `frontmatterRef` stays
         * `{}` unless a manifest was imported in this create session.
         */
        skillManifest = buildSkillManifestForSubmit(
          frontmatterRef.current,
          normalizedName,
          values.description,
          values.instructions,
        );
        ({ filePaths, files: fileBlobs } = buildSkillFilesPayload(
          files,
          filesContentRef.current,
        ));
      }

      setPhase('submitting');
      lastAttemptRef.current = {
        fingerprint,
        bucket: bucket as string,
        path,
        skillManifest,
        filePaths,
        files: fileBlobs,
      };

      try {
        await client.createSkill(
          bucket as string,
          path,
          skillManifest,
          filePaths,
          fileBlobs,
        );
        await refetchSkills();

        setPhase('success');
        onNotify({
          variant: NotificationVariant.Success,
          title: messages.saveSuccessTitle,
          message: messages.createSuccess(normalizedName),
        });
        onNavigate(returnUrl);
      } catch (err) {
        setPhase('failure');
        await applyUploadErrorStatus(err);
      }
    },
    [
      bucket,
      files,
      filesContentRef,
      frontmatterRef,
      messages,
      client,
      onNotify,
      onNavigate,
      returnUrl,
      refetchSkills,
      applyUploadErrorStatus,
    ],
  );

  const handleSubmitEdit = useCallback(
    async (values: SkillEditorValues) => {
      const path = loadedPathRef.current;
      const etag = etagRef.current;
      if (!path || !etag) {
        setSubmitError(messages.saveError);
        return;
      }

      const skillManifest = buildSkillManifestForSubmit(
        frontmatterRef.current,
        values.name,
        values.description,
        values.instructions,
      );
      const { filePaths, files: fileBlobs } = buildSkillFilesPayload(
        files,
        filesContentRef.current,
      );

      setPhase('submitting');
      try {
        const result = await client.updateSkill(
          bucket as string,
          path,
          skillManifest,
          filePaths,
          fileBlobs,
          etag,
        );
        etagRef.current = result.etag ?? etag;
        await refetchSkills();

        setPhase('success');
        onNotify({
          variant: NotificationVariant.Success,
          title: messages.updateSuccessTitle,
          message: messages.updateSuccess(values.name),
        });
        onNavigate(returnUrl);
      } catch (err) {
        setPhase('failure');
        const status = getApiErrorStatus(err);
        if (status === 412) {
          setConflict({ message: messages.conflictMessage });
          return;
        }
        await applyUploadErrorStatus(err);
      }
    },
    [
      bucket,
      files,
      filesContentRef,
      frontmatterRef,
      loadedPathRef,
      etagRef,
      messages,
      client,
      onNotify,
      onNavigate,
      returnUrl,
      refetchSkills,
      applyUploadErrorStatus,
    ],
  );

  const handleSubmit = useCallback(
    async (values: SkillEditorValues) => {
      if (phase === 'submitting' || !bucket) return;

      const nextErrors: SkillEditorErrors = {};
      if (!values.name.trim()) nextErrors.name = messages.required;
      if (!values.description.trim()) {
        nextErrors.description = messages.required;
      }
      if (!values.instructions.trim()) {
        nextErrors.instructions = messages.required;
      }
      if (Object.keys(nextErrors).length > 0) {
        setErrors(nextErrors);
        return;
      }

      setErrors({});
      setSubmitError(undefined);
      setConflict(undefined);

      if (isEditMode) {
        await handleSubmitEdit(values);
      } else {
        await handleSubmitCreate(values);
      }
    },
    [phase, bucket, messages, isEditMode, handleSubmitEdit, handleSubmitCreate],
  );

  return {
    phase,
    errors,
    submitError,
    conflict,
    clearConflict: () => setConflict(undefined),
    handleSubmit,
  };
}

export interface SkillFileActionsMessages extends SkillFileBatchValidationMessages {
  /** Returned as the commit error when an imported manifest's `name` doesn't match the skill being edited. */
  manifestNameMismatch: string;
  /** Returned as the commit error when the user declines the manifest-import confirmation. */
  manifestImportDeclined: string;
  /** Generic fallback commit error for a batch with invalid candidates but no specific batch error. */
  saveError: string;
}

export interface UseSkillFileActionsParams {
  /** The editor's current supporting-file tree. */
  files: SkillFileTreeNode[];
  /** Updates `files`. */
  setFiles: Dispatch<SetStateAction<SkillFileTreeNode[]>>;
  /** In-memory bytes for every supporting file, keyed by relative path. */
  filesContentRef: React.MutableRefObject<Map<string, SkillFileContent>>;
  /** The loaded (or imported) manifest's full parsed frontmatter. */
  frontmatterRef: React.MutableRefObject<Record<string, unknown>>;
  /** The seeded baseline manifest values, used to approximate the projected total size. */
  loadedValues: SkillEditorValues | undefined;
  /** Updates `loadedValues` after a manifest import. */
  setLoadedValues: Dispatch<SetStateAction<SkillEditorValues | undefined>>;
  /** Whether the form is editing an existing skill rather than creating a new one. */
  isEditMode: boolean;
  /** Whether the form currently diverges from its seeded baseline. */
  isDirty: boolean;
  /** Updates the currently selected file-tree node path. */
  setSelectedPath: Dispatch<SetStateAction<string>>;
  /** Localized messages, resolved by the host. */
  messages: SkillFileActionsMessages;
}

export interface UseSkillFileActionsResult {
  /** File-tree mutation operations, passed straight to `SkillEditor`'s `fileActions` prop. */
  fileActions: SkillEditorFileActions;
  /** Whether the "replace Skill metadata?" confirmation prompt should be shown. */
  pendingManifestImport: boolean;
  /** Resolves the in-flight manifest-import confirmation with the user's choice. */
  resolveManifestImport: (accepted: boolean) => void;
}

useSkillFileActions = ({
  files,
  setFiles,
  filesContentRef,
  frontmatterRef,
  loadedValues,
  setLoadedValues,
  isEditMode,
  isDirty,
  setSelectedPath,
  messages,
}: UseSkillFileActionsParams): UseSkillFileActionsResult => {
  const [pendingManifestImport, setPendingManifestImport] = useState(false);
  const manifestImportResolveRef = useRef<((accepted: boolean) => void) | null>(
    null,
  );

  /*
   * The live in-progress name/description/instructions the user is typing
   * live only inside `libs/skill-editor`'s internal form state — this hook
   * only ever sees them via the host's `onSubmit`. `loadedValues` (the seeded
   * baseline) is therefore the closest available approximation of "the
   * current manifest" for the projected-total-size check; the BFF remains
   * the authoritative gate regardless of this estimate's precision.
   */
  const buildBatchValidationContext = useCallback(() => {
    const existingPaths = files
      .filter((node) => node.kind === SkillFileNodeKind.File)
      .map((node) => node.path);
    let existingTotalBytes = 0;
    for (const path of existingPaths) {
      existingTotalBytes +=
        filesContentRef.current.get(path)?.bytes.length ?? 0;
    }
    const baseline = {
      name: loadedValues?.name ?? '',
      description: loadedValues?.description ?? '',
      instructions: loadedValues?.instructions ?? '',
    };
    const manifestText = isEditMode
      ? buildSkillManifestFromFrontmatter(
          frontmatterRef.current,
          baseline.name,
          baseline.description,
          baseline.instructions,
        )
      : buildSkillManifest(baseline);
    return {
      existingPaths,
      existingTotalBytes,
      manifestByteLength: getUtf8ByteLength(manifestText),
      messages,
    };
  }, [
    files,
    filesContentRef,
    isEditMode,
    frontmatterRef,
    loadedValues,
    messages,
  ]);

  const confirmManifestImport = useCallback((): Promise<boolean> => {
    return new Promise<boolean>((resolve) => {
      manifestImportResolveRef.current = resolve;
      setPendingManifestImport(true);
    });
  }, []);

  const resolveManifestImport = useCallback((accepted: boolean) => {
    setPendingManifestImport(false);
    manifestImportResolveRef.current?.(accepted);
    manifestImportResolveRef.current = null;
  }, []);

  const fileActions = useMemo<SkillEditorFileActions>(
    () => ({
      validateBatch: async (candidates: SkillFileUploadCandidate[]) => {
        const { results, batchErrors } = await validateSkillFileBatch(
          candidates,
          buildBatchValidationContext(),
        );
        return { results, batchErrors };
      },
      commitBatch: async (candidates: SkillFileUploadCandidate[]) => {
        const { results, batchErrors, manifestCandidate } =
          await validateSkillFileBatch(
            candidates,
            buildBatchValidationContext(),
          );
        const hasInvalid = results.some((result) => result.error !== undefined);
        if (hasInvalid || batchErrors.length > 0) {
          return {
            error: batchErrors[0]?.message ?? messages.saveError,
          };
        }

        if (manifestCandidate) {
          if (
            isEditMode &&
            manifestCandidate.name !== (loadedValues?.name ?? '')
          ) {
            return { error: messages.manifestNameMismatch };
          }
          if (isEditMode || isDirty) {
            const accepted = await confirmManifestImport();
            if (!accepted) {
              return { error: messages.manifestImportDeclined };
            }
          }
        }

        try {
          const supportingCandidates = candidates.filter(
            (candidate) => candidate.id !== manifestCandidate?.candidateId,
          );
          const reads = await Promise.all(
            supportingCandidates.map(async (candidate) => ({
              path: candidate.path,
              bytes: new Uint8Array(await candidate.file.arrayBuffer()),
              mimeType: candidate.file.type || undefined,
            })),
          );

          for (const read of reads) {
            filesContentRef.current.set(read.path, {
              bytes: read.bytes,
              mimeType: read.mimeType,
            });
          }
          if (reads.length > 0) {
            setFiles((prev) => [
              ...prev,
              ...reads.map((read) => ({
                path: read.path,
                name: nameFromPath(read.path),
                kind: SkillFileNodeKind.File,
              })),
            ]);
          }

          if (manifestCandidate) {
            frontmatterRef.current = isEditMode
              ? { ...frontmatterRef.current, ...manifestCandidate.frontmatter }
              : manifestCandidate.frontmatter;
            setLoadedValues({
              name: isEditMode
                ? (loadedValues?.name ?? manifestCandidate.name)
                : manifestCandidate.name,
              description: manifestCandidate.description,
              instructions: manifestCandidate.instructions,
            });
          }

          return {};
        } catch (err) {
          return { error: err instanceof Error ? err.message : String(err) };
        }
      },
      onRemoveNode: (path) => {
        setFiles((prev) =>
          prev.filter(
            (node) => node.path !== path && !node.path.startsWith(`${path}/`),
          ),
        );
        for (const key of [...filesContentRef.current.keys()]) {
          if (key === path || key.startsWith(`${path}/`)) {
            filesContentRef.current.delete(key);
          }
        }
        setSelectedPath((prev) =>
          prev === path || prev.startsWith(`${path}/`)
            ? SKILL_MANIFEST_FILE
            : prev,
        );
      },
    }),
    [
      buildBatchValidationContext,
      isEditMode,
      isDirty,
      loadedValues,
      confirmManifestImport,
      filesContentRef,
      frontmatterRef,
      setFiles,
      setLoadedValues,
      setSelectedPath,
      messages,
    ],
  );

  return { fileActions, pendingManifestImport, resolveManifestImport };
}

export enum SkillPreviewErrorKind {
  /** HTTP 403 — the caller lacks permission to read this file. */
  Forbidden = 'forbidden',
  /** Any non-403 load failure. */
  Generic = 'generic',
}

export interface UseSkillFilePreviewOptions {
  /**
   * Opaque id of the selected skill file. Changing this resets all state
   * and starts a new load; stale resolutions from the previous id are discarded.
   */
  fileId: string;
  /**
   * App-owned loader; resolves with the raw file bytes when the request
   * succeeds. The hook never constructs a URL or imports a REST client.
   */
  onLoadFile: (fileId: string) => Promise<SkillFileContent>;
}

export interface UseSkillFilePreviewResult {
  /** `true` while the async load is in flight. */
  isLoading: boolean;
  /** Resolved file content, or `null` while loading or after an error. */
  content: SkillFileContent | null;
  /** Classified load error, or `null` while loading or after a success. */
  error: SkillPreviewErrorKind | null;
}

useSkillFilePreview = ({
  fileId,
  onLoadFile,
}: UseSkillFilePreviewOptions): UseSkillFilePreviewResult => {
  const [isLoading, setIsLoading] = useState(false);
  const [content, setContent] = useState<SkillFileContent | null>(null);
  const [error, setError] = useState<SkillPreviewErrorKind | null>(null);

  useEffect(() => {
    let cancelled = false;
    setIsLoading(true);
    setContent(null);
    setError(null);

    const load = async () => {
      try {
        const result = await onLoadFile(fileId);
        if (cancelled) return;
        setContent(result);
        setIsLoading(false);
      } catch (err) {
        if (cancelled) return;
        const status = (err as { status?: number }).status;
        setError(
          status === 403
            ? SkillPreviewErrorKind.Forbidden
            : SkillPreviewErrorKind.Generic,
        );
        setIsLoading(false);
      }
    };

    void load();
    return () => {
      cancelled = true;
    };
  }, [fileId, onLoadFile]);

  return { isLoading, content, error };
}

export interface SkillAboutDetails {
  whenToUse?: string;
  allowedTools?: string[];
  bundledResources?: string[];
  skillPrompt?: string;
}

export interface SkillManifestDocument {
  /** `name` frontmatter field, when present and a string. */
  name?: string;
  /** `description` frontmatter field, when present and a string. */
  description?: string;
  /** Recognised `about.*` frontmatter fields. Absent when none resolved. */
  about?: SkillAboutDetails;
  /** Everything after the frontmatter fence, or the whole file when there is none. */
  body: string;
}

parseSkillManifestDocument = (
  raw: string,
): SkillManifestDocument => {
  /*
   * A BOM survives the fetch, and a Windows-authored manifest arrives with
   * CRLF — left in place, every parsed value would carry a trailing `\r`.
   */
  const text = raw.replace(/^\uFEFF/, '').replace(/\r\n/g, '\n');
  const lines = text.split('\n');

  const openingIndex = lines.findIndex((line) => line.trim() !== '');
  if (openingIndex === -1 || !FENCE_LINE.test(lines[openingIndex].trim())) {
    return { body: raw };
  }

  const closingIndex = lines.findIndex(
    (line, index) => index > openingIndex && FENCE_LINE.test(line.trim()),
  );
  if (closingIndex === -1) {
    return { body: raw };
  }

  let frontmatter: unknown;
  try {
    frontmatter = parseYaml(
      lines.slice(openingIndex + 1, closingIndex).join('\n'),
    );
  } catch {
    return { body: raw };
  }

  const bodyLines = lines.slice(closingIndex + 1);
  /* Drop the single blank line conventionally separating fence from body. */
  if (bodyLines[0] === '') bodyLines.shift();
  const body = bodyLines.join('\n');

  if (frontmatter == null || typeof frontmatter !== 'object') {
    return { body };
  }

  const record = frontmatter as FrontmatterRecord;
  const name = readString(record, ['name']);
  const description = readString(record, ['description']);
  const about = readAbout(record);

  return {
    ...(name != null ? { name } : {}),
    ...(description != null ? { description } : {}),
    ...(about != null ? { about } : {}),
    body,
  };
}

export enum SkillSource {
  /** A skill in the caller's own bucket. */
  Personal = 'personal',
  /** A skill another user shared with the caller. */
  SharedWithMe = 'sharedWithMe',
  /** An organisation-wide skill; read-only for every user. */
  Public = 'public',
}

export interface SkillEntityDetails {
  about?: SkillAboutDetails;
}

export interface ParsedSkillResourceUrl {
  /** DIAL Core bucket name. */
  bucket: string;
  /** Path to the skill within that bucket. */
  path: string;
}

parseSkillResourceUrl = (
  url: string,
): ParsedSkillResourceUrl | null => {
  if (!url.startsWith(SKILL_RESOURCE_PREFIX)) return null;
  const rest = url.slice(SKILL_RESOURCE_PREFIX.length);
  const slashIndex = rest.indexOf('/');
  if (slashIndex <= 0) return null;
  const bucket = rest.slice(0, slashIndex);
  const path = rest.slice(slashIndex + 1);
  if (bucket === '' || path === '') return null;
  return { bucket, path };
}

export interface UseSkillsStateParams {
  /** Fetches the aggregate skill listing from the server. */
  listSkills: () => Promise<SkillCatalogListResponseDto>;
  /** Whether the Skills feature is enabled in the current overlay/tenant config. */
  enabled: boolean;
  /** Whether the user session is ready for API calls (auth has settled). */
  ready: boolean;
}

export interface UseSkillsStateResult {
  /** Skills in the caller's own bucket. */
  skills: SkillMetadataItemDto[];
  /** Skills in the organisation bucket. */
  publicSkills: SkillMetadataItemDto[];
  /** Skills other users shared with the caller. */
  sharedWithMe: SkillMetadataItemDto[];
  /** True until the aggregate listing has settled. */
  isLoading: boolean;
  /** Rejection reason of the most recent failed listing, or `null`. */
  error: unknown;
  /** Re-reads personal, shared, and organisation skills. */
  refetch: () => Promise<void>;
  /** Upserts a single skill into the shared-with-me list by URL identity. */
  mergeSharedSkill: (item: SkillMetadataItemDto) => void;
}

useSkillsState = ({
  listSkills,
  enabled,
  ready,
}: UseSkillsStateParams): UseSkillsStateResult => {
  const [skills, setSkills] = useState<SkillMetadataItemDto[]>([]);
  const [publicSkills, setPublicSkills] = useState<SkillMetadataItemDto[]>([]);
  const [sharedWithMe, setSharedWithMe] = useState<SkillMetadataItemDto[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<unknown>(null);

  const refetch = useCallback(async () => {
    try {
      const response = await listSkills();
      setSkills(response.skills);
      setSharedWithMe(response.sharedWithMe);
      setPublicSkills(response.publicSkills);
      setError(null);
    } catch (err) {
      setError(err);
    }
  }, [listSkills]);

  useEffect(() => {
    if (!enabled) {
      setSkills([]);
      setSharedWithMe([]);
      setPublicSkills([]);
      setError(null);
      setIsLoading(false);
      return;
    }

    /* Keep the loading state visible until session identity has settled. */
    if (!ready) return;

    const cancelled = { value: false };

    const load = async () => {
      const response = await listSkills().catch((reason: unknown) => {
        if (!cancelled.value) setError(reason);
        return null;
      });
      if (cancelled.value) return;

      if (response != null) {
        setSkills(response.skills);
        setSharedWithMe(response.sharedWithMe);
        setPublicSkills(response.publicSkills);
        setError(null);
      }

      setIsLoading(false);
    };

    load();

    return () => {
      cancelled.value = true;
    };
  }, [enabled, ready, listSkills]);

  const mergeSharedSkill = useCallback((item: SkillMetadataItemDto) => {
    setSharedWithMe((prev) => [
      ...prev.filter((skill) => skill.url !== item.url),
      item,
    ]);
  }, []);

  return useMemo(
    () => ({
      skills,
      publicSkills,
      sharedWithMe,
      isLoading,
      error,
      refetch,
      mergeSharedSkill,
    }),
    [
      skills,
      publicSkills,
      sharedWithMe,
      isLoading,
      error,
      refetch,
      mergeSharedSkill,
    ],
  );
}

export interface ConversationRowActionState {
  /** `true` when the item is read-only (shared-with-me, published-with-me, or explicitly readonly). */
  isReadonly: boolean;
  /**
   * Deduplicated list of folder paths (as joined slash-delimited strings)
   * to which this conversation has been published. Empty when the conversation
   * is unowned, readonly, or publish history is unavailable.
   */
  publishedFolders: string[];
  /**
   * `true` when the revoke-access action should be shown: either the
   * recipient count is unknown (lookup pending/failed) or at least one
   * recipient exists.
   */
  isRevokeVisible: boolean;
  /** `true` when publish is applicable (no published folders yet). */
  isPublishApplicable: boolean;
  /** `true` when unpublish is applicable (at least one published folder exists). */
  isUnpublishApplicable: boolean;
}

deriveConversationRowActionState = (
  item: Pick<
    ConversationListItemDto,
    'sharedWithMe' | 'publishedWithMe' | 'isReadonly'
  >,
  publishHistory: PublishHistoryEntry[] | undefined,
  recipients: RecipientsCountEntry,
): ConversationRowActionState => {
  const isReadonly = !!(
    item.isReadonly ||
    item.sharedWithMe ||
    item.publishedWithMe
  );

  /*
   * Deduplicated: history may list one entry per publication event, so a
   * folder published to twice would otherwise appear twice. Keyed by the
   * joined path string; the value stored is that same string.
   */
  const publishedFolders =
    !isReadonly && publishHistory != null
      ? [...new Set(publishHistory.map((entry) => entry.folderPath.join('/')))]
      : [];

  const isRevokeVisible =
    recipients.status === RecipientsCountStatus.Unknown ||
    (recipients.status === RecipientsCountStatus.Resolved &&
      (recipients.count ?? 0) > 0);

  return {
    isReadonly,
    publishedFolders,
    isRevokeVisible,
    isPublishApplicable: publishedFolders.length === 0,
    isUnpublishApplicable: publishedFolders.length > 0,
  };
}

export interface UseActiveConversationSyncParams {
  /**
   * The raw context id of the currently active conversation, as tracked by
   * the host app. `undefined` when no conversation is active.
   */
  activeConversationId: string | undefined;
  /** Raw conversation list from the API. */
  items: ConversationListItemDto[];
  /** Refetches the full conversation list. */
  refreshConversations: () => Promise<void>;
  /** Marks a scheduler-created conversation as viewed by raw context id. */
  markConversationViewed: (id: string) => Promise<void>;
  /**
   * Returns `true` when two ids refer to the same conversation despite
   * possible encoding differences. App-specific.
   */
  conversationIdsMatch: (a: string, b: string) => boolean;
  /** Converts a raw context id to the panel-space id. App-specific. */
  toPanelConversationId: (id: string) => string;
}

useActiveConversationSync = ({
  activeConversationId,
  items,
  refreshConversations,
  markConversationViewed,
  conversationIdsMatch,
  toPanelConversationId,
}: UseActiveConversationSyncParams): string | undefined => {
  const panelActiveConversationId = useMemo(
    () =>
      activeConversationId
        ? toPanelConversationId(activeConversationId)
        : undefined,
    [activeConversationId, toPanelConversationId],
  );

  /* Effect 1: refresh if the active conversation is missing from the list. */
  useEffect(() => {
    if (!panelActiveConversationId) return;
    const isListed = items.some((item) =>
      conversationIdsMatch(item.id, panelActiveConversationId),
    );
    if (!isListed) void refreshConversations();
    // Intentionally not including items or refreshConversations in the
    // dependency array to avoid re-triggering on every list update.
  }, [panelActiveConversationId, conversationIdsMatch]); // eslint-disable-line react-hooks/exhaustive-deps

  /*
   * Effect 2: single shared entry point for marking a scheduler-created
   * conversation as viewed -- fires whenever the active conversation changes,
   * whether the user navigated by clicking a history panel row or via direct
   * URL navigation. markConversationViewed itself no-ops for non-scheduler
   * or already-read items.
   */
  useEffect(() => {
    if (!panelActiveConversationId) return;
    const activeItem = items.find((item) =>
      conversationIdsMatch(item.id, panelActiveConversationId),
    );
    if (activeItem) void markConversationViewed(activeItem.id);
  }, [
    panelActiveConversationId,
    items,
    markConversationViewed,
    conversationIdsMatch,
  ]);

  return panelActiveConversationId;
}

export interface AsyncConfirmDialogControls<T> {
  /**
   * The value currently awaiting confirmation, or `null` when no dialog is
   * open.
   */
  pending: T | null;
  /** `true` when `pending` is not `null`. */
  isPending: boolean;
  /** `true` while the async operation started by `confirm` is in-flight. */
  isRunning: boolean;
  /** Error message set when the last `confirm` run threw, or `null` otherwise. */
  error: string | null;
  /**
   * Opens the dialog by setting `pending` to `value` and clearing any prior
   * error.
   *
   * Pass `returnFocusTo` when the control that opened the dialog will not
   * survive it — a row menu item, for instance, unmounts with its menu, so
   * restoring focus to it is impossible and the caller should name a stable
   * element such as the menu's own trigger. When omitted, whatever held focus
   * at the moment of the call is used.
   */
  open: (value: T, returnFocusTo?: HTMLElement | null) => void;
  /** Closes the dialog by resetting `pending`, `error`, and `isRunning` to their initial values. */
  close: () => void;
  /**
   * Runs `run(pending)` while enforcing a re-entry guard.
   *
   * - No-op when `isRunning` is already `true` or `pending` is `null`.
   * - On success: calls `close()` to reset all state.
   * - On failure: sets `error` to `onError(caughtError)` and leaves `pending`
   *   set so the caller may retry.
   */
  confirm: (
    run: (value: T) => Promise<void>,
    onError: (error: unknown) => string,
  ) => Promise<void>;
}

useAsyncConfirmDialog = <T>(): AsyncConfirmDialogControls<T> => {
  const [pending, setPending] = useState<T | null>(null);
  const [isRunning, setIsRunning] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const pendingRef = useRef<T | null>(null);
  const isRunningRef = useRef(false);
  const operationIdRef = useRef(0);
  const returnFocusRef = useRef<HTMLElement | null>(null);

  const open = useCallback((value: T, returnFocusTo?: HTMLElement | null) => {
    const { activeElement } = document;
    returnFocusRef.current =
      returnFocusTo ??
      (activeElement instanceof HTMLElement ? activeElement : null);
    operationIdRef.current += 1;
    pendingRef.current = value;
    isRunningRef.current = false;
    setPending(value);
    setIsRunning(false);
    setError(null);
  }, []);

  /*
   * Returns keyboard focus to the control the dialog was opened from once it
   * closes, whether it was confirmed, cancelled or dismissed. Without this the
   * dialog unmounts with focus on it and the browser drops focus to <body>,
   * stranding a keyboard user at the top of the document.
   *
   * It runs as an effect rather than inside close(): the restore has to land
   * after the commit that unmounts the dialog, or the dialog's own teardown
   * blurs the element we just focused.
   */
  useEffect(() => {
    if (pending != null) return;
    const opener = returnFocusRef.current;
    returnFocusRef.current = null;
    if (opener?.isConnected) {
      opener.focus({ preventScroll: true });
    }
  }, [pending]);

  const close = useCallback(() => {
    operationIdRef.current += 1;
    pendingRef.current = null;
    isRunningRef.current = false;
    setPending(null);
    setError(null);
    setIsRunning(false);
  }, []);

  const confirm = useCallback(
    async (
      run: (value: T) => Promise<void>,
      onError: (error: unknown) => string,
    ) => {
      const currentPending = pendingRef.current;
      if (isRunningRef.current || currentPending == null) return;
      const operationId = ++operationIdRef.current;
      isRunningRef.current = true;
      setIsRunning(true);
      setError(null);
      try {
        await run(currentPending);
        if (operationId !== operationIdRef.current) return;
        pendingRef.current = null;
        setPending(null);
        setError(null);
        isRunningRef.current = false;
        setIsRunning(false);
      } catch (e) {
        if (operationId !== operationIdRef.current) return;
        setError(onError(e));
        isRunningRef.current = false;
        setIsRunning(false);
      }
    },
    [],
  );

  return {
    pending,
    isPending: pending != null,
    isRunning,
    error,
    open,
    close,
    confirm,
  };
}

export interface UseConversationLookupMapsParams {
