export interface UseTranscribeAudioResult {
  /** Uploads and recognizes one complete recording; rejects with an {@link AudioTranscriptionError}. */
  transcribeAudio: (file: File, signal: AbortSignal) => Promise<string>;
}

useTranscribeAudio = ({
  transcriptionApi,
  filesApi,
  transcribeWithDeployment,
  bucket,
  asrModelId,
  selectedDeploymentId,
  maxSizeBytes,
}: UseTranscribeAudioParams): UseTranscribeAudioResult => {
  const transcribeAudio = useCallback(
    async (file: File, signal: AbortSignal): Promise<string> => {
      signal.throwIfAborted();
      if (!bucket || (!asrModelId && !selectedDeploymentId)) {
        throw new AudioTranscriptionError(
          AudioTranscriptionErrorReason.Unavailable,
        );
      }
      if (file.size > maxSizeBytes) {
        throw new AudioTranscriptionError(
          AudioTranscriptionErrorReason.TooLarge,
          maxSizeBytes,
        );
      }
      try {
        const path = `uploads/${new Date().toISOString().slice(0, 7)}/${encodeURIComponent(file.name)}`;
        const { url } = await filesApi.uploadFile(
          { bucket, path, file },
          { signal },
        );
        signal.throwIfAborted();
        if (asrModelId) {
          if (!transcriptionApi) {
            throw new AudioTranscriptionError(
              AudioTranscriptionErrorReason.Unavailable,
            );
          }
          return await withTranscriptionRetry(async () => {
            const response = await transcriptionApi.transcribeAudio(
              { transcribeAudioDto: { audioUrl: url, mimeType: file.type } },
              { signal },
            );
            return response.transcript ?? '';
          }, signal);
        }
        if (!selectedDeploymentId || !transcribeWithDeployment) {
          throw new AudioTranscriptionError(
            AudioTranscriptionErrorReason.Unavailable,
          );
        }
        return await withTranscriptionRetry(
          () =>
            transcribeWithDeployment({
              audioUrl: url,
              mimeType: file.type,
              deployment: selectedDeploymentId,
              signal,
            }),
          signal,
        );
      } catch (error) {
        if (signal.aborted) throw error;
        if (error instanceof AudioTranscriptionError) throw error;
        throw new AudioTranscriptionError(AudioTranscriptionErrorReason.Failed);
      }
    },
    [
      bucket,
      asrModelId,
      selectedDeploymentId,
      maxSizeBytes,
      filesApi,
      transcriptionApi,
      transcribeWithDeployment,
    ],
  );

  return { transcribeAudio };
}

export interface UseConversationExportParams {
  /** Already-configured generated-client instance used to read conversations. */
  conversationsApi: Pick<
    ConversationsApi,
    'getConversation' | 'listConversations'
  >;
  /** Already-configured generated-client instance used to download attachments. */
  filesApi: Pick<FilesApi, 'downloadFileRaw'>;
  /** Resolves a conversation id to the bucket-qualified path `getConversation` expects. */
  normalizeConversationPath: (conversationId: string) => string;
  /** Classifies a thrown error as unauthorized/not-found. Host-owned error taxonomy; defaults to neither. */
  classifyTransferError?: (error: unknown) => ExportErrorClassification;
  /** Resolves a trace id for a failing request, for display in an error notification. */
  resolveErrorTraceId?: (error: unknown) => Promise<string | undefined>;
  /**
   * Ceiling on the summed byte length of an export's attachments; a larger
   * export fails with `FileTooLarge` instead of being zipped. Defaults to
   * {@link DEFAULT_MAX_ARCHIVE_BYTES}.
   */
  maxArchiveBytes?: number;
  /** Called when a job completes successfully. */
  onSuccess?: (event: ConversationTransferSuccessEvent) => void;
  /** Called when a job succeeds but had to skip something (e.g. an unreachable attachment). */
  onWarning?: (event: ConversationTransferWarningEvent) => void;
  /** Called when a job fails. */
  onError?: (event: ConversationTransferErrorEvent) => void;
}

export interface UseConversationExportResult {
  /** Export jobs, most recently added last. Multiple jobs can be in progress concurrently. */
  jobs: ConversationTransferJob[];
  /** Enqueues a single-conversation export job and starts it immediately. */
  exportSingle: (
    conversationId: string,
    title: string,
    mode: ConversationExportMode,
  ) => Promise<void>;
  /** Enqueues an export-all job and starts it immediately. */
  exportAll: () => Promise<void>;
  /** Aborts a job's underlying requests and marks it canceled, keeping it in `jobs`. */
  cancelJob: (jobId: string) => void;
  /** Removes a job from the queue. If still in progress, aborts its underlying requests. */
  dismissJob: (jobId: string) => void;
  /** Re-attempts a failed or canceled job in place (same job id, same parameters). */
  retryJob: (jobId: string) => void;
  /** Aborts all in-progress jobs and clears the entire queue. */
  dismissAll: () => void;
}

useConversationExport = ({
  conversationsApi,
  filesApi,
  normalizeConversationPath,
  classifyTransferError = () => ({}),
  resolveErrorTraceId = async () => undefined,
  maxArchiveBytes = DEFAULT_MAX_ARCHIVE_BYTES,
  onSuccess,
  onWarning,
  onError,
}: UseConversationExportParams): UseConversationExportResult => {
  const queue = useConversationTransferQueue();

  const fetchAttachments = useCallback(
    async (
      refs: AttachmentRef[],
      signal: AbortSignal,
      onUnitSettled: (completed: number, total: number) => void,
    ): Promise<{
      entries: ZipAttachmentEntry[];
      anySkipped: boolean;
      isUnauthorized: boolean;
    }> => {
      let anySkipped = false;
      let isUnauthorized = false;
      let settled = 0;

      const settleUnit = (): void => {
        settled += 1;
        onUnitSettled(settled, refs.length);
      };

      const entries = await runWithConcurrency(
        refs,
        ATTACHMENT_CONCURRENCY,
        async (ref): Promise<ZipAttachmentEntry | undefined> => {
          if (signal.aborted || isUnauthorized) return undefined;
          const resolved = resolveDialFileBucketAndPath(ref.fileId);
          if (!resolved) {
            anySkipped = true;
            settleUnit();
            return undefined;
          }
          try {
            const apiResponse = await filesApi.downloadFileRaw(
              { bucket: resolved.bucket, path: resolved.path },
              { signal },
            );
            const data = new Uint8Array(await apiResponse.raw.arrayBuffer());
            settleUnit();
            return { path: resolved.path, data };
          } catch (error) {
            if (signal.aborted) return undefined;
            if (classifyTransferError(error).isUnauthorized) {
              isUnauthorized = true;
              return undefined;
            }
            anySkipped = true;
            settleUnit();
            return undefined;
          }
        },
      );

      return {
        entries,
        anySkipped: !signal.aborted && !isUnauthorized && anySkipped,
        isUnauthorized: !signal.aborted && isUnauthorized,
      };
    },
    [classifyTransferError, filesApi],
  );

  const runExportSingle = useCallback(
    async (
      jobId: string,
      conversationId: string,
      title: string,
      mode: ConversationExportMode,
      fileName: string,
      signal: AbortSignal,
    ): Promise<void> => {
      const kind = getExportKind(mode);
      let conversation: Conversation;
      try {
        conversation = await fetchConversationWithRetry(
          conversationsApi,
          normalizeConversationPath(conversationId),
          signal,
        );
      } catch (error) {
        if (signal.aborted) return;
        const classification = classifyTransferError(error);
        if (!classification.isUnauthorized) {
          const traceId = await resolveErrorTraceId(error);
          onError?.({
            jobId,
            code: ConversationTransferErrorCode.Unknown,
            titles: [title],
            traceId,
          });
          queue.failJob(jobId, ConversationTransferErrorCode.Unknown);
        } else {
          onError?.({
            jobId,
            code: ConversationTransferErrorCode.Unauthorized,
          });
          queue.failJob(jobId, ConversationTransferErrorCode.Unauthorized);
        }
        console.error('Failed to fetch conversation for export', error);
        return;
      }
      if (signal.aborted) return;
      queue.setJobProgress(
        jobId,
        buildTransferProgress({
          kind,
          phase: ConversationTransferPhase.Prepare,
        }),
      );

      try {
        if (mode === ConversationExportMode.WithoutAttachments) {
          /*
           * This mode ships no attachment bytes, so the references have to go
           * too: they stay valid `files/{bucket}/{path}` ids pointing at the
           * exporting user's own bucket, and the import writes them back
           * verbatim, which restores for that user the very attachments the
           * mode excluded (issue #8663).
           */
          const envelope = buildExportEnvelope(
            [stripConversationAttachments(conversation)],
            [],
          );
          const blob = serializeExportEnvelope(envelope);
          triggerBlobDownload(blob, fileName);
          onSuccess?.({ jobId, titles: [title] });
          queue.succeedJob(jobId);
          return;
        }

        const attachmentRefs = collectAttachmentRefs(conversation);
        const {
          entries: zipAttachments,
          anySkipped,
          isUnauthorized,
        } = await fetchAttachments(
          attachmentRefs,
          signal,
          (completed, total) => {
            queue.setJobProgress(
              jobId,
              buildTransferProgress(
                {
                  kind,
                  phase: ConversationTransferPhase.Transfer,
                  completed,
                  total,
                },
                {
                  completed,
                  total,
                  kind: ConversationTransferUnitKind.Attachment,
                },
              ),
            );
          },
        );
        if (signal.aborted) return;
        if (isUnauthorized) {
          onError?.({
            jobId,
            code: ConversationTransferErrorCode.Unauthorized,
          });
          queue.failJob(jobId, ConversationTransferErrorCode.Unauthorized);
          return;
        }
        /* Credits the transfer phase in full for a conversation with no attachments. */
        queue.setJobProgress(
          jobId,
          buildTransferProgress({
            kind,
            phase: ConversationTransferPhase.Transfer,
            completed: attachmentRefs.length,
            total: attachmentRefs.length,
          }),
        );

        const totalBytes = zipAttachments.reduce(
          (total, entry) => total + entry.data.byteLength,
          0,
        );
        if (totalBytes > maxArchiveBytes) {
          onError?.({
            jobId,
            code: ConversationTransferErrorCode.FileTooLarge,
            titles: [title],
          });
          queue.failJob(jobId, ConversationTransferErrorCode.FileTooLarge);
          console.error(
            `Refused to build an export archive of ${totalBytes} bytes: over the ${maxArchiveBytes}-byte limit`,
          );
          return;
        }

        const envelope = buildExportEnvelope([conversation], []);
        const { blob, skippedPaths } = buildDialArchive(
          envelope,
          zipAttachments,
        );
        const hasSkippedAttachments = anySkipped || skippedPaths.length > 0;
        if (hasSkippedAttachments) {
          onWarning?.({
            jobId,
            code: ConversationTransferWarningCode.AttachmentSkipped,
          });
        }
        triggerBlobDownload(blob, fileName);
        onSuccess?.({ jobId, titles: [title] });
        /*
         * The archive was still delivered, so this settles at 100% either way;
         * only the status differs, so the row can say the export is incomplete.
         */
        if (hasSkippedAttachments) {
          queue.warnJob(
            jobId,
            ConversationTransferWarningCode.AttachmentSkipped,
          );
        } else {
          queue.succeedJob(jobId);
        }
      } catch (error) {
        if (signal.aborted) return;
        const code = isAllocationFailure(error)
          ? ConversationTransferErrorCode.FileTooLarge
          : ConversationTransferErrorCode.Unknown;
        const traceId = await resolveErrorTraceId(error);
        onError?.({ jobId, code, titles: [title], traceId });
        queue.failJob(jobId, code);
        console.error('Failed to build conversation export archive', error);
      }
    },
    [
      classifyTransferError,
      conversationsApi,
      fetchAttachments,
      maxArchiveBytes,
      normalizeConversationPath,
      onError,
      onSuccess,
      onWarning,
      queue,
      resolveErrorTraceId,
    ],
  );

  const exportSingle = useCallback(
    (
      conversationId: string,
      title: string,
      mode: ConversationExportMode,
    ): Promise<void> => {
      const fileName = buildExportFileName(
        mode === ConversationExportMode.WithoutAttachments
          ? ExportFileNameKind.SingleConversation
          : ExportFileNameKind.SingleConversationWithAttachments,
        EXPORT_APP_NAME,
      );
      const jobId = queue.addJob(
        {
          kind: ConversationTransferSubjectKind.Single,
          title,
        },
        fileName,
      );
      return queue.startJob(jobId, (signal) =>
        runExportSingle(jobId, conversationId, title, mode, fileName, signal),
      );
    },
    [queue, runExportSingle],
  );

  const runExportAll = useCallback(
    async (
      jobId: string,
      fileName: string,
      signal: AbortSignal,
    ): Promise<void> => {
      const kind = ConversationTransferKind.ExportAll;
      const conversationRefs: Array<{ id: string; title: string }> = [];
      let nextToken: string | undefined;
      do {
        if (signal.aborted) return;
        let page: {
          items: ConversationListItemDto[];
          nextToken?: string;
        };
        try {
          page = await conversationsApi.listConversations(
            { nextToken },
            { signal },
          );
        } catch (error) {
          if (signal.aborted) return;
          const classification = classifyTransferError(error);
          if (!classification.isUnauthorized) {
            const traceId = await resolveErrorTraceId(error);
            onError?.({
              jobId,
              code: ConversationTransferErrorCode.Unknown,
              traceId,
            });
            queue.failJob(jobId, ConversationTransferErrorCode.Unknown);
          } else {
            onError?.({
              jobId,
              code: ConversationTransferErrorCode.Unauthorized,
            });
            queue.failJob(jobId, ConversationTransferErrorCode.Unauthorized);
          }
          console.error('Failed to list conversations for export', error);
          return;
        }
        conversationRefs.push(
          ...page.items
            .filter(isOwnConversation)
            .map((item) => ({ id: item.id, title: item.title })),
        );
        nextToken = page.nextToken;
      } while (nextToken);
      queue.setJobProgress(
        jobId,
        buildTransferProgress({
          kind,
          phase: ConversationTransferPhase.Prepare,
        }),
      );

      const conversations: Conversation[] = [];
      for (const ref of conversationRefs) {
        if (signal.aborted) return;
        try {
          const conversation = await fetchConversationWithRetry(
            conversationsApi,
            normalizeConversationPath(ref.id),
            signal,
          );
          conversations.push(conversation);
        } catch (error) {
          if (signal.aborted) return;
          const classification = classifyTransferError(error);
          if (classification.isUnauthorized) {
            onError?.({
              jobId,
              code: ConversationTransferErrorCode.Unauthorized,
            });
            queue.failJob(jobId, ConversationTransferErrorCode.Unauthorized);
            return;
          }
          if (classification.isNotFound) {
            const traceId = await resolveErrorTraceId(error);
            onError?.({
              jobId,
              code: ConversationTransferErrorCode.NotFound,
              titles: [ref.title],
              traceId,
            });
            console.error(
              'Skipped a conversation during export-all: not found',
              error,
            );
            continue;
          }
          const traceId = await resolveErrorTraceId(error);
          onError?.({
            jobId,
            code: ConversationTransferErrorCode.Unknown,
            traceId,
          });
          queue.failJob(jobId, ConversationTransferErrorCode.Unknown);
          console.error(
            'Aborted export-all: failed to fetch conversation',
            error,
          );
          return;
        } finally {
          queue.setJobProgress(
            jobId,
            buildTransferProgress(
              {
                kind,
                phase: ConversationTransferPhase.Transfer,
                completed: conversations.length,
                total: conversationRefs.length,
              },
              {
                completed: conversations.length,
                total: conversationRefs.length,
                kind: ConversationTransferUnitKind.Conversation,
              },
            ),
          );
        }
      }
      if (signal.aborted) return;

      try {
        const envelope = buildExportEnvelope(conversations, []);
        const blob = serializeExportEnvelope(envelope);
        triggerBlobDownload(blob, fileName);
        onSuccess?.({ jobId });
        queue.succeedJob(jobId);
      } catch (error) {
        const code = isAllocationFailure(error)
          ? ConversationTransferErrorCode.FileTooLarge
          : ConversationTransferErrorCode.Unknown;
        const traceId = await resolveErrorTraceId(error);
        onError?.({ jobId, code, traceId });
        queue.failJob(jobId, code);
        console.error('Failed to build export-all archive', error);
      }
    },
    [
      classifyTransferError,
      conversationsApi,
      normalizeConversationPath,
      onError,
      onSuccess,
      queue,
      resolveErrorTraceId,
    ],
  );

  const exportAll = useCallback((): Promise<void> => {
    const fileName = buildExportFileName(
      ExportFileNameKind.AllConversationsHistory,
      EXPORT_APP_NAME,
    );
    const jobId = queue.addJob(
      { kind: ConversationTransferSubjectKind.All },
      fileName,
    );
    return queue.startJob(jobId, (signal) =>
      runExportAll(jobId, fileName, signal),
    );
  }, [queue, runExportAll]);

  return {
    jobs: queue.jobs,
    exportSingle,
    exportAll,
    cancelJob: queue.cancelJob,
    dismissJob: queue.dismissJob,
    retryJob: queue.retryJob,
    dismissAll: queue.dismissAll,
  };
}

export type ConversationStreamStarter = (
  conversationPath: string,
  userContent: string,
  messageIndex: number,
  model: string,
  customContent?: MessageCustomContent,
  generationId?: string,
  mode?: SendCompletionDtoModeEnum,
) => void;

export interface UseConversationHandlersParams {
  conversation: Conversation | null;
  conversationId: string | undefined;
  bucket: string | undefined;
  isStreaming: boolean;
  /** The `startStream` function returned by `useConversationStream`. */
  startStream: ConversationStreamStarter;
  /** Shared mutable channel for the displayed conversation — the same one passed to `useConversationStream`. */
  state: ConversationStateAccessor;
  /** Already-configured generated-client instance used to upload attachments. */
  filesApi: Pick<FilesApi, 'uploadFile'>;
  /** Already-configured generated-client instance used to save/delete the conversation. */
  conversationsApi: Pick<
    ConversationsApi,
    'saveConversation' | 'deleteConversation'
  >;
  /** Already-configured generated-client instance used to rate a message. */
  rateApi: Pick<RateApi, 'rateMessage'>;
  /** Resolves the model id to send with the next completion. Re-evaluated on every call — never cached. */
  resolveModelId: () => string;
  /** Called when deleting the last message also deletes the whole conversation. */
  onConversationDeleted?: () => void;
  /** Called with batched filenames after a burst of network-error upload failures. */
  showNetworkError?: (filenames: string[]) => void;
  /** Tool toggle configuration values merged into every outgoing completion request. */
  toolConfigurationValue?: Record<string, boolean>;
}

export interface UseConversationHandlersResult {
  handleSend: (
    message: string,
    attachments: Attachment[],
    skills?: RequestSkill[],
  ) => Promise<void>;
  handleUploadAttachment: (
    attachment: Attachment,
  ) => Promise<UploadedAttachmentResult>;
  handleRegenerateMessage: (messageIndex: number) => void;
  handleDeleteMessage: (messageIndex: number) => void;
  handleConfirmDelete: () => void;
  handleRateMessage: (
    messageIndex: number,
    rating: MessageRating | null,
    comment?: string,
  ) => Promise<boolean>;
  handleButtonSelect: (
    starter: StarterOption,
    propertyKey?: string,
    description?: string,
  ) => void;
  handleConfirmStarter: () => void;
  handleStartEdit: (messageIndex: number) => void;
  handleCancelEdit: (messageIndex: number) => void;
  handleEditMessage: (
    messageIndex: number,
    text: string,
    keptDisplayAttachments: DisplayAttachment[],
    newAttachments: Attachment[],
    skills?: RequestSkill[],
  ) => Promise<void>;
  editingMessageIndexes: Set<number>;
  pendingDeleteIndex: number | null;
  setPendingDeleteIndex: (index: number | null) => void;
  pendingStarterContext: {
    starter: StarterOption;
    propertyKey?: string;
    description?: string;
  } | null;
  setPendingStarterContext: (
    context: {
      starter: StarterOption;
      propertyKey?: string;
      description?: string;
    } | null,
  ) => void;
}

useConversationHandlers = ({
  conversation,
  conversationId,
  bucket,
  isStreaming,
  startStream,
  state: { setConversation, conversationRef },
  filesApi,
  conversationsApi,
  rateApi,
  resolveModelId,
  onConversationDeleted,
  showNetworkError,
  toolConfigurationValue,
}: UseConversationHandlersParams): UseConversationHandlersResult => {
  const [pendingDeleteIndex, setPendingDeleteIndex] = useState<number | null>(
    null,
  );
  const [editingMessageIndexes, setEditingMessageIndexes] = useState<
    Set<number>
  >(new Set());

  const [pendingStarterContext, setPendingStarterContext] = useState<{
    starter: StarterOption;
    propertyKey?: string;
    description?: string;
  } | null>(null);

  const { handleUploadAttachment } = useAttachmentUpload({
    filesApi,
    bucket,
    onNetworkError: showNetworkError,
  });

  const handleSend = useCallback(
    async (
      message: string,
      attachments: Attachment[],
      skills?: RequestSkill[],
    ) => {
      if (!conversationId || !conversation) return;

      const attachmentDtos = attachmentsToDtos(attachments);
      const hasToolConfig = hasActiveToolConfig(toolConfigurationValue);
      const customContent: MessageCustomContent | undefined =
        attachmentDtos?.length || hasToolConfig || skills?.length
          ? {
              ...(attachmentDtos?.length
                ? { attachments: attachmentDtos }
                : {}),
              ...(hasToolConfig
                ? { configuration_value: toolConfigurationValue }
                : {}),
              ...(skills?.length ? { skills } : {}),
            }
          : undefined;
      const modelId = resolveModelId();
      const { userMessage, assistantMessage } = createMessagePair(
        message,
        customContent,
        modelId,
      );
      setConversation((prev) => {
        if (!prev) return prev;
        const next = {
          ...prev,
          messages: [...prev.messages, userMessage, assistantMessage],
        };
        conversationRef.current = next;
        return next;
      });

      startStream(
        conversationId,
        message,
        conversation.messages.length + 1,
        modelId,
        customContent,
        generateUUID(),
        CompletionMode.Append,
      );
    },
    [
      conversation,
      conversationId,
      conversationRef,
      resolveModelId,
      setConversation,
      startStream,
      toolConfigurationValue,
    ],
  );

  const handleRegenerateMessage = useCallback(
    (messageIndex: number) => {
      if (isStreaming || !conversationId || !conversation) return;

      if (
        messageIndex === -1 ||
        conversation.messages[messageIndex]?.role !== MessageRole.Assistant
      )
        return;

      const userMsg = conversation.messages[messageIndex - 1];
      if (!userMsg || userMsg.role !== MessageRole.User) return;

      const modelId = resolveModelId();

      const regeneratedMessage = {
        ...conversation.messages[messageIndex],
        content: '',
        custom_content: undefined,
        wasStoppedByUser: undefined,
        stoppedWithoutContent: undefined,
        streamErrorMessage: undefined,
        deploymentId: modelId,
      };
      const next = {
        ...conversation,
        messages: [
          ...conversation.messages.slice(0, messageIndex),
          regeneratedMessage,
        ],
      };
      conversationRef.current = next;
      setConversation(next);

      setEditingMessageIndexes(
        (indexes) =>
          new Set([...indexes].filter((index) => index < messageIndex)),
      );

      startStream(
        conversationId,
        userMsg.content,
        messageIndex,
        modelId,
        userMsg.custom_content,
        generateUUID(),
        CompletionMode.Regenerate,
      );
    },
    [
      conversation,
      conversationId,
      conversationRef,
      isStreaming,
      resolveModelId,
      setConversation,
      startStream,
    ],
  );

  const handleDeleteMessage = useCallback(
    (messageIndex: number) => {
      if (isStreaming) return;
      setPendingDeleteIndex(messageIndex);
    },
    [isStreaming],
  );

  const handleConfirmDelete = useCallback(() => {
    if (!conversationId || pendingDeleteIndex == null) return;
    const idx = pendingDeleteIndex;
    setPendingDeleteIndex(null);

    const prev = conversationRef.current;
    if (!prev || idx === -1) return;

    const conversationPath = getConversationPath(conversationId);
    const next =
      prev.messages[idx + 1]?.role === MessageRole.Assistant
        ? prev.messages.filter((_, i) => i !== idx && i !== idx + 1)
        : prev.messages.filter((_, i) => i !== idx);

    if (
      next.length === 0 ||
      (next.length === 1 && next[0].role === MessageRole.Status)
    ) {
      void conversationsApi.deleteConversation({ path: conversationPath });
      onConversationDeleted?.();
      return;
    }

    const updated = { ...prev, messages: next };
    conversationRef.current = updated;
    setConversation(updated);
    void conversationsApi.saveConversation({
      path: conversationPath,
      saveConversationBodyDto: {
        conversation: updated as unknown as ConversationResponseDto,
      },
    });
  }, [
    conversationId,
    conversationRef,
    conversationsApi,
    onConversationDeleted,
    pendingDeleteIndex,
    setConversation,
  ]);

  const handleRateMessage = useCallback(
    async (
      messageIndex: number,
      rating: MessageRating | null,
      comment?: string,
    ): Promise<boolean> => {
      if (!conversationId || !conversation) return false;

      const msg = conversation.messages[messageIndex];
      if (!msg) return false;

      const previousRating = msg.rating;
      const updatedConversation: Conversation = {
        ...conversation,
        messages: conversation.messages.map((m, i) =>
          i === messageIndex ? { ...m, rating: rating ?? undefined } : m,
        ),
      };

      setConversation(() => {
        conversationRef.current = updatedConversation;
        return updatedConversation;
      });

      const conversationPath = getConversationPath(conversationId);

      const revert = () => {
        setConversation((prev) => {
          if (!prev) return prev;
          return {
            ...prev,
            messages: prev.messages.map((m, i) =>
              i === messageIndex ? { ...m, rating: previousRating } : m,
            ),
          };
        });
      };

      const persist = () =>
        conversationsApi.saveConversation({
          path: conversationPath,
          saveConversationBodyDto: {
            conversation:
              updatedConversation as unknown as ConversationResponseDto,
          },
        });

      const responseId = msg.responseId;
      if (!responseId) {
        revert();
        return false;
      }
      try {
        await rateApi.rateMessage({
          rateMessageDto: {
            conversationId: conversation.id,
            responseId,
            modelId: conversation.model.id,
            rate: rating,
            ...(comment ? { comment } : {}),
          },
        });
        await persist();
        return true;
      } catch {
        revert();
        return false;
      }
    },
    [
      conversation,
      conversationId,
      conversationRef,
      conversationsApi,
      rateApi,
      setConversation,
    ],
  );

  const submitStarter = useCallback(
    (starter: StarterOption, propertyKey?: string, description?: string) => {
      if (!conversationId || !conversation) return;

      const displayText = getStarterDisplayText(starter, description);
      const submitText = getStarterSubmitText(starter, description);
      const configurationValue = propertyKey
        ? { [propertyKey]: starter.const }
        : undefined;
      const hasToolConfig = hasActiveToolConfig(toolConfigurationValue);

      const customContent: MessageCustomContent | undefined =
        configurationValue || hasToolConfig
          ? {
              ...(configurationValue ? { form_value: configurationValue } : {}),
              ...(hasToolConfig
                ? { configuration_value: toolConfigurationValue }
                : {}),
            }
          : undefined;

      const modelId = resolveModelId();
      const { userMessage, assistantMessage } = createMessagePair(
        displayText,
        customContent,
        modelId,
      );
      setConversation((prev) => {
        if (!prev) return prev;
        const next = {
          ...prev,
          messages: [...prev.messages, userMessage, assistantMessage],
        };
        conversationRef.current = next;
        return next;
      });

      /* `configuration_value` is sent even when `configurationValue` (the
       * form-based starter value) is absent but a tool toggle is active.
       * Active tool config must always be forwarded so the completion
       * endpoint can apply it regardless of how the starter was triggered. */
      startStream(
        conversationId,
        submitText,
        conversation.messages.length + 1,
        modelId,
        customContent,
        generateUUID(),
        CompletionMode.Append,
      );
    },
    [
      conversation,
      conversationId,
      conversationRef,
      resolveModelId,
      setConversation,
      startStream,
      toolConfigurationValue,
    ],
  );

  const handleButtonSelect = useCallback(
    (starter: StarterOption, propertyKey?: string, description?: string) => {
      if (!conversationId || !conversation || isStreaming) return;

      if (starter['dial:widgetOptions'].confirmationMessage) {
        setPendingStarterContext({ starter, propertyKey, description });
      } else {
        submitStarter(starter, propertyKey, description);
      }
    },
    [conversation, conversationId, isStreaming, submitStarter],
  );

  const handleConfirmStarter = useCallback(() => {
    if (!pendingStarterContext) return;
    const { starter, propertyKey, description } = pendingStarterContext;
    setPendingStarterContext(null);
    submitStarter(starter, propertyKey, description);
  }, [pendingStarterContext, submitStarter]);

  const handleStartEdit = useCallback((messageIndex: number) => {
    setEditingMessageIndexes((prev) => new Set([...prev, messageIndex]));
  }, []);

  const handleCancelEdit = useCallback((messageIndex: number) => {
    setEditingMessageIndexes((prev) => {
      const next = new Set(prev);
      next.delete(messageIndex);
      return next;
    });
  }, []);

  const handleEditMessage = useCallback(
    async (
      messageIndex: number,
      text: string,
      keptDisplayAttachments: DisplayAttachment[],
      newAttachments: Attachment[],
      skills?: RequestSkill[],
    ) => {
      if (isStreaming || !conversationId || !conversation) return;

      const idx = messageIndex;
      if (idx === -1 || conversation.messages[idx].role !== MessageRole.User)
        return;

      const originalMessage = conversation.messages[idx];

      if (
        !shouldRerunGenerationOnEdit(
          conversation.messages,
          idx,
          text,
          keptDisplayAttachments,
          newAttachments,
          skills,
        )
      ) {
        setEditingMessageIndexes((prev) => {
          const next = new Set(prev);
          next.delete(idx);
          return next;
        });
        return;
      }

      const newDtos = attachmentsToDtos(newAttachments);

      const keptIds = new Set(keptDisplayAttachments.map((a) => a.id));
      const keptDtos = (
        originalMessage.custom_content?.attachments ?? []
      ).filter((att) => {
        const id = att.url ?? att.data ?? att.title;
        return keptIds.has(id);
      });

      const allAttachments = [...keptDtos, ...(newDtos ?? [])];

      const {
        attachments: _removed,
        skills: originalSkills,
        ...restCustomContent
      } = originalMessage.custom_content ?? {};
      /*
       * `skills` semantics: `undefined` preserves the message's original
       * skills untouched (the host leaves them alone — e.g. an edit made
       * while the feature flag is off), while an array — including an empty
       * one — is the skill state the edit UI resolved and replaces them
       * (empty means the user removed the skill).
       */
      const nextSkills = skills ?? originalSkills;

      let updatedCustomContent: MessageCustomContent | undefined;
      if (allAttachments.length > 0 || nextSkills?.length) {
        updatedCustomContent = {
          ...restCustomContent,
          ...(allAttachments.length > 0 ? { attachments: allAttachments } : {}),
          ...(nextSkills?.length ? { skills: nextSkills } : {}),
        };
      } else if (Object.keys(restCustomContent).length > 0) {
        updatedCustomContent = restCustomContent;
      } else {
        updatedCustomContent = undefined;
      }

      const updatedUserMessage = {
        ...originalMessage,
        content: text,
        custom_content: updatedCustomContent,
      };

      const now = Date.now();
      const assistantMessage = {
        role: MessageRole.Assistant,
        content: '',
        timestamp: new Date(now).toISOString(),
      };

      const updatedMessages = [
        ...conversation.messages.slice(0, idx),
        updatedUserMessage,
        assistantMessage,
      ];

      const updated = { ...conversation, messages: updatedMessages };

      /* The ref is assigned outside the updater because startStream reads it
       * synchronously below to seed its live-message buffer: React may defer a
       * function updater to the next render, which would seed the buffer with
       * the answer this edit replaces. */
      conversationRef.current = updated;
      setConversation(updated);

      const modelId = resolveModelId();

      // Backend will save the conversation at stream start; no pre-save needed.
      startStream(
        conversationId,
        text,
        updatedMessages.length - 1,
        modelId,
        updatedCustomContent,
        generateUUID(),
        CompletionMode.Edit,
      );

      setEditingMessageIndexes(new Set());
    },
    [
      conversation,
      conversationId,
      conversationRef,
      isStreaming,
      resolveModelId,
      setConversation,
      startStream,
    ],
  );

  return {
    handleSend,
    handleUploadAttachment,
    handleRegenerateMessage,
    handleDeleteMessage,
    handleConfirmDelete,
    handleRateMessage,
    handleButtonSelect,
    handleConfirmStarter,
    handleStartEdit,
    handleCancelEdit,
    handleEditMessage,
    editingMessageIndexes,
    pendingDeleteIndex,
    setPendingDeleteIndex,
    pendingStarterContext,
    setPendingStarterContext,
  };
}

export interface UseConversationImportParams {
  /** Already-configured generated-client instance used to persist imported conversations. */
  conversationsApi: Pick<ConversationsApi, 'saveConversation'>;
  /** Already-configured generated-client instance used to list/upload attachments. */
  filesApi: Pick<FilesApi, 'listFiles' | 'uploadFile'>;
  /** The current user's DIAL Core storage bucket. Import fails with `MissingBucket` when `undefined`. */
  bucket: string | undefined;
  /** Called after at least one conversation in a job was imported successfully. */
  onImported?: () => Promise<void> | void;
  /** Classifies a thrown error as unauthorized. Host-owned error taxonomy; defaults to never. */
  classifyTransferError?: (error: unknown) => { isUnauthorized?: boolean };
  /** Resolves a trace id for a failing request, for display in an error notification. */
  resolveErrorTraceId?: (error: unknown) => Promise<string | undefined>;
  /** Called when a job completes with at least one successfully imported conversation. */
  onSuccess?: (event: ConversationTransferSuccessEvent) => void;
  /** Called when a job succeeds but had to skip an attachment. */
  onWarning?: (event: ConversationTransferWarningEvent) => void;
  /** Called when a job fails, or when some conversations within it failed. */
  onError?: (event: ConversationTransferErrorEvent) => void;
}

export interface UseConversationImportResult {
  /** Import jobs, most recently added last. Multiple jobs can be in progress concurrently. */
  jobs: ConversationTransferJob[];
  /** Parses the given file and starts importing it as a new job. */
  importConversations: (file: File) => Promise<void>;
  /** Aborts a job's underlying requests and marks it canceled, keeping it in `jobs`. */
  cancelJob: (jobId: string) => void;
  /** Removes a job from the queue. If still in progress, aborts its underlying requests. */
  dismissJob: (jobId: string) => void;
  /** Re-attempts a failed or canceled job in place (same job id, reusing the already-parsed file). */
  retryJob: (jobId: string) => void;
  /** Aborts all in-progress jobs and clears the entire queue. */
  dismissAll: () => void;
}

useConversationImport = ({
  conversationsApi,
  filesApi,
  bucket,
  onImported,
  classifyTransferError = () => ({}),
  resolveErrorTraceId = async () => undefined,
  onSuccess,
  onWarning,
  onError,
}: UseConversationImportParams): UseConversationImportResult => {
  const queue = useConversationTransferQueue();

  const runImportJob = useCallback(
    async (
      jobId: string,
      parsed: ParsedImportFile,
      signal: AbortSignal,
    ): Promise<void> => {
      if (!bucket) {
        onError?.({
          jobId,
          code: ConversationTransferErrorCode.MissingBucket,
        });
        queue.failJob(jobId, ConversationTransferErrorCode.MissingBucket);
        return;
      }

      const kind = ConversationTransferKind.Import;
      const attachmentTotal = parsed.attachments.size;
      let attachmentsSettled = 0;
      const reportAttachmentSettled = (): void => {
        attachmentsSettled += 1;
        queue.setJobProgress(
          jobId,
          buildTransferProgress(
            {
              kind,
              phase: ConversationTransferPhase.Transfer,
              completed: attachmentsSettled,
              total: attachmentTotal,
            },
            {
              completed: Math.min(attachmentsSettled, attachmentTotal),
              total: attachmentTotal,
              kind: ConversationTransferUnitKind.Attachment,
            },
          ),
        );
      };
      const reportConversationSettled = (completed: number): void => {
        queue.setJobProgress(
          jobId,
          buildTransferProgress(
            {
              kind,
              phase: ConversationTransferPhase.Finalize,
              completed,
              total: parsed.history.length,
            },
            {
              completed,
              total: parsed.history.length,
              kind: ConversationTransferUnitKind.Conversation,
            },
          ),
        );
      };

      const successNames: string[] = [];
      const failedNames: string[] = [];
      /*
       * A set, not an array: the upload loop runs per conversation, so one
       * attachment referenced by several of them would otherwise be reported
       * once per referencing conversation.
       */
      const skippedAttachmentNames = new Set<string>();
      let isUnauthorized = false;
      /* Only the first failing conversation's trace ID is surfaced in the batch-failure event. */
      let firstFailureTraceId: string | undefined;
      const today = new Date();
      const isUnauthorizedError = (error: unknown): boolean =>
        !!classifyTransferError(error).isUnauthorized;

      /*
       * The allocator is created once for the whole job (not per conversation)
       * so a source path referenced by two different conversations in the same
       * archive still gets a distinct, deterministic ` (n)` suffix rather than
       * two competing uploads. It is pre-filled from the destination folder's
       * current contents so a name that already exists in the bucket — from an
       * earlier upload or a previous import — is suffixed immediately instead
       * of round-tripping through a 409 first.
       */
      let allocator: UploadPathAllocator | undefined;
      if (parsed.isArchive) {
        const uploadFolder = `uploads/${formatDateYM(today)}`;
        let existingNames: string[] = [];
        try {
          const listing = await filesApi.listFiles(
            { bucket, path: uploadFolder },
            { signal },
          );
          existingNames = listing.items.map((item) => item.name);
        } catch (error) {
          if (signal.aborted) return;
          if (isUnauthorizedError(error)) {
            onError?.({
              jobId,
              code: ConversationTransferErrorCode.Unauthorized,
            });
            queue.failJob(jobId, ConversationTransferErrorCode.Unauthorized);
            return;
          }
          /* Listing is an optimization, not a correctness requirement — a
           * missing month folder (404, common on the first import of the
           * month), a permissions error, or a network failure just means the
           * allocator starts empty and relies on retry-on-409 instead. */
          console.error(
            'Failed to list the upload folder for attachment name disambiguation',
            error,
          );
        }
        allocator = createUploadPathAllocator({ date: today, existingNames });
      }
      queue.setJobProgress(
        jobId,
        buildTransferProgress({
          kind,
          phase: ConversationTransferPhase.Prepare,
        }),
      );
      if (attachmentTotal === 0) {
        /* Credits the upload phase in full for a plain `.json` import. */
        queue.setJobProgress(
          jobId,
          buildTransferProgress({
            kind,
            phase: ConversationTransferPhase.Transfer,
          }),
        );
      }

      for (const conversation of parsed.history) {
        if (signal.aborted) return;
        if (isUnauthorized) break;

        try {
          let targetMap = new Map<string, RewrittenAttachmentTarget>();
          if (parsed.isArchive && allocator) {
            const result = await uploadConversationAttachments(
              conversation,
              parsed.attachments,
              bucket,
              allocator,
              filesApi,
              isUnauthorizedError,
              reportAttachmentSettled,
              signal,
            );
            if (signal.aborted) return;
            if (result.isUnauthorized) {
              isUnauthorized = true;
              break;
            }
            for (const skippedName of result.skippedNames) {
              skippedAttachmentNames.add(skippedName);
            }
            targetMap = result.targetMap;
          }

          const rewritten = rewriteAttachmentUrls(conversation, targetMap);
          const { conversation: regenerated, subPath } = rebaseConversationId(
            rewritten,
            bucket,
          );

          /*
           * `llmNamingDone` marks `name` as authoritative on the backend —
           * without it, the stored name is treated as provisional and can be
           * overwritten by the async LLM auto-naming hook. The imported
           * conversation already has its real (exported) name, so force this
           * true to keep it and skip the naming hook, regardless of what the
           * source file carried.
           */
          await conversationsApi.saveConversation(
            {
              path: subPath,
              saveConversationBodyDto: {
                conversation: {
                  ...regenerated,
                  llmNamingDone: true,
                } as unknown as ConversationResponseDto,
              },
            },
            { signal },
          );
          if (signal.aborted) return;
          /* The stored name, not the source one — `rebaseConversationId`
           * sanitizes it, and the notification must name what the list shows. */
          successNames.push(regenerated.name);
        } catch (error) {
          if (signal.aborted) return;
          if (isUnauthorizedError(error)) {
            isUnauthorized = true;
            break;
          }
          failedNames.push(conversation.name);
          if (firstFailureTraceId === undefined) {
            firstFailureTraceId = await resolveErrorTraceId(error);
          }
          console.error('Failed to import a conversation', error);
        }
        reportConversationSettled(successNames.length + failedNames.length);
      }
      if (signal.aborted) return;

      if (isUnauthorized) {
        onError?.({ jobId, code: ConversationTransferErrorCode.Unauthorized });
        queue.failJob(jobId, ConversationTransferErrorCode.Unauthorized);
        return;
      }

      if (successNames.length > 0) {
        try {
          await onImported?.();
        } catch {
          /* The saves already succeeded; a refresh failure must not undo that success. */
        }
        onSuccess?.({ jobId, titles: successNames });
      }
      if (failedNames.length > 0) {
        onError?.({
          jobId,
          code: ConversationTransferErrorCode.Unknown,
          titles: failedNames,
          traceId: firstFailureTraceId,
        });
      }
      if (skippedAttachmentNames.size > 0) {
        onWarning?.({
          jobId,
          code: ConversationTransferWarningCode.AttachmentSkipped,
          names: [...skippedAttachmentNames],
        });
      }
      if (failedNames.length > 0) {
        queue.failJob(jobId, ConversationTransferErrorCode.Unknown);
      } else if (skippedAttachmentNames.size > 0) {
        /*
         * Every conversation imported, but some of their attachments did not
         * come across — delivered, yet not what the user asked for.
         */
        queue.warnJob(
          jobId,
          ConversationTransferWarningCode.AttachmentSkipped,
          [...skippedAttachmentNames],
        );
      } else {
        queue.succeedJob(jobId);
      }
    },
    [
      bucket,
      classifyTransferError,
      conversationsApi,
      filesApi,
      onError,
      onImported,
      onSuccess,
      onWarning,
      queue,
      resolveErrorTraceId,
    ],
  );

  const importConversations = useCallback(
    async (file: File): Promise<void> => {
      let parsed: ParsedImportFile;
      try {
        parsed = await parseImportFile(file);
      } catch (error) {
        /* No job is added for a file that never parses — there is nothing to
         * queue, retry, or dismiss. `jobId` is a transient correlation id
         * only, not a member of `jobs`. */
        onError?.({
          jobId: generateUUID(),
          code: ConversationTransferErrorCode.UnsupportedFormat,
        });
        if (!(error instanceof UnsupportedImportFormatError)) {
          console.error('Failed to parse import file', error);
        }
        return;
      }

      const isMultiple = parsed.history.length > 1;
      const firstConversation = parsed.history[0];
      const subject = isMultiple
        ? { kind: ConversationTransferSubjectKind.All as const }
        : {
            kind: ConversationTransferSubjectKind.Single as const,
            title: firstConversation?.name ?? file.name,
            sourceBreadcrumb: firstConversation
              ? getFolderBreadcrumb(firstConversation)
              : undefined,
          };

      const jobId = queue.addJob(subject, file.name);
      return queue.startJob(jobId, (signal) =>
        runImportJob(jobId, parsed, signal),
      );
    },
    [onError, queue, runImportJob],
  );

  return {
    jobs: queue.jobs,
    importConversations,
    cancelJob: queue.cancelJob,
    dismissJob: queue.dismissJob,
    retryJob: queue.retryJob,
    dismissAll: queue.dismissAll,
  };
}

export interface UseConversationScrollParams<T> {
  /** Messages currently rendered in the list. */
  messages: T[];
  /** Whether an assistant response is currently streaming in. */
  isAssistantTyping: boolean;
  /** Identifier of the conversation being displayed. */
  conversationId: string;
}

export interface UseConversationScrollResult {
  /** Attach to the scrollable message-list element. */
  containerRef: RefObject<HTMLDivElement | null>;
  /** Attach to the element wrapping all rendered messages (used to detect content growth). */
  contentRef: RefObject<HTMLDivElement | null>;
  /**
   * Attach to a spacer element, a sibling rendered right after `contentRef`
   * inside `containerRef`. Its height is set imperatively, not via React
   * state. Render it with `shrink-0` and an initial `style={{ height: 0 }}`.
   */
  spacerRef: RefObject<HTMLDivElement | null>;
  /** Callback ref to register/unregister a rendered message's DOM node by index. */
  setMessageRef: (index: number, el: HTMLDivElement | null) => void;
  /** Whether the scroll-to-bottom button should be shown. */
  isScrollButtonVisible: boolean;
  /** Smoothly scrolls to the current bottom of the actual message content. */
  scrollToBottom: () => void;
  /**
   * Arms the message at `index` to be scrolled near the top of the viewport
   * on the next render — call right before triggering a send, regenerate,
   * or edit-and-resubmit so the resulting message anchors near the top.
   */
  armAnchor: (index: number) => void;
}

useConversationScroll = <T>({
  messages,
  isAssistantTyping,
  conversationId,
}: UseConversationScrollParams<T>): UseConversationScrollResult => {
  const [isScrollButtonVisible, setIsScrollButtonVisible] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  const spacerRef = useRef<HTMLDivElement>(null);
  const isSpacerActiveRef = useRef(false);
  const isSpacerSettledRef = useRef(false);
  const anchorScrollTopRef = useRef<number | null>(null);

  /*
   * Message DOM nodes keyed by index, used to anchor the acted-on message
   * without coupling this hook to send/regenerate/edit handlers.
   */
  const messageRefsMap = useRef<Map<number, HTMLDivElement>>(new Map());
  const setMessageRef = useCallback(
    (index: number, el: HTMLDivElement | null) => {
      if (el) {
        messageRefsMap.current.set(index, el);
      } else {
        messageRefsMap.current.delete(index);
      }
    },
    [],
  );

  /*
   * Message index to anchor after the next render. It is set by `armAnchor`
   * and consumed once by the layout effect below.
   */
  const pendingAnchorIndexRef = useRef<number | null>(null);
  const armAnchor = useCallback((index: number) => {
    pendingAnchorIndexRef.current = index;
  }, []);

  const performScroll = useCallback((targetTop: number, instant: boolean) => {
    const container = containerRef.current;
    if (!container) return;
    container.scrollTo({
      top: targetTop,
      behavior: instant ? 'instant' : 'smooth',
    });
  }, []);

  const clearSpacer = useCallback(() => {
    if (spacerRef.current) {
      spacerRef.current.style.height = '0px';
    }
    isSpacerActiveRef.current = false;
    isSpacerSettledRef.current = false;
    anchorScrollTopRef.current = null;
  }, []);

  /*
   * ScrollTop where the real content bottom, excluding spacer space, aligns
   * with the viewport bottom.
   */
  const getContentBottomScrollTop = useCallback(() => {
    const container = containerRef.current;
    const content = contentRef.current;
    if (!container || !content) return null;
    const containerRect = container.getBoundingClientRect();
    const contentRect = content.getBoundingClientRect();
    return (
      container.scrollTop +
      (contentRect.bottom - containerRect.top) -
      container.clientHeight
    );
  }, []);

  const scrollToBottom = useCallback(
    (instant = false) => {
      const target = getContentBottomScrollTop();
      if (target == null) return;
      performScroll(Math.max(target, 0), instant);
    },
    [performScroll, getContentBottomScrollTop],
  );

  const getDistanceFromContentBottom = useCallback(() => {
    const container = containerRef.current;
    const content = contentRef.current;
    if (!container || !content) return null;
    const containerRect = container.getBoundingClientRect();
    const contentRect = content.getBoundingClientRect();
    return contentRect.bottom - containerRect.top - container.clientHeight;
  }, []);

  const clearSettledSpacerIfPossible = useCallback(() => {
    if (!isSpacerSettledRef.current) return;

    const distanceFromContentBottom = getDistanceFromContentBottom();
    if (
      distanceFromContentBottom == null ||
      distanceFromContentBottom < -SPACER_CLEAR_TOLERANCE
    ) {
      return;
    }

    clearSpacer();
  }, [clearSpacer, getDistanceFromContentBottom]);

  /*
   * Uses rects instead of `offsetTop` because message internals can introduce
   * positioned ancestors for action controls.
   */
  const getMessageTopScrollTarget = useCallback((index: number) => {
    const container = containerRef.current;
    const el = messageRefsMap.current.get(index);
    if (!container || !el) return null;

    const containerRect = container.getBoundingClientRect();
    const elRect = el.getBoundingClientRect();
    const targetTop = container.scrollTop + (elRect.top - containerRect.top);
    return Math.max(targetTop, 0);
  }, []);

  const scrollMessageToTop = useCallback(
    (index: number, instant = false) => {
      const targetTop = getMessageTopScrollTarget(index);
      if (targetTop == null) return;

      performScroll(targetTop, instant);
    },
    [getMessageTopScrollTarget, performScroll],
  );

  const getMaxScrollTopExcludingSpacer = useCallback(() => {
    const target = getContentBottomScrollTop();
    return target == null ? null : Math.max(target, 0);
  }, [getContentBottomScrollTop]);

  const getMaxAllowedScrollTop = useCallback(() => {
    if (!isSpacerActiveRef.current) return null;

    const anchorScrollTop = anchorScrollTopRef.current;
    const contentBottomScrollTop = getMaxScrollTopExcludingSpacer();
    if (anchorScrollTop == null || contentBottomScrollTop == null) return null;

    return Math.max(anchorScrollTop, contentBottomScrollTop);
  }, [getMaxScrollTopExcludingSpacer]);

  const clampScrollToVisibleContent = useCallback(() => {
    const container = containerRef.current;
    const maxAllowedScrollTop = getMaxAllowedScrollTop();
    if (!container || maxAllowedScrollTop == null) return;

    if (container.scrollTop > maxAllowedScrollTop + SCROLL_CLAMP_TOLERANCE) {
      container.scrollTop = maxAllowedScrollTop;
    }
  }, [getMaxAllowedScrollTop]);

  const applyAnchorSpacer = useCallback(
    (targetTop: number) => {
      const spacer = spacerRef.current;
      const maxScrollTopExcludingSpacer = getMaxScrollTopExcludingSpacer();
      if (!spacer || maxScrollTopExcludingSpacer == null) return;

      const spacerHeight = Math.max(targetTop - maxScrollTopExcludingSpacer, 0);
      spacer.style.height = `${spacerHeight}px`;
      isSpacerActiveRef.current = spacerHeight > 0;
      isSpacerSettledRef.current = false;
      anchorScrollTopRef.current = spacerHeight > 0 ? targetTop : null;
    },
    [getMaxScrollTopExcludingSpacer],
  );

  const scrollMessageToTopWithReservation = useCallback(
    (index: number) => {
      const targetTop = getMessageTopScrollTarget(index);
      if (targetTop == null) return;

      applyAnchorSpacer(targetTop);
      scrollMessageToTop(index, false);
    },
    [applyAnchorSpacer, getMessageTopScrollTarget, scrollMessageToTop],
  );

  /*
   * Measures distance to real content bottom so spacer space alone does not
   * keep the scroll-to-bottom button visible.
   */
  const updateScrollButtonVisibility = useCallback(() => {
    const distanceFromContentBottom = getDistanceFromContentBottom();
    if (distanceFromContentBottom == null) return;
    setIsScrollButtonVisible(
      distanceFromContentBottom >= NEAR_BOTTOM_THRESHOLD,
    );
  }, [getDistanceFromContentBottom]);

  /*
   * Anchor an armed turn once. Other non-streaming length changes, such as
   * loading a conversation or deleting a message, keep the old bottom-scroll
   * behavior.
   */
  const prevLengthRef = useRef(messages.length);
  const prevConversationIdRef = useRef<string | null>(null);
  useLayoutEffect(() => {
    const lengthChanged = messages.length !== prevLengthRef.current;
    const conversationChanged =
      conversationId !== prevConversationIdRef.current;

    const commitObservedScrollState = () => {
      prevLengthRef.current = messages.length;
      prevConversationIdRef.current = conversationId;
    };

    if (conversationChanged) {
      clearSpacer();
    }

    const anchorIndex = pendingAnchorIndexRef.current;
    if (anchorIndex != null && messageRefsMap.current.has(anchorIndex)) {
      pendingAnchorIndexRef.current = null;
      scrollMessageToTopWithReservation(anchorIndex);
      commitObservedScrollState();
      return;
    }

    if (isAssistantTyping) return;

    if (lengthChanged || conversationChanged) {
      scrollToBottom(false);
    }

    commitObservedScrollState();
  }, [
    messages,
    isAssistantTyping,
    conversationId,
    scrollToBottom,
    scrollMessageToTopWithReservation,
    clearSpacer,
  ]);

  /*
   * Keep a completed short reply anchored with its reserved room until the
   * user scrolls far enough up that removing the spacer cannot clamp scrollTop.
   */
  useLayoutEffect(() => {
    if (!isAssistantTyping && isSpacerActiveRef.current) {
      isSpacerSettledRef.current = true;
      clearSettledSpacerIfPossible();
    }
  }, [isAssistantTyping, clearSettledSpacerIfPossible]);

  const handleScroll = useCallback(() => {
    clampScrollToVisibleContent();
    clearSettledSpacerIfPossible();
    updateScrollButtonVisibility();
  }, [
    clampScrollToVisibleContent,
    clearSettledSpacerIfPossible,
    updateScrollButtonVisibility,
  ]);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;
    container.addEventListener('scroll', handleScroll, {
      passive: true,
    });
    return () => container.removeEventListener('scroll', handleScroll);
  }, [handleScroll]);

  /*
   * Streaming grows content without firing a native scroll event. Observe
   * content size so the button reflects newly hidden content below the fold.
   */
  useEffect(() => {
    const content = contentRef.current;
    if (!content) return;
    const observer = new ResizeObserver(() => {
      clampScrollToVisibleContent();
      clearSettledSpacerIfPossible();
      updateScrollButtonVisibility();
    });
    observer.observe(content);
    return () => observer.disconnect();
  }, [
    clampScrollToVisibleContent,
    clearSettledSpacerIfPossible,
    updateScrollButtonVisibility,
  ]);

  const handleScrollToBottom = useCallback(() => {
    scrollToBottom(false);
  }, [scrollToBottom]);

  return {
    containerRef,
    contentRef,
    spacerRef,
    setMessageRef,
    isScrollButtonVisible,
    scrollToBottom: handleScrollToBottom,
    armAnchor,
  };
}

export interface StreamCompletionOptions {
  onChunk: (chunk: StreamChunk) => void;
  onComplete: () => void | Promise<void>;
  onError: (error: Error) => void;
  signal: AbortSignal;
}

export interface ConversationStreamTransport {
  /** Starts a completion; delivers chunks/completion/error through `options`, aborted via `options.signal`. */
  streamCompletion(
    path: string,
    message: string | undefined,
    model: string,
    options: StreamCompletionOptions,
    customContent?: MessageCustomContent,
    generationId?: string,
    mode?: SendCompletionDtoModeEnum,
    messageIndex?: number,
    clientChannelId?: string,
  ): void;
  /** Requests the backend stop an active generation. */
  stopCompletion(params: { generationId: string; path: string }): Promise<void>;
  /** Opens a stream of resource-update events for `path`, until aborted via `signal`. */
  watchConversation(
    path: string,
    signal: AbortSignal,
  ): Promise<ReadableStream<Uint8Array>>;
  /**
   * Attaches to an active generation's live replay: a `snapshot` event
   * carrying the assistant message as assembled so far, then a `chunk` event
   * per subsequent delta, then exactly one terminal event (`done`/`error`/
   * `stopped`), until aborted via `signal`. Rejects when no active
   * generation exists for `path` — including one that already finished —
   * so the caller can fall back to `watchConversation`.
   */
  attachToGeneration(
    path: string,
    signal: AbortSignal,
  ): Promise<ReadableStream<Uint8Array>>;
  /** Reloads the persisted conversation by its full (bucket-qualified) id. */
  getConversation(
    conversationId: string,
    signal?: AbortSignal,
  ): Promise<Conversation>;
}

export interface ConversationGenerationLifecycle {
  /** Starts (or replaces) tracking for a generation on `path`, returning its `AbortController`. */
  startGeneration: (path: string, generationId: string) => AbortController;
  /** Marks the generation identified by `path`/`generationId` complete, if it is still the active one. */
  completeGeneration: (path: string, generationId: string) => void;
}

export interface ConversationStreamChannel {
  channelId: string | null;
  ensureConnected: () => void;
  /** Resolves with a channel id, waiting for an in-flight subscribe if one isn't established yet, so a completion sent immediately after mount can still carry it. */
  waitForChannel: (timeoutMs?: number) => Promise<string | null>;
  /** Notifies the host that a generation just ended (completed or errored), so it can consider disconnecting an idle channel. */
  notifyGenerationSettled?: () => void;
}

export interface ConversationStreamOverlayNotifier {
  notifyGenerationStart?: () => void;
  notifyGenerationEnd?: () => void;
  notifyStopGenerating?: () => void;
}

export interface ConversationStateAccessor {
  setConversation: Dispatch<SetStateAction<Conversation | null>>;
  conversationRef: MutableRefObject<Conversation | null>;
}

export interface UseConversationStreamParams {
  conversationId: string | undefined;
  state: ConversationStateAccessor;
  transport: ConversationStreamTransport;
  generation: ConversationGenerationLifecycle;
  channel?: ConversationStreamChannel;
  overlay?: ConversationStreamOverlayNotifier;
  onStopError?: (error: Error) => void;
  /**
   * Message shown on the message bubble when the backend rejects a completion
   * because this conversation is already generating — the case a second
   * browser tab of the same session hits. Defaults to
   * {@link DEFAULT_GENERATION_CONFLICT_MESSAGE}.
   */
  generationConflictMessage?: string;
}

export interface UseConversationStreamResult {
  startStream: (
    conversationId: string,
    userContent: string,
    messageIndex: number,
    model: string,
    customContent?: MessageCustomContent,
    generationId?: string,
    mode?: SendCompletionDtoModeEnum,
  ) => void;
  handleStop: () => void;
  resumeIfAwaitingGeneration: (
    currentConversationId: string,
    conversation: Conversation,
  ) => void;
  /** Restores the accumulated live assistant message when its conversation is loaded again before completion. */
  restoreBufferedGeneration: (
    currentConversationId: string,
    conversation: Conversation,
  ) => Conversation;
  isStreaming: boolean;
  canStopStreaming: boolean;
}

useConversationStream = ({
  conversationId,
  state: { setConversation, conversationRef },
  transport,
  generation: { startGeneration, completeGeneration },
  channel,
  overlay,
  onStopError,
  generationConflictMessage = DEFAULT_GENERATION_CONFLICT_MESSAGE,
}: UseConversationStreamParams): UseConversationStreamResult => {
  /*
   * Paths with an in-flight generation. A Set (not a boolean) so concurrent
   * generations across conversations each track their own streaming state.
   */
  const [streamingPaths, setStreamingPaths] = useState<Set<string>>(
    () => new Set(),
  );
  const [stoppablePath, setStoppablePath] = useState<string | null>(null);
  const activeGenerationIdRef = useRef<string | null>(null);
  const activeGenerationPathRef = useRef<string | null>(null);
  const resumingPathsRef = useRef<Set<string>>(new Set());
  const bufferedGenerationsRef = useRef<Map<string, BufferedGeneration>>(
    new Map(),
  );
  /* Generation ids stopped by the user — onComplete emits notifyStopGenerating's
   * counterpart (nothing) instead of notifyGenerationEnd for these. */
  const stoppedGenerationIdsRef = useRef<Set<string>>(new Set());
  /** Newest generation id started for each path — see `isSuperseded` in `startStream`. */
  const latestGenerationIdsRef = useRef<Map<string, string>>(new Map());

  /*
   * The host component isn't necessarily remounted when navigating between
   * conversations, so this single hook instance may be reused. Stream
   * callbacks must therefore know which conversation is *currently displayed*
   * to avoid writing chunks/reloads into the wrong conversation's state.
   */
  const displayedConversationIdRef = useRef<string | undefined>(conversationId);
  useEffect(() => {
    displayedConversationIdRef.current = conversationId;
  }, [conversationId]);

  const isPathDisplayed = useCallback(
    (path: string): boolean =>
      getConversationPath(displayedConversationIdRef.current ?? '') === path,
    [],
  );

  const addStreamingPath = useCallback((path: string) => {
    setStreamingPaths((prev) => {
      if (prev.has(path)) return prev;
      const next = new Set(prev);
      next.add(path);
      return next;
    });
  }, []);

  const removeStreamingPath = useCallback((path: string) => {
    setStreamingPaths((prev) => {
      if (!prev.has(path)) return prev;
      const next = new Set(prev);
      next.delete(path);
      return next;
    });
  }, []);

  /*
   * An in-flight generation is intentionally NOT aborted on unmount: it is
   * owned by the injected `generation` lifecycle and must survive
   * navigation; only Stop or tab close ends it.
   */

  const startStream = useCallback(
    (
      currentConversationId: string,
      userContent: string,
      messageIndex: number,
      model: string,
      customContent?: MessageCustomContent,
      generationId?: string,
      mode: SendCompletionDtoModeEnum = SendCompletionDtoModeEnum.Append,
    ) => {
      const genId = generationId ?? generateUUID();
      const conversationPath = getConversationPath(currentConversationId);
      activeGenerationIdRef.current = genId;
      activeGenerationPathRef.current = conversationPath;
      latestGenerationIdsRef.current.set(conversationPath, genId);
      setStoppablePath(conversationPath);

      /*
       * `messageIndex` is the local placeholder index (for onChunk); translate it
       * to the backend's truncation index. `Regenerate` truncates at the
       * assistant (same index); `Edit` truncates at the user message (one
       * before it). Any other mode passes no truncation index (append).
       */
      let serverMessageIndex: number | undefined;
      if (mode === SendCompletionDtoModeEnum.Regenerate) {
        serverMessageIndex = messageIndex;
      } else if (mode === SendCompletionDtoModeEnum.Edit) {
        serverMessageIndex = messageIndex - 1;
      }

      /*
       * True once a newer generation has been started on this path: the user
       * stopped this one and immediately re-submitted (Stop re-enables
       * edit/regenerate as soon as the stopped stream closes, while this
       * generation's conversation reload is still in flight). A superseded
       * generation must not clear the new one's streaming state, report its
       * end, or overwrite the conversation with the answer it had fetched.
       */
      const isSuperseded = (): boolean =>
        latestGenerationIdsRef.current.get(conversationPath) !== genId;

      const controller = startGeneration(conversationPath, genId);
      const initialMessage = conversationRef.current?.messages[messageIndex];
      if (initialMessage) {
        bufferedGenerationsRef.current.set(conversationPath, {
          generationId: genId,
          messageIndex,
          message: initialMessage,
        });
      } else {
        bufferedGenerationsRef.current.delete(conversationPath);
      }
      addStreamingPath(conversationPath);
      overlay?.notifyGenerationStart?.();

      /*
       * Best-effort: nudge a disconnected client channel to reconnect so a
       * tool-signin event has a chance to reach this completion.
       */
      channel?.ensureConnected();

      const completionOptions: StreamCompletionOptions = {
        signal: controller.signal,
        onChunk: (chunk) => {
          /*
           * Drop stale chunks from a superseded generation. Background chunks
           * still update the per-path buffer, so returning before the backend's
           * terminal save restores the complete live message.
           */
          if (activeGenerationIdRef.current !== genId) return;

          const buffered = bufferedGenerationsRef.current.get(conversationPath);
          if (buffered?.generationId === genId) {
            const updated = applyChunkToMessages([buffered.message], 0, chunk);
            if (updated) buffered.message = updated[0];
          }

          if (!isPathDisplayed(conversationPath)) return;
          setConversation((prev) => {
            if (!prev) return prev;
            const currentBuffer =
              bufferedGenerationsRef.current.get(conversationPath);
            let next: Conversation;
            if (currentBuffer?.generationId === genId) {
              next = restoreBufferedMessage(prev, currentBuffer);
            } else {
              const updatedMessages = applyChunkToMessages(
                prev.messages,
                messageIndex,
                chunk,
              );
              if (!updatedMessages) return prev;
              next = { ...prev, messages: updatedMessages };
            }
            conversationRef.current = next;
            return next;
          });
        },
        onComplete: async () => {
          if (
            bufferedGenerationsRef.current.get(conversationPath)
              ?.generationId === genId
          ) {
            bufferedGenerationsRef.current.delete(conversationPath);
          }
          if (!isSuperseded()) removeStreamingPath(conversationPath);
          if (activeGenerationIdRef.current === genId) {
            activeGenerationIdRef.current = null;
            activeGenerationPathRef.current = null;
            setStoppablePath(null);
          }
          completeGeneration(conversationPath, genId);
          channel?.notifyGenerationSettled?.();
          if (stoppedGenerationIdsRef.current.has(genId)) {
            stoppedGenerationIdsRef.current.delete(genId);
          } else if (!isSuperseded()) {
            overlay?.notifyGenerationEnd?.();
          }
          /* The generation that superseded this one owns the displayed state
           * and reloads it when it settles. */
          if (isSuperseded()) return;
          /*
           * Only refresh displayed state if the user is still viewing this
           * conversation; otherwise leave the currently-shown chat untouched.
           */
          if (!isPathDisplayed(conversationPath)) return;
          try {
            /*
             * Backend has already saved the conversation; reload to get
             * server-persisted state (including server-computed fields
             * like stage attachment `data`). Unlike `streamCompletion`/
             * `watchConversation` (which take the bucket-stripped
             * `conversationPath`), `getConversation` needs the full
             * `{bucket}/{name}` path — already-percent-encoded segments
             * are decoded back to raw first so the transport's own
             * encoding doesn't double-encode them.
             */
            const refreshed = await transport.getConversation(
              safeDecodeURI(currentConversationId),
            );
            /* Re-checked after the round trip: a re-submit during it makes this
             * reload stale — it would restore the answer the user just replaced. */
            if (isSuperseded() || !isPathDisplayed(conversationPath)) return;
            setConversation(refreshed);
            conversationRef.current = refreshed;
          } catch {
            // Non-fatal: keep local state if reload fails
          }
        },
        onError: (error: Error) => {
          const currentBuffer =
            bufferedGenerationsRef.current.get(conversationPath);
          const buffered =
            currentBuffer?.generationId === genId ? currentBuffer : undefined;
          if (buffered) bufferedGenerationsRef.current.delete(conversationPath);
          if (!isSuperseded()) removeStreamingPath(conversationPath);
          if (activeGenerationIdRef.current === genId) {
            activeGenerationIdRef.current = null;
            activeGenerationPathRef.current = null;
            setStoppablePath(null);
          }
          completeGeneration(conversationPath, genId);
          channel?.notifyGenerationSettled?.();
          /* Surface the error only on the conversation the user is viewing,
           * and never over the generation that superseded this one. */
          if (isSuperseded() || !isPathDisplayed(conversationPath)) return;
          /*
           * A conflict is an expected state, not a transport failure: another
           * tab of this session is already generating into this conversation,
           * so it gets the host-supplied explanation rather than the raw
           * error text (issue #8688).
           */
          const streamErrorMessage =
            error instanceof GenerationConflictError
              ? generationConflictMessage
              : error.message;
          setConversation((prev) => {
            if (!prev) return prev;
            const restored =
              buffered?.generationId === genId
                ? restoreBufferedMessage(prev, buffered)
                : prev;
            const updated = {
              ...restored,
              messages: restored.messages.map((m, index) =>
                index === messageIndex ? { ...m, streamErrorMessage } : m,
              ),
            };
            conversationRef.current = updated;
            return updated;
          });
        },
      };

      // See client-channel-protocol spec for the full rationale.
      const send = async () => {
        try {
          const clientChannelId =
            channel?.channelId ??
            (await channel?.waitForChannel(CHANNEL_WAIT_TIMEOUT_MS)) ??
            undefined;

          /*
           * Under demand-driven subscribe this wait now routinely suspends on
           * a cold subscribe round trip (rather than resolving immediately, as
           * it usually did while the channel was already up). Stop or a
           * re-submit can therefore land while this await is outstanding.
           * `handleStop` never calls `transport.streamCompletion`, so
           * `stoppedGenerationIdsRef` — not `controller.signal.aborted`, which
           * a plain Stop never sets — is what a user-initiated stop leaves
           * behind; a re-submit is caught by `isSuperseded()` (and, since it
           * replaces an Active entry on the same path, `startGeneration`
           * itself aborts this generation's controller too).
           */
          const isStopped = stoppedGenerationIdsRef.current.has(genId);
          if (controller.signal.aborted || isSuperseded() || isStopped) {
            /*
             * Nothing was ever sent, so there is no stream for onComplete/
             * onError to settle through — perform the same settlement
             * bookkeeping they would have (minus the reload, since no
             * completion was made): release this generation's demand, close
             * out the tracked generation entry, and clear per-path streaming
             * state, so neither the client channel nor the "is generating"
             * state is left stuck.
             */
            if (
              bufferedGenerationsRef.current.get(conversationPath)
                ?.generationId === genId
            ) {
              bufferedGenerationsRef.current.delete(conversationPath);
            }
            if (!isSuperseded()) removeStreamingPath(conversationPath);
            if (activeGenerationIdRef.current === genId) {
              activeGenerationIdRef.current = null;
              activeGenerationPathRef.current = null;
              setStoppablePath(null);
            }
            completeGeneration(conversationPath, genId);
            channel?.notifyGenerationSettled?.();
            if (isStopped) {
              stoppedGenerationIdsRef.current.delete(genId);
            } else if (!isSuperseded()) {
              overlay?.notifyGenerationEnd?.();
            }
            return;
          }

          transport.streamCompletion(
            conversationPath,
            userContent,
            model,
            completionOptions,
            customContent,
            genId,
            mode,
            serverMessageIndex,
            clientChannelId,
          );
        } catch (err: unknown) {
          /* streamCompletion is typed void but may throw synchronously; route
           * through onError to preserve the error semantics the calling effect
           * previously got from a synchronous throw. */
          completionOptions.onError(
            err instanceof Error ? err : new Error(String(err)),
          );
        }
      };
      void send();
    },
    // setConversation and conversationRef are stable refs — intentionally omitted
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [
      startGeneration,
      completeGeneration,
      addStreamingPath,
      removeStreamingPath,
      isPathDisplayed,
      channel?.channelId,
      channel?.ensureConnected,
      channel?.waitForChannel,
      channel?.notifyGenerationSettled,
      overlay,
      transport,
      generationConflictMessage,
    ],
  );

  const restoreBufferedGeneration = useCallback(
    (
      currentConversationId: string,
      conversation: Conversation,
    ): Conversation => {
      const conversationPath = getConversationPath(currentConversationId);
      const buffered = bufferedGenerationsRef.current.get(conversationPath);
      return buffered
        ? restoreBufferedMessage(conversation, buffered)
        : conversation;
    },
    [],
  );

  const handleStop = useCallback(() => {
    const genId = activeGenerationIdRef.current;
    if (!genId || !conversationId) return;

    const conversationPath = getConversationPath(conversationId);
    if (activeGenerationPathRef.current !== conversationPath) return;

    stoppedGenerationIdsRef.current.add(genId);
    overlay?.notifyStopGenerating?.();

    /*
     * Only signal the backend; it aborts upstream, saves the partial, and closes
     * the stream. Keeping our fetch open lets onComplete reload the saved partial
     * race-free (do not reload here — it would race the backend save).
     */
    void transport
      .stopCompletion({ generationId: genId, path: conversationPath })
      .catch((err: unknown) => {
        const error = err instanceof Error ? err : new Error(String(err));
        onStopError?.(error);
      });
  }, [conversationId, onStopError, overlay, transport]);

  const resumeIfAwaitingGeneration = useMemo(
    () =>
      createResumeIfAwaitingGeneration({
        transport,
        setConversation,
        conversationRef,
        resumingPathsRef,
        bufferedGenerationsRef,
        addStreamingPath,
        removeStreamingPath,
        isPathDisplayed,
      }),
    // setConversation and conversationRef are stable refs — intentionally omitted
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [addStreamingPath, removeStreamingPath, isPathDisplayed, transport],
  );

  /*
   * Reflects only the currently-displayed conversation: a stream running in a
   * different chat must not show this chat as generating.
   */
  const isStreaming =
    conversationId != null &&
    streamingPaths.has(getConversationPath(conversationId));
  const displayedConversationPath =
    conversationId != null ? getConversationPath(conversationId) : null;
  const canStopStreaming =
    displayedConversationPath != null &&
    stoppablePath === displayedConversationPath;

  return {
    startStream,
    handleStop,
    resumeIfAwaitingGeneration,
    restoreBufferedGeneration,
    isStreaming,
    canStopStreaming,
  };
}

export interface UseConversationSourcesResult {
  /** Deduplicated attachments the user uploaded across the conversation. */
  uploaded: DisplayAttachment[];
  /** Deduplicated attachments the assistant generated across the conversation. */
  generated: DisplayAttachment[];
  /** Quotation sources referenced by assistant messages, deduplicated by URL. */
  sources: QuotationSource[];
}

useConversationSources = (
  messages: Message[],
  resolvers: AttachmentDisplayResolvers = EMPTY_RESOLVERS,
): UseConversationSourcesResult => {
  return useMemo(() => {
    const uploaded: DisplayAttachment[] = [];
    const generated: DisplayAttachment[] = [];
    const sources: QuotationSource[] = [];
    const seenUrls = new Set<string>();
    const seenUploadedIds = new Set<string | undefined>();
    const seenGeneratedIds = new Set<string | undefined>();

    for (const msg of messages) {
      const dtos = msg.custom_content?.attachments;
      if (msg.role === MessageRole.User) {
        for (const dto of dtos ?? []) {
          const att = messageAttachmentToDisplayAttachment(dto, resolvers);
          if (seenUploadedIds.has(att.id)) continue;
          seenUploadedIds.add(att.id);
          uploaded.push(att);
        }
      } else if (msg.role === MessageRole.Assistant) {
        const regularDtos = dtos?.filter(
          (dto) => !isReferenceOnlyAttachment(dto),
        );
        for (const dto of regularDtos ?? []) {
          const att = messageAttachmentToDisplayAttachment(dto, resolvers);
          if (seenGeneratedIds.has(att.id)) continue;
          seenGeneratedIds.add(att.id);
          generated.push(att);
        }

        for (const dto of dtos ?? []) {
          if (!isReferenceOnlyAttachment(dto)) continue;
          const url = dto.reference_url as string;
          if (seenUrls.has(url)) continue;
          seenUrls.add(url);
          sources.push({
            url,
            title: dto.title ?? url,
            contentType: dto.reference_type ?? dto.type ?? '',
            quote: dto.data,
          });
        }

        for (const annotation of resolveMessageAnnotations(msg)) {
          const att = annotation?.body?.source?.attachment;
          const url = att?.url;
          if (!url || seenUrls.has(url)) continue;
          seenUrls.add(url);
          sources.push({
            url,
            title: att?.title ?? url.split('/').pop() ?? url,
            contentType: att?.type ?? '',
            quote: annotation.body?.quote,
          });
        }
      }
    }

    return { uploaded, generated, sources };
  }, [messages, resolvers]);
}

export enum DialFilesApiUploadMode {
  Overwrite = 'overwrite',
  CreateOnly = 'create-only',
}

export interface DialFilesApiUploadOptions {
  /** Aborts the in-flight upload when triggered. */
  signal?: AbortSignal;
  /** Called with the 0–100 upload progress percentage when the transport reports byte progress. */
  onProgress?: (percent: number) => void;
  /** Controls create-only vs. overwrite semantics for the destination path. */
  uploadMode?: DialFilesApiUploadMode;
}

export interface DialFilesApi {
  /** Lists files/folders directly under `params.path` within `params.bucket`. */
  listFiles(
    params: {
      bucket: string;
      path?: string;
      token?: string;
      limit?: number;
      recursive?: boolean;
      permissions?: boolean;
    },
    signal?: AbortSignal,
  ): Promise<ListFilesResponseDto>;
  /** Lists files/folders under the organization's public root. */
  listPublicFiles(
    params: ListPublicFilesRequest,
  ): Promise<ListFilesResponseDto>;
  /** Lists files/folders shared with the current user. */
  listSharedFiles(
    params: ListSharedFilesRequest,
  ): Promise<ListFilesResponseDto>;
  /** Lists items the current user has shared with others, from their own bucket. */
  listSharedByMe(bucket: string): Promise<ListFilesResponseDto>;
  /** Fetches metadata for a single file or folder. */
  getFileMetadata(params: {
    bucket: string;
    path: string;
  }): Promise<FileMetadataResponseDto>;
  /**
   * Uploads a file, reporting progress via `options.onProgress` when supplied
   * and honoring cancellation via `options.signal` or a bare `AbortSignal`.
   */
  uploadFile(
    bucket: string,
    path: string,
    file: File,
    options?: AbortSignal | DialFilesApiUploadOptions,
  ): Promise<FileUploadResponseDto>;
  /** Uploads a ZIP archive and extracts its entries under `destinationPath`. */
  uploadArchive(
    file: File,
    bucket: string,
    destinationPath: string,
  ): Promise<UploadArchiveResponseDto>;
  /** Creates a new folder. */
  createFolder(params: CreateFolderDto): Promise<CreateFolderResponseDto>;
  /** Deletes one or more files/folders. */
  deleteFiles(items: DeleteItemDto[]): Promise<DeleteFilesResponseDto>;
  /** Renames one or more files/folders in place (same parent folder). */
  renameFiles(items: RenameItemDto[]): Promise<RenameFilesResponseDto>;
  /** Copies one or more files/folders to a destination path. */
  copyFiles(
    items: CopyItemDto[],
    signal?: AbortSignal,
  ): Promise<CopyFilesResponseDto>;
  /** Moves one or more files/folders to a destination path (different parent folder). */
  moveFiles(
    items: MoveItemDto[],
    signal?: AbortSignal,
  ): Promise<MoveFilesResponseDto>;
  /** Downloads a single file, returning the raw fetch `Response`. */
  downloadFile(
    bucket: string,
    path: string,
    signal?: AbortSignal,
  ): Promise<Response>;
  /** Downloads a ZIP archive of the given items, returning the raw fetch `Response`. */
  downloadArchive(items: ArchiveItemDto[]): Promise<Response>;
  /** Revokes access previously granted on the given owned items. */
  revokeAccess(items: RevokeAccessItemDto[]): Promise<RevokeAccessResponseDto>;
  /** Discards items shared with the current user. */
  discardShared(
    items: DiscardSharedItemDto[],
  ): Promise<DiscardSharedResponseDto>;
}

export interface FileUploadValidationResult {
  /** Whether the files passed validation. */
  valid: boolean;
  /** Human-readable validation error message when `valid` is false. */
  message?: string;
}

export enum FileManagerNotificationReason {
  /** A folder listing fetch (initial load, expand, invalidate-refetch, or popup preload) failed. */
  FolderLoadFailed = 'folderLoadFailed',
  /** A single-file/folder metadata fetch (`onGetInfo`) failed. */
  MetadataLoadFailed = 'metadataLoadFailed',
  /** `onCreateFolder`'s `createFolder` call failed. */
  FolderCreateFailed = 'folderCreateFailed',
  /** `onDownloadFiles` failed for a single file/folder selection. */
  DownloadFileFailed = 'downloadFileFailed',
  /** `onDownloadFiles` failed for a multi-item selection. */
  DownloadFilesFailed = 'downloadFilesFailed',
  /** `onDeleteFiles` deleted at least one item successfully; `count`/`name`/`folder` describe the result. */
  FilesDeleted = 'filesDeleted',
  /** `onDeleteFiles` completed with at least one failure alongside a success; `names`/`restCount` list the failures. */
  FilesDeletePartiallyFailed = 'filesDeletePartiallyFailed',
  /** `onDeleteFiles`'s `deleteFiles` request itself rejected. */
  DeleteFailed = 'deleteFailed',
  /** `onMoveToFiles`'s rename branch failed for every item in the batch. */
  RenameFailed = 'renameFailed',
  /** `onMoveToFiles`'s rename branch failed for some items; `count` is the failed count. */
  RenamePartiallyFailed = 'renamePartiallyFailed',
  /** `onMoveToFiles`'s move branch failed for every item in the batch. */
  MoveFailed = 'moveFailed',
  /** `onMoveToFiles`'s move branch failed for some items; `count` is the failed count. */
  MovePartiallyFailed = 'movePartiallyFailed',
  /** `onCopyFiles` failed for every item in the batch. */
  CopyFailed = 'copyFailed',
  /** `onCopyFiles` failed for some items; `count` is the failed count. */
  CopyPartiallyFailed = 'copyPartiallyFailed',
  /** `useDialFileSharing`'s `onUnshareFiles` request failed. */
  UnshareFailed = 'unshareFailed',
  /** `useDialFileSharing`'s `onRemoveFilesAccess` request failed. */
  RemoveAccessFailed = 'removeAccessFailed',
  /** `useDialFileUploadBatch`'s plain-file batch had zero successful uploads. */
  UploadFailed = 'uploadFailed',
  /** `useDialFileUploadBatch`'s plain-file batch completed (fully or partially successful). */
  UploadCompleted = 'uploadCompleted',
  /** `onUploadArchive` extracted zero entries successfully; `names`/`restCount` list the failures. */
  UploadArchiveFailed = 'uploadArchiveFailed',
  /** `onUploadArchive` extracted some entries successfully and some failed; `count`/`names`/`restCount` describe the failures. */
  UploadArchivePartiallyFailed = 'uploadArchivePartiallyFailed',
  /** `onUploadArchive`'s `uploadArchive` request itself rejected. */
  UploadArchiveRequestFailed = 'uploadArchiveRequestFailed',
}

export interface FileManagerNotification {
  variant: NotificationVariant;
  title?: string;
  message?: string;
  reason?: FileManagerNotificationReason;
  /** Number of items the notification covers (e.g. a partial-failure count). */
  count?: number;
  /** Name of the affected entity or first successfully affected item. */
  name?: string;
  /** Source or destination folder name the notification refers to. */
  folder?: string;
  /** Up to the first 5 names affected by a partial/full failure list (e.g. archive extraction, delete). */
  names?: string[];
  /** Count of additional affected items beyond `names`' limit. */
  restCount?: number;
}

export type FileNameValidationError =
  | { reason: FileNameValidationErrorReason.Empty }
  | {
      reason: FileNameValidationErrorReason.ForbiddenSymbols;
      symbols: string;
    }
  | { reason: FileNameValidationErrorReason.ReservedName }
  | { reason: FileNameValidationErrorReason.TooLong; maxLength: number }
  | {
      reason: FileNameValidationErrorReason.DuplicateName;
      existingName: string;
    }
  | { reason: FileNameValidationErrorReason.LeadingDot };

export interface FileOperationSuccessEvent {
  /** Which mutation just succeeded. */
  kind: FileOperationKind;
  /** Name of the affected entity or first successfully affected item, when applicable. */
  name?: string;
  /** Number of items the operation covered, when applicable. */
  count?: number;
  /** Destination folder name, for copy/move operations. */
  destinationFolderName?: string;
  /**
   * Whether the affected item is a folder rather than a file. Only set for
   * `fileRenamed`, since it is the only kind whose current wording depends
   * on the item's node type (a rename toast reads "Folder renamed" vs.
   * "File renamed").
   */
  isFolder?: boolean;
}

export interface UseDialFileManagerOptions {
  /** Injected operation port used for every file-manager network call. */
  filesApi: DialFilesApi;
  /** DIAL Core bucket to browse (used only for my_files tab). */
  bucket: string;
  /** Display name for the root folder node. Defaults to `'My files'`. */
  rootLabel?: string;
  /** Active tab — drives listing source and per-tab options. Defaults to MyFiles. */
  activeTab?: DialFileManagerTabs;
  /** Called when a file-manager action should surface a toast notification. */
  onNotification?: (notification: FileManagerNotification) => void;
  /** Called when a mutation succeeds, instead of invoking an application notification service directly. */
  onOperationSuccess?: (event: FileOperationSuccessEvent) => void;
  /** Regexp of characters forbidden in file/folder names (e.g. NOT_ALLOWED_SYMBOLS_REGEXP). */
  forbiddenSymbolsRegExp?: RegExp;
  /** Which host is driving this hook instance. Defaults to `Attach`. */
  variant?: DialFileManagerVariant;
  /** Gates which actions are exposed. Defaults to the value derived from `variant`. */
  actionProfile?: DialFileManagerActionProfile;
  /**
   * Host-supplied action label text, keyed by `DialFileManagerActions`. The
   * hook computes which actions are visible/enabled per tab/variant/
   * actionProfile and intersects that gating with this map — an action the
   * gating allows but this map omits is left out of `actionLabels`.
   */
  labels: Partial<Record<DialFileManagerActions, string>>;
  /** BCP-47 locale string for date formatting, replacing `i18n.language`. */
  locale: string;
  /** Translated tooltip shown on the disabled New/Upload button. */
  disabledNewButtonTooltip: string;
  /** Host-injected browser "Save As"/auto-download seam for `onDownloadFiles`. */
  downloadDestination: DownloadDestinationHandlers;
  /**
   * Builds a translated message from a structured validation-error reason,
   * for `onCreateFolderValidate`/`onRenameValidate`. `item` is passed for a
   * rename (so the host can distinguish file vs. folder wording) and
   * omitted for folder creation.
   */
  buildValidationErrorMessage: (
    error: FileNameValidationError,
    item?: DialFile,
  ) => string;
}

export interface UseDialFileManagerResult {
  /** Hierarchical items for DialFileManager's `items` prop. */
  items: DialFile[];
  /** True while the current folder is loading. */
  isLoading: boolean;
  /** Non-null when the last fetch failed. */
  error: string | null;
  /** Current path in DialFileManager format (e.g. `"/My files"`, `"/My files/reports/"`). */
  path: string;
  /** Pass directly to DialFileManager's `onPathChange`. */
  onPathChange: (nextPath?: string) => void;
  /** Re-runs the fetch for the current `folderPath`. */
  retry: () => void;

  /**
   * Search: called by DialFileManager when the user types in the search box.
   * `folder` is accepted for API parity with DialFileManager but is intentionally
   * unused — this hook always searches from the active-tab root stored in
   * `folderPath`, not from the passed-in `folder` (see design decision D3).
   */
  onSearchFiles: (folder: string, query: string) => void;
  /** Search: true while a search request is in flight. */
  isSearching: boolean;
  /** Search: flat list of matching files, or null when search is not active. */
  searchResults: DialFile[] | null;
  /** Search: clears results and exits search mode. */
  clearSearchResults: () => void;

  /** Tree: controlled set of expanded folder virtual paths. */
  expandedPaths: Set<string>;
  /** Tree: expanded or destination-popup virtual paths whose children are already cached. */
  loadedPaths: Set<string>;
  /** Tree: called by DialFileManager when a folder is expanded/collapsed. */
  onExpandedPathsChange: (paths: Set<string>) => void;
  /** Destination folder popup: preloads the browsed folder without changing the outer grid path. */
  onFolderPopupPathChange: (nextPath?: string) => void;
  /** Destination folder popup: normalized virtual paths currently being preloaded. */
  folderPopupLoadingPaths: Set<string>;

  /** Upload: start a new batch. */
  onUploadFiles: (
    files: DialUploadFileItem[],
    destinationFolder: string,
  ) => void;
  /** Upload: extracts and uploads a ZIP archive's entries to the destination folder. */
  onUploadArchive: (
    file: File,
    name: string,
    destinationFolder: string,
  ) => void;
  /** Upload: validate file names before upload (called by DialFileManager). */
  onValidateUpload: (
    files: DialUploadFileItem[],
    existingFiles: DialFile[],
    destinationFolder: string,
  ) => Promise<FileUploadValidationResult>;
  /** Upload: current batch state (null when idle). */
  uploadBatchState: FileUploadBatchState | null;
  /** Upload: abort all in-flight and queued uploads. */
  cancelUpload: () => void;
  /** Upload: dismiss the progress modal after the batch has settled. */
  clearUploadBatch: () => void;

  /** Folder creation: called when user confirms a new folder name. */
  onCreateFolder: (
    file: DialUploadFileItem,
    folderPath: string,
    fileId: string,
  ) => Promise<void>;
  /** Folder creation: inline synchronous validation (returns error message or null). */
  onCreateFolderValidate: (
    name: string,
    parentFolder: DialFile,
  ) => string | null;
  /** True while a folder creation request is in flight. */
  isCreatingFolder: boolean;

  /** Download: called when user triggers download on one or more items. */
  onDownloadFiles: (dialFiles: DialFile[]) => void;
  /** True while a download is in progress. */
  isDownloading: boolean;

  /** Delete: called when user confirms deletion of one or more items. */
  onDeleteFiles: (items: DialDeletedItem[], sourceFolder: string) => void;
  /** True while a delete request is in flight. */
  isDeleting: boolean;

  /** Rename: inline validation — returns error string or null. */
  onRenameValidate: (value: string, item: DialFile) => string | null;
  /** Rename: called when user confirms an inline rename. Also dispatches cross-folder move (see D3). */
  onMoveToFiles: (
    items: DialCopiedItem[],
    sourceFolder: string,
    destinationFolder: string,
  ) => void;
  /** True while a rename request is in flight. */
  isRenaming: boolean;

  /** Copy: called when user confirms a copy-paste. */
  onCopyFiles: (items: DialCopiedItem[], destinationFolder: string) => void;
  /** True while a copy request is in flight. */
  isCopying: boolean;
  /** True while the cross-folder-move branch of onMoveToFiles is in flight. */
  isMoving: boolean;
  /** Aborts whichever of copy/move is currently in flight. */
  cancelCopyMove: () => void;

  /** True when the current folder grants WRITE (upload + new folder). */
  uploadEnabled: boolean;
  /** True when Upload/New must be disabled. */
  isNewButtonDisabled: boolean;
  /** Tooltip for disabled New/Upload when `isNewButtonDisabled` is true. */
  disabledNewButtonTooltip: string;

  /** Columns to show in the grid — tab-dependent. */
  visibleColumns: FileManagerColumnKey[];
  /** BCP-47 locale string for date formatting, sourced from i18n.language. */
  dateLocale: string;
  /** Fixed date format options for the UpdatedAt column. */
  dateOptions: Intl.DateTimeFormatOptions;
  /** Action labels for grid/tree/bulk — Delete present only on my_files tab. */
  actionLabels: Partial<Record<DialFileManagerActions, string>>;
  /** Root-level shared item paths, populated only on the Shared tab. */
  sharedWithMeIds: string[] | undefined;

  /** Share: paths the user has shared with others, populated only on my_files tab. */
  sharedByMePaths: Set<string>;

  /** Unshare: called when user removes a shared-with-me item (Shared tab only). */
  onUnshareFiles: (files: DialFile[]) => void;
  /** True while an unshare request is in flight. */
  isUnsharing: boolean;
  /** Remove access: called when user revokes access to an owned shared item (my_files tab only). */
  onRemoveFilesAccess: (files: DialFile[]) => void;
  /** True while a remove-access request is in flight. */
  isRemovingAccess: boolean;

  /** Metadata: populated once onGetInfo resolves; passed to fileMetadataPopupOptions.fileMetadata. */
  fileMetadata: DialFile | undefined;
  /** True while a metadata request is in flight. */
  isFileMetadataLoading: boolean;
  /** Metadata: called by DialFileManager.onGetInfo to fetch and display a file's details. */
  onGetInfo: (file: DialFile) => void;
  /** Metadata: resets fileMetadata/isFileMetadataLoading; passed to fileMetadataPopupOptions.clearMetadata. */
  clearMetadata: () => void;

  /**
   * True while any mutating file-manager operation is in flight: the OR of
   * `isCreatingFolder`, `isDownloading`, `isDeleting`, `isRenaming`, `isCopying`,
   * `isMoving`, `isUnsharing`, `isRemovingAccess`, and `uploadBatchState != null`.
   *
   * Deliberately excludes three flags, each already fully contained by its own
   * scoped loading UI:
   * - `isLoading` — a read (listing fetch), not a mutation.
   * - `isSearching` — scoped to ui-kit's own search-progress UI.
   * - `isFileMetadataLoading` — has its own `loading` state in `fileMetadataPopupOptions`.
   */
  isAnyOperationInProgress: boolean;
}

CORE_PERMISSION_MAP: Record<string, DialFilePermission> = {
  READ: DialFilePermission.READ,
  WRITE: DialFilePermission.WRITE,
  SHARE: DialFilePermission.SHARE,
}

export interface SharedRootMeta {
  bucket: string;
  /** DIAL Core URL of the shared root item, e.g. "files/owner-bucket/some-folder/" */
  dialCorePath: string;
}

export interface PreparedCopyMoveItem<TDto> {
  dto: TDto;
  destinationName: string;
}

export interface CopyMoveResult {
  success?: boolean;
  sourcePath?: string;
  destinationPath?: string;
}

prepareCopyItems = (
  copiedItems: DialCopiedItem[],
  bucket: string,
  rootLabel: string,
): PreparedCopyMoveItem<CopyItemDto>[] =>
  copiedItems.map((item) => {
    const isFolder = item.nodeType === DialFileNodeType.FOLDER;
    const sourcePath = virtualPathToApiPath(item.sourceUrl, rootLabel);
    const destinationPath = virtualPathToApiPath(
      item.destinationUrl,
      rootLabel,
    );
    const name = getVirtualPathName(item.sourceUrl, sourcePath);
    const destinationName = getVirtualPathName(
      item.destinationUrl,
      destinationPath,
    );
    return {
      destinationName,
      dto: {
        bucket,
        sourcePath: isFolder
          ? sourcePath.endsWith('/')
            ? sourcePath
            : `${sourcePath}/`
          : sourcePath.replace(/\/$/, ''),
        destinationPath: isFolder
          ? destinationPath.endsWith('/')
            ? destinationPath
            : `${destinationPath}/`
          : destinationPath.replace(/\/$/, ''),
        overwrite: item.overwrite === true,
        nodeType: isFolder
          ? CopyItemDtoNodeTypeEnum.Folder
          : CopyItemDtoNodeTypeEnum.Item,
        name,
      },
    };
  })

prepareMoveRenameItems = (
  copiedItems: DialCopiedItem[],
  bucket: string,
  rootLabel: string,
): {
  renameDtos: RenameItemDto[];
  preparedMoveItems: PreparedCopyMoveItem<MoveItemDto>[];
} => {
  const built: BuiltMoveRenameEntry[] = copiedItems.map((item) => {
    const isFolder = item.nodeType === DialFileNodeType.FOLDER;
    const sourcePath = virtualPathToApiPath(item.sourceUrl, rootLabel);
    const destinationPath = virtualPathToApiPath(
      item.destinationUrl,
      rootLabel,
    );
    const name = getVirtualPathName(item.sourceUrl, sourcePath);
    const destinationName = getVirtualPathName(
      item.destinationUrl,
      destinationPath,
    );
    const normalizedSourcePath = isFolder
      ? sourcePath.endsWith('/')
        ? sourcePath
        : `${sourcePath}/`
      : sourcePath.replace(/\/$/, '');
    const normalizedDestinationPath = isFolder
      ? destinationPath.endsWith('/')
        ? destinationPath
        : `${destinationPath}/`
      : destinationPath.replace(/\/$/, '');
    return {
      isFolder,
      name,
      destinationName,
      overwrite: item.overwrite === true,
      sourcePath: normalizedSourcePath,
      destinationPath: normalizedDestinationPath,
      sourceParent: getParentFolderPath(normalizedSourcePath),
      destinationParent: getParentFolderPath(normalizedDestinationPath),
    };
  });

  const renameDtos: RenameItemDto[] = built
    .filter((b) => b.sourceParent === b.destinationParent)
    .map((b) => ({
      bucket,
      sourcePath: b.sourcePath,
      destinationPath: b.destinationPath,
      nodeType: b.isFolder
        ? RenameItemDtoNodeTypeEnum.Folder
        : RenameItemDtoNodeTypeEnum.Item,
      name: b.name,
    }));

  const preparedMoveItems: PreparedCopyMoveItem<MoveItemDto>[] = built
    .filter((b) => b.sourceParent !== b.destinationParent)
    .map((b) => ({
      destinationName: b.destinationName,
      dto: {
        bucket,
        sourcePath: b.sourcePath,
        destinationPath: b.destinationPath,
        overwrite: b.overwrite,
        nodeType: b.isFolder
          ? MoveItemDtoNodeTypeEnum.Folder
          : MoveItemDtoNodeTypeEnum.Item,
        name: b.name,
      },
    }));

  return { renameDtos, preparedMoveItems };
}

mapCorePermissions = (
  permissions?: string[],
): DialFile['permissions'] | undefined => {
  if (!permissions?.length) return undefined;
  const mapped = permissions
    .map((permission) => CORE_PERMISSION_MAP[permission.toUpperCase()])
    .filter(
      (permission): permission is (typeof CORE_PERMISSION_MAP)[string] =>
        permission != null,
    );
  return mapped.length > 0 ? mapped : undefined;
}

findFirstSuccessfulCopyMoveItem = <
  TDto extends {
    success?: boolean;
    sourcePath?: string;
    destinationPath?: string;
  },
>(
  items: PreparedCopyMoveItem<TDto>[],
  results: {
    success?: boolean;
    sourcePath?: string;
    destinationPath?: string;
  }[],
): PreparedCopyMoveItem<TDto> | undefined => {
  const firstSuccessfulResult = results.find((result) => result.success);
  if (firstSuccessfulResult == null) return undefined;

  return (
    items.find(
      ({ dto }) =>
        dto.sourcePath === firstSuccessfulResult.sourcePath &&
        dto.destinationPath === firstSuccessfulResult.destinationPath,
    ) ??
    items.find(
      ({ dto }) =>
        dto.destinationPath === firstSuccessfulResult.destinationPath,
    ) ??
    items[0]
  );
}

buildFromCache = (
  cache: Map<string, ListFilesItemDto[]>,
  listingPermissionsCache: Map<string, string[] | undefined>,
  apiPath: string,
  virtualBasePath: string,
  folderId: string,
): DialFile[] => {
  const flat = cache.get(apiPath);
  if (flat == null) return [];

  const parentPathBase = virtualBasePath.replace(/\/$/, '');

  return flat.map((item): DialFile => {
    const isFolder = item.nodeType === ListFilesItemDtoNodeTypeEnum.Folder;
    /*
     * DIAL Core returns `name` already decoded (only `url` is percent-encoded).
     * Decoding it again corrupts names that legitimately contain percent
     * escapes — `a%2Fb.txt` would split into a phantom folder and the row would
     * vanish, `a%20b.pdf` would resolve to a path DIAL Core does not have.
     */
    const name = item.name;
    const virtualPath = isFolder
      ? `${parentPathBase}/${name}/`
      : `${parentPathBase}/${name}`;

    const base: DialFile = {
      id: item.path,
      name,
      path: virtualPath,
      url: item.url,
      parentPath: virtualBasePath,
      nodeType: isFolder ? DialFileNodeType.FOLDER : DialFileNodeType.ITEM,
      folderId,
      bucket: item.bucket,
      author: item.author,
      resourceType: item.resourceType as DialFile['resourceType'],
      contentLength: item.contentLength,
      contentType: item.contentType,
      updatedAt: item.updatedAt
        ? new Date(item.updatedAt).toISOString()
        : undefined,
    };

    if (isFolder) {
      const folderApiPath = `${apiPath}${name}/`;
      base.permissions =
        mapCorePermissions(item.permissions) ??
        mapCorePermissions(listingPermissionsCache.get(folderApiPath));
      base.items = buildFromCache(
        cache,
        listingPermissionsCache,
        folderApiPath,
        virtualPath,
        item.path,
      );
    }

    return base;
  });
}

mergeCreatedFolderIntoCache = (
  cache: Map<string, ListFilesItemDto[]>,
  parentApiPath: string,
  created: CreateFolderResponseDto,
  inheritedPermissions?: string[],
): Map<string, ListFilesItemDto[]> => {
  const next = new Map(cache);
  const parentItems = [...(next.get(parentApiPath) ?? [])];
  const folderItem: ListFilesItemDto = {
    name: created.name,
    path: created.path,
    folderId: created.folderId,
    nodeType: ListFilesItemDtoNodeTypeEnum.Folder,
    bucket: created.bucket,
    parentPath: created.parentPath || undefined,
    url: created.path,
    permissions: inheritedPermissions,
  };

  if (
    !parentItems.some(
      (item) => item.name.toLowerCase() === created.name.toLowerCase(),
    )
  ) {
    parentItems.push(folderItem);
  }

  next.set(parentApiPath, parentItems);
  return next;
}

updateEntry = (
  prev: FileUploadBatchState | null,
  index: number,
  patch:
    FileUploadStatus | Partial<Pick<FileUploadEntry, 'status' | 'percent'>>,
): FileUploadBatchState | null => {
  if (!prev) return prev;
  const changes = typeof patch === 'string' ? { status: patch } : patch;
  const files = prev.files.map((f, i) =>
    i === index ? { ...f, ...changes } : f,
  );
  return { ...prev, files };
}

fetchByTab = (
  filesApi: DialFilesApi,
  tab: DialFileManagerTabs,
  bucket: string,
  folderPath: string,
  sharedRootMeta: Map<string, SharedRootMeta>,
): Promise<{ items: ListFilesItemDto[]; permissions?: string[] }> => {
  if (tab === DialFileManagerTabs.Shared) {
    if (folderPath === '') {
      return filesApi
        .listSharedFiles({ path: undefined })
        .then((res) => ({ items: res.items }));
    }
    /*
     * Navigating inside a shared folder — find the owner bucket from the root meta
     * and call listFiles against their bucket with the correct relative path.
     */
    const firstSlash = folderPath.indexOf('/');
    const sharedRootName =
      firstSlash === -1 ? folderPath : folderPath.slice(0, firstSlash);
    const meta = sharedRootMeta.get(sharedRootName);
    if (meta) {
      const rootPathInBucket = dialCorePathToRelative(
        meta.dialCorePath,
        meta.bucket,
      );
      const subPath = firstSlash === -1 ? '' : folderPath.slice(firstSlash + 1);
      const actualPath = rootPathInBucket + subPath;
      return filesApi
        .listFiles({
          bucket: meta.bucket,
          path: actualPath,
          permissions: true,
        })
        .then((res) => ({ items: res.items, permissions: res.permissions }));
    }
    return Promise.resolve({ items: [] });
  }
  if (tab === DialFileManagerTabs.Organization) {
    return filesApi
      .listPublicFiles({ path: folderPath || undefined })
      .then((res) => ({ items: res.items }));
  }
  return filesApi
    .listFiles({
      bucket,
      path: folderPath,
      permissions: true,
    })
    .then((res) => ({ items: res.items, permissions: res.permissions }));
}

fetchForSearch = async (
  filesApi: DialFilesApi,
  tab: DialFileManagerTabs,
  bucket: string,
  folderPath: string,
  sharedRootMeta: Map<string, SharedRootMeta>,
): Promise<{ items: ListFilesItemDto[] }> => {
  if (tab === DialFileManagerTabs.Shared) {
    /*
     * Shared root is handled via client-side cache filter in onSearchFiles.
     * This branch only runs for nested shared folders.
     */
    const firstSlash = folderPath.indexOf('/');
    const sharedRootName =
      firstSlash === -1 ? folderPath : folderPath.slice(0, firstSlash);
    const meta = sharedRootMeta.get(sharedRootName);
    if (!meta) return { items: [] };
    const rootPathInBucket = dialCorePathToRelative(
      meta.dialCorePath,
      meta.bucket,
    );
    const subPath = firstSlash === -1 ? '' : folderPath.slice(firstSlash + 1);
    const actualPath = rootPathInBucket + subPath;
    const { items } = await filesApi.listFiles({
      bucket: meta.bucket,
      path: actualPath,
      permissions: true,
      recursive: true,
    });
    return { items };
  }
  if (tab === DialFileManagerTabs.Organization) {
    const { items } = await filesApi.listPublicFiles({
      path: folderPath || undefined,
      recursive: true,
    });
    return { items };
  }
  const { items } = await filesApi.listFiles({
    bucket,
    path: folderPath,
    permissions: true,
    recursive: true,
  });
  return { items };
}

mapSearchItem = (
  item: ListFilesItemDto,
  fallbackBucket: string,
  rootLabel: string,
): DialFile => {
  const isFolder = item.nodeType === ListFilesItemDtoNodeTypeEnum.Folder;
  // `name` arrives decoded from DIAL Core — see the note in `buildFromCache`.
  const name = item.name;
  const itemBucket = item.bucket ?? fallbackBucket;
  const dialCorePath = item.url ?? item.path ?? '';
  const relativePath = dialCorePathToRelative(dialCorePath, itemBucket);
  const relativeStripped = relativePath.replace(/\/$/, '');
  const lastSlash = relativeStripped.lastIndexOf('/');
  const parentRelative =
    lastSlash > 0 ? relativeStripped.slice(0, lastSlash) : '';
  /*
   * The parent path is derived from the percent-encoded DIAL Core url, so its
   * segments have to be decoded to land in the same virtual-path space as the
   * rows `buildFromCache` produces.
   */
  const virtualParentPath = buildSharedItemVirtualPath(
    parentRelative,
    rootLabel,
    false,
  );
  const virtualPath = isFolder
    ? `${virtualParentPath}/${name}/`
    : `${virtualParentPath}/${name}`;

  return {
    id: item.path,
    name,
    path: virtualPath,
    url: item.url,
    parentPath: virtualParentPath,
    nodeType: isFolder ? DialFileNodeType.FOLDER : DialFileNodeType.ITEM,
    folderId: item.folderId,
    bucket: itemBucket,
    author: item.author,
    contentLength: item.contentLength,
    contentType: item.contentType,
    updatedAt: item.updatedAt
      ? new Date(item.updatedAt).toISOString()
      : undefined,
  };
}

hasForbiddenNameSymbols = (
  name: string,
  forbiddenSymbolsRegExp?: RegExp,
): boolean => {
  if (PATH_SEPARATOR_REGEXP.test(name)) return true;
  if (forbiddenSymbolsRegExp == null) return false;

  forbiddenSymbolsRegExp.lastIndex = 0;
  const hasMatch = forbiddenSymbolsRegExp.test(name);
  forbiddenSymbolsRegExp.lastIndex = 0;
  return hasMatch;
}

normalizeVirtualPath = (value: string): string => {
  return stripTrailingSlashes(value) || '/';
}

getVirtualPathName = (
  virtualPath: string,
  fallback: string,
): string => {
  const segments = virtualPath.split('/').filter(Boolean);
  return segments[segments.length - 1] ?? fallback;
}

findFolderByVirtualPath = (
  nodes: DialFile[],
  virtualPath: string,
): DialFile | undefined => {
  const target = normalizeVirtualPath(virtualPath);
  for (const node of nodes) {
    if (node.nodeType !== DialFileNodeType.FOLDER) continue;
    if (normalizeVirtualPath(node.path) === target) return node;
    const nested = findFolderByVirtualPath(node.items ?? [], virtualPath);
    if (nested) return nested;
  }
  return undefined;
}

findDialFileByPath = (
  nodes: DialFile[],
  targetPath: string,
): DialFile | undefined => {
  for (const node of nodes) {
    if (node.path === targetPath || node.id === targetPath) return node;
    const nested = findDialFileByPath(node.items ?? [], targetPath);
    if (nested) return nested;
  }
  return undefined;
}

isCopyMoveDuplicateAllowed = (
  actionProfile: DialFileManagerActionProfile,
): boolean => {
  switch (actionProfile) {
    case DialFileManagerActionProfile.Attach:
      return false;
    case DialFileManagerActionProfile.Browse:
    case DialFileManagerActionProfile.Full:
      return true;
    default: {
      const exhaustiveCheck: never = actionProfile;
      throw new Error(`Unhandled actionProfile: ${String(exhaustiveCheck)}`);
    }
  }
}

isShareActionsAllowed = (
  actionProfile: DialFileManagerActionProfile,
): boolean => actionProfile === DialFileManagerActionProfile.Full

parseNewFolderVirtualPath = (
  newFolderVirtualPath: string,
  rootLabel: string,
): { parentVirtualPath: string; name: string } => {
  const trimmed = newFolderVirtualPath.replace(/\/$/, '');
  const slashIndex = trimmed.lastIndexOf('/');

  if (slashIndex <= 0) {
    const name = slashIndex === 0 ? trimmed.slice(1) : trimmed;
    return { parentVirtualPath: `/${rootLabel}`, name };
  }

  return {
    parentVirtualPath: trimmed.slice(0, slashIndex),
    name: trimmed.slice(slashIndex + 1),
  };
}

dialCorePathToRelative = (
  dialCorePath: string,
  bucket: string,
): string => {
  const prefix = `files/${bucket}/`;
  return dialCorePath.startsWith(prefix)
    ? dialCorePath.slice(prefix.length)
    : dialCorePath;
}

buildSharedItemVirtualPath = (
  relativePath: string,
  rootLabel: string,
  isFolder: boolean,
): string => {
  /* `filter(Boolean)` already drops the empty segments any leading, trailing, or repeated slash produces. */
  const joined = relativePath
    .split('/')
    .filter(Boolean)
    .map(safeDecodeURI)
    .join('/');
  const base = joined ? `/${rootLabel}/${joined}` : `/${rootLabel}`;
  return isFolder ? `${base}/` : base;
}

resolveOwnerCoords = (
  apiPath: string,
  sharedRootMeta: Map<string, SharedRootMeta>,
  fallbackBucket: string,
): { bucket: string; path: string } => {
  if (!apiPath) return { bucket: fallbackBucket, path: apiPath };
  const firstSlash = apiPath.indexOf('/');
  const sharedRootName =
    firstSlash === -1 ? apiPath : apiPath.slice(0, firstSlash);
  const meta = sharedRootMeta.get(sharedRootName);
  if (!meta) return { bucket: fallbackBucket, path: apiPath };
  const rootPathInBucket = dialCorePathToRelative(
    meta.dialCorePath,
    meta.bucket,
  );
  const subPath = firstSlash === -1 ? '' : apiPath.slice(firstSlash + 1);
  return { bucket: meta.bucket, path: rootPathInBucket + subPath };
}

isDialFileAcceptType = (
  type: string,
): type is DialFileAcceptType => type.startsWith('.') || type.includes('/')

mimeTypesToDialFileAcceptTypes = (
  types?: string[],
): DialFileAcceptType[] | undefined => {
  if (types == null) {
    return undefined;
  }

  return types
    .map((type) => (type === '*' ? ALL_FILES_ACCEPT_TYPE : type))
    .filter(isDialFileAcceptType);
}

mimeTypesToFileAccept = (types?: string[]): string | undefined => {
  const dialFileAcceptTypes = mimeTypesToDialFileAcceptTypes(types);
  if (dialFileAcceptTypes == null || dialFileAcceptTypes.length === 0) {
    return undefined;
  }
  if (dialFileAcceptTypes.some((type) => type === ALL_FILES_ACCEPT_TYPE)) {
    return undefined;
  }
  return dialFileAcceptTypes.join(',');
}

mimeTypesToAttachmentExtensionLabels = (types: string[]): string =>
  types
    .map((type) => {
      if (type.endsWith('/*')) {
        return type;
      }

      const extension = getMimeExtension(type);

      if (extension !== false) {
        return `.${extension}`;
      }

      const subtype = type.split('/')[1];
      return subtype != null ? `.${subtype.toLowerCase()}` : type;
    })
    .join(', ')

export interface UploadFileWithProgressOptions {
  /** Aborts the upload in flight. */
  signal?: AbortSignal;
  /** Called with the upload's progress percentage (0–100). */
  onProgress?: (percent: number) => void;
  /** Defaults to the generated client's own default when omitted. */
  uploadMode?: UploadMode;
}

export type UploadFileWithProgressFn = (
  bucket: string,
  path: string,
  file: File,
  options?: UploadFileWithProgressOptions,
) => Promise<FileUploadResponseDto>;

export interface FilesApiClient {
  listPublicFiles: (
    params: ListPublicFilesRequest,
  ) => Promise<ListFilesResponseDto>;
  listSharedFiles: (
    params: ListSharedFilesRequest,
  ) => Promise<ListFilesResponseDto>;
  listFiles: (
    params: {
      bucket: string;
      path?: string;
      token?: string;
      limit?: number;
      recursive?: boolean;
      permissions?: boolean;
    },
    signal?: AbortSignal,
  ) => Promise<ListFilesResponseDto>;
  uploadFile: (
    bucket: string,
    path: string,
    file: File,
    options?: AbortSignal | UploadFileOptions,
  ) => Promise<FileUploadResponseDto>;
  uploadArchive: (
    file: File,
    bucket: string,
    destinationPath: string,
  ) => Promise<UploadArchiveResponseDto>;
  getFileMetadata: (params: {
    bucket: string;
    path: string;
  }) => Promise<FileMetadataResponseDto>;
  downloadFile: (
    bucket: string,
    path: string,
    signal?: AbortSignal,
  ) => Promise<Response>;
  createFolder: (params: CreateFolderDto) => Promise<CreateFolderResponseDto>;
  deleteFiles: (items: DeleteItemDto[]) => Promise<DeleteFilesResponseDto>;
  renameFiles: (items: RenameItemDto[]) => Promise<RenameFilesResponseDto>;
  copyFiles: (
    items: CopyItemDto[],
    signal?: AbortSignal,
  ) => Promise<CopyFilesResponseDto>;
  moveFiles: (
    items: MoveItemDto[],
    signal?: AbortSignal,
  ) => Promise<MoveFilesResponseDto>;
  downloadArchive: (items: ArchiveItemDto[]) => Promise<Response>;
  revokeAccess: (
    items: RevokeAccessItemDto[],
  ) => Promise<RevokeAccessResponseDto>;
  discardShared: (
    items: DiscardSharedItemDto[],
  ) => Promise<DiscardSharedResponseDto>;
  listSharedByMe: (bucket: string) => Promise<ListFilesResponseDto>;
}

createFilesApiClient = (
  filesApi: FilesApi,
  uploadFileWithProgress: UploadFileWithProgressFn,
): FilesApiClient => ({
  listPublicFiles: (params) => filesApi.listPublicFiles(params),

  listSharedFiles: (params) => filesApi.listSharedFiles(params),

  listFiles: (params, signal) =>
    filesApi.listFiles(params, signal ? { signal } : undefined),

  uploadFile: (bucket, path, file, options) => {
    const { signal, onProgress, uploadMode } = resolveUploadOptions(options);

    if (onProgress != null) {
      return uploadFileWithProgress(bucket, path, file, {
        signal,
        onProgress,
        uploadMode,
      });
    }

    return filesApi.uploadFile(
      { bucket, path, file, uploadMode },
      signal ? { signal } : undefined,
    );
  },

  uploadArchive: (file, bucket, destinationPath) =>
    filesApi.uploadArchive({ file, bucket, destinationPath }),

  getFileMetadata: (params) => filesApi.getFileMetadata(params),

  /*
   * downloadFileRaw() is used instead of downloadFile() because the generator
   * emits `Blob | void` for application/octet-stream responses, which loses stream
   * semantics. The raw method returns the native fetch Response whose `.body` is a
   * ReadableStream and whose `.blob()` buffers the full content when needed.
   */
  downloadFile: async (bucket, path, signal) => {
    const raw = await filesApi.downloadFileRaw(
      { bucket, path },
      ...(signal ? [{ signal }] : []),
    );
    return raw.raw;
  },

  createFolder: (params) => filesApi.createFolder({ createFolderDto: params }),

  deleteFiles: (items) => filesApi.deleteFiles({ deleteFilesDto: { items } }),

  renameFiles: (items) => filesApi.renameFiles({ renameFilesDto: { items } }),

  copyFiles: (items, signal) =>
    filesApi.copyFiles(
      { copyFilesDto: { items } },
      signal ? { signal } : undefined,
    ),

  moveFiles: (items, signal) =>
    filesApi.moveFiles(
      { moveFilesDto: { items } },
      signal ? { signal } : undefined,
    ),

  /*
   * downloadArchiveRaw() is used instead of downloadArchive() for the same reason
   * as downloadFileRaw() above — binary response semantics require the raw fetch Response.
   */
  downloadArchive: async (items) => {
    const raw = await filesApi.downloadArchiveRaw({
      downloadArchiveDto: { items },
    });
    return raw.raw;
  },

  revokeAccess: (items) =>
    filesApi.revokeAccess({ revokeAccessDto: { items } }),

  discardShared: (items) =>
    filesApi.discardShared({ discardSharedDto: { items } }),

  listSharedByMe: (bucket) => filesApi.listSharedByMe({ bucket }),
})

export interface CreateUploadFileWithProgressDeps {
  /** Returns the currently held CSRF token, or `null` when none is set. */
  getCsrfToken: () => string | null;
  /** Stores a CSRF token captured from the upload response header. */
  setCsrfToken: (token: string | null) => void;
  /** Notifies the host that the upload request was unauthorized. */
  notifyUnauthorized: (url: string) => void;
  /** Constructs the error thrown to signal an unauthorized upload. */
  createUnauthorizedError: (url: string) => Error;
  /** The upload endpoint's URL. */
  uploadUrl: string;
  /** Builds the `XMLHttpRequest` instance to upload through. Defaults to `() => new XMLHttpRequest()`. */
  xhrFactory?: () => XMLHttpRequest;
}

createUploadFileWithProgress = (
  deps: CreateUploadFileWithProgressDeps,
): UploadFileWithProgressFn => {
  const { uploadUrl, xhrFactory = () => new XMLHttpRequest() } = deps;

  return (
    bucket: string,
    path: string,
    file: File,
    { signal, onProgress, uploadMode }: UploadFileWithProgressOptions = {},
  ): Promise<FileUploadResponseDto> =>
    new Promise((resolve, reject) => {
      const xhr = xhrFactory();
      xhr.open('POST', uploadUrl);
      xhr.withCredentials = true;

      const csrfToken = deps.getCsrfToken();
      if (csrfToken != null) {
        xhr.setRequestHeader('X-CSRF-Token', csrfToken);
      }

      const formData = new FormData();
      formData.append('file', file);
      formData.append('bucket', bucket);
      formData.append('path', path);
      if (uploadMode != null) {
        formData.append('uploadMode', uploadMode);
      }

      xhr.upload.addEventListener('progress', (event) => {
        if (!onProgress || !event.lengthComputable || event.total <= 0) {
          return;
        }
        onProgress(
          Math.min(100, Math.round((event.loaded / event.total) * 100)),
        );
      });

      xhr.addEventListener('load', () => {
        const rotated = xhr.getResponseHeader('x-csrf-token');
        if (rotated) {
          deps.setCsrfToken(rotated);
        }

        if (xhr.status >= 200 && xhr.status < 300) {
          try {
            resolve(JSON.parse(xhr.responseText) as FileUploadResponseDto);
          } catch {
            reject(new Error('Upload response was not valid JSON'));
          }
          return;
        }

        if (xhr.status === 401) {
          deps.notifyUnauthorized(uploadUrl);
          reject(deps.createUnauthorizedError(uploadUrl));
          return;
        }

        reject(new Error(`Upload failed with status ${xhr.status}`));
      });

      xhr.addEventListener('error', () => {
        reject(new Error('Upload failed'));
      });

      xhr.addEventListener('abort', () => {
        reject(new DOMException('Upload aborted', 'AbortError'));
      });

      if (signal != null) {
        if (signal.aborted) {
          xhr.abort();
          return;
        }
        signal.addEventListener('abort', () => xhr.abort(), { once: true });
      }

      xhr.send(formData);
    });
}

openAnnotationAttachment = (
  attachment: AttachmentResource,
  resolveDownloadUrl: ResolveDownloadUrl,
): void => {
  const { url } = attachment;
  if (url == null) return;

  const fileId = url.split('#')[0];
  if (isDialFileId(fileId)) {
    const downloadUrl = resolveDownloadUrl(fileId);
    if (downloadUrl == null) return;
    triggerAnchorDownload(
      downloadUrl,
      attachment.title ?? fileId.split('/').pop() ?? '',
    );
  } else {
    window.open(url, '_blank', 'noopener,noreferrer');
  }
}

export interface AttachmentCanvasUrlResolvers {
  /** Resolves a DIAL Core file id to a downloadable URL. */
  resolveDialFileDownloadUrl: (fileId: string) => string | undefined;
  /** Resolves the best downloadable DIAL-file URL from an attachment's `url` or `referenceUrl`. */
  resolveDialUrl: (attachment: DisplayAttachment) => string | undefined;
  /** Resolves a DIAL Core file id to a fetchable metadata URL (used for cache-freshness validation). */
  resolveDialFileMetadataUrl: (fileId: string) => string | undefined;
}

clearAttachmentCache = (): void => {
  blobCache.clear();
  textCache.clear();
}

resolveImageCanvasContent = (
  attachment: DisplayAttachment,
  resolvers: AttachmentCanvasUrlResolvers,
): ImageCanvasContent | null => {
  const file =
    'file' in attachment ? (attachment as Attachment).file : undefined;
  const isFileEmpty = file != null && file.size === 0;
  const dialUrl =
    file != null && !isFileEmpty
      ? undefined
      : resolvers.resolveDialUrl(attachment);
  if (file != null && dialUrl == null) {
    return {
      type: AttachmentContentType.Image,
      url: URL.createObjectURL(file),
    };
  }
  if (dialUrl != null) {
    return { type: AttachmentContentType.Image, url: dialUrl };
  }
  if (attachment.previewUrl != null) {
    return { type: AttachmentContentType.Image, url: attachment.previewUrl };
  }
  if (attachment.data != null) {
    return {
      type: AttachmentContentType.Image,
      url: base64ToBlobUrl(attachment.data, attachment.contentType),
    };
  }
  return null;
}

resolveTextCanvasContent = async (
  attachment: DisplayAttachment,
  resolvers: AttachmentCanvasUrlResolvers,
): Promise<PlainTextCanvasContent | ErrorCanvasContent | null> => {
  const result = await resolveAttachmentText(attachment, resolvers);
  if (result == null) return null;
  if (typeof result !== 'string') return result;
  return { type: AttachmentContentType.PlainText, text: result };
}

resolveMarkdownCanvasContent = async (
  attachment: DisplayAttachment,
  resolvers: AttachmentCanvasUrlResolvers,
): Promise<MarkdownCanvasContent | ErrorCanvasContent | null> => {
  const result = await resolveAttachmentText(attachment, resolvers);
  if (result == null) return null;
  if (typeof result !== 'string') return result;
  return { type: AttachmentContentType.Markdown, text: result };
}

resolveCodeCanvasContent = async (
  attachment: DisplayAttachment,
  resolvers: AttachmentCanvasUrlResolvers,
  language?: string,
): Promise<CodeCanvasContent | ErrorCanvasContent | null> => {
  const result = await resolveAttachmentText(attachment, resolvers);
  if (result == null) return null;
  if (typeof result !== 'string') return result;
  return { type: AttachmentContentType.Code, text: result, language };
}

resolveHtmlCanvasContent = async (
  attachment: DisplayAttachment,
  resolvers: AttachmentCanvasUrlResolvers,
): Promise<HtmlCanvasContent | ErrorCanvasContent | null> => {
  const result = await resolveAttachmentText(attachment, resolvers);
  if (result == null) return null;
  if (typeof result !== 'string') return result;
  if (result.length > HTML_SRCDOC_SIZE_LIMIT) return null;
  const url = resolvers.resolveDialUrl(attachment) ?? undefined;
  return { type: AttachmentContentType.Html, srcdoc: result, url };
}

annotationToPdfCanvasContent = (
  annotation: Annotation,
  groups: AnnotationGroup[],
  resolvers: AttachmentCanvasUrlResolvers,
): PdfCanvasContent | null => {
  const source = annotation.body?.source?.attachment;
  if (source?.type !== MIMEType.PDF) return null;

  const url = isDialFileId(source.url)
    ? resolvers.resolveDialFileDownloadUrl(source.url)
    : source.url;
  if (url == null) return null;

  const group = groups.find((g) => g.annotations.includes(annotation));
  const allAnnotations = (group?.annotations ?? [annotation]).filter(
    (entry) => entry.body?.source?.attachment?.url === source.url,
  );
  const selectedIndex = allAnnotations.indexOf(annotation);
  const highlights = annotationsToPdfHighlights(allAnnotations);
  const highlightId = annotationHighlightId(annotation, selectedIndex);

  return {
    type: AttachmentContentType.Pdf,
    url,
    highlights,
    selectedHighlightId: highlights.some(
      (highlight) => highlight.id === highlightId,
    )
      ? highlightId
      : undefined,
    page: getAnnotationPdfPage(annotation),
  };
}

annotationToOoxmlCanvasContent = (
  annotation: Annotation,
  annotations: Annotation[],
  resolvers: AttachmentCanvasUrlResolvers,
): OoxmlCanvasContent | null => {
  const source = annotation.body?.source?.attachment;
  if (source?.url == null) return null;

  const format = getOoxmlFileType(source.title ?? source.url, source.type);
  if (
    format !== OoxmlFileType.Docx &&
    format !== OoxmlFileType.Xlsx &&
    format !== OoxmlFileType.Pptx
  ) {
    return null;
  }

  const url = isDialFileId(source.url)
    ? resolvers.resolveDialFileDownloadUrl(source.url)
    : source.url;
  if (url == null) return null;

  const sameSource = gatherSameSourceAnnotations(annotation, annotations);
  const highlights: OoxmlHighlight[] = [];
  let selectedHighlightId: string | undefined;

  sameSource.forEach((entry, index) => {
    const locations = annotationToOfficeHighlightLocations(entry);
    if (locations.length === 0) return;

    const id = annotationHighlightId(entry, index);
    highlights.push({ id, locations: locations.map(toOoxmlHighlightLocation) });
    if (entry === annotation) selectedHighlightId = id;
  });

  return {
    type: AttachmentContentType.Ooxml,
    url,
    format,
    ...(highlights.length > 0 ? { highlights, selectedHighlightId } : {}),
  };
}

referenceAttachmentToPdfCanvasContent = (
  attachment: AttachmentResource,
  resolvers: AttachmentCanvasUrlResolvers,
): PdfCanvasContent | null => {
  const parsed = parsePdfPageReference(attachment.url);
  if (parsed == null) return null;

  const url = isDialFileId(parsed.baseUrl)
    ? resolvers.resolveDialFileDownloadUrl(parsed.baseUrl)
    : parsed.baseUrl;
  if (url == null) return null;

  if (parsed.page == null) {
    return { type: AttachmentContentType.Pdf, url };
  }

  const selectedHighlightId = `reference-page-${parsed.page}`;
  return {
    type: AttachmentContentType.Pdf,
    url,
    highlights: [
      {
        id: selectedHighlightId,
        bboxes: [{ page: parsed.page, x1: 0, y1: 0, x2: 0, y2: 0 }],
        style: { backgroundColor: 'transparent', opacity: 0 },
      },
    ],
    selectedHighlightId,
    page: parsed.page,
  };
}

resolvePdfCanvasContent = async (
  attachment: DisplayAttachment,
  resolvers: AttachmentCanvasUrlResolvers,
): Promise<PdfCanvasContent | ErrorCanvasContent | null> => {
  const result = await resolveAttachmentBlobUrl(attachment, resolvers);
  if (result != null) {
    if (typeof result !== 'string') return result;
    return { type: AttachmentContentType.Pdf, url: result };
  }
  const externalUrl = resolveExternalAttachmentUrl(attachment);
  return externalUrl != null
    ? { type: AttachmentContentType.Pdf, url: externalUrl }
    : null;
}

resolveOoxmlCanvasContent = async (
  attachment: DisplayAttachment,
  resolvers: AttachmentCanvasUrlResolvers,
  format: OoxmlFileType,
): Promise<OoxmlCanvasContent | ErrorCanvasContent | null> => {
  const result = await resolveAttachmentBlobUrl(attachment, resolvers);
  if (result != null) {
    if (typeof result !== 'string') return result;
    return { type: AttachmentContentType.Ooxml, url: result, format };
  }
  const externalUrl = resolveExternalAttachmentUrl(attachment);
  return externalUrl != null
    ? { type: AttachmentContentType.Ooxml, url: externalUrl, format }
    : null;
}

resolveJsonCanvasContent = async (
  attachment: DisplayAttachment,
  resolvers: AttachmentCanvasUrlResolvers,
): Promise<
  JsonCanvasContent | PlainTextCanvasContent | ErrorCanvasContent | null
> => {
  const result = await resolveAttachmentText(attachment, resolvers);
  if (result == null) return null;
  if (typeof result !== 'string') return result;

  try {
    const value = JSON.parse(result);
    return { type: AttachmentContentType.Json, value };
  } catch {
    return { type: AttachmentContentType.PlainText, text: result };
  }
}

resolveVisualizerCanvasContent = async (
  attachment: DisplayAttachment,
  resolvers: AttachmentCanvasUrlResolvers,
  entry: CustomVisualizer,
  themeId: string,
): Promise<VisualizerCanvasContent | null> => {
  const result = await resolveAttachmentText(attachment, resolvers);
  if (result == null || typeof result !== 'string') return null;

  let data: unknown = {};
  try {
    const parsed = JSON.parse(result);
    if (typeof parsed === 'object' && parsed !== null) {
      data = parsed;
    }
  } catch {
    /* non-JSON payload — send as empty object; visualizer receives raw mimeType */
  }

  return {
    type: AttachmentContentType.Visualizer,
    url: entry.url,
    mimeType: attachment.contentType,
    data,
    layout: {
      width: entry.width,
      height: entry.height,
      mobileHeight: entry.mobileHeight,
      themeId,
    },
    visualizerName: entry.title,
    requestTimeout: entry.requestTimeout,
  };
}

export interface GroupedVisualizerResolution {
  /** The grouped payload, or `null` when no claimed attachment resolved to a URL. */
  content: GroupedVisualizerCanvasContent | null;
  /** The claimed attachments that reached `content.attachments`, in the input's order. The caller returns the rest to the ordinary attachment tray. */
  resolved: DisplayAttachment[];
}

resolveGroupedVisualizerCanvasContent = (
  attachments: DisplayAttachment[],
  resolveAbsoluteUrl: (attachment: DisplayAttachment) => string | undefined,
  entry: ApplicationVisualizer,
  themeId: string,
): GroupedVisualizerResolution => {
  const layout: CustomVisualizerDataLayout = {
    width: entry.width,
    height: entry.height,
    mobileHeight: entry.mobileHeight,
    themeId,
  };

  const items: GroupedAttachmentItem[] = [];
  const resolved: DisplayAttachment[] = [];
  attachments.forEach((attachment) => {
    const url = resolveAbsoluteUrl(attachment);
    if (url == null) return;
    resolved.push(attachment);
    items.push({
      url,
      mimeType: attachment.contentType,
      visualizerData: { layout },
    });
  });

  if (items.length === 0) return { content: null, resolved: [] };

  return {
    content: {
      type: AttachmentContentType.GroupedVisualizer,
      url: entry.url,
      attachments: items,
      layout,
      visualizerName: entry.title,
      requestTimeout: entry.requestTimeout,
    },
    resolved,
  };
}

getUrlFileName = (url: string): string => {
  let path: string;
  try {
    path = new URL(url).pathname;
  } catch {
    /* A relative DIAL resource path has no base to resolve against, so the
     * query and hash are stripped by hand instead. */
    path = stripUrlQueryAndFragment(url);
  }
  const segment = path.split('/').filter(Boolean).pop() ?? '';
  try {
    return decodeURIComponent(segment);
  } catch {
    /* Malformed percent escape — the raw segment still works for extension
     * matching. */
    return segment;
  }
}

resolveExternalSourceContentType = (
  contentType: string,
  url: string,
): string => {
  if (isTrustedSourceContentType(contentType)) {
    return contentType;
  }
  const ext = lowerFileExtension(getUrlFileName(url));
  if (ext === PDF_EXTENSION) return PDF_MIME_TYPE;
  return Object.prototype.hasOwnProperty.call(OOXML_MIME_TYPE_BY_EXTENSION, ext)
    ? OOXML_MIME_TYPE_BY_EXTENSION[ext]
    : contentType;
}

isExternalSourcePreviewable = (
  contentType: string,
  url: string,
): boolean => {
  const resolvedType = resolveExternalSourceContentType(contentType, url);
  if (isTrustedSourceContentType(resolvedType)) {
    return true;
  }
  const ext = lowerFileExtension(getUrlFileName(url));
  /* 'html'/'htm' are not in TEXT_EXTENSIONS (they use HtmlContent), so both must be checked explicitly. */
  return TEXT_EXTENSIONS.has(ext) || HTML_EXTENSIONS.has(ext);
}

annotationToDisplayAttachment = (
  annotation: Annotation,
): DisplayAttachment | null => {
  const att = annotation.body?.source?.attachment;
  if (att == null) return null;
  return {
    id: att.url,
    name: att.url.split('/').pop() ?? att.url,
    contentType: att.type,
    type: att.type.startsWith('image/')
      ? AttachmentType.Image
      : AttachmentType.File,
    status: RequestStatus.Idle,
    url: att.url,
  };
}

resolveRelativeDialFilePath = (
  pathOrFileId: string,
  bucket: string,
): string => {
  const resourcePrefix = `files/${bucket}/`;
  if (pathOrFileId.startsWith(resourcePrefix)) {
    return safeDecodeURI(pathOrFileId.slice(resourcePrefix.length));
  }

  if (isDialFileId(pathOrFileId)) {
    const withoutPrefix = pathOrFileId.slice('files/'.length);
    const slashIdx = withoutPrefix.indexOf('/');
    if (slashIdx >= 0) {
      const pathBucket = withoutPrefix.slice(0, slashIdx);
      const rawPath = withoutPrefix.slice(slashIdx + 1);
      if (pathBucket === bucket) {
        return safeDecodeURI(rawPath);
      }
    }
  }

  return pathOrFileId;
}

resolveDialFileBucketAndPath = (
  fileId: string,
): { bucket: string; path: string } | undefined => {
  if (!isDialFileId(fileId)) return undefined;
  const withoutPrefix = fileId.slice('files/'.length);
  const slashIdx = withoutPrefix.indexOf('/');
  if (slashIdx < 0) return undefined;
  const bucket = withoutPrefix.slice(0, slashIdx);
  const rawPath = withoutPrefix.slice(slashIdx + 1);
  let path: string;
  try {
    path = decodeURIComponent(rawPath);
  } catch {
    path = rawPath;
  }
  return { bucket, path };
}

export interface DialFileToAttachmentOptions {
  /**
   * Resolves an image attachment's `previewUrl` from its DIAL resource URL.
   * Left unset, image attachments get no `previewUrl`. The host owns bucket/
   * icon-path REST construction — this hook never builds those URLs itself.
   */
  resolvePreviewUrl?: (url: string) => string | undefined;
}

dialFileToAttachment = (
  file: DialFile,
  bucket: string,
  options?: DialFileToAttachmentOptions,
): Attachment | null => {
  if (file.nodeType !== DialFileNodeType.ITEM) return null;

  const url = getDialFileUrl(file, bucket);
  if (!url) return null;

  const contentType = file.contentType ?? 'application/octet-stream';
  const isImage = contentType.startsWith('image/');
  const previewUrl = isImage ? options?.resolvePreviewUrl?.(url) : undefined;

  return {
    id: url,
    name: file.name,
    contentType,
    type: isImage ? AttachmentType.Image : AttachmentType.File,
    status: RequestStatus.Idle,
    url,
    file: new File([], file.name, { type: contentType }),
    ...(previewUrl != null ? { previewUrl } : {}),
  };
}

dialFolderPathToAttachment = (folderPath: string): Attachment => {
  const rawSegment =
    folderPath.replace(/\/$/, '').split('/').filter(Boolean).pop() ?? '';
  const name = safeDecodeURI(rawSegment);
  return {
    id: folderPath,
    name,
    contentType: 'application/octet-stream',
    type: AttachmentType.File,
    status: RequestStatus.Idle,
    url: folderPath,
    file: new File([], name),
  };
}

export enum DownloadDestinationType {
  Blob = 'blob',
  Stream = 'stream',
  Cancelled = 'cancelled',
}

export type DownloadDestination =
  | { type: DownloadDestinationType.Blob }
  | {
      type: DownloadDestinationType.Stream;
      writable: WritableStream<Uint8Array>;
    }
  | { type: DownloadDestinationType.Cancelled };

export interface DownloadDestinationHandlers {
  /** Resolves where a download with the given file name/MIME type should be written. */
  resolveDestination(
    filename: string,
    mimeType: string,
  ): Promise<DownloadDestination>;
  /** Writes `response` to `destination` and returns the name it was saved under. */
  triggerDownload(
    response: Response,
    fallbackName: string,
    destination: DownloadDestination,
  ): Promise<string>;
}

prepareDownloadDestination = async (
  filename: string,
  mimeType = 'application/octet-stream',
): Promise<DownloadDestination> => {
  const showSaveFilePicker = (
    window as Window & { showSaveFilePicker?: ShowSaveFilePicker }
  ).showSaveFilePicker;

  if (showSaveFilePicker == null) {
    return { type: DownloadDestinationType.Blob };
  }

  try {
    const extensionIndex = filename.lastIndexOf('.');
    const extension =
      extensionIndex >= 0 ? filename.slice(extensionIndex) : undefined;
    const handle = await showSaveFilePicker.call(window, {
      suggestedName: filename,
      types: [
        {
          description: mimeType,
          accept: {
            [mimeType]: extension != null ? [extension] : [],
          },
        },
      ],
    });
    return {
      type: DownloadDestinationType.Stream,
      writable: await handle.createWritable(),
    };
  } catch (error) {
    if (error instanceof DOMException && error.name === 'AbortError') {
      return { type: DownloadDestinationType.Cancelled };
    }
    throw error;
  }
}

virtualPathToApiPath = (
  virtualPath: string,
  rootLabel: string,
): string => {
  const rootExact = `/${rootLabel}`;
  const rootWithSlash = `/${rootLabel}/`;
  const labelWithSlash = `${rootLabel}/`;

  if (
    virtualPath === rootExact ||
    virtualPath === `${rootLabel}` ||
    virtualPath === rootWithSlash ||
    virtualPath === labelWithSlash
  ) {
    return '';
  }

  let stripped: string;
  if (virtualPath.startsWith(rootWithSlash)) {
    stripped = virtualPath.slice(rootWithSlash.length);
  } else if (virtualPath.startsWith(labelWithSlash)) {
    stripped = virtualPath.slice(labelWithSlash.length);
  } else {
    const withoutLeadingSlash = virtualPath.replace(/^\//, '');
    stripped = withoutLeadingSlash.startsWith(labelWithSlash)
      ? withoutLeadingSlash.slice(labelWithSlash.length)
      : withoutLeadingSlash;
  }

  /*
   * Collapse duplicate slashes (e.g. "folder//name") that ui-kit may produce
   * when concatenating paths, preventing BFF from forwarding malformed paths.
   */
  const collapsed = stripped.replace(/\/{2,}/g, '/');

  return collapsed && !collapsed.endsWith('/') ? `${collapsed}/` : collapsed;
}

getParentFolderPath = (path: string): string => {
  const normalized = path.replace(/\/$/, '');
  const lastSlash = normalized.lastIndexOf('/');
  return lastSlash > 0 ? normalized.slice(0, lastSlash + 1) : '';
}

resolveDialFileApiPath = (
  file: DialFile,
  bucket: string,
  rootLabel: string,
): string => {
  const isFolder = file.nodeType === DialFileNodeType.FOLDER;
  const fromResourceId = file.id
    ? resolveRelativeDialFilePath(file.id, bucket)
    : null;
  const resourceIdLooksValid =
    fromResourceId != null &&
    !looksLikeVirtualDialPath(fromResourceId, rootLabel);

  const apiPath = resourceIdLooksValid
    ? fromResourceId
    : virtualPathToApiPath(file.path, rootLabel);

  if (isFolder) {
    return apiPath.endsWith('/') ? apiPath : `${apiPath}/`;
  }

  return apiPath.replace(/\/$/, '');
}

export enum DialFileManagerActionProfile {
  Attach = 'attach',
  Browse = 'browse',
  Full = 'full',
}

export enum DialFileManagerVariant {
  Attach = 'attach',
  Standalone = 'standalone',
  FolderPicker = 'folder-picker',
}

deriveActionProfile = (
  variant: DialFileManagerVariant,
): DialFileManagerActionProfile => {
  switch (variant) {
    case DialFileManagerVariant.Attach:
      return DialFileManagerActionProfile.Attach;
    case DialFileManagerVariant.Standalone:
      return DialFileManagerActionProfile.Browse;
    case DialFileManagerVariant.FolderPicker:
      return DialFileManagerActionProfile.Full;
  }
}

export interface UseDialFileListingOptions {
  /** Injected operation port used for every listing/search network call. */
  filesApi: DialFilesApi;
  /** DIAL Core bucket to browse (used only for the my_files tab). */
  bucket: string;
  /** Display name for the root folder node (e.g. `'My files'`). */
  rootLabel: string;
  /** Active tab — drives listing source and per-tab options. */
  activeTab: DialFileManagerTabs;
  /** Called with a structured event when a folder-load operation fails. */
  onNotification?: (notification: FileManagerNotification) => void;
}

export interface UseDialFileListingResult {
  items: DialFile[];
  isLoading: boolean;
  error: string | null;
  path: string;
  /** Bucket-relative path of the currently browsed folder (e.g. `"reports/"`, `""` for root). */
  folderPath: string;
  onPathChange: (nextPath?: string) => void;
  retry: () => void;
  onSearchFiles: (folder: string, query: string) => void;
  isSearching: boolean;
  searchResults: DialFile[] | null;
  clearSearchResults: () => void;
  expandedPaths: Set<string>;
  loadedPaths: Set<string>;
  onExpandedPathsChange: (paths: Set<string>) => void;
  onFolderPopupPathChange: (nextPath?: string) => void;
  folderPopupLoadingPaths: Set<string>;
  sharedWithMeIds: string[] | undefined;
  sharedByMePaths: Set<string>;
  currentFolder: DialFile | undefined;
  /** Read-only snapshot of the per-folder listing cache, for `useDialFileUploadBatch`'s overwrite-mode check. */
  cache: Map<string, ListFilesItemDto[]>;
  /** Read-only snapshot of per-folder permissions, for `useDialFileMutations`'s create-folder inherited permissions. */
  listingPermissionsCache: Map<string, string[] | undefined>;
  /** Owner-bucket resolution metadata for the Shared tab, populated by the root listing fetch. */
  sharedRootMetaRef: React.RefObject<Map<string, SharedRootMeta>>;
  /** Imperatively navigates the current folder — used by mutations after a rename/delete of the browsed folder. */
  setFolderPath: React.Dispatch<React.SetStateAction<string>>;
  /**
   * Deletes the given API-path cache keys so the next listing fetch/expand for
   * that folder re-fetches from the server. The only way sibling sub-hooks may
   * invalidate the shared cache (design.md D1).
   */
  invalidateFolders: (apiPaths: string[]) => void;
  /** Merges a just-created folder into its parent's cache entry (optimistic display for create-folder). */
  mergeCreatedFolder: (
    parentApiPath: string,
    created: CreateFolderResponseDto,
    inheritedPermissions?: string[],
  ) => void;
  /** Forces the listing effect to re-fetch the currently browsed folder. */
  bumpRetry: () => void;
}

useDialFileListing = ({
  filesApi,
  bucket,
  rootLabel,
  activeTab,
  onNotification,
}: UseDialFileListingOptions): UseDialFileListingResult => {
  const [folderPath, setFolderPath] = useState('');
  const [cache, setCache] = useState<Map<string, ListFilesItemDto[]>>(
    () => new Map(),
  );
  const cacheRef = useRef(cache);
  useEffect(() => {
    cacheRef.current = cache;
  }, [cache]);
  const [listingPermissionsCache, setListingPermissionsCache] = useState<
    Map<string, string[] | undefined>
  >(() => new Map());
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [retryCounter, setRetryCounter] = useState(0);
  const [sharedRootIds, setSharedRootIds] = useState<string[] | undefined>(
    undefined,
  );
  const [sharedByMePaths, setSharedByMePaths] = useState<Set<string>>(
    () => new Set(),
  );

  // Maps shared root folder name → { bucket, dialCorePath } for subfolder navigation.
  const sharedRootMetaRef = useRef<Map<string, SharedRootMeta>>(new Map());

  const [isSearching, setIsSearching] = useState(false);
  const [searchResults, setSearchResults] = useState<DialFile[] | null>(null);
  const searchDebounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const searchCancelRef = useRef<(() => void) | null>(null);
  const expandingApiPathsRef = useRef<Set<string>>(new Set());
  /*
   * Folder api paths whose last expand fetch failed — excluded from auto-retry
   * on unrelated expand/collapse until the user collapses and re-expands them.
   */
  const erroredApiPathsRef = useRef<Set<string>>(new Set());

  const [expandedPaths, setExpandedPaths] = useState<Set<string>>(
    () => new Set(),
  );
  const [folderPopupLoadingPaths, setFolderPopupLoadingPaths] = useState<
    Set<string>
  >(() => new Set());
  const [folderPopupPaths, setFolderPopupPaths] = useState<Set<string>>(
    () => new Set(),
  );

  // Clear cache and reset path on tab switch
  const prevTabRef = useRef(activeTab);
  useEffect(() => {
    if (prevTabRef.current === activeTab) return;
    prevTabRef.current = activeTab;
    setCache(new Map());
    setListingPermissionsCache(new Map());
    setFolderPath('');
    setSharedRootIds(undefined);
    sharedRootMetaRef.current = new Map();
    expandingApiPathsRef.current = new Set();
    erroredApiPathsRef.current = new Set();
    setFolderPopupLoadingPaths(new Set());
    setFolderPopupPaths(new Set());
    if (searchDebounceRef.current != null) {
      clearTimeout(searchDebounceRef.current);
      searchDebounceRef.current = null;
    }
    searchCancelRef.current?.();
    searchCancelRef.current = null;
    setSearchResults(null);
    setIsSearching(false);
    setExpandedPaths(new Set());
  }, [activeTab]);

  useEffect(() => {
    return () => {
      if (searchDebounceRef.current != null) {
        clearTimeout(searchDebounceRef.current);
      }
      searchCancelRef.current?.();
    };
  }, []);

  /* Fires on mount for every variant (including Standalone) because
   * `folderPath` initializes to `''` above — no separate mount-effect is
   * needed to satisfy the standalone page's "load root listing on open"
   * requirement; it falls out of this effect's existing dependency array. */
  useEffect(() => {
    let cancelled = false;
    setIsLoading(true);
    setError(null);

    fetchByTab(
      filesApi,
      activeTab,
      bucket,
      folderPath,
      sharedRootMetaRef.current,
    )
      .then(({ items: flat, permissions }) => {
        if (cancelled) return;
        setCache((prev) => {
          const next = new Map(prev);
          next.set(folderPath, flat);
          return next;
        });
        setListingPermissionsCache((prev) =>
          new Map(prev).set(folderPath, permissions),
        );
        // Capture root-level shared item paths for sharedWithMeIds and subfolder navigation
        if (activeTab === DialFileManagerTabs.Shared && folderPath === '') {
          setSharedRootIds(
            flat.map((item) => {
              const relative = dialCorePathToRelative(
                item.path,
                item.bucket ?? '',
              );
              return buildSharedItemVirtualPath(
                relative,
                rootLabel,
                item.nodeType === ListFilesItemDtoNodeTypeEnum.Folder,
              );
            }),
          );
          sharedRootMetaRef.current = new Map(
            flat.map((item) => [
              item.name,
              { bucket: item.bucket ?? '', dialCorePath: item.path },
            ]),
          );
        }
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        /* The folder just browsed into can vanish (e.g. its last file was
         * deleted, dropping the now-empty folder from DIAL Core) — DIAL Core
         * then 404s the listing. Fall back to the parent folder instead of
         * surfacing a dead-end error. */
        if (folderPath !== '' && getApiErrorStatus(err) === 404) {
          setFolderPath(getParentFolderPath(folderPath));
          return;
        }
        setError('dialFileManager.error');
      })
      .finally(() => {
        if (!cancelled) setIsLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [activeTab, bucket, filesApi, folderPath, retryCounter, rootLabel]);

  /* sharedByMePaths is bucket-scoped (not folder-scoped) — fetched once per
   * my_files tab activation/retry, independent of the folder-listing effect above. */
  useEffect(() => {
    if (activeTab !== DialFileManagerTabs.MyFiles) {
      setSharedByMePaths(new Set());
      return;
    }

    let cancelled = false;
    filesApi
      .listSharedByMe(bucket)
      .then((res) => {
        if (cancelled) return;
        setSharedByMePaths(
          new Set(
            res.items.map((item) => {
              const relative = dialCorePathToRelative(item.path, bucket);
              return buildSharedItemVirtualPath(
                relative,
                rootLabel,
                item.nodeType === ListFilesItemDtoNodeTypeEnum.Folder,
              );
            }),
          ),
        );
      })
      .catch(() => {
        if (!cancelled) setSharedByMePaths(new Set());
      });

    return () => {
      cancelled = true;
    };
  }, [activeTab, bucket, filesApi, retryCounter, rootLabel]);

  const items = useMemo(
    (): DialFile[] => [
      {
        id: bucket,
        name: rootLabel,
        path: `/${rootLabel}`,
        parentPath: '',
        nodeType: DialFileNodeType.FOLDER,
        folderId: bucket,
        permissions: mapCorePermissions(listingPermissionsCache.get('')),
        items: buildFromCache(
          cache,
          listingPermissionsCache,
          '',
          `/${rootLabel}`,
          bucket,
        ),
      },
    ],
    [cache, listingPermissionsCache, rootLabel, bucket],
  );

  const onPathChange = useCallback(
    (nextPath?: string) => {
      if (nextPath == null) {
        setFolderPath('');
        return;
      }
      const rootWithSlash = `/${rootLabel}/`;
      const labelWithSlash = `${rootLabel}/`;

      if (
        nextPath === `/${rootLabel}` ||
        nextPath === rootWithSlash ||
        nextPath === rootLabel ||
        nextPath === labelWithSlash
      ) {
        setFolderPath('');
        return;
      }

      let stripped: string;
      if (nextPath.startsWith(rootWithSlash)) {
        stripped = nextPath.slice(rootWithSlash.length);
      } else if (nextPath.startsWith(labelWithSlash)) {
        stripped = nextPath.slice(labelWithSlash.length);
      } else {
        const withoutLeadingSlash = nextPath.replace(/^\//, '');
        stripped = withoutLeadingSlash.startsWith(labelWithSlash)
          ? withoutLeadingSlash.slice(labelWithSlash.length)
          : withoutLeadingSlash;
      }

      setFolderPath(
        stripped && !stripped.endsWith('/') ? `${stripped}/` : stripped,
      );
    },
    [rootLabel],
  );

  const retry = useCallback(() => {
    setRetryCounter((c) => c + 1);
  }, []);

  const bumpRetry = retry;

  const invalidateFolders = useCallback(
    (apiPaths: string[]) => {
      if (apiPaths.length === 0) return;

      /*
       * `folderPath` itself is refetched by the retryCounter-driven effect
       * above (via bumpRetry), which already replaces the cache entry only
       * once fresh data arrives rather than deleting it upfront. Any other
       * invalidated key that is an ancestor of `folderPath` — or an
       * already-expanded tree node — is otherwise never refetched:
       * `buildFromCache` recurses top-down from the bucket root, so a
       * deleted ancestor entry breaks the tree walk and makes the
       * still-cached `folderPath` node disappear from `items` until the
       * ancestor is explicitly refetched here.
       */
      const expandedApiPaths = new Set(
        [...expandedPaths].map((p) => virtualPathToApiPath(p, rootLabel)),
      );
      const isVisible = (k: string): boolean =>
        k === folderPath || folderPath.startsWith(k) || expandedApiPaths.has(k);

      /*
       * Keys that aren't currently rendered are safe to purge outright — the
       * next browse/expand will lazily refetch them. Keys that ARE visible
       * are refreshed in place instead (fetch first, then overwrite the
       * cache entry): deleting a visible key before the refetch resolves
       * makes `buildFromCache` treat it as empty for that window, producing
       * a visible flash of "No files yet" even though the old data was
       * still correct.
       */
      const keysToPurgeImmediately = apiPaths.filter((k) => !isVisible(k));
      const keysNeedingRefetch = apiPaths.filter(
        (k) => isVisible(k) && k !== folderPath,
      );

      if (keysToPurgeImmediately.length > 0) {
        setCache((prev) => {
          const next = new Map(prev);
          keysToPurgeImmediately.forEach((k) => next.delete(k));
          return next;
        });
        setListingPermissionsCache((prev) => {
          const next = new Map(prev);
          keysToPurgeImmediately.forEach((k) => next.delete(k));
          return next;
        });
      }

      keysNeedingRefetch.forEach((apiPath) => {
        const loadFolder = async (): Promise<void> => {
          try {
            const { items: flat, permissions } = await fetchByTab(
              filesApi,
              activeTab,
              bucket,
              apiPath,
              sharedRootMetaRef.current,
            );
            setCache((prev) => new Map(prev).set(apiPath, flat));
            if (permissions != null) {
              setListingPermissionsCache((prev) =>
                new Map(prev).set(apiPath, permissions),
              );
            }
          } catch {
            onNotification?.({
              variant: NotificationVariant.Error,
              reason: FileManagerNotificationReason.FolderLoadFailed,
            });
          }
        };
        void loadFolder();
      });
    },
    [
      activeTab,
      bucket,
      filesApi,
      folderPath,
      expandedPaths,
      rootLabel,
      onNotification,
    ],
  );

  const mergeCreatedFolder = useCallback(
    (
      parentApiPath: string,
      created: CreateFolderResponseDto,
      inheritedPermissions?: string[],
    ) => {
      setCache((prev) =>
        mergeCreatedFolderIntoCache(
          prev,
          parentApiPath,
          created,
          inheritedPermissions,
        ),
      );
    },
    [],
  );

  const onFolderPopupPathChange = useCallback(
    (nextPath?: string) => {
      const apiPath =
        nextPath == null ? '' : virtualPathToApiPath(nextPath, rootLabel);
      const virtualPath = nextPath == null ? `/${rootLabel}` : nextPath;

      setFolderPopupPaths((prev) => {
        if (prev.has(virtualPath)) return prev;
        const next = new Set(prev);
        next.add(virtualPath);
        return next;
      });

      if (cacheRef.current.has(apiPath)) {
        return;
      }

      if (expandingApiPathsRef.current.has(apiPath)) {
        setFolderPopupLoadingPaths((prev) => {
          const next = new Set(prev);
          next.add(virtualPath);
          return next;
        });
        return;
      }

      expandingApiPathsRef.current.add(apiPath);
      setFolderPopupLoadingPaths((prev) => {
        const next = new Set(prev);
        next.add(virtualPath);
        return next;
      });

      const loadFolder = async (): Promise<void> => {
        try {
          const { items: flat, permissions } = await fetchByTab(
            filesApi,
            activeTab,
            bucket,
            apiPath,
            sharedRootMetaRef.current,
          );
          setCache((prev) => new Map(prev).set(apiPath, flat));
          if (permissions != null) {
            setListingPermissionsCache((prev) =>
              new Map(prev).set(apiPath, permissions),
            );
          }
          erroredApiPathsRef.current.delete(apiPath);
        } catch {
          onNotification?.({
            variant: NotificationVariant.Error,
            reason: FileManagerNotificationReason.FolderLoadFailed,
          });
        } finally {
          expandingApiPathsRef.current.delete(apiPath);
          setFolderPopupLoadingPaths((prev) => {
            const next = new Set(prev);
            next.delete(virtualPath);
            return next;
          });
        }
      };

      void loadFolder();
    },
    [activeTab, bucket, filesApi, onNotification, rootLabel],
  );

  const loadedPaths = useMemo(() => {
    const result = new Set<string>();
    const candidatePaths = new Set([...expandedPaths, ...folderPopupPaths]);
    for (const virtualPath of candidatePaths) {
      const apiPath = virtualPathToApiPath(virtualPath, rootLabel);
      if (cache.has(apiPath)) {
        result.add(virtualPath);
      }
    }
    return result;
  }, [expandedPaths, folderPopupPaths, cache, rootLabel]);

  const onExpandedPathsChange = useCallback(
    (paths: Set<string>) => {
      /*
       * Collapsed folders drop out of `paths` — clear their errored state so
       * re-expanding the same folder later retries instead of staying blocked.
       */
      expandedPaths.forEach((p) => {
        if (!paths.has(p)) {
          erroredApiPathsRef.current.delete(virtualPathToApiPath(p, rootLabel));
        }
      });

      setExpandedPaths(paths);
      const newlyExpanded = [...paths].filter((p) => {
        const apiPath = virtualPathToApiPath(p, rootLabel);
        return (
          !cacheRef.current.has(apiPath) &&
          !expandingApiPathsRef.current.has(apiPath) &&
          !erroredApiPathsRef.current.has(apiPath)
        );
      });
      newlyExpanded.forEach((virtualPath) => {
        const apiPath = virtualPathToApiPath(virtualPath, rootLabel);
        expandingApiPathsRef.current.add(apiPath);
        const loadFolder = async (): Promise<void> => {
          try {
            const { items: flat, permissions } = await fetchByTab(
              filesApi,
              activeTab,
              bucket,
              apiPath,
              sharedRootMetaRef.current,
            );
            setCache((prev) => new Map(prev).set(apiPath, flat));
            if (permissions != null) {
              setListingPermissionsCache((prev) =>
                new Map(prev).set(apiPath, permissions),
              );
            }
          } catch {
            erroredApiPathsRef.current.add(apiPath);
            onNotification?.({
              variant: NotificationVariant.Error,
              reason: FileManagerNotificationReason.FolderLoadFailed,
            });
          } finally {
            expandingApiPathsRef.current.delete(apiPath);
            setFolderPopupLoadingPaths((prev) => {
              const next = new Set(prev);
              next.delete(virtualPath);
              return next;
            });
          }
        };
        void loadFolder();
      });
    },
    [activeTab, bucket, filesApi, expandedPaths, onNotification, rootLabel],
  );

  const clearSearchResults = useCallback(() => {
    if (searchDebounceRef.current != null) {
      clearTimeout(searchDebounceRef.current);
      searchDebounceRef.current = null;
    }
    searchCancelRef.current?.();
    searchCancelRef.current = null;
    setSearchResults(null);
    setIsSearching(false);
  }, []);

  const onSearchFiles = useCallback(
    (_folder: string, query: string) => {
      if (searchDebounceRef.current != null) {
        clearTimeout(searchDebounceRef.current);
        searchDebounceRef.current = null;
      }
      /*
       * Cancel any in-flight search immediately on every keystroke, so a
       * slower stale fetch can never overwrite the results of a newer one.
       */
      searchCancelRef.current?.();
      searchCancelRef.current = null;

      if (!query.trim()) {
        setSearchResults(null);
        setIsSearching(false);
        return;
      }
      searchDebounceRef.current = setTimeout(() => {
        searchDebounceRef.current = null;
        const lowerQuery = query.toLowerCase();

        // Shared root: filter already-loaded root items from the cache (no BFF call).
        if (activeTab === DialFileManagerTabs.Shared && folderPath === '') {
          searchCancelRef.current?.();
          searchCancelRef.current = null;
          setIsSearching(true);
          const rootItems = cache.get('') ?? [];
          const matched = rootItems.filter((item) =>
            item.name.toLowerCase().includes(lowerQuery),
          );
          setSearchResults(
            matched.map((item) =>
              mapSearchItem(item, item.bucket ?? bucket, rootLabel),
            ),
          );
          setIsSearching(false);
          return;
        }

        let cancelled = false;
        searchCancelRef.current = () => {
          cancelled = true;
        };
        setIsSearching(true);
        const runSearch = async (): Promise<void> => {
          try {
            const { items: searchItems } = await fetchForSearch(
              filesApi,
              activeTab,
              bucket,
              folderPath,
              sharedRootMetaRef.current,
            );
            if (cancelled) return;
            const matched = searchItems.filter((item) =>
              item.name.toLowerCase().includes(lowerQuery),
            );
            setSearchResults(
              matched.map((item) =>
                mapSearchItem(item, item.bucket ?? bucket, rootLabel),
              ),
            );
          } catch {
            if (!cancelled) setSearchResults([]);
          } finally {
            if (!cancelled) setIsSearching(false);
          }
        };
        void runSearch();
      }, 300);
    },
    [activeTab, bucket, cache, filesApi, folderPath, rootLabel],
  );

  const path = folderPath ? `/${rootLabel}/${folderPath}` : `/${rootLabel}`;

  const currentFolder = useMemo((): DialFile | undefined => {
    const root = items[0];
    if (!root) return undefined;
    if (normalizeVirtualPath(path) === normalizeVirtualPath(`/${rootLabel}`)) {
      return root;
    }
    return findFolderByVirtualPath(root.items ?? [], path);
  }, [items, path, rootLabel]);

  const sharedWithMeIds = useMemo(
    (): string[] | undefined =>
      activeTab === DialFileManagerTabs.Shared ? sharedRootIds : undefined,
    [activeTab, sharedRootIds],
  );

  return {
    items,
    isLoading,
    error,
    path,
    folderPath,
    onPathChange,
    retry,
    onSearchFiles,
    isSearching,
    searchResults,
    clearSearchResults,
    expandedPaths,
    loadedPaths,
    onExpandedPathsChange,
    onFolderPopupPathChange,
    folderPopupLoadingPaths,
    sharedWithMeIds,
    sharedByMePaths,
    currentFolder,
    cache,
    listingPermissionsCache,
    sharedRootMetaRef,
    setFolderPath,
    invalidateFolders,
    mergeCreatedFolder,
    bumpRetry,
  };
}

useDialFileManager = ({
  filesApi,
  bucket,
  rootLabel = 'My files',
  activeTab = DialFileManagerTabs.MyFiles,
  onNotification,
  onOperationSuccess,
  forbiddenSymbolsRegExp,
  variant = DialFileManagerVariant.Attach,
  actionProfile,
  labels,
  locale,
  disabledNewButtonTooltip,
  downloadDestination,
  buildValidationErrorMessage,
}: UseDialFileManagerOptions): UseDialFileManagerResult => {
  const resolvedActionProfile = actionProfile ?? deriveActionProfile(variant);

  const listing = useDialFileListing({
    filesApi,
    bucket,
    rootLabel,
    activeTab,
    onNotification,
  });

  const upload = useDialFileUploadBatch({
    filesApi,
    bucket,
    rootLabel,
    activeTab,
    cache: listing.cache,
    sharedRootMetaRef: listing.sharedRootMetaRef,
    invalidateFolders: listing.invalidateFolders,
    bumpRetry: listing.bumpRetry,
    onNotification,
  });

  const mutations = useDialFileMutations({
    filesApi,
    bucket,
    rootLabel,
    activeTab,
    folderPath: listing.folderPath,
    currentFolder: listing.currentFolder,
    sharedRootMetaRef: listing.sharedRootMetaRef,
    listingPermissionsCache: listing.listingPermissionsCache,
    invalidateFolders: listing.invalidateFolders,
    bumpRetry: listing.bumpRetry,
    mergeCreatedFolder: listing.mergeCreatedFolder,
    setFolderPath: listing.setFolderPath,
    onNotification,
    onOperationSuccess,
    downloadDestination,
    forbiddenSymbolsRegExp,
  });

  const sharing = useDialFileSharing({
    filesApi,
    bucket,
    rootLabel,
    bumpRetry: listing.bumpRetry,
    onNotification,
  });

  const metadata = useDialFileMetadata({
    filesApi,
    bucket,
    rootLabel,
    onNotification,
  });

  const canWriteCurrentFolder = hasDialFileWritePermission(
    listing.currentFolder,
  );

  const uploadEnabled = useMemo((): boolean => {
    if (activeTab === DialFileManagerTabs.Organization) return false;
    if (activeTab === DialFileManagerTabs.Shared && listing.folderPath === '') {
      return false;
    }
    return canWriteCurrentFolder;
  }, [activeTab, listing.folderPath, canWriteCurrentFolder]);

  const visibleColumns = useMemo(
    (): FileManagerColumnKey[] =>
      activeTab === DialFileManagerTabs.Shared
        ? COLUMNS_WITH_AUTHOR
        : COLUMNS_WITHOUT_AUTHOR,
    [activeTab],
  );

  const actionLabels = useMemo(() => {
    const result: Partial<Record<DialFileManagerActions, string>> = {};
    const setLabel = (action: DialFileManagerActions): void => {
      const label = labels[action];
      if (label != null) result[action] = label;
    };

    setLabel(DialFileManagerActions.Download);
    if (activeTab === DialFileManagerTabs.MyFiles) {
      setLabel(DialFileManagerActions.Delete);
      if (uploadEnabled) {
        setLabel(DialFileManagerActions.Rename);
        if (isCopyMoveDuplicateAllowed(resolvedActionProfile)) {
          setLabel(DialFileManagerActions.Copy);
          setLabel(DialFileManagerActions.Move);
          setLabel(DialFileManagerActions.Duplicate);
        }
      }
      if (isShareActionsAllowed(resolvedActionProfile)) {
        setLabel(DialFileManagerActions.RemoveAccess);
      }
    } else if (
      activeTab === DialFileManagerTabs.Shared &&
      isShareActionsAllowed(resolvedActionProfile)
    ) {
      setLabel(DialFileManagerActions.Unshare);
    }
    // Info is read-only and available on all three tabs — not tab-branched.
    if (resolvedActionProfile === DialFileManagerActionProfile.Full) {
      setLabel(DialFileManagerActions.Info);
    }
    return result;
  }, [activeTab, uploadEnabled, resolvedActionProfile, labels]);

  const isAnyOperationInProgress = useMemo(
    (): boolean =>
      mutations.isCreatingFolder ||
      mutations.isDownloading ||
      mutations.isDeleting ||
      mutations.isRenaming ||
      mutations.isCopying ||
      mutations.isMoving ||
      sharing.isUnsharing ||
      sharing.isRemovingAccess ||
      upload.uploadBatchState != null,
    [
      mutations.isCreatingFolder,
      mutations.isDownloading,
      mutations.isDeleting,
      mutations.isRenaming,
      mutations.isCopying,
      mutations.isMoving,
      sharing.isUnsharing,
      sharing.isRemovingAccess,
      upload.uploadBatchState,
    ],
  );

  const onCreateFolderValidate = useCallback(
    (name: string, parentFolder: DialFile): string | null => {
      const error = mutations.onCreateFolderValidate(name, parentFolder);
      return error ? buildValidationErrorMessage(error) : null;
    },
    [mutations, buildValidationErrorMessage],
  );

  const onRenameValidate = useCallback(
    (value: string, item: DialFile): string | null => {
      const error = mutations.onRenameValidate(value, item);
      return error ? buildValidationErrorMessage(error, item) : null;
    },
    [mutations, buildValidationErrorMessage],
  );

  return {
    items: listing.items,
    isLoading: listing.isLoading,
    error: listing.error,
    path: listing.path,
    onPathChange: listing.onPathChange,
    retry: listing.retry,
    onSearchFiles: listing.onSearchFiles,
    isSearching: listing.isSearching,
    searchResults: listing.searchResults,
    clearSearchResults: listing.clearSearchResults,
    expandedPaths: listing.expandedPaths,
    loadedPaths: listing.loadedPaths,
    onExpandedPathsChange: listing.onExpandedPathsChange,
    onFolderPopupPathChange: listing.onFolderPopupPathChange,
    folderPopupLoadingPaths: listing.folderPopupLoadingPaths,
    onUploadFiles: upload.onUploadFiles,
    onUploadArchive: upload.onUploadArchive,
    onValidateUpload: upload.onValidateUpload,
    uploadBatchState: upload.uploadBatchState,
    cancelUpload: upload.cancelUpload,
    clearUploadBatch: upload.clearUploadBatch,
    onCreateFolder: mutations.onCreateFolder,
    onCreateFolderValidate,
    isCreatingFolder: mutations.isCreatingFolder,
    onDownloadFiles: mutations.onDownloadFiles,
    isDownloading: mutations.isDownloading,
    onDeleteFiles: mutations.onDeleteFiles,
    isDeleting: mutations.isDeleting,
    onRenameValidate,
    onMoveToFiles: mutations.onMoveToFiles,
    isRenaming: mutations.isRenaming,
    onCopyFiles: mutations.onCopyFiles,
    isCopying: mutations.isCopying,
    isMoving: mutations.isMoving,
    cancelCopyMove: mutations.cancelCopyMove,
    uploadEnabled,
    isNewButtonDisabled: !uploadEnabled,
    disabledNewButtonTooltip,
    visibleColumns,
    dateLocale: locale,
    dateOptions: DATE_OPTIONS,
    actionLabels,
    sharedWithMeIds: listing.sharedWithMeIds,
    sharedByMePaths: listing.sharedByMePaths,
    onUnshareFiles: sharing.onUnshareFiles,
    isUnsharing: sharing.isUnsharing,
    onRemoveFilesAccess: sharing.onRemoveFilesAccess,
    isRemovingAccess: sharing.isRemovingAccess,
    fileMetadata: metadata.fileMetadata,
    isFileMetadataLoading: metadata.isFileMetadataLoading,
    onGetInfo: metadata.onGetInfo,
    clearMetadata: metadata.clearMetadata,
    isAnyOperationInProgress,
  };
}

export interface UseDialFileManagerTabConfigResult {
  tabs: ToolbarOptions['tabs'];
}

useDialFileManagerTabConfig = (
  activeTab: DialFileManagerTabs,
  onTabChange: (tab: DialFileManagerTabs) => void,
  allTabs: TabModel[] | undefined,
  fileManagerTabs: string[] | undefined,
): UseDialFileManagerTabConfigResult => {
  const isTabEnabled = useCallback(
    (tabId: string): boolean =>
      fileManagerTabs == null || fileManagerTabs.includes(tabId),
    [fileManagerTabs],
  );

  const tabs = useMemo(
    () =>
      allTabs
        ?.filter((tab) => isTabEnabled(tab.id))
        .flatMap(({ id, label, disabled }) =>
          typeof label === 'string' ? [{ id, label, disabled }] : [],
        ),
    [allTabs, isTabEnabled],
  );

  useEffect(() => {
    if (isTabEnabled(activeTab)) return;

    const fallbackTab =
      TAB_PRIORITY_ORDER.find((tab) => isTabEnabled(tab)) ??
      DialFileManagerTabs.MyFiles;

    onTabChange(fallbackTab);
  }, [isTabEnabled, activeTab, onTabChange]);

  return { tabs };
}

export interface UseDialFileMetadataOptions {
  /** Injected operation port used for the metadata network call. */
  filesApi: DialFilesApi;
  /** DIAL Core bucket the current user browses (used only for my_files items). */
  bucket: string;
  /** Display name of the root folder node, used to resolve virtual paths back to API paths. */
  rootLabel: string;
  /** Called with a structured event when the metadata fetch fails. */
  onNotification?: (notification: FileManagerNotification) => void;
}

export interface UseDialFileMetadataResult {
  fileMetadata: DialFile | undefined;
  isFileMetadataLoading: boolean;
  onGetInfo: (file: DialFile) => void;
  clearMetadata: () => void;
}

useDialFileMetadata = ({
  filesApi,
  bucket,
  rootLabel,
  onNotification,
}: UseDialFileMetadataOptions): UseDialFileMetadataResult => {
  const [fileMetadata, setFileMetadata] = useState<DialFile | undefined>(
    undefined,
  );
  const [isFileMetadataLoading, setIsFileMetadataLoading] = useState(false);

  const onGetInfo = useCallback(
    (file: DialFile) => {
      const run = async () => {
        setIsFileMetadataLoading(true);
        try {
          const itemBucket = file.bucket ?? bucket;
          const itemPath = resolveDialFileApiPath(file, itemBucket, rootLabel);
          const metadata = await filesApi.getFileMetadata({
            bucket: itemBucket,
            path: itemPath,
          });
          setFileMetadata(mapFileMetadataToDialFile(metadata, file));
        } catch {
          onNotification?.({
            variant: NotificationVariant.Error,
            reason: FileManagerNotificationReason.MetadataLoadFailed,
          });
        } finally {
          setIsFileMetadataLoading(false);
        }
      };
      void run();
    },
    [bucket, filesApi, rootLabel, onNotification],
  );

  const clearMetadata = useCallback(() => {
    setFileMetadata(undefined);
    setIsFileMetadataLoading(false);
  }, []);

  return {
    fileMetadata,
    isFileMetadataLoading,
    onGetInfo,
    clearMetadata,
  };
}

export interface UseDialFileMutationsOptions {
  /** Injected operation port used for every mutation network call. */
  filesApi: DialFilesApi;
  /** DIAL Core bucket to browse (used only for the my_files tab). */
  bucket: string;
  /** Display name for the root folder node. */
  rootLabel: string;
  /** Active tab — drives owner-bucket resolution for the Shared tab. */
  activeTab: DialFileManagerTabs;
  /** Bucket-relative path of the currently browsed folder, owned by `useDialFileListing`. */
  folderPath: string;
  /** Currently browsed folder node, owned by `useDialFileListing`. */
  currentFolder: DialFile | undefined;
  /** Owner-bucket resolution metadata for the Shared tab, owned by `useDialFileListing`. */
  sharedRootMetaRef: React.RefObject<Map<string, SharedRootMeta>>;
  /** Read-only snapshot of `useDialFileListing`'s per-folder permissions cache. */
  listingPermissionsCache: Map<string, string[] | undefined>;
  /** Deletes the given API-path cache keys so the next fetch re-fetches them. */
  invalidateFolders: (apiPaths: string[]) => void;
  /** Forces `useDialFileListing`'s fetch effect to re-run. */
  bumpRetry: () => void;
  /** Merges a newly created folder into its parent's cache entry, owned by `useDialFileListing`. */
  mergeCreatedFolder: (
    parentApiPath: string,
    created: CreateFolderResponseDto,
    inheritedPermissions?: string[],
  ) => void;
  /** Imperatively navigates the current folder after a rename/delete of the browsed folder. */
  setFolderPath: React.Dispatch<React.SetStateAction<string>>;
  /** Called when a mutation should surface a toast notification. */
  onNotification?: (notification: FileManagerNotification) => void;
  /** Called when a mutation succeeds, instead of invoking an application notification service directly. */
  onOperationSuccess?: (event: FileOperationSuccessEvent) => void;
  /** Host-injected browser "Save As"/auto-download seam for `onDownloadFiles`. */
  downloadDestination: DownloadDestinationHandlers;
  /** Regexp of characters forbidden in file/folder names beyond the path separator. */
  forbiddenSymbolsRegExp?: RegExp;
}

export interface UseDialFileMutationsResult {
  isCreatingFolder: boolean;
  isDownloading: boolean;
  isDeleting: boolean;
  isRenaming: boolean;
  isCopying: boolean;
  isMoving: boolean;
  onCreateFolder: (
    file: DialUploadFileItem,
    folderPath: string,
    fileId: string,
  ) => Promise<void>;
  onCreateFolderValidate: (
    name: string,
    parentFolder: DialFile,
  ) => FileNameValidationError | null;
  onDownloadFiles: (dialFiles: DialFile[]) => void;
  onDeleteFiles: (items: DialDeletedItem[], sourceFolder: string) => void;
  onRenameValidate: (
    value: string,
    item: DialFile,
  ) => FileNameValidationError | null;
  onMoveToFiles: (
    items: DialCopiedItem[],
    sourceFolder: string,
    destinationFolder: string,
  ) => void;
  onCopyFiles: (items: DialCopiedItem[], destinationFolder: string) => void;
  cancelCopyMove: () => void;
}

useDialFileMutations = ({
  filesApi,
  bucket,
  rootLabel,
  activeTab,
  folderPath,
  currentFolder,
  sharedRootMetaRef,
  listingPermissionsCache,
  invalidateFolders,
  bumpRetry,
  mergeCreatedFolder,
  setFolderPath,
  onNotification,
  onOperationSuccess,
  downloadDestination,
  forbiddenSymbolsRegExp,
}: UseDialFileMutationsOptions): UseDialFileMutationsResult => {
  const [isCreatingFolder, setIsCreatingFolder] = useState(false);
  const [isDownloading, setIsDownloading] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isRenaming, setIsRenaming] = useState(false);
  const [isCopying, setIsCopying] = useState(false);
  const [isMoving, setIsMoving] = useState(false);
  const copyMoveAbortControllerRef = useRef<AbortController | null>(null);

  /*
   * The host `DialFileManager` grid shows this validation result inline
   * while the user types but does not reliably gate its own `onCreateFolder`
   * confirm callback on it — and the name it eventually passes to
   * `onCreateFolder` is derived by splitting a constructed virtual path on
   * '/', which silently swallows an embedded '/' the user typed as if it
   * were a path separator (see #7968). Track the last live-typed validation
   * result here so `onCreateFolder` can refuse even when the value it
   * receives no longer reflects that error.
   */
  const lastLiveValidationErrorRef = useRef<FileNameValidationError | null>(
    null,
  );

  const onCreateFolderValidate = useCallback(
    (name: string, parentFolder: DialFile): FileNameValidationError | null => {
      let error: FileNameValidationError | null = null;
      if (!name || name.trim() === '') {
        error = { reason: FileNameValidationErrorReason.Empty };
      } else if (hasForbiddenNameSymbols(name, forbiddenSymbolsRegExp)) {
        error = {
          reason: FileNameValidationErrorReason.ForbiddenSymbols,
          symbols: NOT_ALLOWED_SYMBOLS,
        };
      } else if (name.startsWith('.')) {
        error = { reason: FileNameValidationErrorReason.LeadingDot };
      } else if (name === RESERVED_MARKER_NAME) {
        error = { reason: FileNameValidationErrorReason.ReservedName };
      } else if (name.length > 255) {
        error = {
          reason: FileNameValidationErrorReason.TooLong,
          maxLength: 255,
        };
      } else {
        const siblings = parentFolder.items ?? [];
        const lowerName = name.toLowerCase();
        const matched = siblings.find(
          (s) => s.name.toLowerCase() === lowerName,
        );
        if (matched) {
          error = {
            reason: FileNameValidationErrorReason.DuplicateName,
            existingName: matched.name,
          };
        }
      }
      lastLiveValidationErrorRef.current = error;
      return error;
    },
    [forbiddenSymbolsRegExp],
  );

  const onCreateFolder = useCallback(
    async (
      _file: DialUploadFileItem,
      newFolderPath: string,
      _fileId: string,
    ): Promise<void> => {
      const { parentVirtualPath, name } = parseNewFolderVirtualPath(
        newFolderPath,
        rootLabel,
      );
      const parentApiPath = virtualPathToApiPath(parentVirtualPath, rootLabel);

      const parentFolder: DialFile =
        currentFolder && folderPath === parentApiPath
          ? currentFolder
          : {
              id: parentApiPath,
              path: parentApiPath,
              name: parentVirtualPath.split('/').filter(Boolean).pop() ?? '',
              folderId: parentApiPath,
              nodeType: DialFileNodeType.FOLDER,
              items: [],
            };

      // Captured before re-validating below, which overwrites the ref.
      const priorLiveError = lastLiveValidationErrorRef.current;
      lastLiveValidationErrorRef.current = null;

      if (onCreateFolderValidate(name, parentFolder) || priorLiveError) return;

      setIsCreatingFolder(true);
      const { bucket: targetBucket, path: targetParentPath } =
        activeTab === DialFileManagerTabs.Shared
          ? resolveOwnerCoords(parentApiPath, sharedRootMetaRef.current, bucket)
          : { bucket, path: parentApiPath };
      try {
        const created = await filesApi.createFolder({
          /*
           * At the bucket root `targetParentPath` is the empty string, and it
           * is sent as such rather than being dropped: the API contract states
           * the key as "empty for root", so an omitted key and an empty one are
           * the same folder but not the same request.
           */
          bucket: targetBucket,
          parentPath: targetParentPath,
          name,
        });
        mergeCreatedFolder(
          parentApiPath,
          created,
          listingPermissionsCache.get(parentApiPath),
        );
        bumpRetry();
        onOperationSuccess?.({ kind: FileOperationKind.FolderCreated, name });
      } catch {
        onNotification?.({
          variant: NotificationVariant.Error,
          reason: FileManagerNotificationReason.FolderCreateFailed,
        });
      } finally {
        setIsCreatingFolder(false);
      }
    },
    [
      activeTab,
      bucket,
      currentFolder,
      filesApi,
      folderPath,
      onCreateFolderValidate,
      rootLabel,
      listingPermissionsCache,
      mergeCreatedFolder,
      bumpRetry,
      onOperationSuccess,
      sharedRootMetaRef,
      onNotification,
    ],
  );

  const onDownloadFiles = useCallback(
    (dialFiles: DialFile[]) => {
      const run = async () => {
        setIsDownloading(true);
        try {
          const filename =
            dialFiles.length === 1
              ? dialFiles[0].nodeType === DialFileNodeType.ITEM
                ? dialFiles[0].name
                : `${dialFiles[0].name}.zip`
              : 'files.zip';
          const destination = await downloadDestination.resolveDestination(
            filename,
            dialFiles.length === 1 &&
              dialFiles[0].nodeType === DialFileNodeType.ITEM
              ? (dialFiles[0].contentType ?? 'application/octet-stream')
              : 'application/zip',
          );
          if (destination.type === DownloadDestinationType.Cancelled) return;

          if (
            dialFiles.length === 1 &&
            dialFiles[0].nodeType === DialFileNodeType.ITEM
          ) {
            const file = dialFiles[0];
            if (!file.bucket) {
              throw new Error('File is missing bucket');
            }
            const filePath = resolveDialFileApiPath(
              file,
              file.bucket,
              rootLabel,
            );
            const response = await filesApi.downloadFile(file.bucket, filePath);
            if (!response.ok) {
              throw new Error(`Download failed with status ${response.status}`);
            }
            const savedName = await downloadDestination.triggerDownload(
              response,
              file.name,
              destination,
            );
            onOperationSuccess?.({
              kind: FileOperationKind.FileDownloaded,
              name: savedName,
              count: 1,
            });
          } else {
            const archiveItems: ArchiveItemDto[] = dialFiles.map((f) => ({
              bucket: f.bucket ?? bucket,
              path: resolveDialFileApiPath(f, f.bucket ?? bucket, rootLabel),
              name: f.name,
              nodeType:
                f.nodeType === DialFileNodeType.FOLDER
                  ? ArchiveItemDtoNodeTypeEnum.Folder
                  : ArchiveItemDtoNodeTypeEnum.Item,
            }));
            const response = await filesApi.downloadArchive(archiveItems);
            if (!response.ok) {
              throw new Error(`Download failed with status ${response.status}`);
            }
            const savedName = await downloadDestination.triggerDownload(
              response,
              filename,
              destination,
            );
            /*
             * A lone folder is reported as a name-only event; a multi-item
             * selection is reported as a count only, since the archive
             * itself is not an entity the user picked.
             */
            if (dialFiles.length === 1) {
              onOperationSuccess?.({
                kind: FileOperationKind.FileDownloaded,
                name: savedName,
              });
            } else {
              onOperationSuccess?.({
                kind: FileOperationKind.FilesDownloaded,
                count: dialFiles.length,
              });
            }
          }
        } catch {
          onNotification?.({
            variant: NotificationVariant.Error,
            reason:
              dialFiles.length === 1
                ? FileManagerNotificationReason.DownloadFileFailed
                : FileManagerNotificationReason.DownloadFilesFailed,
          });
        } finally {
          setIsDownloading(false);
        }
      };
      void run();
    },
    [
      bucket,
      rootLabel,
      onOperationSuccess,
      onNotification,
      filesApi,
      downloadDestination,
    ],
  );

  const onDeleteFiles = useCallback(
    (deletedItems: DialDeletedItem[], sourceFolder: string) => {
      if (deletedItems.length === 0) return;

      const run = async () => {
        setIsDeleting(true);

        const dtos: DeleteItemDto[] = deletedItems.map((item) => {
          const isFolder = item.nodeType === DialFileNodeType.FOLDER;
          const apiPath = virtualPathToApiPath(item.sourceUrl, rootLabel);
          const relPath = isFolder ? apiPath : apiPath.replace(/\/$/, '');
          const name = getVirtualPathName(item.sourceUrl, relPath);
          const { bucket: itemBucket, path: itemPath } =
            activeTab === DialFileManagerTabs.Shared
              ? resolveOwnerCoords(relPath, sharedRootMetaRef.current, bucket)
              : { bucket, path: relPath };
          return {
            bucket: itemBucket,
            path: itemPath,
            name,
            nodeType: isFolder
              ? DeleteItemDtoNodeTypeEnum.Folder
              : DeleteItemDtoNodeTypeEnum.Item,
          };
        });

        try {
          const { results } = await filesApi.deleteFiles(dtos);
          const failedResults = results.filter((r) => !r.success);
          const failedCount = failedResults.length;
          const successCount = results.length - failedCount;
          const firstSuccessfulResult = results.find(
            (result) => result.success,
          );
          const firstSuccessfulDto =
            dtos.find((item) => item.path === firstSuccessfulResult?.path) ??
            dtos[0];

          if (successCount > 0) {
            onNotification?.({
              variant: NotificationVariant.Success,
              reason: FileManagerNotificationReason.FilesDeleted,
              count: successCount,
              name: firstSuccessfulDto?.name,
              folder: sourceFolder || rootLabel,
            });
          }

          if (failedCount > 0) {
            const failedNames = failedResults.slice(0, 3).map((result) => {
              const failedDto = dtos.find((item) => item.path === result.path);
              return failedDto?.name ?? result.path;
            });
            const restCount = failedCount - failedNames.length;

            onNotification?.({
              variant: NotificationVariant.Error,
              reason: FileManagerNotificationReason.FilesDeletePartiallyFailed,
              names: failedNames,
              restCount,
            });
          }
        } catch {
          onNotification?.({
            variant: NotificationVariant.Error,
            reason: FileManagerNotificationReason.DeleteFailed,
          });
        }

        const deletedFolderPaths = dtos
          .filter((d) => d.nodeType === DeleteItemDtoNodeTypeEnum.Folder)
          .map((d) => (d.path.endsWith('/') ? d.path : `${d.path}/`));

        const affectedFolderKeys = new Set<string>(
          dtos.map((d) => {
            if (d.nodeType === DeleteItemDtoNodeTypeEnum.Folder) {
              return d.path.endsWith('/') ? d.path : `${d.path}/`;
            }
            const lastSlash = d.path.lastIndexOf('/');
            return lastSlash > 0 ? d.path.slice(0, lastSlash + 1) : '';
          }),
        );

        invalidateFolders([...affectedFolderKeys]);

        const isCurrentFolderDeleted = deletedFolderPaths.some(
          (fp) => folderPath === fp || folderPath.startsWith(fp),
        );
        if (isCurrentFolderDeleted) {
          setFolderPath((prev) => prev.replace(/[^/]+\/$/, ''));
        }

        bumpRetry();
        setIsDeleting(false);
      };
      void run();
    },
    [
      activeTab,
      bucket,
      rootLabel,
      folderPath,
      onNotification,
      filesApi,
      sharedRootMetaRef,
      invalidateFolders,
      bumpRetry,
      setFolderPath,
    ],
  );

  const onRenameValidate = useCallback(
    (value: string, item: DialFile): FileNameValidationError | null => {
      if (!value || value.trim() === '') {
        return { reason: FileNameValidationErrorReason.Empty };
      }
      if (value === RESERVED_MARKER_NAME) {
        return { reason: FileNameValidationErrorReason.ReservedName };
      }
      if (hasForbiddenNameSymbols(value, forbiddenSymbolsRegExp)) {
        return {
          reason: FileNameValidationErrorReason.ForbiddenSymbols,
          symbols: NOT_ALLOWED_SYMBOLS,
        };
      }
      if (value.length > 255) {
        return {
          reason: FileNameValidationErrorReason.TooLong,
          maxLength: 255,
        };
      }
      const siblings = currentFolder?.items ?? [];
      const lowerValue = value.toLowerCase();
      const matched = siblings.find(
        (s) => s.path !== item.path && s.name.toLowerCase() === lowerValue,
      );
      if (matched) {
        return {
          reason: FileNameValidationErrorReason.DuplicateName,
          existingName: matched.name,
        };
      }
      return null;
    },
    [forbiddenSymbolsRegExp, currentFolder],
  );

  const onCopyFiles = useCallback(
    (copiedItems: DialCopiedItem[], destinationFolder: string) => {
      if (copiedItems.length === 0 || isCopying || isMoving) return;

      const controller = new AbortController();
      copyMoveAbortControllerRef.current = controller;

      const run = async () => {
        setIsCopying(true);

        const preparedItems = prepareCopyItems(copiedItems, bucket, rootLabel);
        const dtos = preparedItems.map(({ dto }) => dto);

        try {
          const { results } = await filesApi.copyFiles(dtos, controller.signal);
          const failedCount = results.filter((r) => !r.success).length;
          const successCount = results.length - failedCount;

          if (successCount > 0) {
            const firstSuccessfulItem = findFirstSuccessfulCopyMoveItem(
              preparedItems,
              results,
            );

            onOperationSuccess?.({
              kind:
                successCount === 1
                  ? FileOperationKind.FileCopied
                  : FileOperationKind.FilesCopied,
              name: firstSuccessfulItem?.destinationName,
              count: successCount,
              destinationFolderName: formatOperationFolderName(
                destinationFolder,
                rootLabel,
              ),
            });
          }

          if (failedCount > 0 && failedCount < results.length) {
            onNotification?.({
              variant: NotificationVariant.Error,
              reason: FileManagerNotificationReason.CopyPartiallyFailed,
              count: failedCount,
            });
          } else if (failedCount === results.length) {
            onNotification?.({
              variant: NotificationVariant.Error,
              reason: FileManagerNotificationReason.CopyFailed,
            });
          }
        } catch {
          if (!controller.signal.aborted) {
            onNotification?.({
              variant: NotificationVariant.Error,
              reason: FileManagerNotificationReason.CopyFailed,
            });
          }
        } finally {
          const affectedKeys = new Set(
            dtos.flatMap((dto) => [
              getParentFolderPath(dto.sourcePath),
              getParentFolderPath(dto.destinationPath),
            ]),
          );

          invalidateFolders([...affectedKeys]);
          bumpRetry();
          setIsCopying(false);
          copyMoveAbortControllerRef.current = null;
        }
      };

      void run();
    },
    [
      bucket,
      rootLabel,
      onNotification,
      onOperationSuccess,
      filesApi,
      isCopying,
      isMoving,
      invalidateFolders,
      bumpRetry,
    ],
  );

  const cancelCopyMove = useCallback(() => {
    copyMoveAbortControllerRef.current?.abort();
  }, []);

  const onMoveToFiles = useCallback(
    (
      copiedItems: DialCopiedItem[],
      _sourceFolder: string,
      destinationFolder: string,
    ) => {
      if (copiedItems.length === 0 || isCopying || isMoving || isRenaming) {
        return;
      }

      const { renameDtos, preparedMoveItems } = prepareMoveRenameItems(
        copiedItems,
        bucket,
        rootLabel,
      );
      const moveDtos = preparedMoveItems.map(({ dto }) => dto);

      const controller = new AbortController();
      if (moveDtos.length > 0) {
        copyMoveAbortControllerRef.current = controller;
      }

      const run = async () => {
        if (renameDtos.length > 0) setIsRenaming(true);
        if (moveDtos.length > 0) setIsMoving(true);

        const runRename = async (): Promise<{
          results: Awaited<ReturnType<DialFilesApi['renameFiles']>>['results'];
          threw: boolean;
        }> => {
          if (renameDtos.length === 0) return { results: [], threw: false };
          try {
            const { results } = await filesApi.renameFiles(renameDtos);
            return { results, threw: false };
          } catch {
            return { results: [], threw: true };
          }
        };

        const runMove = async (): Promise<{
          results: Awaited<ReturnType<DialFilesApi['moveFiles']>>['results'];
          threw: boolean;
          aborted: boolean;
        }> => {
          if (moveDtos.length === 0) {
            return { results: [], threw: false, aborted: false };
          }
          try {
            const { results } = await filesApi.moveFiles(
              moveDtos,
              controller.signal,
            );
            return { results, threw: false, aborted: false };
          } catch {
            return {
              results: [],
              threw: true,
              aborted: controller.signal.aborted,
            };
          }
        };

        const [renameOutcome, moveOutcome] = await Promise.all([
          runRename(),
          runMove(),
        ]);

        const renameFailedCount = renameOutcome.threw
          ? renameDtos.length
          : renameOutcome.results.filter((r) => !r.success).length;
        const moveWasAborted = moveOutcome.threw && moveOutcome.aborted;
        const moveTotal = moveWasAborted ? 0 : moveDtos.length;
        const moveFailedCount = moveWasAborted
          ? 0
          : moveOutcome.threw
            ? moveDtos.length
            : moveOutcome.results.filter((r) => !r.success).length;
        const moveSuccessCount = moveOutcome.threw
          ? 0
          : moveOutcome.results.filter((r) => r.success).length;

        const totalCount = renameDtos.length + moveTotal;
        const totalFailed = renameFailedCount + moveFailedCount;
        const useMoveCopy = moveFailedCount > 0;

        if (moveSuccessCount > 0) {
          const firstSuccessfulItem = findFirstSuccessfulCopyMoveItem(
            preparedMoveItems,
            moveOutcome.results,
          );

          onOperationSuccess?.({
            kind:
              moveSuccessCount === 1
                ? FileOperationKind.FileMoved
                : FileOperationKind.FilesMoved,
            name: firstSuccessfulItem?.destinationName,
            count: moveSuccessCount,
            destinationFolderName: formatOperationFolderName(
              destinationFolder,
              rootLabel,
            ),
          });
        }

        /*
         * Renaming from the grid is always a single item, so a fully successful
         * single rename is confirmed by name. A multi-item rename batch — which
         * the UI cannot produce today — stays silent rather than claiming a name
         * that only covers part of the batch.
         */
        if (renameDtos.length === 1 && renameFailedCount === 0) {
          const [renamedDto] = renameDtos;
          onOperationSuccess?.({
            kind: FileOperationKind.FileRenamed,
            name: getVirtualPathName(
              renamedDto.destinationPath,
              renamedDto.destinationPath,
            ),
            isFolder: renamedDto.nodeType === RenameItemDtoNodeTypeEnum.Folder,
          });
        }

        if (totalFailed > 0) {
          if (totalFailed === totalCount) {
            onNotification?.({
              variant: NotificationVariant.Error,
              reason: useMoveCopy
                ? FileManagerNotificationReason.MoveFailed
                : FileManagerNotificationReason.RenameFailed,
            });
          } else {
            onNotification?.({
              variant: NotificationVariant.Error,
              reason: useMoveCopy
                ? FileManagerNotificationReason.MovePartiallyFailed
                : FileManagerNotificationReason.RenamePartiallyFailed,
              count: totalFailed,
            });
          }
        }

        // Navigate away if the current folder was renamed successfully.
        const renamedFolderDto = renameDtos.find(
          (dto) =>
            dto.nodeType === RenameItemDtoNodeTypeEnum.Folder &&
            renameOutcome.results.some(
              (result) =>
                result.success && result.sourcePath === dto.sourcePath,
            ),
        );
        if (renamedFolderDto != null) {
          const srcPrefix = renamedFolderDto.sourcePath.endsWith('/')
            ? renamedFolderDto.sourcePath
            : `${renamedFolderDto.sourcePath}/`;
          if (folderPath === srcPrefix || folderPath.startsWith(srcPrefix)) {
            const destPrefix = renamedFolderDto.destinationPath.endsWith('/')
              ? renamedFolderDto.destinationPath
              : `${renamedFolderDto.destinationPath}/`;
            setFolderPath(folderPath.replace(srcPrefix, destPrefix));
          }
        }

        const affectedKeys = new Set(
          [...renameDtos, ...moveDtos].flatMap((dto) => [
            getParentFolderPath(dto.sourcePath),
            getParentFolderPath(dto.destinationPath),
          ]),
        );

        invalidateFolders([...affectedKeys]);
        bumpRetry();
        setIsRenaming(false);
        setIsMoving(false);
        if (moveDtos.length > 0) {
          copyMoveAbortControllerRef.current = null;
        }
      };

      void run();
    },
    [
      bucket,
      rootLabel,
      folderPath,
      onOperationSuccess,
      onNotification,
      filesApi,
      isCopying,
      isMoving,
      isRenaming,
      invalidateFolders,
      bumpRetry,
      setFolderPath,
    ],
  );

  return {
    isCreatingFolder,
    isDownloading,
    isDeleting,
    isRenaming,
    isCopying,
    isMoving,
    onCreateFolder,
    onCreateFolderValidate,
    onDownloadFiles,
    onDeleteFiles,
    onRenameValidate,
    onMoveToFiles,
    onCopyFiles,
    cancelCopyMove,
  };
}

export interface UseDialFileSharingOptions {
  /** Injected operation port used for every sharing network call. */
  filesApi: DialFilesApi;
  /** DIAL Core bucket to browse (used only for the my_files tab). */
  bucket: string;
  /** Display name for the root folder node. */
  rootLabel: string;
  /** Forces `useDialFileListing`'s fetch effect to re-run after a mutation settles. */
  bumpRetry: () => void;
  /** Called when a sharing mutation fails and should surface a toast notification. */
  onNotification?: (notification: FileManagerNotification) => void;
}

export interface UseDialFileSharingResult {
  isUnsharing: boolean;
  isRemovingAccess: boolean;
  onUnshareFiles: (files: DialFile[]) => void;
  onRemoveFilesAccess: (files: DialFile[]) => void;
}

useDialFileSharing = ({
  filesApi,
  bucket,
  rootLabel,
  bumpRetry,
  onNotification,
}: UseDialFileSharingOptions): UseDialFileSharingResult => {
  const [isUnsharing, setIsUnsharing] = useState(false);
  const [isRemovingAccess, setIsRemovingAccess] = useState(false);

  const onUnshareFiles = useCallback(
    (files: DialFile[]) => {
      if (files.length === 0) return;

      const run = async () => {
        setIsUnsharing(true);
        const dtos = files.map((file) => {
          const itemBucket = file.bucket ?? bucket;
          return {
            bucket: itemBucket,
            path: resolveDialFileApiPath(file, itemBucket, rootLabel),
          };
        });

        try {
          await filesApi.discardShared(dtos);
          bumpRetry();
        } catch {
          onNotification?.({
            variant: NotificationVariant.Error,
            reason: FileManagerNotificationReason.UnshareFailed,
          });
        } finally {
          setIsUnsharing(false);
        }
      };
      void run();
    },
    [bucket, rootLabel, onNotification, filesApi, bumpRetry],
  );

  const onRemoveFilesAccess = useCallback(
    (files: DialFile[]) => {
      if (files.length === 0) return;

      const run = async () => {
        setIsRemovingAccess(true);
        const dtos = files.map((file) => {
          const itemBucket = file.bucket ?? bucket;
          return {
            bucket: itemBucket,
            path: resolveDialFileApiPath(file, itemBucket, rootLabel),
          };
        });

        try {
          await filesApi.revokeAccess(dtos);
          bumpRetry();
        } catch {
          onNotification?.({
            variant: NotificationVariant.Error,
            reason: FileManagerNotificationReason.RemoveAccessFailed,
          });
        } finally {
          setIsRemovingAccess(false);
        }
      };
      void run();
    },
    [bucket, rootLabel, onNotification, filesApi, bumpRetry],
  );

  return {
    isUnsharing,
    isRemovingAccess,
    onUnshareFiles,
    onRemoveFilesAccess,
  };
}

export interface UseDialFileUploadBatchOptions {
  /** Injected operation port used for every upload network call. */
  filesApi: DialFilesApi;
  /** DIAL Core bucket to browse (used only for the my_files tab). */
  bucket: string;
  /** Display name for the root folder node. */
  rootLabel: string;
  /** Active tab — drives owner-bucket resolution for the Shared tab. */
  activeTab: DialFileManagerTabs;
  /** Read-only snapshot of `useDialFileListing`'s cache, used to decide overwrite vs. create-only upload mode. */
  cache: Map<string, ListFilesItemDto[]>;
  /** Owner-bucket resolution metadata for the Shared tab, owned by `useDialFileListing`. */
  sharedRootMetaRef: React.RefObject<Map<string, SharedRootMeta>>;
  /** Deletes the given API-path cache keys so the next fetch re-fetches them. */
  invalidateFolders: (apiPaths: string[]) => void;
  /** Forces `useDialFileListing`'s fetch effect to re-run. */
  bumpRetry: () => void;
  /** Called when an upload batch fails or completes and should surface a toast notification. */
  onNotification?: (notification: FileManagerNotification) => void;
}

export interface UseDialFileUploadBatchResult {
  onUploadFiles: (
    files: DialUploadFileItem[],
    destinationFolder: string,
  ) => void;
  onUploadArchive: (
    file: File,
    name: string,
    destinationFolder: string,
  ) => void;
  onValidateUpload: (
    files: DialUploadFileItem[],
    existingFiles: DialFile[],
    destinationFolder: string,
  ) => Promise<FileUploadValidationResult>;
  uploadBatchState: FileUploadBatchState | null;
  cancelUpload: () => void;
  clearUploadBatch: () => void;
}

useDialFileUploadBatch = ({
  filesApi,
  bucket,
  rootLabel,
  activeTab,
  cache,
  sharedRootMetaRef,
  invalidateFolders,
  bumpRetry,
  onNotification,
}: UseDialFileUploadBatchOptions): UseDialFileUploadBatchResult => {
  const [uploadBatchState, setUploadBatchState] =
    useState<FileUploadBatchState | null>(null);
  const uploadAbortControllerRef = useRef<AbortController | null>(null);

  const uploadArchiveToFolder = useCallback(
    (file: File, name: string, destinationFolder: string) => {
      const destinationApiPath = virtualPathToApiPath(
        destinationFolder,
        rootLabel,
      );

      setUploadBatchState({
        files: [
          {
            id: `${Date.now()}-archive`,
            name,
            status: FileUploadStatus.Uploading,
          },
        ],
        isOpen: true,
      });

      const run = async (): Promise<void> => {
        try {
          const { results } = await filesApi.uploadArchive(
            file,
            bucket,
            buildArchiveDestinationPath(destinationApiPath, name),
          );
          const successCount = results.filter((r) => r.success).length;
          const failedResults = results.filter((r) => !r.success);
          const failedCount = failedResults.length;
          const { names, restCount } = formatArchiveFailedNames(failedResults);

          if (results.length > 0 && successCount === 0) {
            onNotification?.({
              variant: NotificationVariant.Error,
              reason: FileManagerNotificationReason.UploadArchiveFailed,
              names,
              restCount,
            });
          } else if (failedCount > 0) {
            onNotification?.({
              variant: NotificationVariant.Error,
              reason:
                FileManagerNotificationReason.UploadArchivePartiallyFailed,
              count: failedCount,
              names,
              restCount,
            });
          }
        } catch {
          onNotification?.({
            variant: NotificationVariant.Error,
            reason: FileManagerNotificationReason.UploadArchiveRequestFailed,
          });
        } finally {
          invalidateFolders([destinationApiPath]);
          bumpRetry();
          setUploadBatchState(null);
        }
      };

      void run();
    },
    [bucket, rootLabel, onNotification, filesApi, invalidateFolders, bumpRetry],
  );

  const onUploadFiles = useCallback(
    (files: DialUploadFileItem[], destinationFolder: string) => {
      if (files.length === 0) return;

      const archiveConflictFile = getArchiveConflictUploadFallback(files);
      if (archiveConflictFile != null) {
        uploadArchiveToFolder(
          archiveConflictFile.fileContent,
          archiveConflictFile.name,
          destinationFolder,
        );
        return;
      }

      const controller = new AbortController();
      uploadAbortControllerRef.current = controller;

      const entries: FileUploadEntry[] = files.map((f, i) => ({
        id: `${Date.now()}-${i}`,
        name: f.name,
        status: FileUploadStatus.Queued,
      }));

      setUploadBatchState({ files: entries, isOpen: true });

      const destinationApiPath = virtualPathToApiPath(
        destinationFolder,
        rootLabel,
      );
      const { bucket: uploadBucket, path: uploadBasePath } =
        activeTab === DialFileManagerTabs.Shared
          ? resolveOwnerCoords(
              destinationApiPath,
              sharedRootMetaRef.current,
              bucket,
            )
          : { bucket, path: destinationApiPath };

      const cachedNames = new Set(
        (cache.get(destinationApiPath) ?? []).map((item) =>
          item.name.toLowerCase(),
        ),
      );

      const processBatch = async () => {
        let nextIndex = 0;
        let successCount = 0;
        let failedCount = 0;

        const worker = async () => {
          while (nextIndex < files.length) {
            const i = nextIndex++;
            const file = files[i];

            if (controller.signal.aborted) {
              setUploadBatchState((prev) =>
                updateEntry(prev, i, FileUploadStatus.Cancelled),
              );
              continue;
            }

            setUploadBatchState((prev) =>
              updateEntry(prev, i, {
                status: FileUploadStatus.Uploading,
                percent: 0,
              }),
            );

            const uploadMode = cachedNames.has(file.name.toLowerCase())
              ? DialFilesApiUploadMode.Overwrite
              : DialFilesApiUploadMode.CreateOnly;

            try {
              await filesApi.uploadFile(
                uploadBucket,
                `${uploadBasePath}${file.name}`,
                file.fileContent,
                {
                  signal: controller.signal,
                  uploadMode,
                  onProgress: (percent) => {
                    setUploadBatchState((prev) =>
                      updateEntry(prev, i, {
                        status: FileUploadStatus.Uploading,
                        percent,
                      }),
                    );
                  },
                },
              );
              setUploadBatchState((prev) =>
                updateEntry(prev, i, {
                  status: FileUploadStatus.Completed,
                  percent: 100,
                }),
              );
              successCount += 1;
            } catch {
              const status = controller.signal.aborted
                ? FileUploadStatus.Cancelled
                : FileUploadStatus.Failed;
              if (status === FileUploadStatus.Failed) {
                failedCount += 1;
              }
              setUploadBatchState((prev) => updateEntry(prev, i, status));
            }
          }
        };

        await Promise.all(
          Array.from({ length: UPLOAD_CONCURRENCY }, () => worker()),
        );

        if (!controller.signal.aborted) {
          if (successCount === 0 && failedCount > 0) {
            onNotification?.({
              variant: NotificationVariant.Error,
              reason: FileManagerNotificationReason.UploadFailed,
            });
          } else {
            onNotification?.({
              variant: NotificationVariant.Success,
              reason: FileManagerNotificationReason.UploadCompleted,
              folder: uploadBasePath || rootLabel,
            });
          }
        }

        invalidateFolders([destinationApiPath]);
        bumpRetry();
        uploadAbortControllerRef.current = null;
        setUploadBatchState(null);
      };

      void processBatch();
    },
    [
      activeTab,
      bucket,
      cache,
      rootLabel,
      onNotification,
      filesApi,
      sharedRootMetaRef,
      invalidateFolders,
      bumpRetry,
      uploadArchiveToFolder,
    ],
  );

  const onUploadArchive = useCallback(
    (file: File, name: string, destinationFolder: string) => {
      uploadArchiveToFolder(file, name, destinationFolder);
    },
    [uploadArchiveToFolder],
  );

  const onValidateUpload = useCallback(
    async (
      files: DialUploadFileItem[],
      _existingFiles: DialFile[],
      _destinationFolder: string,
    ): Promise<FileUploadValidationResult> => {
      for (const file of files) {
        file.name = sanitizeFileName(file.name);
      }
      return { valid: true };
    },
    [],
  );

  const cancelUpload = useCallback(() => {
    uploadAbortControllerRef.current?.abort();
  }, []);

  const clearUploadBatch = useCallback(() => {
    setUploadBatchState(null);
  }, []);

  return {
    onUploadFiles,
    onUploadArchive,
    onValidateUpload,
    uploadBatchState,
    cancelUpload,
    clearUploadBatch,
  };
}

