getBrowserTimezone = (): string | undefined => {
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone || undefined;
  } catch {
    return undefined;
  }
}

isValidAbsoluteUrl = (value: string): boolean => {
  const trimmed = value.trim();
  if (!trimmed) return false;
  if (!/^https?:\/\//.test(trimmed)) return false;
  try {
    return Boolean(new URL(trimmed));
  } catch {
    return false;
  }
}

parseFeaturesData = (
  value: string,
): Record<string, unknown> | undefined => {
  const trimmed = value.trim();
  if (!trimmed) return undefined;
  try {
    return JSON.parse(trimmed) as Record<string, unknown>;
  } catch {
    return undefined;
  }
}

isValidFeaturesData = (value: string): boolean => {
  const trimmed = value.trim();
  if (!trimmed) return true;
  try {
    const parsed: unknown = JSON.parse(trimmed);
    if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed))
      return false;
    const keys = Object.keys(parsed as Record<string, unknown>);
    return (
      keys.length > 0 &&
      keys.every((key) => ALLOWED_FEATURES_DATA_KEYS.includes(key))
    );
  } catch {
    return false;
  }
}

export interface ParsedExternalServiceUrl {
  /** The application's own resource id — used for `GET /api/v1/deployments/{appId}/details`. */
  appId: string;
  /** Key into `applicationDetails.externalServices` for this specific dependency. */
  serviceName: string;
}

parseExternalServiceUrl = (
  url: string,
): ParsedExternalServiceUrl | null => {
  const index = url.indexOf(EXTERNAL_SERVICE_URL_SEGMENT);
  if (index === -1) return null;

  const appId = url.slice(0, index);
  const serviceName = url.slice(index + EXTERNAL_SERVICE_URL_SEGMENT.length);
  if (!appId || !serviceName) return null;

  return { appId, serviceName };
}

getExternalServiceFallbackName = (serviceName: string): string => {
  try {
    return decodeURIComponent(serviceName);
  } catch {
    return serviceName;
  }
}

resolveLocalizedText = (
  value: LocalizedText | undefined | null,
  activeLocale: string,
  primaryLocale: string,
): string => {
  if (value == null) return '';
  if (typeof value === 'string') return value;
  const base = toBaseLocale(activeLocale);
  return (
    value[activeLocale] ??
    value[base] ??
    value[primaryLocale] ??
    Object.values(value).find((entry) => entry !== undefined) ??
    ''
  );
}

composeLocalePayload = (
  otherLocales: DeploymentCreationFormLocaleEntry[],
  primaryLocale: string,
): LocaleTextEntryDto[] | undefined => {
  const byLanguage = new Map<string, LocaleTextEntryDto>();

  for (const entry of otherLocales) {
    if (!entry.language || entry.language === primaryLocale) continue;
    if (!entry.name && !entry.description) continue;
    byLanguage.set(entry.language, {
      language: entry.language,
      name: entry.name || undefined,
      description: entry.description || undefined,
    });
  }

  return byLanguage.size > 0 ? Array.from(byLanguage.values()) : undefined;
}

decomposeLocalizedFields = (
  displayName: LocalizedText | undefined,
  description: LocalizedText | undefined,
  primaryLocale: string,
): DeploymentCreationFormLocaleEntry[] => {
  const nameMap = typeof displayName === 'object' ? displayName : {};
  const descriptionMap = typeof description === 'object' ? description : {};
  const languages = new Set([
    ...Object.keys(nameMap),
    ...Object.keys(descriptionMap),
  ]);
  languages.delete(primaryLocale);

  let rowId = 0;
  return Array.from(languages, (language) => ({
    id: `decomposed-locale-${++rowId}`,
    language,
    name: nameMap[language] ?? '',
    description: descriptionMap[language] ?? '',
  }));
}

safeDecodeURI = (path: string): string => {
  try {
    return decodeURIComponent(path);
  } catch {
    return path;
  }
}

stripTrailingSlashes = (path: string): string => {
  let end = path.length;
  while (end > 0 && path[end - 1] === '/') end -= 1;
  return path.slice(0, end);
}

stripSurroundingSlashes = (path: string): string => {
  let start = 0;
  let end = path.length;
  while (start < end && path[start] === '/') start += 1;
  while (end > start && path[end - 1] === '/') end -= 1;
  return path.slice(start, end);
}

