export interface UseShareLinkResult {
  /** Resolved share-link data, or `undefined` while loading or on error. */
  data: ShareLinkData | undefined;
  /** Whether the share link is still being created. */
  isLoading: boolean;
  /** Set when the share link could not be created. */
  error: Error | null;
  /** Requests a new share link for the given access levels. */
  setAccess: (access: ShareLinkAccess[]) => void;
}

useShareLink = (
  shareApi: Pick<ShareApi, 'createShareLink'>,
  itemId: string,
  origin: string = window.location.origin,
): UseShareLinkResult => {
  const [data, setData] = useState<ShareLinkData>();
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);
  const requestIdRef = useRef(0);

  /*
   * Access is not merely display state: DIAL Core issues a distinct link per
   * access level, so changing it re-requests a fresh link rather than
   * patching the previous response in place.
   */
  const load = useCallback(
    async (access: ShareLinkAccess[] = [ShareLinkAccess.View]) => {
      const requestId = ++requestIdRef.current;
      setIsLoading(true);
      setError(null);

      try {
        const response = await shareApi.createShareLink({
          createShareLinkDto: { itemId, access },
        });
        if (requestIdRef.current === requestId) {
          setData({
            url: withOrigin(response.url, origin),
            expiresInDays: response.expiresInDays,
            access: toShareLinkAccess(response.access),
          });
        }
      } catch (err) {
        if (requestIdRef.current === requestId) {
          setError(
            err instanceof Error
              ? err
              : new Error('Failed to create share link'),
          );
        }
      } finally {
        if (requestIdRef.current === requestId) setIsLoading(false);
      }
    },
    [itemId, origin, shareApi],
  );

  useEffect(() => {
    setData(undefined);
    void load();
  }, [itemId, load]);

  const setAccess = useCallback(
    (access: ShareLinkAccess[]) => {
      void load(access);
    },
    [load],
  );

  return { data, isLoading, error, setAccess };
}

export enum RecipientsCountStatus {
  /** Nothing requested yet for this resource. */
  Idle = 'idle',
  /** A lookup is in flight. */
  Loading = 'loading',
  /** A count came back and is known exactly. */
  Resolved = 'resolved',
  /** The lookup failed, so the count is unknown. */
  Unknown = 'unknown',
}

export interface RecipientsCountEntry {
  /** Where the lookup for this resource currently stands. */
  status: RecipientsCountStatus;
  /** Number of users holding access; present only once the status is `Resolved`. */
  count?: number;
}

export interface UseShareRecipientsCountResult {
  /** Starts a lookup for the resource unless one already ran for it. */
  requestRecipientsCount: (itemId: string) => void;
  /** Current lookup state for the resource. */
  getRecipientsCount: (itemId: string) => RecipientsCountEntry;
  /** Drops the resource's cached result so the next request fetches it again. */
  invalidateRecipientsCount: (itemId: string) => void;
}

useShareRecipientsCount = (
  shareApi: Pick<ShareApi, 'getShareRecipientsCount'>,
): UseShareRecipientsCountResult => {
  const [entries, setEntries] = useState<
    Record<string, RecipientsCountEntry | undefined>
  >({});
  /* Ids whose lookup has already been started, so reopening the same menu does
   * not re-issue the request. */
  const requestedIdsRef = useRef(new Set<string>());

  const requestRecipientsCount = useCallback(
    (itemId: string) => {
      if (requestedIdsRef.current.has(itemId)) return;
      requestedIdsRef.current.add(itemId);
      setEntries((prev) => ({
        ...prev,
        [itemId]: { status: RecipientsCountStatus.Loading },
      }));

      const resolve = async () => {
        try {
          const { recipientsCount } = await shareApi.getShareRecipientsCount({
            itemId,
          });
          setEntries((prev) => ({
            ...prev,
            [itemId]: {
              status: RecipientsCountStatus.Resolved,
              count: recipientsCount,
            },
          }));
        } catch {
          /* An unresolved count must not remove the only way to revoke, so the
           * action stays reachable — just without a number. */
          setEntries((prev) => ({
            ...prev,
            [itemId]: { status: RecipientsCountStatus.Unknown },
          }));
        }
      };
      void resolve();
    },
    [shareApi],
  );

  const getRecipientsCount = useCallback(
    (itemId: string) => entries[itemId] ?? IDLE_ENTRY,
    [entries],
  );

  const invalidateRecipientsCount = useCallback((itemId: string) => {
    requestedIdsRef.current.delete(itemId);
    setEntries(({ [itemId]: _removed, ...rest }) => rest);
  }, []);

  return {
    requestRecipientsCount,
    getRecipientsCount,
    invalidateRecipientsCount,
  };
}

export interface UseToolsMenuParams {
  /** Id of the currently selected deployment, or `null` when none is selected. */
  selectedItemId: string | null;
  /** JSON-schema configuration for the selected deployment, or `null` when none. */
  selectedDeploymentConfiguration: DeploymentConfigurationSchema | null;
  /** Icon element rendered on every tool menu item. Defaults to `null`. */
  toolIcon?: ReactNode;
}

export type UseToolsMenuResult = {
  /** One item per boolean property of the deployment configuration schema, in schema order. */
  toolsMenuItems: ToolMenuItem[];
  /** Toggles the tool with the given id; ignores unknown ids. */
  onToolToggle: (id: string) => void;
  /** Stable record of tool ids to their current on/off state, for completion requests. */
  toolConfigurationValue: Record<string, boolean>;
  /** Restores toggle state from a persisted tool configuration record. */
  restoreToolConfiguration: (
    configurationValue: Record<string, unknown> | undefined,
  ) => void;
};

useToolsMenu = (
  params: UseToolsMenuParams,
): UseToolsMenuResult => {
  const { selectedItemId, selectedDeploymentConfiguration, toolIcon } = params;

  const toolDefinitions = useMemo(
    () => buildToolDefinitions(selectedDeploymentConfiguration),
    [selectedDeploymentConfiguration],
  );

  const defaultSelections = useMemo(
    () =>
      Object.fromEntries(
        toolDefinitions.map(({ id, defaultValue }) => [id, defaultValue]),
      ),
    [toolDefinitions],
  );

  const [selections, setSelections] =
    useState<Record<string, boolean>>(defaultSelections);

  /*
   * The effect below must not re-run just because the host handed us a new
   * schema object with identical contents — that would reset the toggles on
   * every render. Compare the defaults by value, and read the latest object
   * through a ref when a reset is actually due.
   */
  const defaultSelectionsSignature = JSON.stringify(defaultSelections);
  const defaultSelectionsRef = useRef(defaultSelections);
  defaultSelectionsRef.current = defaultSelections;

  useEffect(() => {
    setSelections(defaultSelectionsRef.current);
  }, [selectedItemId, defaultSelectionsSignature]);

  const onToolToggle = useCallback(
    (id: string) => {
      setSelections((prev) => {
        if (!(id in prev)) return prev;
        return { ...prev, [id]: !prev[id] };
      });
    },
    [setSelections],
  );

  const restoreToolConfiguration = useCallback(
    (configurationValue: Record<string, unknown> | undefined) => {
      if (configurationValue == null) return;
      setSelections((prev) => {
        let hasChange = false;
        const restored = { ...prev };
        for (const id of Object.keys(prev)) {
          const value = configurationValue[id];
          if (typeof value === 'boolean' && value !== prev[id]) {
            restored[id] = value;
            hasChange = true;
          }
        }
        return hasChange ? restored : prev;
      });
    },
    [setSelections],
  );

  const toolsMenuItems: ToolMenuItem[] = useMemo(
    () =>
      toolDefinitions.map(({ id, label }) => ({
        id,
        label,
        icon: toolIcon ?? null,
        isSelected: selections[id] ?? false,
      })),
    [toolDefinitions, selections, toolIcon],
  );

  const toolConfigurationValue: Record<string, boolean> = useMemo(
    () =>
      Object.fromEntries(
        toolDefinitions.map(({ id }) => [id, selections[id] ?? false]),
      ),
    [toolDefinitions, selections],
  );

  return {
    toolsMenuItems,
    onToolToggle,
    toolConfigurationValue,
    restoreToolConfiguration,
  };
}

export interface UseUsageDataResult {
  /** Calendar-period usage and rate-limit stats for every deployment the caller has used in the current UTC day, week, and month, plus the caller's global cost budget. Retained across a `refreshToken`-triggered re-fetch until the new response resolves. */
  usage: UserLimitStatsResponseDto | undefined;
  /** `true` while a fetch is in flight, including a `refreshToken`-triggered re-fetch. */
  isLoading: boolean;
  /** Set when the `getUserUsage` call rejects. */
  usageError: Error | undefined;
}

useUsageData = (
  getUserUsage: () => Promise<UserLimitStatsResponseDto>,
  enabled = true,
  refreshToken = 0,
): UseUsageDataResult => {
  const [usage, setUsage] = useState<UserLimitStatsResponseDto>();
  const [isLoading, setIsLoading] = useState(enabled);
  const [usageError, setUsageError] = useState<Error>();

  useEffect(() => {
    if (!enabled) {
      setIsLoading(false);
      return;
    }

    let cancelled = false;
    setIsLoading(true);

    const fetchUsageData = async () => {
      try {
        const result = await getUserUsage();
        if (cancelled) return;
        setUsage(result);
      } catch (reason) {
        if (cancelled) return;
        setUsageError(toError(reason));
      } finally {
        if (!cancelled) setIsLoading(false);
      }
    };

    void fetchUsageData();

    return () => {
      cancelled = true;
    };
  }, [enabled, getUserUsage, refreshToken]);

  return { usage, isLoading, usageError };
}

useViewportWidth = (): number => {
  const [width, setWidth] = useState(getInnerWidth);

  useEffect(() => {
    if (typeof window === 'undefined') return;

    const handleResize = () => setWidth(window.innerWidth);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  return width;
}

